import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [scanTarget, setScanTarget] = useState<'in' | 'out' | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Form states
  const [formProduct, setFormProduct] = useState<QRPayload | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState(''); // Supplier or Recipient
  const [approver, setApprover] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const handleQRScan = (text: string) => {
    let payload: QRPayload;
    const cleanText = text.trim();

    try {
      // Öncelikle JSON formatında olup olmadığını kontrol et
      const data = JSON.parse(cleanText);
      if (data && typeof data === 'object') {
        payload = {
          id: (data.id || data.sku || cleanText).toString(),
          name: (data.name || data.product || data.id || cleanText).toString(),
          supplier: data.supplier
        };
      } else {
        throw new Error('Not an object');
      }
    } catch (e) {
      // JSON değilse, okunan metni doğrudan isim ve ID olarak kullan
      payload = {
        id: cleanText,
        name: cleanText
      };
    }

    setFormProduct(payload);
    if (payload.supplier) setPartner(payload.supplier);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla okundu', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
  };

  const handleTransaction = () => {
    if (!formProduct || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === formProduct.id);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: formProduct.id,
      productName: formProduct.name,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setFormProduct(null);
    setQuantity(1);
    setPartner('');
    setApprover('');
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const existing = map.get(tx.productId) || {
        productId: tx.productId,
        productName: tx.productName,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(tx.productId, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        onClick={() => { setActiveTab(id); setSidebarOpen(false); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[60] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white animate-bounce ${
            notification.type === 'success' ? 'bg-emerald-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <header>
              <h2 className="text-2xl font-bold text-slate-800">Genel Bakış</h2>
              <p className="text-slate-500">Depo güncel durumu ve son hareketler.</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo' },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose' },
                { label: 'Aktif Stok Çeşidi', val: inventory.length, color: 'emerald' },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <p className="text-sm font-medium text-slate-500 mb-1">{card.label}</p>
                  <p className={`text-3xl font-bold text-${card.color}-600`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="font-bold mb-6 text-slate-700">Stok Dağılımı</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={inventory.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="productName" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="totalIn" name="Giriş" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="totalOut" name="Çıkış" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <h3 className="font-bold mb-4 text-slate-700">En Çok Kalan Ürünler</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead>
                      <tr className="text-slate-400 border-b">
                        <th className="pb-3 font-medium">Ürün</th>
                        <th className="pb-3 font-medium">Gelen</th>
                        <th className="pb-3 font-medium">Giden</th>
                        <th className="pb-3 font-medium">Kalan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {inventory.sort((a,b) => b.remaining - a.remaining).slice(0, 5).map((p, i) => (
                        <tr key={i} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 font-semibold text-slate-800 truncate max-w-[150px]" title={p.productName}>{p.productName}</td>
                          <td className="py-4 text-emerald-600">+{p.totalIn}</td>
                          <td className="py-4 text-rose-500">-{p.totalOut}</td>
                          <td className="py-4 font-bold">{p.remaining}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-2xl mx-auto space-y-6">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">Herhangi bir QR kod okutarak işleme başlayın.</p>
            </header>

            {!formProduct ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">Ürün üzerindeki etiketi okutun</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in">
                <div className="flex justify-between items-start">
                  <div className="overflow-hidden">
                    <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider">Okunan Ürün / Kod</h3>
                    <p className="text-2xl font-bold text-slate-900 break-all">{formProduct.name}</p>
                    <p className="text-slate-500 font-mono text-sm">Kimlik: {formProduct.id.substring(0, 20)}...</p>
                  </div>
                  <button onClick={() => setFormProduct(null)} className="text-indigo-600 text-sm font-medium hover:underline flex-shrink-0">
                    Yeniden Tara
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      onChange={(e) => setPartner(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                      placeholder="İlgili birim adı..."
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Miktar (Adet)</label>
                    <input 
                      type="number" 
                      value={quantity}
                      min="1"
                      onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
                </div>

                {activeTab === 'in' && (
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Onaylayan Kişi</label>
                    <input 
                      type="text" 
                      value={approver}
                      onChange={(e) => setApprover(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                      placeholder="Onaylayan yönetici..."
                    />
                  </div>
                )}

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg shadow-indigo-200 transition-all hover:scale-[1.02] active:scale-95 ${
                    activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500 shadow-rose-200'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Kaydet' : 'Stok Çıkışını Onayla'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Yapılan tüm stok hareketlerinin dökümü.</p>
              </div>
              <div className="flex gap-2">
                 <button 
                  onClick={() => {
                    const csvContent = "data:text/csv;charset=utf-8," 
                      + "Tarih,Tip,Ürün,Miktar,Firma,İşlem Yapan,Onaylayan\n"
                      + transactions.map(t => `${t.date},${t.type},${t.productName},${t.quantity},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                    const encodedUri = encodeURI(csvContent);
                    window.open(encodedUri);
                  }}
                  className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm"
                >
                  Excel'e Aktar
                </button>
              </div>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">İlişkili Firma</th>
                      <th className="px-6 py-4 font-semibold">Operatör</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4 font-bold text-slate-800 break-all max-w-[200px]">{t.productName}</td>
                        <td className="px-6 py-4 font-medium whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-slate-600">{t.supplier || t.recipient}</td>
                        <td className="px-6 py-4 text-slate-500">{t.operator}</td>
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                          Henüz bir işlem kaydı bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Sisteme erişebilen personel listesi.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-indigo-600 font-bold text-xl">
                {u.fullName.charAt(0)}
              </div>
              <div>
                <p className="font-bold text-slate-800">{u.fullName}</p>
                <p className="text-sm text-slate-500">@{u.username} • {u.role}</p>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 p-2">
                <X size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export interface User {
  id: string;
  username: string;
  password?: string;
  role: UserRole;
  fullName: string;
}

export enum TransactionType {
  IN = 'Giriş',
  OUT = 'Çıkış'
}

export interface Transaction {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  size?: string;
  color?: string;
  feature?: string;
  supplier?: string; // Sadece girişlerde
  recipient?: string; // Sadece çıkışlarda
  quantity: number;
  type: TransactionType;
  date: string;
  operator: string; // İşlemi yapan
  approver?: string; // Onaylayan
}

export interface ProductStock {
  productId: string;
  productName: string;
  productCode: string;
  totalIn: number;
  totalOut: number;
  remaining: number;
  lastUpdate: string;
}

export interface QRPayload {
  id: string;
  name: string;
  productCode: string;
  supplier?: string;
  size?: string;
  color?: string;
  feature?: string;
  quantity?: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();

    // Tırnak içindeki verileri yakala
    const matches = [...cleanText.matchAll(/"([^"]*)"/g)].map(m => m[1]);

    // Eşleşen verileri sırasıyla ata veya varsayılan değerleri kullan
    // Beklenen Sıra: "Ürün Kodu" "Ürün Adı" "Tedarikçi" "Beden" "Renk" "Özellik"
    const parsed: QRPayload = {
      id: matches[0] || cleanText,
      productCode: matches[0] || cleanText,
      name: matches[1] || 'Bilinmeyen Ürün',
      supplier: matches[2] || '',
      size: matches[3] || '',
      color: matches[4] || '',
      feature: matches[5] || '',
      quantity: 1
    };

    setProductId(parsed.id);
    setProductCode(parsed.productCode);
    setProductName(parsed.name);
    setPartner(parsed.supplier || '');
    setSize(parsed.size || '');
    setColor(parsed.color || '');
    setFeature(parsed.feature || '');
    setQuantity(1);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla okundu', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
  };

  const toggleEdit = () => {
    if (!isEditable) {
      if (window.confirm('Otomatik doldurulan bilgileri manuel olarak değiştirmek istediğinize emin misiniz?')) {
        setIsEditable(true);
      }
    } else {
      setIsEditable(false);
    }
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(1);
    setPartner('');
    setApprover('');
  };

  const handleTransaction = () => {
    if (!productName || !productCode || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === productId);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId,
      productName,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const existing = map.get(tx.productId) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(tx.productId, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[60] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white animate-bounce ${
            notification.type === 'success' ? 'bg-emerald-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <header>
              <h2 className="text-2xl font-bold text-slate-800">Genel Bakış</h2>
              <p className="text-slate-500">Depo güncel durumu ve son hareketler.</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo' },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose' },
                { label: 'Aktif Stok Çeşidi', val: inventory.length, color: 'emerald' },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <p className="text-sm font-medium text-slate-500 mb-1">{card.label}</p>
                  <p className={`text-3xl font-bold text-${card.color}-600`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="font-bold mb-6 text-slate-700">Stok Dağılımı</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={inventory.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="productName" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="totalIn" name="Giriş" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="totalOut" name="Çıkış" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <h3 className="font-bold mb-4 text-slate-700">En Çok Kalan Ürünler</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead>
                      <tr className="text-slate-400 border-b">
                        <th className="pb-3 font-medium">Ürün Kodu</th>
                        <th className="pb-3 font-medium">Ürün Adı</th>
                        <th className="pb-3 font-medium">Kalan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {inventory.sort((a,b) => b.remaining - a.remaining).slice(0, 5).map((p, i) => (
                        <tr key={i} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 font-mono text-xs">{p.productCode}</td>
                          <td className="py-4 font-semibold text-slate-800 truncate max-w-[150px]" title={p.productName}>{p.productName}</td>
                          <td className="py-4 font-bold">{p.remaining}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-3xl mx-auto space-y-6">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">QR okutun, veriler otomatik dolsun.</p>
            </header>

            {!isFormActive ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">QR kod okutarak formun dolmasını sağlayın</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in relative">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-bold text-slate-800">İşlem Detayları</h3>
                  <div className="flex gap-2">
                    <button 
                      onClick={toggleEdit}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
                        isEditable ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600'
                      }`}
                    >
                      {isEditable ? <Unlock size={14} /> : <Lock size={14} />}
                      {isEditable ? 'Düzenleme Açık' : 'Düzenlemek için Tıkla'}
                    </button>
                    <button onClick={resetForm} className="text-indigo-600 text-sm font-medium hover:underline">
                      Yeniden Tara
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Kodu</label>
                    <input 
                      type="text" 
                      value={productCode}
                      disabled={!isEditable}
                      onChange={(e) => setProductCode(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Adı</label>
                    <input 
                      type="text" 
                      value={productName}
                      disabled={!isEditable}
                      onChange={(e) => setProductName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      disabled={!isEditable}
                      onChange={(e) => setPartner(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Miktar</label>
                      <input 
                        type="number" 
                        value={quantity}
                        min="1"
                        onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Beden</label>
                      <input 
                        type="text" 
                        value={size}
                        disabled={!isEditable}
                        onChange={(e) => setSize(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Renk</label>
                    <input 
                      type="text" 
                      value={color}
                      disabled={!isEditable}
                      onChange={(e) => setColor(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Özellik</label>
                    <input 
                      type="text" 
                      value={feature}
                      disabled={!isEditable}
                      onChange={(e) => setFeature(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:cursor-not-allowed"
                    />
                  </div>
                </div>

                {activeTab === 'in' && (
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Onaylayan Kişi</label>
                    <input 
                      type="text" 
                      value={approver}
                      onChange={(e) => setApprover(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                      placeholder="Onaylayan yönetici..."
                    />
                  </div>
                )}

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all hover:scale-[1.02] active:scale-95 ${
                    activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Kaydet' : 'Stok Çıkışını Onayla'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <button 
                onClick={() => {
                  const csvContent = "data:text/csv;charset=utf-8," 
                    + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                    + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                  const encodedUri = encodeURI(csvContent);
                  window.open(encodedUri);
                }}
                className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm"
              >
                Excel'e Aktar
              </button>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Operatör</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-medium whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          {t.size && <span className="mr-2">Beden: {t.size}</span>}
                          {t.color && <span className="mr-2">Renk: {t.color}</span>}
                          <p className="mt-1 italic">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">{t.operator}</td>
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                          Henüz bir işlem kaydı bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-indigo-600 font-bold text-xl">
                {u.fullName.charAt(0)}
              </div>
              <div>
                <p className="font-bold text-slate-800">{u.fullName}</p>
                <p className="text-sm text-slate-500">@{u.username} • {u.role}</p>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 p-2">
                <X size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();

    // Extract everything between quotes
    const matches = [...cleanText.matchAll(/"([^"]*)"/g)].map(m => m[1]);

    /**
     * User requested order for parsing:
     * Tedarikçi Firma, Miktar, Beden, (Adet - used as quantity too), Renk, Özellik, Ürün Kodu
     * We'll also try to extract a Product Name if available.
     */
    const parsed = {
      supplier: matches[0] || '',
      quantity: parseInt(matches[1]) || 1,
      size: matches[2] || '',
      color: matches[4] || '', // Skipping index 3 as it might be "Adet"
      feature: matches[5] || '',
      productCode: matches[6] || cleanText,
      name: matches[7] || matches[6] || 'Ürün ' + (matches[6] || 'Tanımsız')
    };

    setProductId(parsed.productCode || Math.random().toString(36).substr(2, 9));
    setProductCode(parsed.productCode);
    setProductName(parsed.name);
    setPartner(parsed.supplier);
    setSize(parsed.size);
    setColor(parsed.color);
    setFeature(parsed.feature);
    setQuantity(parsed.quantity);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla okundu ve ayrıştırıldı', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isEditable) {
      const confirmEdit = window.confirm('Otomatik doldurulan bilgileri manuel olarak değiştirmek istediğinize emin misiniz?');
      if (confirmEdit) {
        setIsEditable(true);
      }
    } else {
      setIsEditable(false);
    }
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(1);
    setPartner('');
    setApprover('');
  };

  const handleTransaction = () => {
    if (!productCode || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === productId || p.productCode === productCode);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const key = tx.productId;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <header>
              <h2 className="text-2xl font-bold text-slate-800">Genel Bakış</h2>
              <p className="text-slate-500">Depo güncel durumu ve son hareketler.</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo' },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose' },
                { label: 'Aktif Stok Çeşidi', val: inventory.length, color: 'emerald' },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <p className="text-sm font-medium text-slate-500 mb-1">{card.label}</p>
                  <p className={`text-3xl font-bold text-slate-900`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="font-bold mb-6 text-slate-700">Stok Dağılımı</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={inventory.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="productName" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="totalIn" name="Giriş" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="totalOut" name="Çıkış" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <h3 className="font-bold mb-4 text-slate-700">En Çok Kalan Ürünler</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead>
                      <tr className="text-slate-400 border-b">
                        <th className="pb-3 font-medium">Ürün Kodu</th>
                        <th className="pb-3 font-medium">Ürün Adı</th>
                        <th className="pb-3 font-medium">Kalan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {inventory.sort((a,b) => b.remaining - a.remaining).slice(0, 5).map((p, i) => (
                        <tr key={i} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 font-mono text-xs">{p.productCode}</td>
                          <td className="py-4 font-semibold text-slate-800 truncate max-w-[150px]" title={p.productName}>{p.productName}</td>
                          <td className="py-4 font-bold">{p.remaining}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-3xl mx-auto space-y-6">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">QR okutun, veriler otomatik dolsun.</p>
            </header>

            {!isFormActive ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">QR kod okutarak formun dolmasını sağlayın</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in">
                <div className="flex justify-between items-center gap-4">
                  <h3 className="text-lg font-bold text-slate-800">İşlem Detayları</h3>
                  <div className="flex gap-2 shrink-0">
                    <button 
                      type="button"
                      onClick={toggleEdit}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all z-10 ${
                        isEditable ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {isEditable ? <Unlock size={14} /> : <Lock size={14} />}
                      {isEditable ? 'Düzenleme Açık' : 'Düzenlemek için Tıkla'}
                    </button>
                    <button onClick={resetForm} className="text-indigo-600 text-sm font-medium hover:underline p-1.5">
                      Yeniden Tara
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Kodu</label>
                    <input 
                      type="text" 
                      value={productCode}
                      disabled={!isEditable}
                      onChange={(e) => setProductCode(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Adı</label>
                    <input 
                      type="text" 
                      value={productName}
                      disabled={!isEditable}
                      onChange={(e) => setProductName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      disabled={!isEditable}
                      onChange={(e) => setPartner(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Miktar</label>
                      <input 
                        type="number" 
                        value={quantity}
                        min="1"
                        onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Beden</label>
                      <input 
                        type="text" 
                        value={size}
                        disabled={!isEditable}
                        onChange={(e) => setSize(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Renk</label>
                    <input 
                      type="text" 
                      value={color}
                      disabled={!isEditable}
                      onChange={(e) => setColor(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Özellik</label>
                    <input 
                      type="text" 
                      value={feature}
                      disabled={!isEditable}
                      onChange={(e) => setFeature(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                </div>

                {activeTab === 'in' && (
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Onaylayan Kişi</label>
                    <input 
                      type="text" 
                      value={approver}
                      onChange={(e) => setApprover(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                      placeholder="Onaylayan yönetici adı..."
                    />
                  </div>
                )}

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all transform hover:scale-[1.01] active:scale-[0.98] ${
                    activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-100 hover:bg-indigo-700' : 'bg-rose-500 shadow-rose-100 hover:bg-rose-600'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Kaydet' : 'Stok Çıkışını Onayla'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <button 
                onClick={() => {
                  const csvContent = "data:text/csv;charset=utf-8," 
                    + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                    + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                  const encodedUri = encodeURI(csvContent);
                  window.open(encodedUri);
                }}
                className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm transition-colors"
              >
                Excel'e Aktar
              </button>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Operatör</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-medium whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          {t.size && <span className="mr-2">Beden: {t.size}</span>}
                          {t.color && <span className="mr-2">Renk: {t.color}</span>}
                          <p className="mt-1 italic truncate max-w-[120px]">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">{t.operator}</td>
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                          Henüz bir işlem kaydı bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0">
                {u.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-slate-800 truncate">{u.fullName}</p>
                <p className="text-sm text-slate-500 truncate">@{u.username} • {u.role}</p>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 p-2 transition-colors">
                <X size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();

    // Extract everything between quotes
    const matches = [...cleanText.matchAll(/"([^"]*)"/g)].map(m => m[1]);

    /**
     * Parsing logic based on user request:
     * Tedarikçi Firma (0), Miktar (1), Beden (2), Adet (3), Renk (4), Özellik (5), Ürün Kodu (6)
     */
    const parsed = {
      supplier: matches[0] || '',
      quantity: parseInt(matches[1]) || parseInt(matches[3]) || 1,
      size: matches[2] || '',
      color: matches[4] || '',
      feature: matches[5] || '',
      productCode: matches[6] || cleanText,
      name: matches[7] || matches[6] || 'Ürün ' + (matches[6] || 'Tanımsız')
    };

    setProductId(parsed.productCode || Math.random().toString(36).substr(2, 9));
    setProductCode(parsed.productCode);
    setProductName(parsed.name);
    setPartner(parsed.supplier);
    setSize(parsed.size);
    setColor(parsed.color);
    setFeature(parsed.feature);
    setQuantity(parsed.quantity);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla okundu ve ayrıştırıldı', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    // Removed confirmation window as per user request
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(1);
    setPartner('');
    setApprover('');
  };

  const handleTransaction = () => {
    if (!productCode || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === productId || p.productCode === productCode);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const key = tx.productId;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <header>
              <h2 className="text-2xl font-bold text-slate-800">Genel Bakış</h2>
              <p className="text-slate-500">Depo güncel durumu ve son hareketler.</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo' },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose' },
                { label: 'Aktif Stok Çeşidi', val: inventory.length, color: 'emerald' },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <p className="text-sm font-medium text-slate-500 mb-1">{card.label}</p>
                  <p className={`text-3xl font-bold text-slate-900`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="font-bold mb-6 text-slate-700">Stok Dağılımı</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={inventory.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="productName" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="totalIn" name="Giriş" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="totalOut" name="Çıkış" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <h3 className="font-bold mb-4 text-slate-700">En Çok Kalan Ürünler</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead>
                      <tr className="text-slate-400 border-b">
                        <th className="pb-3 font-medium">Ürün Kodu</th>
                        <th className="pb-3 font-medium">Ürün Adı</th>
                        <th className="pb-3 font-medium">Kalan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {inventory.sort((a,b) => b.remaining - a.remaining).slice(0, 5).map((p, i) => (
                        <tr key={i} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 font-mono text-xs">{p.productCode}</td>
                          <td className="py-4 font-semibold text-slate-800 truncate max-w-[150px]" title={p.productName}>{p.productName}</td>
                          <td className="py-4 font-bold">{p.remaining}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-3xl mx-auto space-y-6">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">QR okutun, veriler otomatik dolsun.</p>
            </header>

            {!isFormActive ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">QR kod okutarak formun dolmasını sağlayın</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in">
                <div className="flex justify-between items-center gap-4">
                  <h3 className="text-lg font-bold text-slate-800">İşlem Detayları</h3>
                  <div className="flex gap-2 shrink-0">
                    <button 
                      type="button"
                      onClick={toggleEdit}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all z-10 ${
                        isEditable ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {isEditable ? <Unlock size={14} /> : <Lock size={14} />}
                      {isEditable ? 'Düzenleme Açık' : 'Düzenlemek için Tıkla'}
                    </button>
                    <button onClick={resetForm} className="text-indigo-600 text-sm font-medium hover:underline p-1.5">
                      Yeniden Tara
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Kodu</label>
                    <input 
                      type="text" 
                      value={productCode}
                      disabled={!isEditable}
                      onChange={(e) => setProductCode(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Adı</label>
                    <input 
                      type="text" 
                      value={productName}
                      disabled={!isEditable}
                      onChange={(e) => setProductName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      disabled={!isEditable}
                      onChange={(e) => setPartner(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Miktar</label>
                      <input 
                        type="number" 
                        value={quantity}
                        min="1"
                        onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Beden</label>
                      <input 
                        type="text" 
                        value={size}
                        disabled={!isEditable}
                        onChange={(e) => setSize(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Renk</label>
                    <input 
                      type="text" 
                      value={color}
                      disabled={!isEditable}
                      onChange={(e) => setColor(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Özellik</label>
                    <input 
                      type="text" 
                      value={feature}
                      disabled={!isEditable}
                      onChange={(e) => setFeature(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                </div>

                {activeTab === 'in' && (
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Onaylayan Kişi</label>
                    <input 
                      type="text" 
                      value={approver}
                      onChange={(e) => setApprover(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                      placeholder="Onaylayan yönetici adı..."
                    />
                  </div>
                )}

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all transform hover:scale-[1.01] active:scale-[0.98] ${
                    activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-100 hover:bg-indigo-700' : 'bg-rose-500 shadow-rose-100 hover:bg-rose-600'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Kaydet' : 'Stok Çıkışını Onayla'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <button 
                onClick={() => {
                  const csvContent = "data:text/csv;charset=utf-8," 
                    + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                    + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                  const encodedUri = encodeURI(csvContent);
                  window.open(encodedUri);
                }}
                className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm transition-colors"
              >
                Excel'e Aktar
              </button>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Operatör</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-medium whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          {t.size && <span className="mr-2">Beden: {t.size}</span>}
                          {t.color && <span className="mr-2">Renk: {t.color}</span>}
                          <p className="mt-1 italic truncate max-w-[120px]">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">{t.operator}</td>
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                          Henüz bir işlem kaydı bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0">
                {u.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-slate-800 truncate">{u.fullName}</p>
                <p className="text-sm text-slate-500 truncate">@{u.username} • {u.role}</p>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 p-2 transition-colors">
                <X size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();

    // Split by ;; and remove empty strings from ends if they exist
    const parts = cleanText.split(';;').filter(part => part.length > 0);

    /**
     * Parsing logic based on user request (Segments between ;;):
     * Index 0: Tedarikçi Firma
     * Index 1: Miktar
     * Index 2: Beden
     * Index 3: Adet (can be used as quantity if Index 1 is empty)
     * Index 4: Renk
     * Index 5: Özellik
     * Index 6: Ürün Kodu
     * Index 7: Ürün Adı (optional)
     */
    const parsed = {
      supplier: parts[0] || '',
      quantity: parseInt(parts[1]) || parseInt(parts[3]) || 1,
      size: parts[2] || '',
      color: parts[4] || '',
      feature: parts[5] || '',
      productCode: parts[6] || cleanText,
      name: parts[7] || parts[6] || 'Ürün ' + (parts[6] || 'Tanımsız')
    };

    setProductId(parsed.productCode || Math.random().toString(36).substr(2, 9));
    setProductCode(parsed.productCode);
    setProductName(parsed.name);
    setPartner(parsed.supplier);
    setSize(parsed.size);
    setColor(parsed.color);
    setFeature(parsed.feature);
    setQuantity(parsed.quantity);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla okundu ve ayrıştırıldı', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(1);
    setPartner('');
    setApprover('');
  };

  const handleTransaction = () => {
    if (!productCode || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === productId || p.productCode === productCode);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const key = tx.productId;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

