const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0">
                {u.fullName.charAt(0)}
