import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2 } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    // Tarayıcı örneğini oluştur
    const html5QrCode = new Html5Qrcode(scannerId);
    html5QrCodeRef.current = html5QrCode;

    const startScanner = async () => {
      try {
        setIsInitializing(true);
        // Önce kamera izinlerini ve mevcut kameraları kontrol et
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          const config = {
            fps: 15,
            qrbox: { width: 250, height: 250 },
          };

          await html5QrCode.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
              // Başarılı okuma
              onScan(decodedText);
              stopScanner();
            },
            (errorMessage) => {
              // Okuma hatası (genelde kod bulunamadığında sürekli tetiklenir, sessiz kalıyoruz)
            }
          );
          setPermissionError(null);
        } else {
          setPermissionError("Cihazınızda kamera bulunamadı.");
        }
      } catch (err: any) {
        console.error("Scanner error:", err);
        if (err.toString().includes("NotAllowedError") || err.toString().includes("Permission denied")) {
          setPermissionError("Kamera erişim izni reddedildi. Lütfen tarayıcı ayarlarından izin verin.");
        } else {
          setPermissionError("Kamera başlatılamadı. Lütfen sayfayı yenileyip tekrar deneyin.");
        }
      } finally {
        setIsInitializing(false);
      }
    };

    // DOM hazır olduktan sonra başlat
    const timer = setTimeout(() => startScanner(), 100);

    return () => {
      clearTimeout(timer);
      stopScanner();
    };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Stop error:", err);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
      <div className="bg-white w-full max-w-md rounded-3xl overflow-hidden shadow-2xl animate-fade-in border border-white/20">
        <div className="p-5 border-b flex justify-between items-center bg-slate-50/50">
          <div>
            <h3 className="font-bold text-xl text-slate-800">QR Tarayıcı</h3>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Kamera Bağlantısı</p>
          </div>
          <button 
            onClick={onClose}
            className="p-2 hover:bg-slate-200 text-slate-400 hover:text-slate-600 rounded-full transition-all"
          >
            <XCircle size={24} />
          </button>
        </div>

        <div className="p-6 min-h-[300px] flex flex-col items-center justify-center relative">
          {isInitializing && (
            <div className="absolute inset-0 z-10 bg-white flex flex-col items-center justify-center space-y-3">
              <Loader2 className="animate-spin text-indigo-600" size={40} />
              <p className="text-sm font-medium text-slate-500">Kamera hazırlanıyor...</p>
            </div>
          )}

          {permissionError ? (
            <div className="flex flex-col items-center justify-center text-center space-y-4 py-8">
              <div className="w-20 h-20 bg-rose-50 rounded-3xl flex items-center justify-center text-rose-500">
                <CameraOff size={40} />
              </div>
              <div className="space-y-2">
                <h4 className="font-bold text-slate-800">Erişim Engellendi</h4>
                <p className="text-slate-500 text-sm max-w-[250px]">
                  {permissionError}
                </p>
              </div>
              <button 
                onClick={onClose}
                className="px-6 py-2 bg-slate-900 text-white font-bold rounded-xl hover:bg-black transition-all"
              >
                Kapat
              </button>
            </div>
          ) : (
            <div className="w-full">
              <div 
                id={scannerId} 
                className="w-full rounded-2xl overflow-hidden border-2 border-slate-100 bg-slate-900 shadow-inner"
              ></div>

              {!isInitializing && (
                <div className="mt-6 flex flex-col items-center gap-3">
                  <div className="flex items-center gap-2 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-100">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                    Canlı Tarama Aktif
                  </div>
                  <p className="text-center text-xs text-slate-400 font-medium">
                    Ürün üzerindeki QR kodu karenin içine hizalayın
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="bg-slate-50 p-4 text-center border-t border-slate-100">
          <p className="text-[10px] text-slate-300 font-bold uppercase tracking-[0.2em]">
            SmartStock Optic Engine v3.0
          </p>
        </div>
      </div>
    </div>
  );
};

