              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                {permissionStatus === 'granted' ? 'Kamera Aktif' : 'İzin Bekleniyor'}
              </p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3 hover:bg-slate-200 text-slate-400 hover:text-slate-600 rounded-2xl transition-all active:scale-95"
