        </div>

        {/* Scanner Content Area */}
        <div className="p-8 min-h-[350px] flex flex-col items-center justify-center relative bg-white">

          {/* Permission Prompt View */}
          {permissionStatus === 'prompt' && !permissionError && (
            <div className="flex flex-col items-center justify-center text-center space-y-6 animate-fade-in">
              <div className="w-24 h-24 bg-indigo-50 rounded-[2rem] flex items-center justify-center text-indigo-600 shadow-inner">
