        {activeTab === 'history' && (
          <div className="space-y-6">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <button 
                onClick={() => {
                  const csvContent = "data:text/csv;charset=utf-8," 
                    + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                    + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                  const encodedUri = encodeURI(csvContent);
                  window.open(encodedUri);
                }}
                className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm transition-colors"
              >
                Excel'e Aktar
              </button>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Operatör</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-medium whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          {t.size && <span className="mr-2">Beden: {t.size}</span>}
                          {t.color && <span className="mr-2">Renk: {t.color}</span>}
                          <p className="mt-1 italic truncate max-w-[120px]">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">{t.operator}</td>
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                          Henüz bir işlem kaydı bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => {
            setShowAdd(true);
            setNewUsername('');
            setNewPass('');
            setNewName('');
          }}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
        >
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0">
                {u.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-slate-800 truncate">{u.fullName}</p>
                <p className="text-sm text-slate-500 truncate">@{u.username} • {u.role}</p>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 p-2 transition-colors">
                <X size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId);
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');

          const config = {
            fps: 15,
            qrbox: { width: 250, height: 250 },
          };

          await html5QrCode.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
              onScan(decodedText);
              stopScanner();
            },
            () => {
              // Sessiz okuma hataları
            }
          );
        } else {
          setPermissionError("Cihazınızda kamera bulunamadı.");
        }
      } catch (err: any) {
        console.error("Scanner error:", err);
        const errorStr = err.toString();

        if (errorStr.includes("NotAllowedError") || errorStr.includes("Permission denied")) {
          setPermissionStatus('denied');
          setPermissionError("Kamera erişim izni verilmedi. Lütfen tarayıcı ayarlarından kamerayı etkinleştirin.");
        } else {
          setPermissionError("Kamera başlatılırken bir sorun oluştu.");
        }
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();

    return () => {
      stopScanner();
    };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Stop error:", err);
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !html5QrCodeRef.current) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      const decodedText = await html5QrCodeRef.current.scanFile(file, true);
      onScan(decodedText);
      onClose();
    } catch (err) {
      console.error("File scan error:", err);
      setFileError("Seçilen görselde geçerli bir QR kod bulunamadı.");
      setTimeout(() => setFileError(null), 4000);
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/90 backdrop-blur-xl p-4">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in border border-white/20">

        {/* Header */}
        <div className="p-6 border-b flex justify-between items-center bg-slate-50/80">
          <div className="flex items-center gap-4">
            <button 
              onClick={onClose}
              className="p-2 hover:bg-slate-200 text-slate-600 rounded-xl transition-all active:scale-95 group"
              title="Geri Git"
            >
              <ArrowLeft size={22} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h3 className="font-bold text-xl text-slate-800 leading-none mb-1">QR Tarayıcı</h3>
              <div className="flex items-center gap-2">
                <span className={`w-1.5 h-1.5 rounded-full ${permissionStatus === 'granted' ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></span>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                  {permissionStatus === 'granted' ? 'Canlı Kamera' : 'Hazırlanıyor'}
                </p>
              </div>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all active:scale-95"
          >
            <XCircle size={24} />
          </button>
        </div>

        {/* Main Content Area */}
        <div className="p-6 min-h-[400px] flex flex-col items-center relative bg-white">

          {/* File Processing Overlay */}
          {isProcessingFile && (
            <div className="absolute inset-0 z-30 bg-white/90 backdrop-blur-sm flex flex-col items-center justify-center space-y-4">
              <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
              <p className="font-bold text-indigo-600">Görsel işleniyor...</p>
            </div>
          )}

          {/* Camera Scan Area */}
          <div className="w-full relative">
            {permissionStatus === 'prompt' && !permissionError && (
              <div className="flex flex-col items-center justify-center text-center space-y-6 py-10 animate-fade-in">
                <div className="w-24 h-24 bg-indigo-50 rounded-[2rem] flex items-center justify-center text-indigo-600 shadow-inner">
                  <Camera size={48} strokeWidth={1.5} className="animate-bounce" />
                </div>
                <div className="space-y-2">
                  <h4 className="text-lg font-bold text-slate-800">Kamera Erişimi</h4>
                  <p className="text-slate-500 text-sm max-w-[280px]">
                    Lütfen kamera iznini onaylayın veya dosyadan bir görsel seçin.
                  </p>
                </div>
              </div>
            )}

            {isInitializing && permissionStatus === 'granted' && (
              <div className="absolute inset-0 z-10 bg-slate-50 rounded-[2rem] flex flex-col items-center justify-center space-y-3">
                <Loader2 className="animate-spin text-indigo-600" size={32} />
                <p className="text-xs font-bold text-slate-400 uppercase">Hazırlanıyor</p>
              </div>
            )}

            {permissionError ? (
              <div className="flex flex-col items-center justify-center text-center space-y-5 py-8 animate-fade-in">
                <div className="w-20 h-20 bg-rose-50 rounded-[1.5rem] flex items-center justify-center text-rose-500">
                  <CameraOff size={40} />
                </div>
                <div className="space-y-2 px-4">
                  <h4 className="font-bold text-slate-800 text-lg">Kamera Devre Dışı</h4>
                  <p className="text-slate-500 text-sm leading-relaxed">
                    {permissionError}
                  </p>
                </div>
              </div>
            ) : (
              <div className={`transition-opacity duration-500 ${permissionStatus === 'granted' && !isInitializing ? 'opacity-100' : 'opacity-0'}`}>
                <div 
                  id={scannerId} 
                  className="w-full aspect-square rounded-[2rem] overflow-hidden border-4 border-slate-50 bg-black shadow-2xl relative"
                >
                  {permissionStatus === 'granted' && !isInitializing && (
                    <div className="absolute top-0 left-0 w-full h-full pointer-events-none z-10">
                      <div className="absolute top-[50%] left-[10%] right-[10%] h-[2px] bg-indigo-500 shadow-[0_0_15px_rgba(79,70,229,0.8)] animate-[scan_2s_infinite]"></div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* File Upload Section */}
          <div className="w-full mt-6 space-y-4">
            <div className="relative">
              <input 
                type="file" 
                ref={fileInputRef}
                onChange={handleFileUpload}
                accept="image/*"
                className="hidden"
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-center gap-3 py-4 bg-slate-100 text-slate-700 font-bold rounded-2xl hover:bg-slate-200 transition-all border-2 border-transparent hover:border-indigo-200 active:scale-[0.98]"
              >
                <ImageIcon size={20} className="text-indigo-600" />
                Dosyadan QR Yükle
              </button>
            </div>

            <button 
              onClick={onClose}
              className="w-full py-3 text-slate-400 font-semibold text-sm hover:text-slate-600 transition-colors"
            >
              Vazgeç ve Geri Dön
            </button>

            {fileError && (
              <div className="flex items-center gap-3 p-3 bg-rose-50 text-rose-600 rounded-xl text-xs font-bold border border-rose-100 animate-fade-in">
                <AlertCircle size={16} className="shrink-0" />
                {fileError}
              </div>
            )}
          </div>
        </div>

        {/* Footer Info */}
        <div className="bg-slate-50 p-5 text-center border-t border-slate-100">
          <p className="text-[10px] text-slate-300 font-bold uppercase tracking-[0.2em] flex items-center justify-center gap-2">
            <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
            SmartStock Optic Core v3.2
            <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
          </p>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { transform: translateY(-120px); }
          50% { transform: translateY(120px); }
        }
      `}</style>
    </div>
  );
};

export default Scanner;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock, QRPayload } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock,
  Bell,
  Settings
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  /**
   * Gelişmiş QR Çözümleme Mantığı
   * Hem JSON ("key":"value") hem de düz metin (Key: Value) formatlarını destekler.
   */
  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    // 1. JSON denemesi
    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        throw new Error("Not JSON");
      }
    } catch (e) {
      // 2. Regex ile anahtar-değer çiftlerini ayıklama
      // "anahtar":"değer", anahtar:değer, "anahtar":değer formatlarını yakalar
      const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
      let match;
      while ((match = regex.exec(cleanText)) !== null) {
        data[match[1]] = match[2].trim();
      }
    }

    // Eğer hiçbir çift bulunamadıysa ve metin varsa, metnin tamamını kod olarak al
    if (Object.keys(data).length === 0 && cleanText.length > 0) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    // Alan Eşleştirme Sözlüğü (Turkish/English mapping)
    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'ÜrünKodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'ÜrünAdı', 'Açıklama', 'description']);
    // Tedarikçi alanına "tedarikciFirma" ve Türkçe karakterli versiyonlar eklendi
    const extractedPartner = findInResult(['firma', 'partner', 'vendor', 'customer', 'tedarikci', 'tedarikciFirma', 'tedarikçi', 'tedarikçiFirma', 'alıcı', 'supplier', 'recipient']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount', 'stok']);
    const extractedSize = findInResult(['beden', 'size', 'ölçü', 'ebat']);
    const extractedColor = findInResult(['renk', 'color']);
    const extractedFeature = findInResult(['ozellik', 'feature', 'özellik', 'not', 'ekstra']);

    // State Güncelleme
    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));
    setPartner(extractedPartner || '');
    setQuantity(parseInt(extractedQty) || 1);
    setSize(extractedSize || '');
    setColor(extractedColor || '');
    setFeature(extractedFeature || '');
    setProductId(extractedCode || cleanText);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(1);
    setPartner('');
    setApprover('');
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    transactions.forEach(tx => {
      const key = tx.productId;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const lowStockProducts = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    });
  }, [inventory, thresholds]);

  const handleTransaction = () => {
    if (!productCode || quantity <= 0 || !partner || (activeTab === 'in' && !approver)) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const stock = inventory.find(p => p.productId === productId || p.productCode === productCode);
      if (!stock || stock.remaining < quantity) {
        showNotification('Yetersiz stok!', 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: activeTab === 'in' ? approver : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');

    // Check for low stock alert after transaction
    setTimeout(() => {
      const updatedInventory = StorageService.getTransactions().reduce((acc: any, tx) => {
        if (tx.productCode === productCode) acc.rem += (tx.type === TransactionType.IN ? tx.quantity : -tx.quantity);
        return acc;
      }, { rem: 0 });

      const threshold = thresholds[productCode] || 0;
      if (threshold > 0 && updatedInventory.rem <= threshold) {
        showNotification(`${productCode} kodlu ürün için stok kritik seviyenin altında (${updatedInventory.rem} adet)!`, 'warning');
      }
    }, 500);
  };

  const handleSaveThreshold = (code: string) => {
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Stok eşiği güncellendi.', 'success');
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : notification.type === 'warning' ? <Bell size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <header className="flex justify-between items-start">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Genel Bakış</h2>
                <p className="text-slate-500">Depo güncel durumu ve son hareketler.</p>
              </div>
              {lowStockProducts.length > 0 && (
                <div className="bg-amber-100 text-amber-800 px-4 py-2 rounded-xl flex items-center gap-2 font-bold animate-pulse">
                  <Bell size={18} />
                  <span>{lowStockProducts.length} Kritik Stok Uyarısı</span>
                </div>
              )}
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo' },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose' },
                { label: 'Aktif Stok Çeşidi', val: inventory.length, color: 'emerald' },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <p className="text-sm font-medium text-slate-500 mb-1">{card.label}</p>
                  <p className={`text-3xl font-bold text-slate-900`}>{card.val}</p>
                </div>
              ))}
            </div>

            {lowStockProducts.length > 0 && (
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-amber-200 bg-amber-50/30 overflow-hidden">
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-amber-500 text-white rounded-lg">
                    <Bell size={20} />
                  </div>
                  <h3 className="font-bold text-slate-800 uppercase tracking-wider text-sm">Kritik Stok Uyarıları</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {lowStockProducts.map(p => (
                    <div key={p.productId} className="bg-white border border-amber-200 p-4 rounded-xl flex justify-between items-center shadow-sm">
                      <div>
                        <p className="text-xs font-mono text-slate-400">{p.productCode}</p>
                        <p className="font-bold text-slate-800 truncate max-w-[120px]">{p.productName}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-black text-rose-500">{p.remaining}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Eşik: {thresholds[p.productCode]}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="font-bold mb-6 text-slate-700">Stok Dağılımı</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={inventory.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="productName" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="totalIn" name="Giriş" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="totalOut" name="Çıkış" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <h3 className="font-bold mb-4 text-slate-700">En Çok Kalan Ürünler & Eşik Ayarları</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead>
                      <tr className="text-slate-400 border-b">
                        <th className="pb-3 font-medium">Kod / Ürün</th>
                        <th className="pb-3 font-medium">Mevcut</th>
                        <th className="pb-3 font-medium text-right">Alt Limit</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {inventory.sort((a,b) => b.remaining - a.remaining).slice(0, 8).map((p, i) => (
                        <tr key={i} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4">
                            <p className="text-[10px] font-mono text-slate-400 leading-none">{p.productCode}</p>
                            <p className="font-semibold text-slate-800 truncate max-w-[150px]">{p.productName}</p>
                          </td>
                          <td className="py-4">
                            <span className={`font-bold ${thresholds[p.productCode] && p.remaining <= thresholds[p.productCode] ? 'text-rose-600' : 'text-slate-800'}`}>
                              {p.remaining}
                            </span>
                          </td>
                          <td className="py-4 text-right">
                            {editingThreshold === p.productCode ? (
                              <div className="flex items-center justify-end gap-2">
                                <input 
                                  type="number" 
                                  className="w-16 px-2 py-1 border rounded-lg text-xs outline-none focus:ring-1 focus:ring-indigo-500"
                                  value={tempThreshold}
                                  autoFocus
                                  onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                  onBlur={() => handleSaveThreshold(p.productCode)}
                                  onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(p.productCode)}
                                />
                              </div>
                            ) : (
                              <button 
                                onClick={() => {
                                  setEditingThreshold(p.productCode);
                                  setTempThreshold(thresholds[p.productCode] || 0);
                                }}
                                className="group flex items-center justify-end gap-1.5 ml-auto"
                              >
                                <span className="text-slate-400 group-hover:text-indigo-600 transition-colors font-medium">
                                  {thresholds[p.productCode] || 0}
                                </span>
                                <Settings size={14} className="text-slate-300 group-hover:text-indigo-600" />
                              </button>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-3xl mx-auto space-y-6">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">QR okutun, veriler otomatik dolsun.</p>
            </header>

            {!isFormActive ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">Kamera veya Dosya ile QR okutun</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in">
                <div className="flex justify-between items-center gap-4">
                  <h3 className="text-lg font-bold text-slate-800">İşlem Detayları</h3>
                  <div className="flex gap-2 shrink-0">
                    <button 
                      type="button"
                      onClick={toggleEdit}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all z-10 ${
                        isEditable ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {isEditable ? <Unlock size={14} /> : <Lock size={14} />}
                      {isEditable ? 'Düzenleme Açık' : 'Düzenlemek için Tıkla'}
                    </button>
                    <button onClick={resetForm} className="text-indigo-600 text-sm font-medium hover:underline p-1.5">
                      Yeniden Tara
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Kodu</label>
                    <input 
                      type="text" 
                      value={productCode}
                      disabled={!isEditable}
                      onChange={(e) => setProductCode(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500 font-mono font-bold"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Adı</label>
                    <input 
                      type="text" 
                      value={productName}
                      disabled={!isEditable}
                      onChange={(e) => setProductName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      disabled={!isEditable}
                      onChange={(e) => setPartner(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Miktar</label>
                      <input 
                        type="number" 
                        value={quantity}
                        min="1"
                        onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Beden</label>
                      <input 
                        type="text" 
                        value={size}
                        disabled={!isEditable}
                        onChange={(e) => setSize(e.target.value)}
