                    <h4 className="font-bold text-slate-700">Ürün Hareket Geçmişi</h4>
                    <span className="text-xs font-bold text-slate-400">{productDetailData?.transactions.length} Kayıt</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                      <thead>
                        <tr className="bg-slate-50 text-slate-500 text-xs font-black uppercase">
                          <th className="px-6 py-4">Tarih</th>
