                  <div>
                    <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Onaylayan Kişi (Zorunlu)</label>
                    <div className="relative">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-indigo-400">
                        <UserCheck size={18} />
                      </div>
                      <input 
                        type="text" 
                        value={approver}
                        onChange={(e) => setApprover(e.target.value)}
                        className="w-full px-4 py-3 pl-11 bg-white border border-indigo-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold text-slate-800 placeholder:text-slate-300 shadow-sm"
                        placeholder="Yönetici adı giriniz..."
                      />
                    </div>
                  </div>
                </div>

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all transform hover:scale-[1.01] active:scale-[0.98] ${
                    activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-100 hover:bg-indigo-700' : 'bg-rose-500 shadow-rose-100 hover:bg-rose-600'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Onayla & Kaydet' : 'Stok Çıkışını Onayla & Kaydet'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6 animate-fade-in">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <div className="flex gap-3">
                {user.role === UserRole.ADMIN && transactions.length > 0 && (
                  <button 
                    onClick={handleClearAllHistory}
                    className="px-4 py-2 bg-rose-50 border border-rose-200 rounded-xl text-rose-600 font-bold hover:bg-rose-100 shadow-sm transition-colors flex items-center gap-2"
                  >
                    <Trash2 size={18} />
                    Tüm Geçmişi Temizle
                  </button>
                )}
                <button 
                  onClick={() => {
                    const csvContent = "data:text/csv;charset=utf-8," 
                      + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                      + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                    const encodedUri = encodeURI(csvContent);
                    window.open(encodedUri);
                  }}
                  className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm transition-colors"
                >
                  Excel'e Aktar
                </button>
              </div>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Onaylayan</th>
                      {user.role === UserRole.ADMIN && <th className="px-6 py-4 font-semibold text-right">İşlem</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap text-xs">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-black uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type === TransactionType.IN ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1 uppercase tracking-wider">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-black whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          <div className="flex flex-wrap gap-1 mb-1">
                            {t.size && <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px]">Beden: {t.size}</span>}
                            {t.color && <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px]">Renk: {t.color}</span>}
                          </div>
                          <p className="italic truncate max-w-[120px] font-medium text-indigo-600">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">
                          <div className="flex items-center gap-2">
                            <div className="p-1.5 bg-slate-100 text-indigo-600 rounded-lg">
                              <UserCheck size={14} />
                            </div>
                            <span className="font-semibold text-slate-700">{t.approver}</span>
                          </div>
                        </td>
                        {user.role === UserRole.ADMIN && (
                          <td className="px-6 py-4 text-right">
                            <button 
                              onClick={() => handleDeleteTransaction(t.id)}
                              className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                              title="Kaydı Sil"
                            >
                              <Trash2 size={16} />
                            </button>
                          </td>
                        )}
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={user.role === UserRole.ADMIN ? 7 : 6} className="px-6 py-20 text-center text-slate-400">
                          <div className="flex flex-col items-center gap-3">
                            <History size={48} className="opacity-10" />
                            <p className="font-bold">Henüz bir işlem kaydı bulunmuyor.</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const handleAdd = () => {
    if (!newUsername || !newPass || !newName) return;
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(newUser);
    setUsers(StorageService.getUsers());
    setShowAdd(false);
    setNewUsername(''); setNewPass(''); setNewName('');
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz? Bu işlem kullanıcının geçmişte yaptığı işlem kayıtlarını SİLMEZ.')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => {
            setShowAdd(true);
            setNewUsername('');
            setNewPass('');
            setNewName('');
          }}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2"
        >
          <Users size={18} />
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">Yeni Personel Tanımla</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleAdd} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">Kaydet</button>
            <button onClick={() => setShowAdd(false)} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between group hover:shadow-md transition-shadow">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0 group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                {u.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-slate-800 truncate">{u.fullName}</p>
                <div className="flex items-center gap-2">
                  <p className="text-sm text-slate-500 truncate">@{u.username}</p>
                  <span className={`text-[10px] font-black uppercase px-1.5 py-0.5 rounded ${u.role === UserRole.ADMIN ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>
                    {u.role}
                  </span>
                </div>
              </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => handleDelete(u.id)} className="text-slate-300 hover:text-red-600 p-2 transition-colors">
                <Trash2 size={20} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

