import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Dashboard States
  const [dashboardSearch, setDashboardSearch] = useState('');
  const [selectedProductCode, setSelectedProductCode] = useState<string | null>(null);
  const [detailFilters, setDetailFilters] = useState({
    size: '',
    color: '',
    feature: ''
  });

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Envanter hesaplama
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const sortedTxs = [...transactions].reverse();

    sortedTxs.forEach(tx => {
      const key = tx.productCode;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Seçili Ürün Detay Analizi için Veriler
  const productDetailData = useMemo(() => {
    if (!selectedProductCode) return null;

    const productTxs = transactions.filter(t => t.productCode === selectedProductCode);
    const productInfo = inventory.find(i => i.productCode === selectedProductCode);

    // Dinamik filtre seçenekleri
    const sizes = Array.from(new Set(productTxs.map(t => t.size).filter(Boolean)));
    const colors = Array.from(new Set(productTxs.map(t => t.color).filter(Boolean)));
    const features = Array.from(new Set(productTxs.map(t => t.feature).filter(Boolean)));

    // Filtreleri uygula
    const filteredTxs = productTxs.filter(t => {
      return (!detailFilters.size || t.size === detailFilters.size) &&
             (!detailFilters.color || t.color === detailFilters.color) &&
             (!detailFilters.feature || t.feature === detailFilters.feature);
    });

    const stats = filteredTxs.reduce((acc, curr) => {
      if (curr.type === TransactionType.IN) acc.in += curr.quantity;
      else acc.out += curr.quantity;
      return acc;
    }, { in: 0, out: 0 });

    return {
      info: productInfo,
      transactions: filteredTxs,
      filterOptions: { sizes, colors, features },
      stats: { ...stats, remaining: stats.in - stats.out }
    };
  }, [selectedProductCode, transactions, inventory, detailFilters]);

  // Arama filtresi uygulanmış envanter (Dashboard listesi için)
  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  // Mevcut ürünün stok durumunu bul (Formlar için)
  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        throw new Error("Not JSON");
      }
    } catch (e) {
      const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
      let match;
      while ((match = regex.exec(cleanText)) !== null) {
        data[match[1]] = match[2].trim();
      }
    }

    if (Object.keys(data).length === 0 && cleanText.length > 0) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'ÜrünKodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'ÜrünAdı', 'Açıklama', 'description']);
    const extractedPartner = findInResult(['firma', 'partner', 'vendor', 'customer', 'tedarikci', 'tedarikciFirma', 'tedarikçi', 'tedarikçiFirma', 'alıcı', 'supplier', 'recipient']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount', 'stok']);
    const extractedSize = findInResult(['beden', 'size', 'ölçü', 'ebat']);
    const extractedColor = findInResult(['renk', 'color']);
    const extractedFeature = findInResult(['ozellik', 'feature', 'özellik', 'not', 'ekstra']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));

    if (activeTab === 'out') {
      setPartner('');
      setQuantity('');
    } else {
      setPartner(extractedPartner || '');
      setQuantity(parseInt(extractedQty) || 1);
    }

    setSize(extractedSize || '');
    setColor(extractedColor || '');
    setFeature(extractedFeature || '');
    setProductId(extractedCode || cleanText);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(activeTab === 'in' ? 1 : '');
    setPartner('');
    setApprover('');
  };

  const lowStockProducts = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    });
  }, [inventory, thresholds]);

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;

    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları (Onaylayan dahil) doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('Bu işlem kaydını silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem kaydı silindi.', 'success');
    }
  };

  const handleClearAllHistory = () => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('TÜM işlem geçmişini kalıcı olarak silmek üzeresiniz. Bu işlem geri alınamaz. Onaylıyor musunuz?')) {
      StorageService.clearAllTransactions();
      setTransactions([]);
      showNotification('Tüm geçmiş temizlendi.', 'warning');
    }
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Stok eşiği güncellendi.', 'success');
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : notification.type === 'warning' ? <Bell size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Depo Analiz Paneli</h2>
                <p className="text-slate-500">Stoklarınızı kategorize edin ve anlık izleyin.</p>
              </div>
              <div className="flex items-center gap-3">
                {!selectedProductCode && (
                  <div className="relative">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text"
                      placeholder="Ürün veya Kod Ara..."
                      value={dashboardSearch}
                      onChange={(e) => setDashboardSearch(e.target.value)}
                      className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 w-full md:w-64 shadow-sm text-sm"
                    />
                  </div>
                )}
                {lowStockProducts.length > 0 && !selectedProductCode && (
                  <div className="bg-amber-100 text-amber-800 px-4 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-sm border border-amber-200 animate-pulse">
                    <Bell size={18} />
                    <span className="hidden sm:inline">Kritik Stok:</span> {lowStockProducts.length}
                  </div>
                )}
                {selectedProductCode && (
                  <button 
                    onClick={() => { setSelectedProductCode(null); setDetailFilters({size:'',color:'',feature:''}); }}
                    className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-700 transition-all shadow-lg"
                  >
                    <ArrowLeft size={18} />
                    Analizi Kapat
                  </button>
                )}
              </div>
            </header>

            {!selectedProductCode ? (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  {[
                    { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo', icon: TrendingUp },
                    { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose', icon: TrendingDown },
                    { label: 'Mevcut Stok Adeti', val: inventory.reduce((a,b)=>a+b.remaining,0), color: 'emerald', icon: Calculator },
                    { label: 'Aktif Ürün Çeşidi', val: inventory.length, color: 'amber', icon: Layers },
                  ].map((card, i) => (
                    <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
                      <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{card.label}</p>
                        <p className="text-3xl font-black text-slate-900">{card.val.toLocaleString()}</p>
                      </div>
                      <div className={`p-3 rounded-2xl bg-${card.color}-50 text-${card.color}-600`}>
                        <card.icon size={24} />
                      </div>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col">
                    <h3 className="font-bold mb-6 text-slate-700 flex items-center gap-2">
                      <TrendingUp size={20} className="text-indigo-600" />
                      Stok Hacim Grafiği (Top 5)
                    </h3>
                    <div className="flex-1 min-h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={inventory.slice(0, 5)} layout="vertical">
                          <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                          <XAxis type="number" hide />
                          <YAxis dataKey="productName" type="category" width={100} fontSize={12} stroke="#64748b" />
                          <Tooltip 
                            cursor={{fill: '#f8fafc'}}
                            contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                          />
                          <Bar dataKey="remaining" name="Mevcut Stok" fill="#4f46e5" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                      <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Layers size={20} className="text-indigo-600" />
                        Güncel Stok & Eşik Ayarları
                      </h3>
                      <span className="text-xs font-bold text-slate-400 bg-white px-3 py-1 rounded-full border border-slate-100">
                        Ürüne Tıklayarak Analizi Başlatın
                      </span>
                    </div>
                    <div className="overflow-x-auto max-h-[500px] overflow-y-auto">
                      <table className="w-full text-sm text-left">
                        <thead className="sticky top-0 bg-white shadow-sm z-10">
                          <tr className="text-slate-400 border-b">
                            <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                            <th className="px-6 py-4 font-semibold text-center">Durum</th>
                            <th className="px-6 py-4 font-semibold">Mevcut</th>
                            <th className="px-6 py-4 font-semibold">Alt Limit</th>
                            <th className="px-6 py-4 font-semibold text-right">İşlem</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                          {filteredInventory.map((p) => {
                            const threshold = thresholds[p.productCode] || 0;
                            const isCritical = threshold > 0 && p.remaining <= threshold;

                            return (
                              <tr 
                                key={p.productCode} 
                                onClick={() => setSelectedProductCode(p.productCode)}
                                className="hover:bg-indigo-50/30 cursor-pointer transition-colors group"
                              >
                                <td className="px-6 py-4">
                                  <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${isCritical ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} />
                                    <div>
                                      <p className="text-[10px] font-mono font-bold text-slate-400 leading-none mb-1 group-hover:text-indigo-600 transition-colors uppercase tracking-wider">{p.productCode}</p>
                                      <p className="font-bold text-slate-800 truncate max-w-[180px]">{p.productName}</p>
                                    </div>
                                  </div>
                                </td>
                                <td className="px-6 py-4 text-center">
                                  {isCritical ? (
                                    <span className="px-2 py-1 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-lg border border-rose-100">Kritik</span>
                                  ) : (
                                    <span className="px-2 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase rounded-lg border border-emerald-100">Normal</span>
                                  )}
                                </td>
                                <td className="px-6 py-4">
                                  <span className={`text-base font-black ${isCritical ? 'text-rose-600' : 'text-slate-900'}`}>
                                    {p.remaining.toLocaleString()}
                                  </span>
                                </td>
                                <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                                  {editingThreshold === p.productCode && user?.role === UserRole.ADMIN ? (
                                    <input 
                                      type="number" 
                                      autoFocus
                                      className="w-20 px-2 py-1.5 border-2 border-indigo-500 rounded-lg text-xs outline-none"
                                      value={tempThreshold}
                                      onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                      onBlur={() => handleSaveThreshold(p.productCode)}
                                      onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(p.productCode)}
                                    />
                                  ) : (
                                    <div className="flex items-center gap-2">
                                      <span className="text-slate-500 font-bold">{thresholds[p.productCode] || 0}</span>
                                      {user?.role === UserRole.ADMIN && (
                                        <button 
                                          onClick={() => {
                                            setEditingThreshold(p.productCode);
                                            setTempThreshold(thresholds[p.productCode] || 0);
                                          }}
                                          className="p-1 hover:bg-indigo-50 text-slate-300 hover:text-indigo-600 rounded-md transition-colors"
                                        >
                                          <Settings size={14} />
                                        </button>
                                      )}
                                    </div>
                                  )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                  <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-600 transition-colors ml-auto" />
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="space-y-6 animate-fade-in">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-indigo-100">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                    <div className="flex items-center gap-5">
                      <div className="w-16 h-16 rounded-3xl bg-indigo-600 flex items-center justify-center text-white shadow-lg shadow-indigo-200">
                        <Layers size={32} />
                      </div>
                      <div>
                        <p className="text-xs font-black text-indigo-500 uppercase tracking-widest leading-none mb-1">
                          {productDetailData?.info?.productCode}
                        </p>
                        <h3 className="text-3xl font-black text-slate-800 leading-tight">
                          {productDetailData?.info?.productName}
                        </h3>
                      </div>
                    </div>

                    <div className="flex gap-4">
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 min-w-[120px]">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Filtreli Stok</p>
                        <p className="text-2xl font-black text-indigo-600">{productDetailData?.stats.remaining}</p>
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 min-w-[120px]">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Giriş/Çıkış</p>
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-bold text-emerald-600">+{productDetailData?.stats.in}</span>
                          <span className="text-xs font-bold text-rose-600">-{productDetailData?.stats.out}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 p-4 bg-slate-50 rounded-3xl border border-slate-100">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-1 flex items-center gap-1">
                        <Filter size={10} /> Beden Filtresi
                      </label>
                      <select 
                        value={detailFilters.size}
                        onChange={(e) => setDetailFilters(prev => ({...prev, size: e.target.value}))}
                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold"
                      >
                        <option value="">Tüm Bedenler</option>
                        {productDetailData?.filterOptions.sizes.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-1 flex items-center gap-1">
                        <Filter size={10} /> Renk Filtresi
                      </label>
                      <select 
                        value={detailFilters.color}
                        onChange={(e) => setDetailFilters(prev => ({...prev, color: e.target.value}))}
                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold"
                      >
                        <option value="">Tüm Renkler</option>
                        {productDetailData?.filterOptions.colors.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-1 flex items-center gap-1">
                        <Filter size={10} /> Özellik Filtresi
                      </label>
                      <select 
                        value={detailFilters.feature}
                        onChange={(e) => setDetailFilters(prev => ({...prev, feature: e.target.value}))}
                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold"
                      >
                        <option value="">Tüm Özellikler</option>
                        {productDetailData?.filterOptions.features.map(f => <option key={f} value={f}>{f}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                  <div className="p-6 border-b flex justify-between items-center">
                    <h4 className="font-bold text-slate-700">Ürün Hareket Geçmişi</h4>
                    <span className="text-xs font-bold text-slate-400">{productDetailData?.transactions.length} Kayıt</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                      <thead>
                        <tr className="bg-slate-50 text-slate-500 text-xs font-black uppercase">
                          <th className="px-6 py-4">Tarih</th>
                          <th className="px-6 py-4">Tip</th>
                          <th className="px-6 py-4">Miktar</th>
                          <th className="px-6 py-4">Varyant</th>
                          <th className="px-6 py-4">Partner</th>
                          <th className="px-6 py-4 text-right">Onaylayan</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {productDetailData?.transactions.map(t => (
                          <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                            <td className="px-6 py-4 whitespace-nowrap text-xs">{t.date}</td>
                            <td className="px-6 py-4">
                              <span className={`px-2 py-0.5 rounded-md text-[10px] font-black uppercase ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                {t.type}
                              </span>
                            </td>
                            <td className="px-6 py-4 font-black">{t.quantity}</td>
                            <td className="px-6 py-4 text-xs">
                              <div className="flex flex-wrap gap-1">
                                {t.size && <span className="bg-slate-100 px-1.5 py-0.5 rounded">{t.size}</span>}
                                {t.color && <span className="bg-slate-100 px-1.5 py-0.5 rounded">{t.color}</span>}
                                {t.feature && <span className="bg-slate-100 px-1.5 py-0.5 rounded">{t.feature}</span>}
                              </div>
                            </td>
                            <td className="px-6 py-4 italic font-medium text-slate-500">{t.supplier || t.recipient}</td>
                            <td className="px-6 py-4 text-right font-medium text-slate-700">{t.approver}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out') && (
          <div className="max-w-3xl mx-auto space-y-6 animate-fade-in">
            <header className="text-center">
              <h2 className="text-3xl font-bold text-slate-800">
                {activeTab === 'in' ? 'Mal Kabul (Stok Girişi)' : 'Depo Çıkış (Sevkiyat)'}
              </h2>
              <p className="text-slate-500">QR okutun, veriler otomatik dolsun.</p>
            </header>

            {!isFormActive ? (
              <div 
                onClick={() => setIsScannerOpen(true)}
                className="bg-white border-2 border-dashed border-indigo-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group shadow-sm"
              >
                <div className="w-20 h-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
                  <Search size={40} />
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-slate-700">Taramaya Başla</p>
                  <p className="text-slate-400">Kamera veya Dosya ile QR okutun</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 space-y-6 animate-fade-in">
                {productCode && (
                  <div className={`p-4 rounded-2xl flex items-center justify-between border ${activeTab === 'out' ? 'bg-rose-50 border-rose-100' : 'bg-indigo-50 border-indigo-100'}`}>
                    <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-xl ${activeTab === 'out' ? 'bg-rose-500' : 'bg-indigo-500'} text-white`}>
                        <Calculator size={20} />
                      </div>
                      <div>
                        <p className="text-xs font-bold text-slate-500 uppercase">Mevcut Stok Miktarı</p>
                        <p className={`text-xl font-black ${activeTab === 'out' ? 'text-rose-600' : 'text-indigo-600'}`}>
                          {currentProductStock?.remaining || 0} Adet
                        </p>
                      </div>
                    </div>
                    {activeTab === 'out' && (
                      <div className="text-right">
                        <p className="text-xs font-bold text-slate-500 uppercase">İşlem Sonrası Kalan</p>
                        <p className="text-xl font-black text-slate-700">
                          {Math.max(0, (currentProductStock?.remaining || 0) - (quantity === '' ? 0 : quantity))} Adet
                        </p>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex justify-between items-center gap-4">
                  <h3 className="text-lg font-bold text-slate-800">İşlem Detayları</h3>
                  <div className="flex gap-2 shrink-0">
                    <button 
                      type="button"
                      onClick={toggleEdit}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all z-10 ${
                        isEditable ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {isEditable ? <Unlock size={14} /> : <Lock size={14} />}
                      {isEditable ? 'Düzenleme Açık' : 'Düzenlemek için Tıkla'}
                    </button>
                    <button onClick={resetForm} className="text-indigo-600 text-sm font-medium hover:underline p-1.5">
                      Yeniden Tara
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Kodu</label>
                    <input 
                      type="text" 
                      value={productCode}
                      disabled={!isEditable}
                      onChange={(e) => setProductCode(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500 font-mono font-bold uppercase"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Ürün Adı</label>
                    <input 
                      type="text" 
                      value={productName}
                      disabled={!isEditable}
                      onChange={(e) => setProductName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">
                      {activeTab === 'in' ? 'Tedarikçi Firma' : 'Alıcı / Departman'}
                    </label>
                    <input 
                      type="text" 
                      value={partner}
                      disabled={activeTab === 'in' ? !isEditable : false}
                      onChange={(e) => setPartner(e.target.value)}
                      placeholder={activeTab === 'out' ? "Alıcı bilgisi giriniz..." : ""}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">İşlem Adeti</label>
                      <input 
                        type="number" 
                        value={quantity}
                        min="1"
                        onChange={(e) => setQuantity(e.target.value === '' ? '' : parseInt(e.target.value) || 0)}
                        placeholder="Miktar..."
                        className={`w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 font-bold ${activeTab === 'out' && quantity !== '' && (currentProductStock?.remaining || 0) < quantity ? 'border-rose-500 ring-rose-200 ring-2' : 'focus:ring-indigo-500'}`}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Beden</label>
                      <input 
                        type="text" 
                        value={size}
                        disabled={!isEditable}
                        onChange={(e) => setSize(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Renk</label>
                    <input 
                      type="text" 
                      value={color}
                      disabled={!isEditable}
                      onChange={(e) => setColor(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-1">Özellik</label>
                    <input 
                      type="text" 
                      value={feature}
                      disabled={!isEditable}
                      onChange={(e) => setFeature(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50 border rounded-xl disabled:opacity-70 disabled:bg-slate-100 disabled:cursor-not-allowed outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                  <div>
                    <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">İşlemi Yapan Personel</label>
                    <div className="flex items-center gap-3 px-4 py-3 bg-white border border-indigo-100 rounded-xl">
                      <div className="w-8 h-8 rounded-full bg-indigo-600 flex items-center justify-center text-white text-xs font-bold">
                        {user.fullName.charAt(0)}
                      </div>
                      <span className="font-bold text-slate-700">{user.fullName}</span>
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Onaylayan Kişi (Zorunlu)</label>
                    <div className="relative">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-indigo-400">
                        <UserCheck size={18} />
                      </div>
                      <input 
                        type="text" 
                        value={approver}
                        onChange={(e) => setApprover(e.target.value)}
                        className="w-full px-4 py-3 pl-11 bg-white border border-indigo-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold text-slate-800 placeholder:text-slate-300 shadow-sm"
                        placeholder="Yönetici adı giriniz..."
                      />
                    </div>
                  </div>
                </div>

                <button 
                  onClick={handleTransaction}
                  className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all transform hover:scale-[1.01] active:scale-[0.98] ${
                    activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-100 hover:bg-indigo-700' : 'bg-rose-500 shadow-rose-100 hover:bg-rose-600'
                  }`}
                >
                  {activeTab === 'in' ? 'Stok Girişini Onayla & Kaydet' : 'Stok Çıkışını Onayla & Kaydet'}
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6 animate-fade-in">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">İşlem Geçmişi</h2>
                <p className="text-slate-500">Tüm hareketlerin dökümü.</p>
              </div>
              <div className="flex gap-3">
                {user.role === UserRole.ADMIN && transactions.length > 0 && (
                  <button 
                    onClick={handleClearAllHistory}
                    className="px-4 py-2 bg-rose-50 border border-rose-200 rounded-xl text-rose-600 font-bold hover:bg-rose-100 shadow-sm transition-colors flex items-center gap-2"
                  >
                    <Trash2 size={18} />
                    Tüm Geçmişi Temizle
                  </button>
                )}
                <button 
                  onClick={() => {
                    const csvContent = "data:text/csv;charset=utf-8," 
                      + "Tarih,Tip,Kod,Ürün,Miktar,Beden,Renk,Özellik,Firma,İşlem Yapan,Onaylayan\n"
                      + transactions.map(t => `${t.date},${t.type},${t.productCode},${t.productName},${t.quantity},${t.size||''},${t.color||''},${t.feature||''},${t.supplier || t.recipient},${t.operator},${t.approver || ''}`).join("\n");
                    const encodedUri = encodeURI(csvContent);
                    window.open(encodedUri);
                  }}
                  className="px-4 py-2 bg-white border rounded-xl text-slate-600 font-medium hover:bg-slate-50 shadow-sm transition-colors"
                >
                  Excel'e Aktar
                </button>
              </div>
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 uppercase text-xs tracking-wider">
                      <th className="px-6 py-4 font-semibold">Tarih</th>
                      <th className="px-6 py-4 font-semibold">Tür</th>
                      <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                      <th className="px-6 py-4 font-semibold">Miktar</th>
                      <th className="px-6 py-4 font-semibold">Detaylar</th>
                      <th className="px-6 py-4 font-semibold">Onaylayan</th>
                      {user.role === UserRole.ADMIN && <th className="px-6 py-4 font-semibold text-right">İşlem</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {transactions.map((t) => (
                      <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                        <td className="px-6 py-4 text-slate-600 whitespace-nowrap text-xs">{t.date}</td>
                        <td className="px-6 py-4">
                          <span className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-black uppercase ${
                            t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                          }`}>
                            {t.type === TransactionType.IN ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                            {t.type}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                           <p className="font-mono text-[10px] text-slate-400 leading-none mb-1 uppercase tracking-wider">{t.productCode}</p>
                           <p className="font-bold text-slate-800 truncate max-w-[150px]">{t.productName}</p>
                        </td>
                        <td className="px-6 py-4 font-black whitespace-nowrap">{t.quantity} Adet</td>
                        <td className="px-6 py-4 text-xs text-slate-500">
                          <div className="flex flex-wrap gap-1 mb-1">
                            {t.size && <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px]">Beden: {t.size}</span>}
                            {t.color && <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px]">Renk: {t.color}</span>}
                          </div>
                          <p className="italic truncate max-w-[120px] font-medium text-indigo-600">{t.supplier || t.recipient}</p>
                        </td>
                        <td className="px-6 py-4 text-slate-500 whitespace-nowrap">
                          <div className="flex items-center gap-2">
                            <div className="p-1.5 bg-slate-100 text-indigo-600 rounded-lg">
                              <UserCheck size={14} />
                            </div>
                            <span className="font-semibold text-slate-700">{t.approver}</span>
                          </div>
                        </td>
                        {user.role === UserRole.ADMIN && (
                          <td className="px-6 py-4 text-right">
                            <button 
                              onClick={() => handleDeleteTransaction(t.id)}
                              className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                              title="Kaydı Sil"
                            >
                              <Trash2 size={16} />
                            </button>
                          </td>
                        )}
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={user.role === UserRole.ADMIN ? 7 : 6} className="px-6 py-20 text-center text-slate-400">
                          <div className="flex flex-col items-center gap-3">
                            <History size={48} className="opacity-10" />
                            <p className="font-bold">Henüz bir işlem kaydı bulunmuyor.</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const resetForm = () => {
    setShowAdd(false);
    setEditingUser(null);
    setNewUsername('');
    setNewPass('');
    setNewName('');
    setNewRole(UserRole.USER);
  };

  const handleEditClick = (user: User) => {
    setEditingUser(user);
    setNewName(user.fullName);
    setNewUsername(user.username);
    setNewPass(user.password || '');
    setNewRole(user.role);
    setShowAdd(true);
  };

  const handleSave = () => {
    if (!newUsername || !newPass || !newName) return;

    const userData: User = {
      id: editingUser ? editingUser.id : Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };

    StorageService.saveUser(userData);
    setUsers(StorageService.getUsers());
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz? Bu işlem kullanıcının geçmişte yaptığı işlem kayıtlarını SİLMEZ.')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => {
            resetForm();
            setShowAdd(true);
          }}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2"
        >
          <Users size={18} />
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">{editingUser ? 'Kullanıcı Bilgilerini Güncelle' : 'Yeni Personel Tanımla'}</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium">
              <option value={UserRole.USER}>Standart Kullanıcı</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleSave} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors">
              {editingUser ? 'Güncelle' : 'Kaydet'}
            </button>
            <button onClick={resetForm} className="bg-slate-200 text-slate-600 px-6 py-2 rounded-xl font-bold hover:bg-slate-300 transition-colors">Vazgeç</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between group hover:shadow-md transition-shadow relative overflow-hidden">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xl shrink-0 group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                {u.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-slate-800 truncate">{u.fullName}</p>
                <div className="flex items-center gap-2">
                  <p className="text-sm text-slate-500 truncate">@{u.username}</p>
                  <span className={`text-[10px] font-black uppercase px-1.5 py-0.5 rounded ${u.role === UserRole.ADMIN ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>
                    {u.role}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-1">
               <button 
                  onClick={() => handleEditClick(u)}
                  className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  title="Düzenle"
                >
                  <Edit2 size={18} />
                </button>
                {u.username !== 'admin' && (
                  <button 
                    onClick={() => handleDelete(u.id)} 
                    className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
                    title="Sil"
                  >
                    <Trash2 size={18} />
                  </button>
                )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock,
  Bell,
  Settings,
  TrendingUp,
  TrendingDown,
  Calculator,
  Layers,
  Calendar,
  Filter,
  ArrowLeft,
  ChevronRight,
  UserCheck,
  Trash2,
  Edit2,
  User as UserIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'in' | 'out' | 'history' | 'users'>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Dashboard States
  const [dashboardSearch, setDashboardSearch] = useState('');
  const [selectedProductCode, setSelectedProductCode] = useState<string | null>(null);
  const [detailFilters, setDetailFilters] = useState({
    size: '',
    color: '',
    feature: ''
  });

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Envanter hesaplama
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const sortedTxs = [...transactions].reverse();

    sortedTxs.forEach(tx => {
      const key = tx.productCode;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Seçili Ürün Detay Analizi için Veriler
  const productDetailData = useMemo(() => {
    if (!selectedProductCode) return null;

    const productTxs = transactions.filter(t => t.productCode === selectedProductCode);
    const productInfo = inventory.find(i => i.productCode === selectedProductCode);

    // Dinamik filtre seçenekleri
    const sizes = Array.from(new Set(productTxs.map(t => t.size).filter(Boolean)));
    const colors = Array.from(new Set(productTxs.map(t => t.color).filter(Boolean)));
    const features = Array.from(new Set(productTxs.map(t => t.feature).filter(Boolean)));

    // Filtreleri uygula
    const filteredTxs = productTxs.filter(t => {
      return (!detailFilters.size || t.size === detailFilters.size) &&
             (!detailFilters.color || t.color === detailFilters.color) &&
             (!detailFilters.feature || t.feature === detailFilters.feature);
    });

    const stats = filteredTxs.reduce((acc, curr) => {
      if (curr.type === TransactionType.IN) acc.in += curr.quantity;
      else acc.out += curr.quantity;
      return acc;
    }, { in: 0, out: 0 });

    return {
      info: productInfo,
      transactions: filteredTxs,
      filterOptions: { sizes, colors, features },
      stats: { ...stats, remaining: stats.in - stats.out }
    };
  }, [selectedProductCode, transactions, inventory, detailFilters]);

  // Arama filtresi uygulanmış envanter (Dashboard listesi için)
  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  // Mevcut ürünün stok durumunu bul (Formlar için)
  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        throw new Error("Not JSON");
      }
    } catch (e) {
      const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
      let match;
      while ((match = regex.exec(cleanText)) !== null) {
        data[match[1]] = match[2].trim();
      }
    }

    if (Object.keys(data).length === 0 && cleanText.length > 0) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'ÜrünKodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'ÜrünAdı', 'Açıklama', 'description']);
    const extractedPartner = findInResult(['firma', 'partner', 'vendor', 'customer', 'tedarikci', 'tedarikciFirma', 'tedarikçi', 'tedarikçiFirma', 'alıcı', 'supplier', 'recipient']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount', 'stok']);
    const extractedSize = findInResult(['beden', 'size', 'ölçü', 'ebat']);
    const extractedColor = findInResult(['renk', 'color']);
    const extractedFeature = findInResult(['ozellik', 'feature', 'özellik', 'not', 'ekstra']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));

    if (activeTab === 'out') {
      setPartner('');
      setQuantity('');
    } else {
      setPartner(extractedPartner || '');
      setQuantity(parseInt(extractedQty) || 1);
    }

    setSize(extractedSize || '');
    setColor(extractedColor || '');
    setFeature(extractedFeature || '');
    setProductId(extractedCode || cleanText);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(activeTab === 'in' ? 1 : '');
    setPartner('');
    setApprover('');
  };

  const lowStockProducts = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    });
  }, [inventory, thresholds]);

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;

    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları (Onaylayan dahil) doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('Bu işlem kaydını silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem kaydı silindi.', 'success');
    }
  };

  const handleClearAllHistory = () => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('TÜM işlem geçmişini kalıcı olarak silmek üzeresiniz. Bu işlem geri alınamaz. Onaylıyor musunuz?')) {
      StorageService.clearAllTransactions();
      setTransactions([]);
      showNotification('Tüm geçmiş temizlendi.', 'warning');
    }
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Stok eşiği güncellendi.', 'success');
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock Pro
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : notification.type === 'warning' ? <Bell size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Depo Analiz Paneli</h2>
                <p className="text-slate-500">Stoklarınızı kategorize edin ve anlık izleyin.</p>
              </div>
              <div className="flex items-center gap-3">
                {!selectedProductCode && (
                  <div className="relative">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text"
                      placeholder="Ürün veya Kod Ara..."
                      value={dashboardSearch}
                      onChange={(e) => setDashboardSearch(e.target.value)}
                      className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 w-full md:w-64 shadow-sm text-sm"
                    />
                  </div>
                )}
                {lowStockProducts.length > 0 && !selectedProductCode && (
                  <div className="bg-amber-100 text-amber-800 px-4 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-sm border border-amber-200 animate-pulse">
                    <Bell size={18} />
                    <span className="hidden sm:inline">Kritik Stok:</span> {lowStockProducts.length}
                  </div>
                )}
                {selectedProductCode && (
                  <button 
                    onClick={() => { setSelectedProductCode(null); setDetailFilters({size:'',color:'',feature:''}); }}
                    className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-700 transition-all shadow-lg"
                  >
                    <ArrowLeft size={18} />
                    Analizi Kapat
                  </button>
                )}
              </div>
            </header>

            {!selectedProductCode ? (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  {[
                    { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo', icon: TrendingUp },
                    { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose', icon: TrendingDown },
                    { label: 'Mevcut Stok Adeti', val: inventory.reduce((a,b)=>a+b.remaining,0), color: 'emerald', icon: Calculator },
                    { label: 'Aktif Ürün Çeşidi', val: inventory.length, color: 'amber', icon: Layers },
                  ].map((card, i) => (
                    <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
                      <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{card.label}</p>
                        <p className="text-3xl font-black text-slate-900">{card.val.toLocaleString()}</p>
                      </div>
                      <div className={`p-3 rounded-2xl bg-${card.color}-50 text-${card.color}-600`}>
                        <card.icon size={24} />
                      </div>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col">
                    <h3 className="font-bold mb-6 text-slate-700 flex items-center gap-2">
                      <TrendingUp size={20} className="text-indigo-600" />
                      Stok Hacim Grafiği (Top 5)
                    </h3>
                    <div className="flex-1 min-h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={inventory.slice(0, 5)} layout="vertical">
                          <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                          <XAxis type="number" hide />
                          <YAxis dataKey="productName" type="category" width={100} fontSize={12} stroke="#64748b" />
                          <Tooltip 
                            cursor={{fill: '#f8fafc'}}
                            contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                          />
                          <Bar dataKey="remaining" name="Mevcut Stok" fill="#4f46e5" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                      <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Layers size={20} className="text-indigo-600" />
                        Güncel Stok & Eşik Ayarları
                      </h3>
                      <span className="text-xs font-bold text-slate-400 bg-white px-3 py-1 rounded-full border border-slate-100">
                        Ürüne Tıklayarak Analizi Başlatın
                      </span>
                    </div>
                    <div className="overflow-x-auto max-h-[500px] overflow-y-auto">
                      <table className="w-full text-sm text-left">
                        <thead className="sticky top-0 bg-white shadow-sm z-10">
                          <tr className="text-slate-400 border-b">
                            <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                            <th className="px-6 py-4 font-semibold text-center">Durum</th>
                            <th className="px-6 py-4 font-semibold">Mevcut</th>
                            <th className="px-6 py-4 font-semibold">Alt Limit</th>
                            <th className="px-6 py-4 font-semibold text-right">İşlem</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
