                        {user.role === UserRole.ADMIN && (
                          <td className="px-6 py-4 text-right">
                            <button 
                              onClick={() => handleDeleteTransaction(t.id)}
                              className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                              title="Kaydı Sil"
                            >
                              <Trash2 size={16} />
                            </button>
                          </td>
                        )}
                      </tr>
                    ))}
                    {transactions.length === 0 && (
                      <tr>
                        <td colSpan={user.role === UserRole.ADMIN ? 7 : 6} className="px-6 py-20 text-center text-slate-400">
                          <div className="flex flex-col items-center gap-3">
                            <History size={48} className="opacity-10" />
                            <p className="font-bold">Henüz bir işlem kaydı bulunmuyor.</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

