import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft, ImagePlus } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId);
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');

          const config = {
            fps: 15,
            qrbox: { width: 250, height: 250 },
          };

          await html5QrCode.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
              onScan(decodedText);
              stopScanner();
            },
            () => {
              // Sessiz okuma hataları
            }
          );
        } else {
          setPermissionStatus('denied');
          setPermissionError("Cihazınızda aktif bir kamera bulunamadı.");
        }
      } catch (err: any) {
        console.error("Scanner error:", err);
        const errorStr = err.toString();

        if (errorStr.includes("NotAllowedError") || errorStr.includes("Permission denied")) {
          setPermissionStatus('denied');
          setPermissionError("Kamera erişim izni verilmedi. Lütfen tarayıcı ayarlarından kamerayı etkinleştirin veya galeriden görsel seçin.");
        } else {
          setPermissionError("Kamera başlatılırken bir sorun oluştu.");
        }
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();

    return () => {
      stopScanner();
    };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Stop error:", err);
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !html5QrCodeRef.current) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      // Eğer kamera açıksa dosya yüklemeden önce durdurulabilir ancak 
      // kütüphane dosya tarama işlemini bağımsız yapabilir.
      const decodedText = await html5QrCodeRef.current.scanFile(file, true);
      onScan(decodedText);
      // Başarılı taramadan sonra modalı kapatıyoruz
    } catch (err) {
      console.error("File scan error:", err);
      setFileError("Seçilen görselde geçerli bir QR kod bulunamadı. Lütfen daha net bir görsel deneyin.");
      setTimeout(() => setFileError(null), 4000);
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/95 backdrop-blur-md p-4">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in border border-white/20">

        {/* Header */}
        <div className="p-6 border-b flex justify-between items-center bg-slate-50/80">
          <div className="flex items-center gap-4">
            <button 
              onClick={onClose}
              className="p-2 hover:bg-slate-200 text-slate-600 rounded-xl transition-all active:scale-95 group"
              title="Kapat"
            >
              <ArrowLeft size={22} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h3 className="font-bold text-xl text-slate-800 leading-none mb-1">QR Kod Okut</h3>
              <div className="flex items-center gap-2">
                <span className={`w-1.5 h-1.5 rounded-full ${permissionStatus === 'granted' && !isInitializing ? 'bg-emerald-500 animate-pulse' : 'bg-slate-300'}`}></span>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                  {permissionStatus === 'granted' && !isInitializing ? 'Kamera Aktif' : 'Hazırlanıyor'}
                </p>
              </div>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all active:scale-95"
          >
            <XCircle size={24} />
          </button>
        </div>

        {/* Main Content Area */}
        <div className="p-6 min-h-[400px] flex flex-col items-center relative bg-white">

          {/* File Processing Overlay */}
          {isProcessingFile && (
            <div className="absolute inset-0 z-30 bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center space-y-4">
              <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
              <div className="text-center">
                <p className="font-black text-indigo-600">Görsel Çözümleniyor</p>
                <p className="text-xs text-slate-400">Lütfen bekleyin...</p>
              </div>
            </div>
          )}

          {/* Camera Scan Area */}
          <div className="w-full relative">
            {permissionStatus === 'prompt' && !permissionError && (
              <div className="flex flex-col items-center justify-center text-center space-y-6 py-10 animate-fade-in">
                <div className="w-24 h-24 bg-indigo-50 rounded-[2rem] flex items-center justify-center text-indigo-600 shadow-inner">
                  <Camera size={48} strokeWidth={1.5} className="animate-bounce" />
                </div>
                <div className="space-y-2">
                  <h4 className="text-lg font-bold text-slate-800">Kamera Bekleniyor</h4>
                  <p className="text-slate-500 text-sm max-w-[280px]">
                    Lütfen kamera iznini onaylayın veya galeriden bir QR kod görseli seçin.
                  </p>
                </div>
              </div>
            )}

            {isInitializing && permissionStatus === 'granted' && (
              <div className="absolute inset-0 z-10 bg-slate-50 rounded-[2rem] flex flex-col items-center justify-center space-y-3 min-h-[250px]">
                <Loader2 className="animate-spin text-indigo-600" size={32} />
                <p className="text-xs font-bold text-slate-400 uppercase">Kamera Modülü Yükleniyor</p>
              </div>
            )}

            {permissionError ? (
              <div className="flex flex-col items-center justify-center text-center space-y-5 py-8 animate-fade-in bg-slate-50 rounded-[2rem] border border-dashed border-slate-200">
                <div className="w-16 h-16 bg-rose-50 rounded-[1.2rem] flex items-center justify-center text-rose-500">
                  <CameraOff size={32} />
                </div>
                <div className="space-y-2 px-6">
                  <h4 className="font-bold text-slate-800">Kamera Kullanılamıyor</h4>
                  <p className="text-slate-500 text-xs leading-relaxed">
                    {permissionError}
                  </p>
                </div>
              </div>
            ) : (
              <div className={`transition-opacity duration-500 ${permissionStatus === 'granted' && !isInitializing ? 'opacity-100' : 'opacity-0'}`}>
                <div 
                  id={scannerId} 
                  className="w-full aspect-square rounded-[2rem] overflow-hidden border-4 border-slate-50 bg-black shadow-xl relative"
                >
                  {permissionStatus === 'granted' && !isInitializing && (
                    <div className="absolute top-0 left-0 w-full h-full pointer-events-none z-10">
                      <div className="absolute top-[50%] left-[10%] right-[10%] h-[2px] bg-indigo-500 shadow-[0_0_15px_rgba(79,70,229,0.8)] animate-[scan_2s_infinite]"></div>
                      <div className="absolute top-[10%] bottom-[10%] left-[10%] right-[10%] border-2 border-white/20 rounded-2xl"></div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* File Upload Section */}
          <div className="w-full mt-8 space-y-4">
            <div className="relative">
              <input 
                type="file" 
                ref={fileInputRef}
                onChange={handleFileUpload}
                accept="image/*"
                className="hidden"
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex flex-col items-center justify-center gap-2 py-6 bg-indigo-50 text-indigo-700 font-bold rounded-3xl hover:bg-indigo-100 transition-all border-2 border-dashed border-indigo-200 hover:border-indigo-400 active:scale-[0.98] group"
              >
                <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform">
                   <ImagePlus size={24} className="text-indigo-600" />
                </div>
                <span className="text-sm">Galeriden QR Kod Seç</span>
              </button>
            </div>

            {fileError && (
              <div className="flex items-center gap-3 p-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-bold border border-rose-100 animate-fade-in">
                <AlertCircle size={18} className="shrink-0" />
