import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft, ImagePlus, CheckCircle2 } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');

          const config = {
            fps: 20,
            qrbox: { width: 260, height: 260 },
            aspectRatio: 1.0,
            videoConstraints: {
              facingMode: "environment",
              focusMode: "continuous" as any
            }
          };

          await html5QrCode.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
              onScan(decodedText);
              stopScanner();
            },
            () => {
              // Sessiz tarama
            }
          );
        } else {
          setPermissionStatus('denied');
          setPermissionError("Cihazınızda aktif bir kamera bulunamadı.");
        }
      } catch (err: any) {
        console.error("Scanner error:", err);
        const errorStr = err.toString();

        if (errorStr.includes("NotAllowedError") || errorStr.includes("Permission denied")) {
          setPermissionStatus('denied');
          setPermissionError("Kamera erişim izni verilmedi. Lütfen tarayıcı ayarlarından kamerayı etkinleştirin veya galeriden görsel seçin.");
        } else {
          setPermissionError("Kamera sistemi başlatılamadı. Galeriden seçim yapabilirsiniz.");
        }
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();

    return () => {
      stopScanner();
    };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Stop error:", err);
      }
    }
  };

  /**
   * Görseli optimize ederek okuma başarısını artıran yardımcı fonksiyon
   */
  const processAndScan = async (file: File) => {
    if (!html5QrCodeRef.current) return;

    return new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const img = new Image();
        img.onload = async () => {
          try {
            // Görsel çok büyükse (modern telefonlar gibi 12MP+), 
            // tarayıcının daha iyi odaklanması için makul bir boyuta çekiyoruz.
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 1200;
            const MAX_HEIGHT = 1200;
            let width = img.width;
            let height = img.height;

            if (width > height) {
              if (width > MAX_WIDTH) {
                height *= MAX_WIDTH / width;
                width = MAX_WIDTH;
              }
            } else {
              if (height > MAX_HEIGHT) {
                width *= MAX_HEIGHT / height;
                height = MAX_HEIGHT;
              }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, 0, 0, width, height);

              // Canvas üzerinden tarama yapmayı deniyoruz
              // html5-qrcode'un scanFile metodu File veya Blob alabilir.
              canvas.toBlob(async (blob) => {
                if (blob) {
                  const processedFile = new File([blob], "processed.jpg", { type: "image/jpeg" });
                  try {
                    const decodedText = await html5QrCodeRef.current!.scanFile(processedFile, false);
                    resolve(decodedText);
                  } catch (err) {
                    // Eğer boyutlandırma yetmediyse orijinali son kez deniyoruz
                    try {
                        const originalDecoded = await html5QrCodeRef.current!.scanFile(file, false);
                        resolve(originalDecoded);
                    } catch (finalErr) {
                        reject(finalErr);
                    }
                  }
                } else {
                  reject("Görsel işlenemedi.");
                }
              }, 'image/jpeg', 0.95);
            }
          } catch (err) {
            reject(err);
          }
        };
        img.onerror = () => reject("Görsel yüklenemedi.");
        img.src = e.target?.result as string;
      };
      reader.onerror = () => reject("Dosya okunamadı.");
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      const decodedText = await processAndScan(file);
      onScan(decodedText);
      await stopScanner();
    } catch (err) {
      console.error("Scan error:", err);
      setFileError("Görselde QR kod tespit edilemedi. Lütfen daha yakından ve net bir fotoğraf seçin.");
      setTimeout(() => setFileError(null), 5000);
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl p-4">
      <div className="bg-white w-full max-w-md rounded-[3rem] overflow-hidden shadow-2xl animate-fade-in border border-white/20">

        {/* Modern Header */}
        <div className="p-8 pb-4 flex justify-between items-start">
