import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft, ImagePlus } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);
  const [processingStep, setProcessingStep] = useState<string>('');

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');

          const config = {
            fps: 20,
            qrbox: { width: 280, height: 280 },
            aspectRatio: 1.0,
            videoConstraints: {
              facingMode: "environment",
              focusMode: "continuous" as any
            }
          };

          await html5QrCode.start(
            { facingMode: "environment" },
            config,
            (decodedText) => {
              onScan(decodedText);
              stopScanner();
            },
            () => { /* Sessiz hata */ }
          );
        } else {
          setPermissionStatus('denied');
          setPermissionError("Cihazınızda kamera bulunamadı.");
        }
      } catch (err: any) {
        setPermissionStatus('denied');
        setPermissionError("Kamera başlatılamadı. Galeriden dosya seçebilirsiniz.");
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();

    return () => {
      stopScanner();
    };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Stop error:", err);
      }
    }
  };

  /**
   * Gelismiş Görüntü İşleme ve QR Arama Motoru
   */
  const advancedScan = async (file: File): Promise<string> => {
    if (!html5QrCodeRef.current) throw new Error("Tarayıcı motoru hazır değil.");

    // AŞAMA 1: Doğrudan Dosyayı Tara (Hızlı Deneme)
    try {
      setProcessingStep('Orijinal dosya taranıyor...');
      return await html5QrCodeRef.current.scanFile(file, false);
    } catch (e) {
      console.log("Aşama 1 başarısız, görüntü işleme başlıyor...");
    }

    // AŞAMA 2: Görüntü İyileştirme (Gri Tonlama + Kontrast)
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = async () => {
          try {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d', { willReadFrequently: true });
            if (!ctx) throw new Error("Canvas context hatası");

            // Akıllı Ölçeklendirme (Tarayıcı için en ideal boyutlar: 800-1000px)
            const MAX_DIM = 1000;
            let width = img.width;
            let height = img.height;
            if (width > height) {
              if (width > MAX_DIM) {
                height *= MAX_DIM / width;
                width = MAX_DIM;
              }
            } else {
              if (height > MAX_DIM) {
                width *= MAX_DIM / height;
                height = MAX_DIM;
              }
            }

            canvas.width = width;
            canvas.height = height;

            // AŞAMA 2.1: Gri Tonlama ve Keskinleştirme
            setProcessingStep('Görüntü netleştiriliyor...');
            ctx.filter = 'grayscale(100%) contrast(150%) brightness(110%)';
            ctx.drawImage(img, 0, 0, width, height);

            canvas.toBlob(async (blob) => {
              if (!blob) return reject("Blob oluşturulamadı");
              const processedFile = new File([blob], "scan.jpg", { type: "image/jpeg" });

              try {
                const result = await html5QrCodeRef.current!.scanFile(processedFile, false);
                resolve(result);
              } catch (err) {
                // AŞAMA 2.2: Negatif Tarama (Beyaz zeminli olmayan kodlar için)
                setProcessingStep('Alternatif modlar deneniyor...');
                ctx.filter = 'invert(100%) grayscale(100%) contrast(150%)';
                ctx.drawImage(img, 0, 0, width, height);

                canvas.toBlob(async (negBlob) => {
                  if (!negBlob) return reject("Negatif blob hatası");
                  const negFile = new File([negBlob], "neg.jpg", { type: "image/jpeg" });
                  try {
                    const result = await html5QrCodeRef.current!.scanFile(negFile, false);
                    resolve(result);
                  } catch (finalErr) {
                    reject("QR kod tespit edilemedi.");
                  }
                }, 'image/jpeg', 0.9);
              }
            }, 'image/jpeg', 0.9);
          } catch (err) {
            reject(err);
          }
        };
        img.src = e.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      const decodedText = await advancedScan(file);
      onScan(decodedText);
      await stopScanner();
    } catch (err) {
      setFileError("Görselde QR kod bulunamadı. Lütfen kodu daha yakından, düz ve net şekilde çekip tekrar deneyin.");
      setTimeout(() => setFileError(null), 6000);
    } finally {
      setIsProcessingFile(false);
      setProcessingStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/95 backdrop-blur-2xl p-4">
      <div className="bg-white w-full max-w-md rounded-[3rem] overflow-hidden shadow-[0_0_50px_rgba(0,0,0,0.3)] animate-fade-in border border-white/10">

        {/* Header */}
        <div className="p-8 pb-4 flex justify-between items-start">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">QR Tarayıcı</h3>
            <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Gelişmiş Vizyon Sistemi</p>
          </div>
          <button 
            onClick={onClose}
            className="p-3 bg-slate-100 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all active:scale-90"
          >
            <XCircle size={24} />
          </button>
        </div>

        {/* Content Area */}
        <div className="p-8 pt-4 flex flex-col items-center relative">

          {/* Enhanced Loader Overlay */}
          {isProcessingFile && (
            <div className="absolute inset-0 z-50 bg-white/95 backdrop-blur-md flex flex-col items-center justify-center space-y-6 animate-fade-in">
              <div className="relative">
                 <div className="w-24 h-24 border-[6px] border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                 <ImagePlus className="absolute inset-0 m-auto text-indigo-600 animate-pulse" size={32} />
              </div>
              <div className="text-center space-y-2">
                <p className="font-black text-slate-800 text-xl">Analiz Ediliyor</p>
                <p className="text-sm text-indigo-500 font-bold uppercase tracking-widest animate-pulse">
                  {processingStep || 'Yapay zeka taranıyor...'}
                </p>
              </div>
            </div>
          )}

          <div className="w-full relative">
            {/* Camera Loading/Init */}
            {(isInitializing || permissionStatus === 'prompt') && !permissionError && (
              <div className="flex flex-col items-center justify-center text-center space-y-6 py-14 bg-slate-50 rounded-[3rem] border-2 border-dashed border-slate-200">
                <Camera size={48} className="text-indigo-200 animate-bounce" />
                <p className="text-slate-400 text-sm font-medium px-10">Kamera sistemi hazırlanıyor...</p>
              </div>
            )}

            {/* Error Message */}
            {permissionError && !isProcessingFile && (
              <div className="flex flex-col items-center justify-center text-center space-y-5 py-10 bg-rose-50 rounded-[3rem] border border-rose-100">
                <CameraOff size={40} className="text-rose-400" />
                <p className="text-rose-700 text-xs font-bold px-8 leading-relaxed">
                  {permissionError}
                </p>
              </div>
            )}

            {/* Active Live Scanner */}
            <div className={`transition-all duration-500 ${permissionStatus === 'granted' && !isInitializing ? 'opacity-100 scale-100' : 'opacity-0 scale-95 h-0 overflow-hidden'}`}>
              <div 
                id={scannerId} 
                className="w-full aspect-square rounded-[3rem] overflow-hidden border-8 border-white bg-slate-900 shadow-2xl relative"
              >
                {/* Visual Overlays */}
                <div className="absolute inset-0 pointer-events-none z-10 border-[1.5rem] border-black/20">
                   <div className="absolute top-0 left-0 w-full h-[2px] bg-indigo-500 shadow-[0_0_20px_#6366f1] animate-[scan_2.5s_infinite]"></div>
                   <div className="absolute inset-10 border-2 border-white/30 rounded-3xl"></div>
                </div>
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="w-full mt-10 space-y-4">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*"
              className="hidden"
            />

            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full flex items-center justify-between p-3 pl-8 bg-slate-900 text-white rounded-[2.5rem] hover:bg-slate-800 transition-all active:scale-[0.98] shadow-2xl group"
            >
              <div className="flex items-center gap-4">
                <ImageIcon size={22} className="text-indigo-400" />
                <span className="font-black text-sm tracking-tight">Galeriden Görsel Seç</span>
              </div>
              <div className="bg-indigo-600 p-4 rounded-full group-hover:rotate-12 transition-transform">
                 <ImagePlus size={22} />
              </div>
            </button>

            {fileError && (
              <div className="flex items-start gap-3 p-5 bg-rose-50 text-rose-700 rounded-3xl text-xs font-bold border border-rose-100 animate-fade-in">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p>{fileError}</p>
              </div>
            )}

            <div className="flex justify-center pt-2">
               <button 
                onClick={onClose}
                className="px-10 py-3 text-slate-400 hover:text-rose-500 font-black text-[10px] uppercase tracking-[0.3em] transition-colors"
              >
                Kapat
              </button>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0% { transform: translateY(0); opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { transform: translateY(100%); opacity: 0; }
        }
        #qr-reader-core video {
          object-fit: cover !important;
          width: 100% !important;
          height: 100% !important;
        }
        #qr-reader-core { border: none !important; }
      `}</style>
    </div>
  );
};

