import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft, ImagePlus } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);
  const [processingStep, setProcessingStep] = useState<string>('');

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');
          const config = {
            fps: 20,
            qrbox: { width: 280, height: 280 },
            aspectRatio: 1.0,
            videoConstraints: { facingMode: "environment" }
          };
          await html5QrCode.start({ facingMode: "environment" }, config, (text) => {
            onScan(text);
            stopScanner();
          }, () => {});
        } else {
          setPermissionStatus('denied');
          setPermissionError("Kamera bulunamadı.");
        }
      } catch (err: any) {
        setPermissionStatus('denied');
        setPermissionError("Kamera hazır değil. Galeriden devam edebilirsiniz.");
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();
    return () => { stopScanner(); };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current?.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) { console.warn(err); }
    }
  };

  /**
   * Hibrit Vizyon Motoru: Görselden QR okumayı garantiler
   */
  const advancedScan = async (file: File): Promise<string> => {
    if (!html5QrCodeRef.current) throw new Error("Motor hazır değil.");

    // 1. ADIM: Native Browser Barcode Detector (Modern tarayıcılar için en iyisi)
    // @ts-ignore
    if ('BarcodeDetector' in window && BarcodeDetector.getSupportedFormats) {
      try {
        setProcessingStep('Donanım hızlandırmalı tarama...');
        // @ts-ignore
        const detector = new BarcodeDetector({ formats: ['qr_code'] });
        const bitmap = await createImageBitmap(file);
        const barcodes = await detector.detect(bitmap);
        if (barcodes.length > 0) return barcodes[0].rawValue;
      } catch (e) { console.log("Native tarama başarısız."); }
    }

    // 2. ADIM: Standart Motor ile Hızlı Deneme
    try {
      setProcessingStep('Hızlı tarama yapılıyor...');
      return await html5QrCodeRef.current.scanFile(file, false);
    } catch (e) { /* Devam et */ }

    // 3. ADIM: Çoklu Çözünürlük ve Filtreleme (Canvas İşleme)
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = async () => {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d', { willReadFrequently: true });
          if (!ctx) return reject("Canvas hatası");

          // Farklı çözünürlük ve filtre kombinasyonlarını dene
          const scanAttempts = [
            { size: 1200, filter: 'grayscale(100%) contrast(150%)', label: 'Netleştiriliyor...' },
            { size: 800, filter: 'contrast(200%) brightness(110%)', label: 'Derin analiz...' },
            { size: img.width, filter: 'invert(100%) grayscale(100%)', label: 'Negatif mod deneniyor...' }
          ];

          for (const attempt of scanAttempts) {
            try {
              setProcessingStep(attempt.label);
              let w = img.width;
              let h = img.height;
              if (w > attempt.size) {
                h *= attempt.size / w;
                w = attempt.size;
              }

              canvas.width = w;
              canvas.height = h;
              ctx.filter = attempt.filter;
              ctx.drawImage(img, 0, 0, w, h);

              const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
              if (blob) {
                const tempFile = new File([blob], "scan.jpg", { type: "image/jpeg" });
                const result = await html5QrCodeRef.current!.scanFile(tempFile, false);
                return resolve(result);
              }
            } catch (err) { /* Bu deneme başarısız, bir sonrakine geç */ }
          }
          reject("QR kod bulunamadı.");
        };
        img.src = e.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      const decodedText = await advancedScan(file);
      onScan(decodedText);
      onClose(); // Başarılı olunca kapat
    } catch (err) {
      setFileError("QR kod okunamadı. Lütfen görselin net olduğundan ve QR kodun tamamının göründüğünden emin olun.");
      setTimeout(() => setFileError(null), 5000);
    } finally {
