import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, CameraOff, XCircle, Loader2, Camera, Image as ImageIcon, ArrowLeft, ImagePlus, CheckCircle2 } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [permissionError, setPermissionError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);
  const [processingStep, setProcessingStep] = useState<string>('');

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-core";

  useEffect(() => {
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    const initScanner = async () => {
      try {
        setIsInitializing(true);
        const devices = await Html5Qrcode.getCameras();

        if (devices && devices.length > 0) {
          setPermissionStatus('granted');
          const config = {
            fps: 24,
            qrbox: { width: 280, height: 280 },
            aspectRatio: 1.0,
            videoConstraints: { 
              facingMode: "environment",
              focusMode: "continuous" as any 
            }
          };
          await html5QrCode.start({ facingMode: "environment" }, config, (text) => {
            onScan(text);
            stopScanner();
          }, () => {});
        } else {
          setPermissionStatus('denied');
          setPermissionError("Kamera bulunamadı.");
        }
      } catch (err: any) {
        setPermissionStatus('denied');
        setPermissionError("Kamera hazır değil. Galeriden devam edebilirsiniz.");
      } finally {
        setIsInitializing(false);
      }
    };

    initScanner();
    return () => { stopScanner(); };
  }, []);

  const stopScanner = async () => {
    if (html5QrCodeRef.current?.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) { console.warn(err); }
    }
  };

  /**
   * Ultra Gelişmiş Vizyon Motoru
   * Her türlü zorlu görselden (bulanık, karanlık, düşük çözünürlüklü) QR kod çıkarmaya odaklanır.
   */
  const advancedScan = async (file: File): Promise<string> => {
    if (!html5QrCodeRef.current) throw new Error("Motor hazır değil.");

    // 1. ADIM: Donanım Hızlandırmalı Native Barcode Detector
    // @ts-ignore
    if ('BarcodeDetector' in window) {
      try {
        setProcessingStep('GPU tabanlı tarama...');
        // @ts-ignore
        const detector = new BarcodeDetector({ formats: ['qr_code'] });
        const bitmap = await createImageBitmap(file);
        const barcodes = await detector.detect(bitmap);
        if (barcodes.length > 0) return barcodes[0].rawValue;
      } catch (e) { console.log("Native tarama atlandı."); }
    }

    // 2. ADIM: Orijinal Dosya Üzerinde Hızlı Deneme
    try {
      setProcessingStep('Hızlı tarama...');
      return await html5QrCodeRef.current.scanFile(file, false);
    } catch (e) { /* Başarısız ise derin işlemeye geç */ }

    // 3. ADIM: Derin Görüntü İşleme Hattı (Deep Image Processing Pipeline)
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = async () => {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d', { willReadFrequently: true });
          if (!ctx) return reject("Görsel işleme hatası");

          /**
           * Farklı ışık, odak ve çözünürlük senaryoları için filtre setleri
           */
          const scanAttempts = [
            // Klasik Kontrast - Genelde yeterlidir
            { size: 1000, filter: 'grayscale(100%) contrast(180%) brightness(110%)', label: 'Netlik artırılıyor...' },
            // Binarizasyon Simülasyonu - Bulanık kodlar için pikselleri belirginleştirir
            { size: 800, filter: 'grayscale(100%) contrast(1000%)', label: 'Pikseller ayrıştırılıyor...' },
            // Düşük Işık Modu - Karanlık çekimler için
            { size: 1000, filter: 'grayscale(100%) brightness(160%) contrast(150%)', label: 'Işık dengeleniyor...' },
            // Negatif Mod - Beyaz üzerine siyah olmayan QR'lar için
            { size: 1000, filter: 'invert(100%) grayscale(100%) contrast(200%)', label: 'Renkler tersine çevriliyor...' },
            // Yüksek Çözünürlüklü Tarama - Çok küçük QR kodları için
            { size: 1600, filter: 'grayscale(100%) contrast(140%) blur(0px)', label: 'Mikro detay analizi...' },
            // Gürültü Azaltma Modu - Grenli fotoğraflar için
            { size: 600, filter: 'grayscale(100%) contrast(120%)', label: 'Gürültü temizleniyor...' }
          ];

          for (const attempt of scanAttempts) {
            try {
              setProcessingStep(attempt.label);

              let w = img.width;
              let h = img.height;
              const scale = attempt.size / Math.max(w, h);

              if (scale < 1 || attempt.size > 1200) {
                w *= scale;
                h *= scale;
              }

              canvas.width = w;
              canvas.height = h;

              // CSS filtreleri uygulayarak görüntüyü iyileştir
              ctx.filter = attempt.filter;
              ctx.drawImage(img, 0, 0, w, h);

              // Canvas'tan yeni bir blob oluştur ve tarat
              const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
              if (blob) {
                const tempFile = new File([blob], "scan_optimized.jpg", { type: "image/jpeg" });
                const result = await html5QrCodeRef.current!.scanFile(tempFile, false);
                return resolve(result);
              }
            } catch (err) {
              // Bu filtre kombinasyonu sonuç vermedi, bir sonrakine geç
              continue;
            }
          }

          reject("Görselden kod okunamadı.");
        };
        img.src = e.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      const decodedText = await advancedScan(file);
      onScan(decodedText);
      // Başarılı olduğunda modalı hemen kapatmak yerine bir anlık başarı gösterilebilir
      // ama şu anki akışta onScan modalı kapatıyor olabilir.
    } catch (err) {
      setFileError("Görselde geçerli bir QR kod bulunamadı. Lütfen daha net, düz ve yakından çekilmiş bir fotoğraf deneyin.");
      setTimeout(() => setFileError(null), 6000);
    } finally {
      setIsProcessingFile(false);
      setProcessingStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/95 backdrop-blur-2xl p-4">
      <div className="bg-white w-full max-w-md rounded-[3rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.5)] animate-fade-in border border-white/20">

        {/* Header */}
        <div className="p-8 pb-4 flex justify-between items-start">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">QR Vizyon</h3>
            <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Akıllı Çözümleme Hattı</p>
          </div>
          <button 
            onClick={onClose}
            className="p-3 bg-slate-100 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all shadow-sm"
          >
            <XCircle size={24} />
          </button>
        </div>

        {/* Action Area */}
        <div className="p-8 pt-4 flex flex-col items-center relative">

          {/* Analysis Overlay */}
          {isProcessingFile && (
            <div className="absolute inset-0 z-50 bg-white/98 backdrop-blur-xl flex flex-col items-center justify-center space-y-8 animate-fade-in">
              <div className="relative">
                 <div className="w-28 h-28 border-[6px] border-indigo-50 border-t-indigo-600 rounded-full animate-spin shadow-inner"></div>
                 <div className="absolute inset-0 flex items-center justify-center">
                    <ImagePlus className="text-indigo-600 animate-pulse" size={32} />
                 </div>
              </div>
              <div className="text-center space-y-3 px-8">
                <p className="font-black text-slate-800 text-2xl">Pikseller İşleniyor</p>
                <div className="flex flex-col gap-1">
                  <p className="text-sm text-indigo-500 font-bold uppercase tracking-[0.15em] animate-pulse">
                    {processingStep || 'Motor başlatılıyor...'}
                  </p>
                  <div className="w-full bg-slate-100 h-1 rounded-full overflow-hidden mt-2">
                    <div className="h-full bg-indigo-500 animate-[loading_2s_infinite]"></div>
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="w-full relative">
            {/* Live Camera View */}
            <div className={`transition-all duration-700 ${permissionStatus === 'granted' && !isInitializing ? 'opacity-100 scale-100' : 'opacity-0 scale-95 h-0 overflow-hidden'}`}>
              <div 
                id={scannerId} 
                className="w-full aspect-square rounded-[3rem] overflow-hidden border-8 border-white bg-slate-900 shadow-2xl relative ring-2 ring-slate-100"
              >
                <div className="absolute inset-0 pointer-events-none z-10">
                   <div className="absolute top-0 left-0 w-full h-[3px] bg-gradient-to-r from-transparent via-indigo-500 to-transparent shadow-[0_0_25px_#6366f1] animate-[scan_3s_infinite]"></div>
                   <div className="absolute inset-16 border-2 border-white/20 rounded-[2.5rem] shadow-[0_0_0_100vw_rgba(0,0,0,0.3)]"></div>
                   <div className="absolute inset-16 flex items-center justify-center">
                      <div className="w-8 h-8 border-t-4 border-l-4 border-white/50 absolute top-0 left-0 rounded-tl-2xl"></div>
                      <div className="w-8 h-8 border-t-4 border-r-4 border-white/50 absolute top-0 right-0 rounded-tr-2xl"></div>
                      <div className="w-8 h-8 border-b-4 border-l-4 border-white/50 absolute bottom-0 left-0 rounded-bl-2xl"></div>
                      <div className="w-8 h-8 border-b-4 border-r-4 border-white/50 absolute bottom-0 right-0 rounded-br-2xl"></div>
                   </div>
                </div>
              </div>
            </div>

            {/* Fallback/Loading UI */}
            {(isInitializing || permissionStatus !== 'granted') && !isProcessingFile && (
              <div className="flex flex-col items-center justify-center text-center space-y-8 py-16 bg-slate-50 rounded-[3.5rem] border-2 border-dashed border-slate-200 shadow-inner">
                <div className="relative">
                  <div className="w-24 h-24 bg-white rounded-[2.5rem] flex items-center justify-center text-indigo-400 shadow-xl border border-slate-100">
                    <Camera size={44} strokeWidth={1.5} />
                  </div>
                  <div className="absolute -top-2 -right-2 w-8 h-8 bg-indigo-600 rounded-full border-4 border-white flex items-center justify-center text-white animate-bounce">
                    <span className="text-[10px] font-black">!</span>
                  </div>
                </div>
                <div className="space-y-2">
                  <p className="text-slate-700 font-black text-lg">Kamera Bekleniyor</p>
                  <p className="text-slate-400 text-xs px-12 leading-relaxed font-medium">
                    Kamera izni verin veya daha yüksek başarı oranı için <span className="text-indigo-600 font-bold">Galeriden Görsel</span> seçin.
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Action Buttons */}
          <div className="w-full mt-10 space-y-5">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*"
              className="hidden"
            />

            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full flex items-center justify-between p-4 pl-10 bg-slate-900 text-white rounded-[2.5rem] hover:bg-slate-800 transition-all active:scale-[0.97] shadow-[0_20px_40px_rgba(0,0,0,0.15)] group overflow-hidden relative"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-indigo-600/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
              <div className="flex items-center gap-5 relative z-10">
                <ImagePlus size={24} className="text-indigo-400" />
                <span className="font-black text-base tracking-tight">Galeriden Görsel Seç</span>
              </div>
              <div className="bg-indigo-600 p-4 rounded-full group-hover:scale-110 transition-transform relative z-10 shadow-lg shadow-indigo-500/30">
                 <ImageIcon size={24} />
              </div>
            </button>

            {fileError && (
              <div className="flex items-start gap-4 p-6 bg-rose-50 text-rose-700 rounded-[2.5rem] text-xs font-bold border border-rose-100 animate-fade-in shadow-sm">
                <AlertCircle size={20} className="shrink-0 text-rose-500" />
                <p className="leading-relaxed">{fileError}</p>
              </div>
            )}

            <button 
              onClick={onClose}
              className="w-full py-5 text-slate-400 hover:text-rose-500 font-black text-[11px] uppercase tracking-[0.4em] transition-all hover:tracking-[0.6em]"
