  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const sortedTxs = [...transactions].reverse();

    sortedTxs.forEach(tx => {
      const key = tx.productCode;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
        let match;
        while ((match = regex.exec(cleanText)) !== null) {
          data[match[1]] = match[2].trim();
        }
      }
    } catch (e) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount']);
    const extractedPartner = findInResult(['firma', 'partner', 'tedarikci', 'alıcı', 'supplier', 'recipient']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));
    setQuantity(parseInt(extractedQty) || 1);
    setPartner(extractedPartner || '');

    // Textile logic
    if (activeTab === 'in' || activeTab === 'out') {
      setSize(findInResult(['beden', 'size']));
      setColor(findInResult(['renk', 'color']));
      setFeature(findInResult(['ozellik', 'feature']));
    } 
    // General logic: Collect EVERYTHING else as extraFields
    else {
      const coreKeys = ['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode', 'urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description', 'miktar', 'adet', 'qty', 'quantity', 'amount', 'firma', 'partner', 'tedarikci', 'alıcı', 'supplier', 'recipient'];
      const extras: Record<string, string> = {};
      Object.entries(data).forEach(([key, val]) => {
        if (!coreKeys.some(ck => ck.toLowerCase() === key.toLowerCase())) {
          extras[key] = val;
        }
      });
      setExtraFields(extras);
    }

    setProductId(extractedCode || cleanText);
    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setQuantity(activeTab.includes('in') ? 1 : '');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;
    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab.includes('out')) {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: {id: ActiveTab, icon: any, label: string, adminOnly?: boolean}) => {
    if (adminOnly && user?.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={18} />
        <span className="font-medium text-sm">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Top Bar */}
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-black bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock
            </h1>
          </div>

          <div className="space-y-1 flex-1 overflow-y-auto pr-2 custom-scrollbar">
            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-4">Analiz</p>
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Tekstil Modülü</p>
            <NavItem id="in" icon={PackagePlus} label="Stok Giriş (Bedenli)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (Bedenli)" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Genel Stok Modülü</p>
            <NavItem id="gen_in" icon={Box} label="Genel Mal Kabul" />
            <NavItem id="gen_out" icon={ClipboardList} label="Genel Sevkiyat" />

            {user.role === UserRole.ADMIN && (
              <>
                <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Yönetim</p>
                <NavItem id="users" icon={Users} label="Kullanıcı Yönetimi" adminOnly />
              </>
            )}
          </div>

          <div className="mt-auto pt-6 border-t">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors">
              <LogOut size={18} />
              <span className="font-bold text-sm">Güvenli Çıkış</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.message}
          </div>
        )}

        {/* Dashboard and History remains similar but with tab logic */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex justify-between items-center">
               <h2 className="text-2xl font-black text-slate-800 tracking-tight">Depo İzleme Merkezi</h2>
            </header>

            {/* ... Existing Dashboard UI from previous file ... */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo', icon: TrendingUp },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose', icon: TrendingDown },
                { label: 'Mevcut Stok', val: inventory.reduce((a,b)=>a+b.remaining,0), color: 'emerald', icon: Calculator },
                { label: 'Ürün Çeşidi', val: inventory.length, color: 'amber', icon: Layers },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{card.label}</p>
                    <p className="text-3xl font-black text-slate-900">{card.val.toLocaleString()}</p>
                  </div>
                  <div className={`p-4 rounded-2xl bg-${card.color}-50 text-${card.color}-600`}>
                    <card.icon size={24} />
                  </div>
                </div>
              ))}
            </div>

            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
               <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                  <h3 className="font-bold text-slate-700">Güncel Envanter Listesi</h3>
               </div>
               <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                     <thead className="bg-white text-slate-400 uppercase text-[10px] font-black tracking-widest">
                        <tr>
                           <th className="px-8 py-4">Ürün Detayı</th>
                           <th className="px-8 py-4">Mevcut Stok</th>
                           <th className="px-8 py-4">Son İşlem</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-50">
                        {filteredInventory.map(p => (
                          <tr key={p.productCode} className="hover:bg-slate-50/50 transition-colors">
                             <td className="px-8 py-4">
                                <p className="font-mono text-[10px] text-indigo-500 font-bold">{p.productCode}</p>
                                <p className="font-bold text-slate-800">{p.productName}</p>
                             </td>
                             <td className="px-8 py-4">
                                <span className={`text-lg font-black ${p.remaining < 10 ? 'text-rose-600' : 'text-emerald-600'}`}>{p.remaining}</span>
                             </td>
                             <td className="px-8 py-4 text-xs text-slate-400">{p.lastUpdate}</td>
                          </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out' || activeTab === 'gen_in' || activeTab === 'gen_out') && (
          <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <header className="text-center space-y-2">
              <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${activeTab.includes('gen') ? 'bg-amber-100 text-amber-700' : 'bg-indigo-100 text-indigo-700'}`}>
                {activeTab.includes('gen') ? 'Genel Stok Modülü' : 'Tekstil Modülü'}
              </span>
              <h2 className="text-3xl font-black text-slate-800">
                {activeTab.includes('in') ? 'Mal Kabul (QR Giriş)' : 'Stok Çıkış (QR Sevkiyat)'}
              </h2>
            </header>

            {!isFormActive ? (
              <div onClick={() => setIsScannerOpen(true)} className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-20 flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-200 hover:bg-indigo-50/30 transition-all group">
                <div className="w-24 h-24 rounded-[2rem] bg-indigo-600 flex items-center justify-center text-white shadow-2xl shadow-indigo-200 group-hover:scale-110 transition-transform">
                  <Search size={44} />
                </div>
                <div className="text-center">
                  <p className="text-2xl font-black text-slate-800">QR Taramayı Başlat</p>
                  <p className="text-slate-400 font-medium">Kamera veya dosya ile veri girişi yapın</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100 space-y-10 animate-fade-in">
                {/* Product Summary */}
                <div className="flex items-center justify-between p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                   <div className="flex items-center gap-4">
                      <div className="w-16 h-16 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-2xl">
                         {productName.charAt(0)}
                      </div>
                      <div>
                         <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{productCode}</p>
                         <h3 className="text-xl font-black text-slate-800">{productName}</h3>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Mevcut Bakiye</p>
                      <p className="text-3xl font-black text-slate-900">{currentProductStock?.remaining || 0} <span className="text-sm font-medium text-slate-400">Adet</span></p>
                   </div>
                </div>

                {/* Form Content */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {/* Common Fields */}
                  <div className="space-y-6">
                    <h4 className="font-black text-slate-400 text-xs uppercase tracking-[0.2em] border-b pb-2">Ana Bilgiler</h4>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">İşlem Adeti</label>
                      <input type="number" value={quantity} onChange={e => setQuantity(e.target.value === '' ? '' : parseInt(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-black text-xl" placeholder="0" />
                    </div>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">{activeTab.includes('in') ? 'Tedarikçi Firma' : 'Alıcı / Departman'}</label>
                      <input type="text" value={partner} onChange={e => setPartner(e.target.value)} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Firma adı..." />
                    </div>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">Onaylayan Kişi</label>
                      <input type="text" value={approver} onChange={e => setApprover(e.target.value)} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Yönetici onayı..." />
                    </div>
                  </div>

                  {/* Context Specific Fields */}
                  <div className="space-y-6">
                    <h4 className="font-black text-slate-400 text-xs uppercase tracking-[0.2em] border-b pb-2">Ürün Detayları</h4>

                    {/* TEXTILE MODULE UI */}
                    {(!activeTab.includes('gen')) ? (
                      <div className="grid grid-cols-1 gap-4">
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Beden</span>
                           <span className="font-black text-slate-800">{size || 'Tanımsız'}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Renk</span>
                           <span className="font-black text-slate-800">{color || 'Tanımsız'}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Özellik</span>
                           <span className="font-black text-slate-800">{feature || 'Tanımsız'}</span>
                        </div>
                      </div>
                    ) : (
                      /* GENERAL MODULE DYNAMIC UI */
                      <div className="grid grid-cols-1 gap-4 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                        {Object.keys(extraFields).length > 0 ? (
                          Object.entries(extraFields).map(([key, val]) => (
                            <div key={key} className="p-4 bg-amber-50/50 rounded-2xl border border-amber-100 flex flex-col">
                               <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">{key}</span>
                               <span className="font-bold text-slate-800">{val}</span>
                            </div>
                          ))
                        ) : (
                          <div className="p-10 border-2 border-dashed border-slate-100 rounded-[2rem] text-center">
                             <Info size={32} className="mx-auto text-slate-200 mb-2" />
                             <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ek detay bulunamadı</p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex gap-4 pt-6">
                  <button onClick={resetForm} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-slate-200 transition-all">İptal Et</button>
                  <button onClick={handleTransaction} className={`flex-[2] py-5 rounded-3xl font-black text-sm text-white uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98] ${activeTab.includes('in') ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'}`}>
                    {activeTab.includes('in') ? 'Stok Girişini Onayla' : 'Sevkiyatı Tamamla'}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
           <div className="space-y-6 animate-fade-in">
              <h2 className="text-2xl font-black text-slate-800">İşlem Hareket Geçmişi</h2>
              <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                       <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                          <tr>
                             <th className="px-8 py-5">Tarih</th>
                             <th className="px-8 py-5">Ürün / Modül</th>
                             <th className="px-8 py-5">Tip</th>
                             <th className="px-8 py-5">Miktar</th>
                             <th className="px-8 py-5">Onay</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-50">
                          {transactions.map(t => (
                            <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-8 py-5 text-slate-400 text-xs">{t.date}</td>
                               <td className="px-8 py-5">
                                  <p className="font-bold text-slate-800">{t.productName}</p>
                                  <p className="text-[10px] font-black text-indigo-400 uppercase">{t.metadata ? 'Genel Stok' : 'Tekstil'}</p>
                               </td>
                               <td className="px-8 py-5">
                                  <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>{t.type}</span>
                               </td>
                               <td className="px-8 py-5 font-black text-slate-900">{t.quantity}</td>
                               <td className="px-8 py-5 text-indigo-600 font-bold">{t.approver}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

// UserManagement remains mostly same as previous version but fits the aesthetic
const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const resetForm = () => {
    setShowAdd(false);
    setEditingUser(null);
    setNewUsername('');
    setNewPass('');
    setNewName('');
    setNewRole(UserRole.USER);
  };

  const handleSave = () => {
    if (!newUsername || !newPass || !newName) return;
    const userData: User = {
      id: editingUser ? editingUser.id : Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(userData);
    setUsers(StorageService.getUsers());
    resetForm();
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <header className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-slate-800">Sistem Kullanıcıları</h2>
        <button onClick={() => setShowAdd(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200">Yeni Personel</button>
      </header>

      {showAdd && (
        <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-indigo-100 space-y-4">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Ad Soyad" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newUsername} onChange={e=>setNewUsername(e.target.value)} placeholder="Kullanıcı Adı" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newPass} type="password" onChange={e=>setNewPass(e.target.value)} placeholder="Şifre" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <select value={newRole} onChange={e=>setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600 font-bold">
                 <option value={UserRole.USER}>Personel</option>
                 <option value={UserRole.ADMIN}>Yönetici</option>
              </select>
           </div>
           <div className="flex gap-2">
              <button onClick={handleSave} className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold">Kaydet</button>
              <button onClick={resetForm} className="px-6 py-2 bg-slate-100 text-slate-500 rounded-xl font-bold">Vazgeç</button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex items-center justify-between group">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-black text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all">
                  {u.fullName.charAt(0)}
               </div>
               <div>
                  <p className="font-bold text-slate-800">{u.fullName}</p>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{u.role}</p>
               </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => { StorageService.deleteUser(u.id); setUsers(StorageService.getUsers()); }} className="p-2 text-rose-300 hover:text-rose-600 transition-colors"><Trash2 size={18} /></button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock,
  Bell,
  Settings,
  TrendingUp,
  TrendingDown,
  Calculator,
  Layers,
  Calendar,
  Filter,
  ArrowLeft,
  ChevronRight,
  UserCheck,
  Trash2,
  Edit2,
  User as UserIcon,
  Box,
  ClipboardList,
  Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'gen_in' | 'gen_out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Dashboard States
  const [dashboardSearch, setDashboardSearch] = useState('');
  const [selectedProductCode, setSelectedProductCode] = useState<string | null>(null);
  const [detailFilters, setDetailFilters] = useState({
    size: '',
    color: '',
    feature: ''
  });

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Core Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  // Textile Specific Data
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // General Stock Dynamic Data
  const [extraFields, setExtraFields] = useState<Record<string, string>>({});

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const sortedTxs = [...transactions].reverse();

    sortedTxs.forEach(tx => {
      const key = tx.productCode;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
        let match;
        while ((match = regex.exec(cleanText)) !== null) {
          data[match[1]] = match[2].trim();
        }
      }
    } catch (e) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount']);
    const extractedPartner = findInResult(['firma', 'partner', 'tedarikci', 'tedarikciFirma', 'alıcı', 'supplier', 'recipient', 'vendor', 'customer']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));
    setQuantity(parseInt(extractedQty) || 1);
    setPartner(extractedPartner || '');

    // Textile logic
    if (activeTab === 'in' || activeTab === 'out') {
      setSize(findInResult(['beden', 'size']));
      setColor(findInResult(['renk', 'color']));
      setFeature(findInResult(['ozellik', 'feature']));
    } 
    // General logic: Collect EVERYTHING else as extraFields
    else {
      const coreKeys = [
        'urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode', 
        'urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description', 
        'miktar', 'adet', 'qty', 'quantity', 'amount', 
        'firma', 'partner', 'tedarikci', 'tedarikciFirma', 'alıcı', 'supplier', 'recipient', 'vendor', 'customer'
      ];
      const extras: Record<string, string> = {};
      Object.entries(data).forEach(([key, val]) => {
        if (!coreKeys.some(ck => ck.toLowerCase() === key.toLowerCase())) {
          extras[key] = val;
        }
      });
      setExtraFields(extras);
    }

    setProductId(extractedCode || cleanText);
    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setQuantity(activeTab.includes('in') ? 1 : '');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;
    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab.includes('out')) {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: {id: ActiveTab, icon: any, label: string, adminOnly?: boolean}) => {
    if (adminOnly && user?.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={18} />
        <span className="font-medium text-sm">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Top Bar */}
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">SmartStock</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-black bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              SmartStock
            </h1>
          </div>

          <div className="space-y-1 flex-1 overflow-y-auto pr-2 custom-scrollbar">
            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-4">Analiz</p>
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Tekstil Modülü</p>
            <NavItem id="in" icon={PackagePlus} label="Stok Giriş (Bedenli)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (Bedenli)" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Genel Stok Modülü</p>
            <NavItem id="gen_in" icon={Box} label="Genel Mal Kabul" />
            <NavItem id="gen_out" icon={ClipboardList} label="Genel Sevkiyat" />

            {user.role === UserRole.ADMIN && (
              <>
                <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Yönetim</p>
                <NavItem id="users" icon={Users} label="Kullanıcı Yönetimi" adminOnly />
              </>
            )}
          </div>

          <div className="mt-auto pt-6 border-t">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors">
              <LogOut size={18} />
              <span className="font-bold text-sm">Güvenli Çıkış</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex justify-between items-center">
               <h2 className="text-2xl font-black text-slate-800 tracking-tight">Depo İzleme Merkezi</h2>
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo', icon: TrendingUp },
                { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose', icon: TrendingDown },
                { label: 'Mevcut Stok', val: inventory.reduce((a,b)=>a+b.remaining,0), color: 'emerald', icon: Calculator },
                { label: 'Ürün Çeşidi', val: inventory.length, color: 'amber', icon: Layers },
              ].map((card, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{card.label}</p>
                    <p className="text-3xl font-black text-slate-900">{card.val.toLocaleString()}</p>
                  </div>
                  <div className={`p-4 rounded-2xl bg-${card.color}-50 text-${card.color}-600`}>
                    <card.icon size={24} />
                  </div>
                </div>
              ))}
            </div>

            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
               <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                  <h3 className="font-bold text-slate-700">Güncel Envanter Listesi</h3>
               </div>
               <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                     <thead className="bg-white text-slate-400 uppercase text-[10px] font-black tracking-widest">
                        <tr>
                           <th className="px-8 py-4">Ürün Detayı</th>
                           <th className="px-8 py-4">Mevcut Stok</th>
                           <th className="px-8 py-4">Son İşlem</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-50">
                        {filteredInventory.map(p => (
                          <tr key={p.productCode} className="hover:bg-slate-50/50 transition-colors">
                             <td className="px-8 py-4">
                                <p className="font-mono text-[10px] text-indigo-500 font-bold">{p.productCode}</p>
                                <p className="font-bold text-slate-800">{p.productName}</p>
                             </td>
                             <td className="px-8 py-4">
                                <span className={`text-lg font-black ${p.remaining < 10 ? 'text-rose-600' : 'text-emerald-600'}`}>{p.remaining}</span>
                             </td>
                             <td className="px-8 py-4 text-xs text-slate-400">{p.lastUpdate}</td>
                          </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out' || activeTab === 'gen_in' || activeTab === 'gen_out') && (
          <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <header className="text-center space-y-2">
              <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${activeTab.includes('gen') ? 'bg-amber-100 text-amber-700' : 'bg-indigo-100 text-indigo-700'}`}>
                {activeTab.includes('gen') ? 'Genel Stok Modülü' : 'Tekstil Modülü'}
              </span>
              <h2 className="text-3xl font-black text-slate-800">
                {activeTab.includes('in') ? 'Mal Kabul (QR Giriş)' : 'Stok Çıkış (QR Sevkiyat)'}
              </h2>
            </header>

            {!isFormActive ? (
              <div onClick={() => setIsScannerOpen(true)} className="bg-white border-4 border-dashed border-slate-100 rounded-[3rem] p-20 flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-200 hover:bg-indigo-50/30 transition-all group">
                <div className="w-24 h-24 rounded-[2rem] bg-indigo-600 flex items-center justify-center text-white shadow-2xl shadow-indigo-200 group-hover:scale-110 transition-transform">
                  <Search size={44} />
                </div>
                <div className="text-center">
                  <p className="text-2xl font-black text-slate-800">QR Taramayı Başlat</p>
                  <p className="text-slate-400 font-medium">Kamera veya dosya ile veri girişi yapın</p>
                </div>
              </div>
            ) : (
              <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100 space-y-10 animate-fade-in">
                {/* Product Summary */}
                <div className="flex items-center justify-between p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                   <div className="flex items-center gap-4">
                      <div className="w-16 h-16 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-2xl">
                         {productName.charAt(0)}
                      </div>
                      <div>
                         <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{productCode}</p>
                         <h3 className="text-xl font-black text-slate-800">{productName}</h3>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Mevcut Bakiye</p>
                      <p className="text-3xl font-black text-slate-900">{currentProductStock?.remaining || 0} <span className="text-sm font-medium text-slate-400">Adet</span></p>
                   </div>
                </div>

                {/* Form Content */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <h4 className="font-black text-slate-400 text-xs uppercase tracking-[0.2em] border-b pb-2">Ana Bilgiler</h4>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">İşlem Adeti</label>
                      <input type="number" value={quantity} onChange={e => setQuantity(e.target.value === '' ? '' : parseInt(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-black text-xl" placeholder="0" />
                    </div>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">{activeTab.includes('in') ? 'Tedarikçi Firma' : 'Alıcı / Departman'}</label>
                      <input type="text" value={partner} onChange={e => setPartner(e.target.value)} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Firma adı..." />
                    </div>
                    <div>
                      <label className="text-[11px] font-bold text-slate-400 uppercase ml-2">Onaylayan Kişi</label>
                      <input type="text" value={approver} onChange={e => setApprover(e.target.value)} className="w-full px-6 py-4 bg-slate-50 border-0 rounded-2xl focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Yönetici onayı..." />
                    </div>
                  </div>

                  <div className="space-y-6">
                    <h4 className="font-black text-slate-400 text-xs uppercase tracking-[0.2em] border-b pb-2">Ürün Detayları</h4>

                    {!activeTab.includes('gen') ? (
                      <div className="grid grid-cols-1 gap-4">
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Beden</span>
                           <span className="font-black text-slate-800">{size || 'Tanımsız'}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Renk</span>
                           <span className="font-black text-slate-800">{color || 'Tanımsız'}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                           <span className="text-xs font-bold text-indigo-700">Özellik</span>
                           <span className="font-black text-slate-800">{feature || 'Tanımsız'}</span>
                        </div>
                      </div>
                    ) : (
                      <div className="grid grid-cols-1 gap-4 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                        {Object.keys(extraFields).length > 0 ? (
                          Object.entries(extraFields).map(([key, val]) => (
                            <div key={key} className="p-4 bg-amber-50/50 rounded-2xl border border-amber-100 flex flex-col">
                               <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">{key}</span>
                               <span className="font-bold text-slate-800">{val}</span>
                            </div>
                          ))
                        ) : (
                          <div className="p-10 border-2 border-dashed border-slate-100 rounded-[2rem] text-center">
                             <Info size={32} className="mx-auto text-slate-200 mb-2" />
                             <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ek detay bulunamadı</p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex gap-4 pt-6">
                  <button onClick={resetForm} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-slate-200 transition-all">İptal Et</button>
                  <button onClick={handleTransaction} className={`flex-[2] py-5 rounded-3xl font-black text-sm text-white uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98] ${activeTab.includes('in') ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'}`}>
                    {activeTab.includes('in') ? 'Stok Girişini Onayla' : 'Sevkiyatı Tamamla'}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
           <div className="space-y-6 animate-fade-in">
              <h2 className="text-2xl font-black text-slate-800">İşlem Hareket Geçmişi</h2>
              <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                       <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                          <tr>
                             <th className="px-8 py-5">Tarih</th>
                             <th className="px-8 py-5">Ürün / Modül</th>
                             <th className="px-8 py-5">Tip</th>
                             <th className="px-8 py-5">Miktar</th>
                             <th className="px-8 py-5">Onay</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-50">
                          {transactions.map(t => (
                            <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-8 py-5 text-slate-400 text-xs">{t.date}</td>
                               <td className="px-8 py-5">
                                  <p className="font-bold text-slate-800">{t.productName}</p>
                                  <p className="text-[10px] font-black text-indigo-400 uppercase">{t.metadata ? 'Genel Stok' : 'Tekstil'}</p>
                               </td>
                               <td className="px-8 py-5">
                                  <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>{t.type}</span>
                               </td>
                               <td className="px-8 py-5 font-black text-slate-900">{t.quantity}</td>
                               <td className="px-8 py-5 text-indigo-600 font-bold">{t.approver}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <UserManagement />
        )}
      </main>

      {isScannerOpen && (
        <Scanner onScan={handleQRScan} onClose={() => setIsScannerOpen(false)} />
      )}
    </div>
  );
};

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const resetForm = () => {
    setShowAdd(false);
    setEditingUser(null);
    setNewUsername('');
    setNewPass('');
    setNewName('');
    setNewRole(UserRole.USER);
  };

  const handleSave = () => {
    if (!newUsername || !newPass || !newName) return;
    const userData: User = {
      id: editingUser ? editingUser.id : Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(userData);
    setUsers(StorageService.getUsers());
    resetForm();
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <header className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-slate-800">Sistem Kullanıcıları</h2>
        <button onClick={() => setShowAdd(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200">Yeni Personel</button>
      </header>

      {showAdd && (
        <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-indigo-100 space-y-4">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Ad Soyad" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newUsername} onChange={e=>setNewUsername(e.target.value)} placeholder="Kullanıcı Adı" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newPass} type="password" onChange={e=>setNewPass(e.target.value)} placeholder="Şifre" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <select value={newRole} onChange={e=>setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600 font-bold">
                 <option value={UserRole.USER}>Personel</option>
                 <option value={UserRole.ADMIN}>Yönetici</option>
              </select>
           </div>
           <div className="flex gap-2">
              <button onClick={handleSave} className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold">Kaydet</button>
              <button onClick={resetForm} className="px-6 py-2 bg-slate-100 text-slate-500 rounded-xl font-bold">Vazgeç</button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex items-center justify-between group">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-black text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all">
                  {u.fullName.charAt(0)}
               </div>
               <div>
                  <p className="font-bold text-slate-800">{u.fullName}</p>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{u.role}</p>
               </div>
            </div>
            {u.username !== 'admin' && (
              <button onClick={() => { StorageService.deleteUser(u.id); setUsers(StorageService.getUsers()); }} className="p-2 text-rose-300 hover:text-rose-600 transition-colors"><Trash2 size={18} /></button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

