}

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Lock,
  Unlock,
  Bell,
  Settings,
  TrendingUp,
  TrendingDown,
  Calculator,
  Layers,
  Calendar,
  Filter,
  ArrowLeft,
  ChevronRight,
  UserCheck,
  Trash2,
  Edit2,
  User as UserIcon,
  Box,
  ClipboardList,
  Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'gen_in' | 'gen_out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Dashboard States
  const [dashboardSearch, setDashboardSearch] = useState('');
  const [selectedProductCode, setSelectedProductCode] = useState<string | null>(null);
  const [detailFilters, setDetailFilters] = useState({
    size: '',
    color: '',
    feature: ''
  });

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [isEditable, setIsEditable] = useState(false);

  // Core Product Data
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1);
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');

  // Textile Specific Data
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // General Stock Dynamic Data
  const [extraFields, setExtraFields] = useState<Record<string, string>>({});

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const sortedTxs = [...transactions].reverse();

    sortedTxs.forEach(tx => {
      const key = tx.productCode;
      const existing = map.get(key) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
        let match;
        while ((match = regex.exec(cleanText)) !== null) {
          data[match[1]] = match[2].trim();
        }
      }
    } catch (e) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount']);
    const extractedPartner = findInResult(['firma', 'partner', 'tedarikci', 'tedarikciFirma', 'alıcı', 'supplier', 'recipient', 'vendor', 'customer']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));
    setQuantity(parseInt(extractedQty) || 1);
    setPartner(extractedPartner || '');

    // Textile logic
    if (activeTab === 'in' || activeTab === 'out') {
      setSize(findInResult(['beden', 'size']));
      setColor(findInResult(['renk', 'color']));
      setFeature(findInResult(['ozellik', 'feature']));
    } 
    // General logic: Collect EVERYTHING else as extraFields
    else {
      const coreKeys = [
        'urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'itemCode', 
        'urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'description', 
        'miktar', 'adet', 'qty', 'quantity', 'amount', 
        'firma', 'partner', 'tedarikci', 'tedarikciFirma', 'alıcı', 'supplier', 'recipient', 'vendor', 'customer'
      ];
      const extras: Record<string, string> = {};
      Object.entries(data).forEach(([key, val]) => {
        if (!coreKeys.some(ck => ck.toLowerCase() === key.toLowerCase())) {
          extras[key] = val;
        }
      });
      setExtraFields(extras);
    }

    setProductId(extractedCode || cleanText);
    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setQuantity(activeTab.includes('in') ? 1 : '');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;
    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab.includes('out')) {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: {id: ActiveTab, icon: any, label: string, adminOnly?: boolean}) => {
    if (adminOnly && user?.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={18} />
        <span className="font-medium text-sm">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Top Bar */}
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">KaratProStock QR</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-black bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              KaratProStock QR
            </h1>
          </div>

          <div className="space-y-1 flex-1 overflow-y-auto pr-2 custom-scrollbar">
            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-4">Analiz</p>
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Tekstil Modülü</p>
            <NavItem id="in" icon={PackagePlus} label="Stok Giriş (Bedenli)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (Bedenli)" />

            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Genel Stok Modülü</p>
            <NavItem id="gen_in" icon={Box} label="Genel Mal Kabul" />
            <NavItem id="gen_out" icon={ClipboardList} label="Genel Sevkiyat" />

            {user.role === UserRole.ADMIN && (
              <>
                <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-6">Yönetim</p>
                <NavItem id="users" icon={Users} label="Kullanıcı Yönetimi" adminOnly />
              </>
            )}
          </div>

          <div className="mt-auto pt-6 border-t">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors">
              <LogOut size={18} />
              <span className="font-bold text-sm">Güvenli Çıkış</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
