      </header>

      {showAdd && (
        <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-indigo-100 space-y-4">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Ad Soyad" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newUsername} onChange={e=>setNewUsername(e.target.value)} placeholder="Kullanıcı Adı" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <input value={newPass} type="password" onChange={e=>setNewPass(e.target.value)} placeholder="Şifre" className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600" />
              <select value={newRole} onChange={e=>setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 rounded-xl border-0 focus:ring-2 focus:ring-indigo-600 font-bold">
                 <option value={UserRole.USER}>Personel</option>
