              <svg viewBox="0 0 24 24" className="w-10 h-10 fill-current" xmlns="http://www.w3.org/2000/svg">
                <path d="M4 4h7v7H4zm0 9h7v7H4zm9-9h7v7h-7zm0 9h7v7h-7z" />
              </svg>
            </div>
            <h1 className="text-3xl font-black text-slate-900 mb-2">KaratProStock QR</h1>
            <p className="text-slate-500 font-medium">Giriş yapmak için bilgilerinizi girin.</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-4">
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400">
                  <UserIcon size={20} />
                </div>
                <input
                  type="text"
                  required
