        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) {
        existing.totalIn += tx.quantity;
      } else {
        existing.totalOut += tx.quantity;
      }
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(key, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Seçili Ürün Detay Analizi için Veriler
  const productDetailData = useMemo(() => {
    if (!selectedProductCode) return null;

    const productTxs = transactions.filter(t => t.productCode === selectedProductCode);
    const productInfo = inventory.find(i => i.productCode === selectedProductCode);

    // Dinamik filtre seçenekleri
    const sizes = Array.from(new Set(productTxs.map(t => t.size).filter(Boolean)));
    const colors = Array.from(new Set(productTxs.map(t => t.color).filter(Boolean)));
    const features = Array.from(new Set(productTxs.map(t => t.feature).filter(Boolean)));

    // Filtreleri uygula
    const filteredTxs = productTxs.filter(t => {
      return (!detailFilters.size || t.size === detailFilters.size) &&
             (!detailFilters.color || t.color === detailFilters.color) &&
             (!detailFilters.feature || t.feature === detailFilters.feature);
    });

    const stats = filteredTxs.reduce((acc, curr) => {
      if (curr.type === TransactionType.IN) acc.in += curr.quantity;
      else acc.out += curr.quantity;
      return acc;
    }, { in: 0, out: 0 });

    return {
      info: productInfo,
      transactions: filteredTxs,
      filterOptions: { sizes, colors, features },
      stats: { ...stats, remaining: stats.in - stats.out }
    };
  }, [selectedProductCode, transactions, inventory, detailFilters]);

  // Arama filtresi uygulanmış envanter (Dashboard listesi için)
  const filteredInventory = useMemo(() => {
    return inventory
      .filter(p => 
        p.productName.toLowerCase().includes(dashboardSearch.toLowerCase()) || 
        p.productCode.toLowerCase().includes(dashboardSearch.toLowerCase())
      )
      .sort((a, b) => {
        const aThreshold = thresholds[a.productCode] || 0;
        const bThreshold = thresholds[b.productCode] || 0;
        const aCritical = aThreshold > 0 && a.remaining <= aThreshold;
        const bCritical = bThreshold > 0 && b.remaining <= bThreshold;
        if (aCritical && !bCritical) return -1;
        if (!aCritical && bCritical) return 1;
        return b.remaining - a.remaining;
      });
  }, [inventory, dashboardSearch, thresholds]);

  // Mevcut ürünün stok durumunu bul (Formlar için)
  const currentProductStock = useMemo(() => {
    if (!productCode) return null;
    return inventory.find(p => p.productCode === productCode) || null;
  }, [inventory, productCode]);

  const handleQRScan = (text: string) => {
    const cleanText = text.trim();
    let data: Record<string, string> = {};

    try {
      if (cleanText.startsWith('{') && cleanText.endsWith('}')) {
        data = JSON.parse(cleanText);
      } else {
        throw new Error("Not JSON");
      }
    } catch (e) {
      const regex = /(?:"?([^":\s]+)"?\s*:\s*"?([^",\n]+)"?)/gi;
      let match;
      while ((match = regex.exec(cleanText)) !== null) {
        data[match[1]] = match[2].trim();
      }
    }

    if (Object.keys(data).length === 0 && cleanText.length > 0) {
      if (cleanText.includes(';;')) {
        const parts = cleanText.split(';;').map(p => p.trim());
        data['Firma'] = parts[0];
        data['Miktar'] = parts[1] || parts[3];
        data['Beden'] = parts[2];
        data['Renk'] = parts[4];
        data['Özellik'] = parts[5];
        data['Kod'] = parts[6];
        data['Ad'] = parts[7];
      } else {
        data['Kod'] = cleanText;
      }
    }

    const findInResult = (keys: string[]) => {
      for (const key of keys) {
        const foundKey = Object.keys(data).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) return data[foundKey];
      }
      return '';
    };

    const extractedCode = findInResult(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'ÜrünKodu', 'itemCode']);
    const extractedName = findInResult(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'ÜrünAdı', 'Açıklama', 'description']);
    const extractedPartner = findInResult(['firma', 'partner', 'vendor', 'customer', 'tedarikci', 'tedarikciFirma', 'tedarikçi', 'tedarikçiFirma', 'alıcı', 'supplier', 'recipient']);
    const extractedQty = findInResult(['miktar', 'adet', 'qty', 'quantity', 'amount', 'stok']);
    const extractedSize = findInResult(['beden', 'size', 'ölçü', 'ebat']);
    const extractedColor = findInResult(['renk', 'color']);
    const extractedFeature = findInResult(['ozellik', 'feature', 'özellik', 'not', 'ekstra']);

    setProductCode(extractedCode || cleanText);
    setProductName(extractedName || extractedCode || 'Ürün ' + (extractedCode || 'Tanımsız'));

    if (activeTab === 'out') {
      setPartner('');
      setQuantity('');
    } else {
      setPartner(extractedPartner || '');
      setQuantity(parseInt(extractedQty) || 1);
    }

    setSize(extractedSize || '');
    setColor(extractedColor || '');
    setFeature(extractedFeature || '');
    setProductId(extractedCode || cleanText);

    setIsFormActive(true);
    setIsEditable(false);
    setIsScannerOpen(false);
    showNotification('QR Kod başarıyla çözümlendi', 'success');
  };

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const toggleEdit = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditable(!isEditable);
  };

  const resetForm = () => {
    setIsFormActive(false);
    setIsEditable(false);
    setProductId('');
    setProductName('');
    setProductCode('');
    setSize('');
    setColor('');
    setFeature('');
    setQuantity(activeTab === 'in' ? 1 : '');
    setPartner('');
    setApprover('');
  };

  const lowStockProducts = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    });
  }, [inventory, thresholds]);

  const handleDeleteTransaction = (id: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('Bu işlem kaydını silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      const updatedTransactions = StorageService.getTransactions();
      setTransactions(updatedTransactions);
      showNotification('İşlem kaydı başarıyla silindi.', 'success');
    }
  };

  const handleTransaction = () => {
    const finalQuantity = quantity === '' ? 0 : quantity;

    if (!productCode || finalQuantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları (Onaylayan dahil) doldurun.', 'error');
      return;
    }

    if (activeTab === 'out') {
      const available = currentProductStock?.remaining || 0;
      if (available < finalQuantity) {
        showNotification(`Yetersiz stok! Mevcut bakiye: ${available} adet.`, 'error');
        return;
      }
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      productId: productId || productCode,
      productName: productName || productCode,
      productCode,
      size,
      color,
      feature,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      quantity: finalQuantity,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver: approver
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem başarıyla kaydedildi.', 'success');
  };

  const handleClearAllHistory = () => {
    if (user?.role !== UserRole.ADMIN) return;
    if (confirm('TÜM işlem geçmişini kalıcı olarak silmek üzeresiniz. Bu işlem geri alınamaz. Onaylıyor musunuz?')) {
      StorageService.clearAllTransactions();
      setTransactions([]);
      showNotification('Tüm geçmiş temizlendi.', 'warning');
    }
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Stok eşiği güncellendi.', 'success');
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const NavItem = ({ id, icon: Icon, label, adminOnly = false }: any) => {
    if (adminOnly && user.role !== UserRole.ADMIN) return null;
    const active = activeTab === id;
    return (
      <button
        type="button"
        onClick={() => { setActiveTab(id); setSidebarOpen(false); resetForm(); setSelectedProductCode(null); }}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <h1 className="font-bold text-xl text-indigo-600">KaratProStock QR</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-200 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:block mb-10 text-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">
              KaratProStock QR
            </h1>
          </div>

          <div className="space-y-2 flex-1">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="in" icon={PackagePlus} label="Mal Kabul (QR)" />
            <NavItem id="out" icon={PackageMinus} label="Stok Çıkış (QR)" />
            <NavItem id="history" icon={History} label="İşlem Geçmişi" />
            <NavItem id="users" icon={Users} label="Kullanıcılar" adminOnly />
          </div>

          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-2 mb-4">
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold shrink-0">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-xs text-slate-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Çıkış Yap</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        {notification && (
          <div className={`fixed top-4 right-4 z-[100] px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 text-white transition-all duration-300 transform translate-y-0 ${
            notification.type === 'success' ? 'bg-emerald-500' : notification.type === 'warning' ? 'bg-amber-500' : 'bg-rose-500'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : notification.type === 'warning' ? <Bell size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Depo Analiz Paneli</h2>
                <p className="text-slate-500">Stoklarınızı kategorize edin ve anlık izleyin.</p>
              </div>
              <div className="flex items-center gap-3">
                {!selectedProductCode && (
                  <div className="relative">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text"
                      placeholder="Ürün veya Kod Ara..."
                      value={dashboardSearch}
                      onChange={(e) => setDashboardSearch(e.target.value)}
                      className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 w-full md:w-64 shadow-sm text-sm"
                    />
                  </div>
                )}
                {lowStockProducts.length > 0 && !selectedProductCode && (
                  <div className="bg-amber-100 text-amber-800 px-4 py-2.5 rounded-xl flex items-center gap-2 font-bold shadow-sm border border-amber-200 animate-pulse">
                    <Bell size={18} />
                    <span className="hidden sm:inline">Kritik Stok:</span> {lowStockProducts.length}
                  </div>
                )}
                {selectedProductCode && (
                  <button 
                    onClick={() => { setSelectedProductCode(null); setDetailFilters({size:'',color:'',feature:''}); }}
                    className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-700 transition-all shadow-lg"
                  >
                    <ArrowLeft size={18} />
                    Analizi Kapat
                  </button>
                )}
              </div>
            </header>

            {!selectedProductCode ? (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  {[
                    { label: 'Toplam Giriş', val: inventory.reduce((a,b)=>a+b.totalIn,0), color: 'indigo', icon: TrendingUp },
                    { label: 'Toplam Çıkış', val: inventory.reduce((a,b)=>a+b.totalOut,0), color: 'rose', icon: TrendingDown },
                    { label: 'Mevcut Stok Adeti', val: inventory.reduce((a,b)=>a+b.remaining,0), color: 'emerald', icon: Calculator },
                    { label: 'Aktif Ürün Çeşidi', val: inventory.length, color: 'amber', icon: Layers },
                  ].map((card, i) => (
                    <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
                      <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{card.label}</p>
                        <p className="text-3xl font-black text-slate-900">{card.val.toLocaleString()}</p>
                      </div>
                      <div className={`p-3 rounded-2xl bg-${card.color}-50 text-${card.color}-600`}>
                        <card.icon size={24} />
                      </div>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col">
                    <h3 className="font-bold mb-6 text-slate-700 flex items-center gap-2">
                      <TrendingUp size={20} className="text-indigo-600" />
                      Stok Hacim Grafiği (Top 5)
                    </h3>
                    <div className="flex-1 min-h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={inventory.slice(0, 5)} layout="vertical">
                          <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                          <XAxis type="number" hide />
                          <YAxis dataKey="productName" type="category" width={100} fontSize={12} stroke="#64748b" />
                          <Tooltip 
                            cursor={{fill: '#f8fafc'}}
                            contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                          />
                          <Bar dataKey="remaining" name="Mevcut Stok" fill="#4f46e5" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                      <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Layers size={20} className="text-indigo-600" />
                        Güncel Stok & Eşik Ayarları
                      </h3>
                    </div>
                    <div className="overflow-x-auto max-h-[500px] overflow-y-auto">
                      <table className="w-full text-sm text-left">
                        <thead className="sticky top-0 bg-white shadow-sm z-10">
                          <tr className="text-slate-400 border-b">
                            <th className="px-6 py-4 font-semibold">Kod / Ürün</th>
                            <th className="px-6 py-4 font-semibold text-center">Durum</th>
                            <th className="px-6 py-4 font-semibold">Mevcut</th>
                            <th className="px-6 py-4 font-semibold">Alt Limit</th>
                            <th className="px-6 py-4 font-semibold text-right">İşlem</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                          {filteredInventory.map((p) => {
                            const threshold = thresholds[p.productCode] || 0;
                            const isCritical = threshold > 0 && p.remaining <= threshold;

                            return (
                              <tr 
                                key={p.productCode} 
                                onClick={() => setSelectedProductCode(p.productCode)}
                                className="hover:bg-indigo-50/30 cursor-pointer transition-colors group"
                              >
                                <td className="px-6 py-4">
                                  <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${isCritical ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} />
                                    <div>
                                      <p className="text-[10px] font-mono font-bold text-slate-400 leading-none mb-1 group-hover:text-indigo-600 transition-colors uppercase tracking-wider">{p.productCode}</p>
                                      <p className="font-bold text-slate-800 truncate max-w-[180px]">{p.productName}</p>
                                    </div>
                                  </div>
                                </td>
                                <td className="px-6 py-4 text-center">
                                  {isCritical ? (
                                    <span className="px-2 py-1 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-lg border border-rose-100">Kritik</span>
                                  ) : (
                                    <span className="px-2 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase rounded-lg border border-emerald-100">Normal</span>
                                  )}
                                </td>
                                <td className="px-6 py-4">
                                  <span className={`text-base font-black ${isCritical ? 'text-rose-600' : 'text-slate-900'}`}>
                                    {p.remaining.toLocaleString()}
                                  </span>
                                </td>
                                <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                                  {editingThreshold === p.productCode && user?.role === UserRole.ADMIN ? (
                                    <input 
                                      type="number" 
                                      autoFocus
                                      className="w-20 px-2 py-1.5 border-2 border-indigo-500 rounded-lg text-xs outline-none"
                                      value={tempThreshold}
                                      onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                      onBlur={() => handleSaveThreshold(p.productCode)}
                                      onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(p.productCode)}
                                    />
                                  ) : (
                                    <div className="flex items-center gap-2">
                                      <span className="text-slate-500 font-bold">{thresholds[p.productCode] || 0}</span>
                                      {user?.role === UserRole.ADMIN && (
                                        <button 
                                          onClick={() => {
                                            setEditingThreshold(p.productCode);
                                            setTempThreshold(thresholds[p.productCode] || 0);
                                          }}
                                          className="p-1 hover:bg-indigo-50 text-slate-300 hover:text-indigo-600 rounded-md transition-colors"
                                        >
                                          <Settings size={14} />
                                        </button>
                                      )}
                                    </div>
                                  )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                  <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-600 transition-colors ml-auto" />
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="space-y-6 animate-fade-in">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-indigo-100">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                    <div className="flex items-center gap-5">
                      <div className="w-16 h-16 rounded-3xl bg-indigo-600 flex items-center justify-center text-white shadow-lg shadow-indigo-200">
                        <Layers size={32} />
                      </div>
                      <div>
                        <p className="text-xs font-black text-indigo-500 uppercase tracking-widest leading-none mb-1">
                          {productDetailData?.info?.productCode}
                        </p>
                        <h3 className="text-3xl font-black text-slate-800 leading-tight">
                          {productDetailData?.info?.productName}
                        </h3>
                      </div>
                    </div>

                    <div className="flex gap-4">
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 min-w-[120px]">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Filtreli Stok</p>
                        <p className="text-2xl font-black text-indigo-600">{productDetailData?.stats.remaining}</p>
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 min-w-[120px]">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Giriş/Çıkış</p>
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-bold text-emerald-600">+{productDetailData?.stats.in}</span>
                          <span className="text-xs font-bold text-rose-600">-{productDetailData?.stats.out}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 p-4 bg-slate-50 rounded-3xl border border-slate-100">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-1 flex items-center gap-1">
                        <Filter size={10} /> Beden Filtresi
                      </label>
                      <select 
                        value={detailFilters.size}
                        onChange={(e) => setDetailFilters(prev => ({...prev, size: e.target.value}))}
                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold"
                      >
                        <option value="">Tüm Bedenler</option>
                        {productDetailData?.filterOptions.sizes.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-1 flex items-center gap-1">
                        <Filter size={10} /> Renk Filtresi
                      </label>
                      <select 
                        value={detailFilters.color}
                        onChange={(e) => setDetailFilters(prev => ({...prev, color: e.target.value}))}
                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold"
