const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [showAdd, setShowAdd] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const [newUsername, setNewUsername] = useState('');
  const [newPass, setNewPass] = useState('');
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState(UserRole.USER);

  const resetForm = () => {
    setShowAdd(false);
    setEditingUser(null);
    setNewUsername('');
    setNewPass('');
    setNewName('');
    setNewRole(UserRole.USER);
  };

  const handleEditClick = (user: User) => {
    setEditingUser(user);
    setNewName(user.fullName);
    setNewUsername(user.username);
    setNewPass(user.password || '');
    setNewRole(user.role);
    setShowAdd(true);
  };

  const handleSave = () => {
    if (!newUsername || !newPass || !newName) return;
    const userData: User = {
      id: editingUser ? editingUser.id : Math.random().toString(36).substr(2, 9),
      username: newUsername,
      password: newPass,
      fullName: newName,
      role: newRole
    };
    StorageService.saveUser(userData);
    setUsers(StorageService.getUsers());
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (confirm('Kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <header className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Kullanıcı Yönetimi</h2>
          <p className="text-slate-500">Personel listesi ve erişim yetkileri.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setShowAdd(true); }}
          className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2"
        >
          <Users size={18} />
          Yeni Kullanıcı
        </button>
      </header>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-indigo-100 animate-fade-in">
          <h3 className="font-bold mb-4">{editingUser ? 'Güncelle' : 'Yeni Kayıt'}</h3>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <input placeholder="Ad Soyad" value={newName} onChange={e => setNewName(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Kullanıcı Adı" value={newUsername} onChange={e => setNewUsername(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <input placeholder="Şifre" type="password" value={newPass} onChange={e => setNewPass(e.target.value)} className="p-3 bg-slate-50 border rounded-xl" />
            <select value={newRole} onChange={e => setNewRole(e.target.value as UserRole)} className="p-3 bg-slate-50 border rounded-xl">
              <option value={UserRole.USER}>Standart</option>
              <option value={UserRole.ADMIN}>Yönetici</option>
            </select>
          </div>
          <div className="flex gap-2 mt-4">
            <button onClick={handleSave} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold">Kaydet</button>
            <button onClick={resetForm} className="bg-slate-200 px-6 py-2 rounded-xl font-bold">İptal</button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {users.map(u => (
          <div key={u.id} className="bg-white p-6 rounded-2xl shadow-sm border flex items-center justify-between">
            <div>
              <p className="font-bold text-slate-800">{u.fullName}</p>
              <p className="text-sm text-slate-500">@{u.username} • {u.role}</p>
            </div>
            <div className="flex gap-2">
              <button onClick={() => handleEditClick(u)} className="p-2 text-slate-400 hover:text-indigo-600"><Edit2 size={18} /></button>
              {u.username !== 'admin' && (
                <button onClick={() => handleDelete(u.id)} className="p-2 text-slate-400 hover:text-rose-600"><Trash2 size={18} /></button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

