import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  ClipboardList,
  Info,
  TrendingUp,
  TrendingDown,
  Layers,
  Trash2,
  Undo2,
  Settings,
  Bell,
  ArrowRight
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'gen_in' | 'gen_out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [undoConfirm, setUndoConfirm] = useState<Transaction | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [extraFields, setExtraFields] = useState<Record<string, string>>({});

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    // İşlemleri en eskiden en yeniye işleyerek mevcut stoğu hesaplarız
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;

      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values()).sort((a, b) => b.remaining - a.remaining);
  }, [transactions]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      let data: Record<string, string> = {};
      const cleanText = text.trim();

      if (cleanText.startsWith('{')) {
        data = JSON.parse(cleanText);
      } else if (cleanText.includes(';;')) {
        const p = cleanText.split(';;').map(s => s.trim());
        data = { 'Firma': p[0], 'Miktar': p[1], 'Beden': p[2], 'Renk': p[4], 'Kod': p[6], 'Ad': p[7] };
      } else {
        data = { 'Kod': cleanText, 'Ad': 'Ürün ' + cleanText };
      }

      const getVal = (keys: string[]) => {
        for (const k of keys) {
          const found = Object.keys(data).find(dk => dk.toLowerCase() === k.toLowerCase());
          if (found) return data[found];
        }
        return '';
      };

      const code = getVal(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu']);
      const name = getVal(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı']);
      const qty = getVal(['miktar', 'adet', 'qty', 'quantity']);
      const ptnr = getVal(['firma', 'partner', 'tedarikci', 'tedarikciFirma', 'alıcı', 'supplier', 'recipient']);

      setProductCode(code || cleanText);
      setProductName(name || code || 'Tanımsız Ürün');

      // Çıkış modunda ise alanları boş bırak, Giriş modunda QR'daki firma/miktar gelsin
      if (activeTab.includes('out')) {
        setQuantity('');
        setPartner('');
      } else {
        setQuantity(parseInt(qty) || 1);
        setPartner(ptnr || '');
      }

      if (!activeTab.includes('gen')) {
        setSize(getVal(['beden', 'size']));
        setColor(getVal(['renk', 'color']));
        setFeature(getVal(['ozellik', 'feature']));
      } else {
        const core = ['kod', 'ad', 'miktar', 'firma', 'code', 'name', 'qty', 'partner'];
        const extras: Record<string, string> = {};
        Object.entries(data).forEach(([k, v]) => {
          if (!core.some(c => k.toLowerCase().includes(c))) extras[k] = v;
        });
        setExtraFields(extras);
      }

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('QR Kod Çözüldü', 'success');
    } catch (e) {
      showNotification('QR Geçersiz Format', 'error');
    }
  };

  const resetForm = () => {
    setIsFormActive(false);
    setProductCode('');
    setProductName('');
    setQuantity('');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleSave = () => {
    if (!productCode || quantity === '' || quantity <= 0 || !partner || !approver) {
      showNotification('Lütfen tüm zorunlu alanları doldurun!', 'error');
      return;
    }

    const currentStock = inventory.find(p => p.productCode === productCode)?.remaining || 0;
    if (activeTab.includes('out') && currentStock < (quantity as number)) {
      showNotification(`Yetersiz stok! Mevcut bakiye: ${currentStock}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem Başarıyla Kaydedildi', 'success');
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Alt limit güncellendi', 'success');
  };

  const criticalProductsCount = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    }).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Nav */}
      <div className="md:hidden bg-white border-b p-4 flex justify-between items-center sticky top-0 z-40">
        <h1 className="font-bold text-indigo-600">KaratProStock QR</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 flex flex-col h-full">
          <div className="mb-8 hidden md:block text-center">
            <h1 className="text-xl font-black text-indigo-600">KaratProStock</h1>
          </div>
          <nav className="space-y-1 flex-1 overflow-y-auto">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Dashboard" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            <div className="pt-6 pb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3">Tekstil Modülü</div>
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Giriş" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkış" />
            <div className="pt-6 pb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3">Genel Stok Modülü</div>
            <NavItem active={activeTab==='gen_in'} onClick={()=>setActiveTab('gen_in')} icon={Box} label="Genel Giriş" />
            <NavItem active={activeTab==='gen_out'} onClick={()=>setActiveTab('gen_out')} icon={ClipboardList} label="Genel Çıkış" />
            {user.role === UserRole.ADMIN && (
              <>
                <div className="pt-6 pb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3">Yönetim</div>
                <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcılar" />
              </>
            )}
          </nav>
          <div className="mt-auto pt-6 border-t">
            <div className="flex items-center gap-3 px-3 mb-4">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold text-xs">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-xs font-bold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[10px] text-slate-400 uppercase">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all">
              <LogOut size={18} /> Çıkış Yap
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        {notification && (
          <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-3 ${notification.type==='success' ? 'bg-emerald-500' : notification.type==='warning' ? 'bg-amber-500' : 'bg-rose-500'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            {notification.message}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex justify-between items-center">
              <div className="space-y-1">
                <h2 className="text-2xl font-black text-slate-800 tracking-tight">Depo İzleme Merkezi</h2>
                <p className="text-slate-400 text-sm">Anlık envanter dökümü ve stok analizleri</p>
              </div>
              {criticalProductsCount > 0 && (
                <div className="bg-rose-50 border border-rose-100 px-4 py-2 rounded-2xl flex items-center gap-2 text-rose-600 animate-pulse">
                  <Bell size={18} />
                  <span className="text-sm font-bold">{criticalProductsCount} Ürün Kritik Seviyede!</span>
                </div>
              )}
            </header>

            {/* Genişletilmiş Rapor Kartları */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <StatCard label="Mevcut Toplam Bakiye" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
              <StatCard label="Toplam Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
              <StatCard label="Toplam Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
              <StatCard label="Kritik Stok Ürünleri" val={criticalProductsCount} icon={AlertCircle} color="amber" />
            </div>

            {/* Güncel Stok & Eşik Ayarları Tablosu */}
            <div className="bg-white rounded-[2.5rem] border shadow-sm overflow-hidden p-1">
              <div className="p-6 border-b flex justify-between items-center">
                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                  <Box size={20} className="text-indigo-600" />
                  Güncel Stok & Eşik Ayarları (Tüm Kategoriler)
                </h3>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    <tr>
                      <th className="px-6 py-4">Ürün Kodu & Adı</th>
                      <th className="px-6 py-4">Mevcut Stok</th>
                      <th className="px-6 py-4">Durum</th>
                      <th className="px-6 py-4">Alt Limit</th>
                      <th className="px-6 py-4 text-right">Son Güncelleme</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {inventory.length > 0 ? inventory.map(item => {
                      const threshold = thresholds[item.productCode] || 0;
                      const isCritical = threshold > 0 && item.remaining <= threshold;

                      return (
                        <tr key={item.productCode} className="hover:bg-slate-50/50 transition-colors group">
                          <td className="px-6 py-4">
                            <div className="flex flex-col">
                              <span className="font-bold text-slate-800">{item.productName}</span>
                              <span className="text-[10px] font-mono text-indigo-500 uppercase">{item.productCode}</span>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`text-lg font-black ${isCritical ? 'text-rose-600' : 'text-slate-900'}`}>
                              {item.remaining.toLocaleString()}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            {isCritical ? (
                              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100">
                                <AlertCircle size={12} /> Kritik
                              </span>
                            ) : (
                              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase border border-emerald-100">
                                <CheckCircle2 size={12} /> Yeterli
                              </span>
                            )}
                          </td>
                          <td className="px-6 py-4">
                            {user.role === UserRole.ADMIN ? (
                              editingThreshold === item.productCode ? (
                                <div className="flex items-center gap-2">
                                  <input 
                                    type="number" 
                                    autoFocus
                                    className="w-16 px-2 py-1 border border-indigo-200 rounded-lg text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                                    value={tempThreshold}
                                    onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                    onBlur={() => handleSaveThreshold(item.productCode)}
                                    onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(item.productCode)}
                                  />
                                </div>
                              ) : (
                                <button 
                                  onClick={() => { setEditingThreshold(item.productCode); setTempThreshold(threshold); }}
                                  className="flex items-center gap-2 text-slate-500 hover:text-indigo-600 transition-colors"
                                >
                                  <span className="font-bold">{threshold}</span>
                                  <Settings size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                                </button>
                              )
                            ) : (
                              <span className="font-bold text-slate-400">{threshold}</span>
                            )}
                          </td>
                          <td className="px-6 py-4 text-right text-xs text-slate-400">
                            {item.lastUpdate}
                          </td>
                        </tr>
                      );
                    }) : (
                      <tr>
                        <td colSpan={5} className="py-20 text-center text-slate-400 italic">
                          <Info size={40} className="mx-auto mb-4 opacity-10" />
                          Sistemde henüz kayıtlı ürün bulunmuyor.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out' || activeTab === 'gen_in' || activeTab === 'gen_out') && (
          <div className="max-w-3xl mx-auto space-y-6">
            <header className="text-center space-y-2 mb-8">
              <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab.includes('in') ? 'Stok Giriş Modülü' : 'Stok Çıkış Modülü'}
              </h2>
