import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, XCircle, Loader2, Camera, ImagePlus, CheckCircle2 } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        // stop() sonrası clear() çağrısı donanımı tamamen bırakır
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const startCamera = useCallback(async () => {
    // Mevcut bir instance varsa ve çalışıyorsa durdur
    await stopScanner();

    // Yeni bir instance oluştur (dosya tarama sonrası temiz bir başlangıç için)
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const devices = await Html5Qrcode.getCameras();

      if (devices && devices.length > 0) {
        setPermissionStatus('granted');
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 20,
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0
          },
          (text) => {
            onScan(text);
            stopScanner().then(() => onClose());
          },
          () => {} // On error - vizör akarken sessiz kal
        );
      } else {
        setPermissionStatus('denied');
      }
    } catch (err) {
      console.error("Kamera başlatma hatası:", err);
      setPermissionStatus('denied');
    } finally {
      setIsInitializing(false);
    }
  }, [onScan, stopScanner, onClose]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, [startCamera, stopScanner]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);

    try {
      // 1. Kamerayı durdur ve donanımı serbest bırak
      await stopScanner();

      // 2. Kısa bir bekleme (tarayıcının donanımı bırakması için)
      await new Promise(resolve => setTimeout(resolve, 400));

      // 3. Dosya tarama işlemi
      // Not: Instance oluşturulmamış olsa bile scanFile statik olarak çalışabilir
      // Ancak mevcut instance üzerinden yapmak daha stabil sonuç verir
      const tempScanner = new Html5Qrcode(scannerId);
      const decodedText = await tempScanner.scanFile(file, true);

      if (decodedText) {
        onScan(decodedText);
        onClose();
      } else {
        throw new Error("QR Kod tespit edilemedi.");
      }
    } catch (err) {
      console.error("Dosya tarama hatası:", err);
      setFileError("Seçilen görselden QR kod okunamadı. Lütfen daha net bir görsel seçin veya kamerayı kullanın.");

      // Hata durumunda kamerayı tekrar canlandır
      setTimeout(() => {
        startCamera();
      }, 1000);

      setTimeout(() => setFileError(null), 6000);
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/95 backdrop-blur-lg p-4 transition-all duration-300">
      <div className="bg-white w-full max-w-md rounded-[3rem] overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.3)] animate-fade-in border border-white/20">

        <div className="p-7 flex justify-between items-center border-b border-slate-100 bg-white/50 backdrop-blur-sm">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">QR Tarayıcı</h3>
            <div className="flex items-center gap-2">
              <span className={`flex h-2 w-2 rounded-full ${isProcessingFile ? 'bg-amber-500 animate-bounce' : 'bg-emerald-500 animate-pulse'}`}></span>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                {isProcessingFile ? 'Görsel Analiz Ediliyor' : 'Sistem Hazır'}
              </p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3 bg-slate-100 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all active:scale-90"
          >
            <XCircle size={24} />
          </button>
        </div>

        <div className="p-8 flex flex-col items-center">
          <div className="w-full relative aspect-square mb-8 group">
            {/* Vizör Çerçevesi */}
            <div className="absolute -inset-2 border-2 border-indigo-500/20 rounded-[2.5rem] pointer-events-none group-hover:border-indigo-500/40 transition-colors duration-500"></div>

            <div 
              id={scannerId} 
              className={`w-full h-full rounded-[2rem] overflow-hidden bg-slate-900 shadow-inner border-4 border-white relative z-0 ${permissionStatus === 'granted' || isInitializing ? 'block' : 'hidden'}`}
            ></div>

            {permissionStatus === 'denied' && !isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center space-y-4 bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <div className="p-5 bg-white rounded-3xl shadow-sm text-slate-300">
                  <Camera size={48} />
                </div>
                <div className="px-10">
                  <p className="text-slate-600 font-bold">Kamera İzni Gerekli</p>
                  <p className="text-slate-400 text-xs mt-2 leading-relaxed">QR tarama için tarayıcı ayarlarından kamera izni vermeniz veya dosyadan yükleme yapmanız gerekir.</p>
                </div>
              </div>
            )}

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-slate-900 rounded-[2rem] z-10">
                <Loader2 size={40} className="text-indigo-400 animate-spin" />
                <p className="text-[10px] font-black text-indigo-400/60 uppercase tracking-widest">Vizör Başlatılıyor</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600/95 backdrop-blur-md flex flex-col items-center justify-center rounded-[2rem] z-20 animate-fade-in text-white">
                <div className="relative">
                  <div className="absolute -inset-4 bg-white/20 rounded-full animate-ping"></div>
                  <Loader2 size={48} className="animate-spin relative" />
                </div>
                <p className="font-black text-lg tracking-tight mt-6">Görsel Okunuyor</p>
                <p className="text-indigo-200 text-[10px] uppercase font-bold tracking-widest mt-1">Lütfen bekleyin...</p>
              </div>
            )}

            {/* Tarayıcı Animasyon Çizgisi */}
            {permissionStatus === 'granted' && !isProcessingFile && !isInitializing && (
              <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent z-10 animate-[scan_2.5s_ease-in-out_infinite] opacity-60"></div>
            )}
          </div>

          <div className="w-full space-y-4">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*"
              className="hidden"
            />

            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isProcessingFile}
              className="w-full flex items-center justify-center gap-4 py-5 bg-slate-900 text-white rounded-2xl hover:bg-slate-800 transition-all shadow-xl shadow-slate-200 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none group"
            >
              <div className="p-2 bg-white/10 rounded-xl group-hover:scale-110 transition-transform">
                <ImagePlus size={20} />
              </div>
              <div className="text-left">
                <p className="font-black text-sm leading-none">Dosyadan QR Yükle</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter mt-1">Ekran Görüntüsü veya Fotoğraf</p>
              </div>
            </button>

            {fileError && (
              <div className="flex items-start gap-3 p-5 bg-rose-50 text-rose-600 rounded-2xl text-xs font-bold border border-rose-100 animate-fade-in">
                <AlertCircle size={20} className="shrink-0" />
                <p className="leading-relaxed">{fileError}</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-slate-50 p-5 text-center border-t border-slate-100">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">KaratProStock Vision Engine v2.5</p>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { 
          width: 100% !important; 
          height: 100% !important; 
          object-fit: cover !important;
          border-radius: 1.5rem;
        }
        #qr-reader-container { 
          border: none !important; 
        }
        @keyframes scan {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(350px); opacity: 0; }
        }
      `}</style>
    </div>
  );
};

