import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { AlertCircle, XCircle, Loader2, Camera, ImagePlus, CheckCircle2, Zap } from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const startCamera = useCallback(async () => {
    await stopScanner();
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const devices = await Html5Qrcode.getCameras();

      if (devices && devices.length > 0) {
        setPermissionStatus('granted');
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 25,
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0
          },
          (text) => {
            onScan(text);
            stopScanner().then(() => onClose());
          },
          () => {} 
        );
      } else {
        setPermissionStatus('denied');
      }
    } catch (err) {
      console.error("Kamera başlatma hatası:", err);
      setPermissionStatus('denied');
    } finally {
      setIsInitializing(false);
    }
  }, [onScan, stopScanner, onClose]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, [startCamera, stopScanner]);

  const processImage = (file: File, contrast: number = 1, grayscale: boolean = false): Promise<File> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject('Canvas context error');

          canvas.width = img.width;
          canvas.height = img.height;

          // Apply filters
          let filter = '';
          if (grayscale) filter += 'grayscale(100%) ';
          if (contrast !== 1) filter += `contrast(${contrast * 100}%) `;
          if (filter) ctx.filter = filter.trim();

          ctx.drawImage(img, 0, 0);

          canvas.toBlob((blob) => {
            if (blob) {
              const processedFile = new File([blob], file.name, { type: 'image/jpeg' });
              resolve(processedFile);
            } else {
              reject('Blob conversion error');
            }
          }, 'image/jpeg', 0.95);
        };
        img.onerror = reject;
        img.src = e.target?.result as string;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Orijinal Görsel Analiz Ediliyor');

    try {
      await stopScanner();
      await new Promise(resolve => setTimeout(resolve, 300));
      const tempScanner = new Html5Qrcode(scannerId);

      // Pass 1: Orijinal
      try {
        const result = await tempScanner.scanFile(file, true);
        onScan(result);
        return onClose();
      } catch (e) {
        console.log("Pass 1 failed, trying Pass 2...");
