  // Görüntü iyileştirme fonksiyonu
  const enhanceImage = (file: File, options: { 
    contrast?: number, 
    grayscale?: boolean, 
    sharpen?: boolean,
    scale?: number 
  }): Promise<File> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d', { willReadFrequently: true });
          if (!ctx) return reject('Canvas context error');

          // QR okuma başarısı için boyutu normalize et (Minimum 1000px)
          let width = img.width;
          let height = img.height;
          const minSize = 1000;

          if (options.scale) {
            width *= options.scale;
            height *= options.scale;
          } else if (Math.max(width, height) < minSize) {
            const ratio = minSize / Math.max(width, height);
            width *= ratio;
            height *= ratio;
          }

          canvas.width = width;
          canvas.height = height;

          // Filtreleri uygula
          let filter = '';
          if (options.grayscale) filter += 'grayscale(100%) ';
          if (options.contrast && options.contrast !== 1) filter += `contrast(${options.contrast * 100}%) `;
          if (filter) ctx.filter = filter.trim();

          ctx.drawImage(img, 0, 0, width, height);

          // Keskinleştirme (Sharpening) filtresi - Bulanık QR'lar için kritik
          if (options.sharpen) {
            const imageData = ctx.getImageData(0, 0, width, height);
            const data = imageData.data;
            const originalData = new Uint8ClampedArray(data);
            const weights = [0, -1, 0, -1, 5, -1, 0, -1, 0]; // Sharpen matrix

            for (let y = 1; y < height - 1; y++) {
              for (let x = 1; x < width - 1; x++) {
                for (let c = 0; c < 3; c++) {
                  let val = 0;
                  for (let ky = -1; ky <= 1; ky++) {
                    for (let kx = -1; kx <= 1; kx++) {
                      const idx = ((y + ky) * width + (x + kx)) * 4 + c;
                      val += originalData[idx] * weights[(ky + 1) * 3 + (kx + 1)];
                    }
                  }
                  data[(y * width + x) * 4 + c] = Math.min(255, Math.max(0, val));
                }
              }
            }
            ctx.putImageData(imageData, 0, 0);
          }

          canvas.toBlob((blob) => {
            if (blob) {
              const processedFile = new File([blob], file.name, { type: 'image/jpeg' });
              resolve(processedFile);
            } else {
              reject('Blob error');
            }
          }, 'image/jpeg', 0.9);
        };
        img.onerror = reject;
        img.src = e.target?.result as string;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Orijinal Görsel Taranıyor...');

    try {
      await stopScanner();
      await new Promise(resolve => setTimeout(resolve, 500));
      const tempScanner = new Html5Qrcode(scannerId);

