      setScanStep('Görüntü İyileştiriliyor (Gri/Kontrast)...');
      try {
        const p2 = await enhanceImage(file, { grayscale: true, contrast: 1.5 });
        const result = await tempScanner.scanFile(p2, false);
        onScan(result);
        return onClose();
      } catch (e) { console.log("Pass 2 failed"); }

      // PASS 3: Keskinleştirme (Bulanık görseller için)
      setScanStep('Keskinleştirme Uygulanıyor (Bulanıklık Giderici)...');
      try {
        const p3 = await enhanceImage(file, { grayscale: true, contrast: 2.0, sharpen: true });
        const result = await tempScanner.scanFile(p3, false);
        onScan(result);
        return onClose();
      } catch (e) { console.log("Pass 3 failed"); }

      // PASS 4: Ekstrem Kontrast + %150 Büyütme (Küçük QR'lar için)
      setScanStep('Derin Analiz (Ekstrem Kontrast & Zoom)...');
      try {
        const p4 = await enhanceImage(file, { grayscale: true, contrast: 3.5, scale: 1.5 });
        const result = await tempScanner.scanFile(p4, false);
        onScan(result);
        return onClose();
      } catch (e) {
        throw new Error("QR kod tespit edilemedi. Lütfen daha net bir fotoğraf çekin veya QR kodu kadraja daha yakın tutun.");
      }

    } catch (err: any) {
      setFileError(err.message || "QR kod okunamadı.");
      // Hata durumunda kamerayı canlandır
      setTimeout(() => startCamera(), 1500);
      setTimeout(() => setFileError(null), 6000);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/95 backdrop-blur-2xl p-4 transition-all duration-300">
      <div className="bg-white w-full max-w-md rounded-[3.5rem] overflow-hidden shadow-[0_25px_70px_rgba(0,0,0,0.6)] animate-fade-in border border-white/20">

        <div className="p-8 flex justify-between items-center border-b border-slate-100 bg-white">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">QR Vizör</h3>
            <div className="flex items-center gap-2">
              <span className={`flex h-2.5 w-2.5 rounded-full ${isProcessingFile ? 'bg-amber-500 animate-pulse' : 'bg-indigo-500 animate-pulse'}`}></span>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                {isProcessingFile ? 'Vision AI İşleniyor' : 'Kamera Aktif'}
              </p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3.5 bg-slate-50 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-3xl transition-all active:scale-90"
          >
            <XCircle size={26} />
          </button>
        </div>

        <div className="p-8 flex flex-col items-center">
          <div className="w-full relative aspect-square mb-8 group">
            {/* Vizör Çerçeve Efekti */}
            <div className="absolute -inset-4 border-2 border-indigo-500/10 rounded-[4rem] pointer-events-none group-hover:border-indigo-500/20 transition-all duration-700"></div>

            <div 
              id={scannerId} 
              className={`w-full h-full rounded-[3rem] overflow-hidden bg-slate-950 shadow-2xl border-4 border-white relative z-0 ${permissionStatus === 'granted' || isInitializing ? 'block' : 'hidden'}`}
            ></div>

            {permissionStatus === 'denied' && !isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center space-y-4 bg-slate-50 rounded-[3rem] border-2 border-dashed border-slate-200">
                <Camera size={56} className="text-slate-200" />
                <div className="px-10">
                  <p className="text-slate-600 font-bold">Kamera Erişimi Yok</p>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-2 leading-relaxed">Ayarlardan izin verin veya dosyadan yükleyin</p>
                </div>
              </div>
            )}

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-5 bg-slate-950 rounded-[3rem] z-10">
                <Loader2 size={44} className="text-indigo-400 animate-spin" />
                <p className="text-[10px] font-black text-indigo-400/60 uppercase tracking-[0.3em]">Hardware Sync...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center rounded-[3rem] z-20 animate-fade-in text-white overflow-hidden shadow-inner">
