            )}

            {permissionStatus === 'granted' && !isProcessingFile && !isInitializing && (
              <div className="absolute top-0 left-0 w-full h-1.5 bg-indigo-400 z-10 animate-[scan_3s_ease-in-out_infinite] opacity-60 shadow-[0_0_20px_rgba(129,140,248,1)]"></div>
            )}
