      stopScanner();
    };
  }, [startCamera, stopScanner]);

  // Hibrit Görüntü İşleme ve Analiz Fonksiyonu
  const processImage = async (img: HTMLImageElement, options: { 
    contrast?: number, 
    grayscale?: boolean, 
    threshold?: number,
    sharpen?: boolean,
    width?: number 
  }): Promise<string> => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error('Canvas context error');

    let width = options.width || img.width;
    let height = (img.height / img.width) * width;

    canvas.width = width;
    canvas.height = height;

    // Filtreleri uygula
    let filters = [];
    if (options.grayscale) filters.push('grayscale(100%)');
    if (options.contrast) filters.push(`contrast(${options.contrast * 100}%)`);
    if (filters.length > 0) ctx.filter = filters.join(' ');

    ctx.drawImage(img, 0, 0, width, height);

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Eşikleme (Binarization) Algoritması - QR için en etkili yöntem
    if (options.threshold) {
      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > options.threshold ? 255 : 0;
        data[i] = data[i+1] = data[i+2] = val;
      }
    }

    // Keskinleştirme (Sharpening convolution)
    if (options.sharpen) {
      const weights = [0, -1, 0, -1, 5, -1, 0, -1, 0];
      const side = Math.round(Math.sqrt(weights.length));
      const halfSide = Math.floor(side / 2);
      const src = data;
      const sw = width;
      const sh = height;
      const outputData = ctx.createImageData(sw, sh);
      const dst = outputData.data;

      for (let y = 0; y < sh; y++) {
        for (let x = 0; x < sw; x++) {
          const sy = y;
          const sx = x;
          const dstOff = (y * sw + x) * 4;
          let r = 0, g = 0, b = 0;
          for (let cy = 0; cy < side; cy++) {
            for (let cx = 0; cx < side; cx++) {
              const scy = sy + cy - halfSide;
              const scx = sx + cx - halfSide;
              if (scy >= 0 && scy < sh && scx >= 0 && scx < sw) {
                const srcOff = (scy * sw + scx) * 4;
                const wt = weights[cy * side + cx];
                r += src[srcOff] * wt;
                g += src[srcOff + 1] * wt;
                b += src[srcOff + 2] * wt;
              }
            }
          }
          dst[dstOff] = r;
          dst[dstOff + 1] = g;
          dst[dstOff + 2] = b;
          dst[dstOff + 3] = 255;
        }
      }
      ctx.putImageData(outputData, 0, 0);
    } else {
      ctx.putImageData(imageData, 0, 0);
    }

    return canvas.toDataURL('image/jpeg', 0.9);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Hibrit Analiz Motoru Başlatılıyor...');

    try {
      await stopScanner();
      await new Promise(resolve => setTimeout(resolve, 300));

      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      const tempScanner = new Html5Qrcode(scannerId);

      // AŞAMA 1: Native Barcode Detector (Varsa)
      setScanStep('Donanım Hızlandırıcı Kullanılıyor...');
      if ('BarcodeDetector' in window) {
        try {
          // @ts-ignore
          const detector = new window.BarcodeDetector({ formats: ['qr_code'] });
          const barcodes = await detector.detect(img);
          if (barcodes.length > 0) {
            onScan(barcodes[0].rawValue);
            return onClose();
          }
        } catch (e) { console.warn("Native Detector failed"); }
      }

      // AŞAMA 2: Ham Görsel Taraması
      setScanStep('Orijinal Veri Taranıyor...');
      try {
        const res = await tempScanner.scanFile(file, false);
        onScan(res);
        return onClose();
      } catch (e) { }

      // AŞAMA 3: Normalizasyon (1200px + Gri Tonlama)
      setScanStep('Görsel Normalize Ediliyor (1200px)...');
      try {
        const dataUrl = await processImage(img, { width: 1200, grayscale: true, contrast: 1.2 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) { }

      // AŞAMA 4: Adaptive Thresholding (QR için kritik aşama)
      setScanStep('Adaptif Eşikleme Analizi (Binarization)...');
      try {
        const dataUrl = await processImage(img, { width: 800, threshold: 128 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) { }

      // AŞAMA 5: Derin Tarama (Keskinleştirme + Yüksek Kontrast)
      setScanStep('Derin Analiz ve Kenar Belirginleştirme...');
      try {
        const dataUrl = await processImage(img, { width: 1000, sharpen: true, contrast: 2.5, grayscale: true });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) {
        throw new Error("QR kod okunamadı. Lütfen görselin net olduğundan ve QR kodun tamamının göründüğünden emin olun.");
      }

    } catch (err: any) {
      setFileError(err.message);
      setTimeout(() => startCamera(), 1000);
      setTimeout(() => setFileError(null), 5000);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/98 backdrop-blur-3xl p-4 transition-all duration-500">
      <div className="bg-white w-full max-w-lg rounded-[4rem] overflow-hidden shadow-[0_30px_100px_rgba(0,0,0,0.7)] animate-fade-in border border-white/10">

        <div className="p-10 flex justify-between items-center border-b border-slate-50 bg-white">
          <div className="space-y-1.5">
            <h3 className="font-black text-3xl text-slate-800 tracking-tight">Hibrit QR Vizör</h3>
            <div className="flex items-center gap-2.5">
              <span className={`flex h-3 w-3 rounded-full ${isProcessingFile ? 'bg-amber-500 animate-pulse' : 'bg-indigo-600 animate-pulse'}`}></span>
              <p className="text-[11px] text-slate-400 font-black uppercase tracking-widest">
                {isProcessingFile ? 'Vision AI Katmanı Aktif' : 'Donanım Hızlandırma Hazır'}
              </p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-4 bg-slate-50 hover:bg-rose-50 text-slate-400 hover:text-rose-600 rounded-[2rem] transition-all active:scale-90"
          >
            <XCircle size={28} />
          </button>
        </div>

        <div className="p-10 flex flex-col items-center">
          <div className="w-full relative aspect-square mb-10 group">
            {/* Animasyonlu Çerçeve */}
            <div className="absolute -inset-5 border-2 border-indigo-500/5 rounded-[5rem] pointer-events-none group-hover:border-indigo-500/15 transition-all duration-1000"></div>
            <div className="absolute -inset-1 border border-indigo-500/20 rounded-[3.5rem] pointer-events-none"></div>

            <div 
              id={scannerId} 
              className={`w-full h-full rounded-[3rem] overflow-hidden bg-slate-950 shadow-2xl border-[6px] border-white relative z-0 ${permissionStatus === 'granted' || isInitializing ? 'block' : 'hidden'}`}
            ></div>

            {permissionStatus === 'denied' && !isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center space-y-6 bg-slate-50 rounded-[3rem] border-4 border-dashed border-slate-200">
                <div className="p-6 bg-white rounded-full shadow-lg text-slate-200">
                    <Camera size={64} />
                </div>
                <div className="px-12 space-y-2">
                  <p className="text-slate-700 font-black text-lg">Kamera Bağlantısı Yok</p>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest leading-relaxed">Donanım izni alınamadı, dosyadan yükleme yapabilirsiniz.</p>
                </div>
              </div>
            )}

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-6 bg-slate-950 rounded-[3rem] z-10">
                <div className="relative">
                    <div className="absolute inset-0 bg-indigo-500/20 rounded-full blur-2xl animate-pulse"></div>
                    <Loader2 size={56} className="text-indigo-500 animate-spin relative" />
                </div>
                <p className="text-[11px] font-black text-indigo-400/60 uppercase tracking-[0.4em]">Engine Booting...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-700 flex flex-col items-center justify-center rounded-[3rem] z-20 animate-fade-in text-white overflow-hidden">
                <div className="absolute inset-0 opacity-40 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
                <div className="relative mb-10">
                  <Zap size={72} className="text-amber-400 animate-[bounce_1s_infinite] shadow-amber-500" />
                  <div className="absolute -inset-8 bg-white/10 rounded-full animate-ping"></div>
                </div>
                <div className="text-center px-10 space-y-3 relative">
                    <p className="font-black text-2xl tracking-tight uppercase leading-none">{scanStep}</p>
                    <p className="text-indigo-200 text-xs font-black uppercase tracking-[0.3em] opacity-70">Aşama {scanStep.includes('Donanım') ? '1' : scanStep.includes('Orijinal') ? '2' : scanStep.includes('Normal') ? '3' : '4'}/4</p>
                </div>
                <div className="mt-12 flex gap-3">
                    <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
                    <div className="w-3 h-3 bg-white/60 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-3 h-3 bg-white/30 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                </div>
              </div>
            )}

            {permissionStatus === 'granted' && !isProcessingFile && !isInitializing && (
              <div className="absolute top-0 left-0 w-full h-2 bg-indigo-500 z-10 animate-[scan_3.5s_ease-in-out_infinite] opacity-80 shadow-[0_0_30px_rgba(99,102,241,1)]"></div>
            )}
          </div>

          <div className="w-full space-y-5">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*"
              className="hidden"
            />

            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isProcessingFile}
              className="w-full flex items-center justify-center gap-6 py-7 bg-slate-900 text-white rounded-[2.5rem] hover:bg-indigo-600 transition-all shadow-[0_20px_40px_rgba(0,0,0,0.2)] active:scale-[0.96] disabled:opacity-50 group border-b-4 border-slate-950 hover:border-indigo-800"
            >
              <div className="p-3.5 bg-white/10 rounded-2xl group-hover:bg-white group-hover:text-indigo-600 transition-all">
                <ImagePlus size={28} />
              </div>
              <div className="text-left">
                <p className="font-black text-lg leading-none">Dosyadan Fotoğraf Seç</p>
                <p className="text-[11px] text-slate-400 font-bold uppercase tracking-widest mt-2 group-hover:text-indigo-100 transition-colors">Hybrid Vision Engine v4.0</p>
              </div>
            </button>

            {fileError && (
              <div className="flex items-start gap-4 p-7 bg-rose-50 text-rose-600 rounded-[2.5rem] text-xs font-bold border border-rose-100 animate-fade-in shadow-sm">
                <AlertCircle size={24} className="shrink-0 mt-0.5" />
                <p className="leading-relaxed">{fileError}</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-slate-50 p-8 text-center border-t border-slate-100 flex items-center justify-center gap-4">
            <Maximize size={18} className="text-indigo-600" />
            <p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Precision Scanning: Ultra High</p>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { 
          width: 100% !important; 
          height: 100% !important; 
          object-fit: cover !important;
          border-radius: 2.5rem;
        }
        #qr-reader-container { 
          border: none !important; 
        }
        @keyframes scan {
          0% { transform: translateY(0); opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { transform: translateY(400px); opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default Scanner;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  AlertCircle, 
  XCircle, 
  Loader2, 
  Camera, 
  ImagePlus, 
  Zap, 
  Maximize, 
  Settings2, 
  Sun, 
  Contrast, 
  Wind, 
  Binary,
  RotateCcw,
  SlidersHorizontal
} from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

interface ManualSettings {
  brightness: number;
  contrast: number;
  sharpen: number;
  threshold: number;
  useManual: boolean;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);

  // Manuel Ayarlar
  const [settings, setSettings] = useState<ManualSettings>({
    brightness: 1.0,
    contrast: 1.5,
    sharpen: 1,
    threshold: 128,
    useManual: false
  });

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const startCamera = useCallback(async () => {
    await stopScanner();
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const devices = await Html5Qrcode.getCameras();

      if (devices && devices.length > 0) {
        setPermissionStatus('granted');
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 30,
            qrbox: { width: 260, height: 260 },
            aspectRatio: 1.0
          },
          (text) => {
            onScan(text);
            stopScanner().then(() => onClose());
          },
          () => {} 
        );
      } else {
        setPermissionStatus('denied');
      }
    } catch (err) {
      setPermissionStatus('denied');
    } finally {
      setIsInitializing(false);
    }
  }, [onScan, stopScanner, onClose]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, [startCamera, stopScanner]);

  const processImage = async (img: HTMLImageElement, options: { 
    contrast?: number, 
    brightness?: number,
    grayscale?: boolean, 
    threshold?: number,
    sharpen?: number,
    width?: number 
  }): Promise<string> => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error('Canvas context error');

    let width = options.width || img.width;
    let height = (img.height / img.width) * width;

    canvas.width = width;
    canvas.height = height;

    let filters = [];
    if (options.grayscale) filters.push('grayscale(100%)');
    if (options.contrast) filters.push(`contrast(${options.contrast * 100}%)`);
    if (options.brightness) filters.push(`brightness(${options.brightness * 100}%)`);
    if (filters.length > 0) ctx.filter = filters.join(' ');

    ctx.drawImage(img, 0, 0, width, height);

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Eşikleme (Binarization)
    if (options.threshold) {
      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > options.threshold ? 255 : 0;
        data[i] = data[i+1] = data[i+2] = val;
      }
    }

    // Gelişmiş Keskinleştirme (Convolution Matrix based on weight)
    if (options.sharpen && options.sharpen > 0) {
      const amount = options.sharpen;
      const weights = [0, -amount, 0, -amount, 1 + 4*amount, -amount, 0, -amount, 0];
      const side = 3;
      const halfSide = 1;
      const src = data;
      const sw = width;
      const sh = height;
      const outputData = ctx.createImageData(sw, sh);
      const dst = outputData.data;

      for (let y = 0; y < sh; y++) {
        for (let x = 0; x < sw; x++) {
          const dstOff = (y * sw + x) * 4;
          let r = 0, g = 0, b = 0;
          for (let cy = 0; cy < side; cy++) {
            for (let cx = 0; cx < side; cx++) {
              const scy = y + cy - halfSide;
              const scx = x + cx - halfSide;
              if (scy >= 0 && scy < sh && scx >= 0 && scx < sw) {
                const srcOff = (scy * sw + scx) * 4;
                const wt = weights[cy * side + cx];
                r += src[srcOff] * wt;
                g += src[srcOff + 1] * wt;
                b += src[srcOff + 2] * wt;
              }
            }
          }
          dst[dstOff] = Math.min(255, Math.max(0, r));
          dst[dstOff + 1] = Math.min(255, Math.max(0, g));
          dst[dstOff + 2] = Math.min(255, Math.max(0, b));
          dst[dstOff + 3] = 255;
        }
      }
      ctx.putImageData(outputData, 0, 0);
    } else {
      ctx.putImageData(imageData, 0, 0);
    }

    return canvas.toDataURL('image/jpeg', 0.9);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Analiz Hazırlanıyor...');

    try {
      await stopScanner();
      await new Promise(resolve => setTimeout(resolve, 300));

      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      const tempScanner = new Html5Qrcode(scannerId);

      // EĞER MANUEL MOD AKTİFSE SADECE ONU DENE
      if (settings.useManual) {
        setScanStep('Özel Ayarlar Uygulanıyor...');
        const dataUrl = await processImage(img, { 
          width: 1200, 
          grayscale: true, 
          contrast: settings.contrast,
          brightness: settings.brightness,
          sharpen: settings.sharpen,
          threshold: settings.threshold
        });
        try {
          const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
          onScan(res);
          return onClose();
        } catch (e) {
          throw new Error("Belirlediğiniz ayarlarla kod okunamadı. Lütfen ayarları güncelleyin veya 'Hibrit Mod'a geri dönün.");
        }
      }

      // HİBRİT OTOMATİK MOD (Mevcut Başarılı Akış)
      setScanStep('Hibrit Mod: Donanım Analizi...');
      if ('BarcodeDetector' in window) {
        try {
          // @ts-ignore
          const detector = new window.BarcodeDetector({ formats: ['qr_code'] });
          const barcodes = await detector.detect(img);
          if (barcodes.length > 0) {
            onScan(barcodes[0].rawValue);
            return onClose();
          }
        } catch (e) {}
      }

      setScanStep('Hibrit Mod: Ham Veri Taraması...');
      try {
        const res = await tempScanner.scanFile(file, false);
        onScan(res);
        return onClose();
      } catch (e) {}

      setScanStep('Hibrit Mod: Gri Normalizasyonu...');
      try {
        const dataUrl = await processImage(img, { width: 1200, grayscale: true, contrast: 1.5 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) {}

      setScanStep('Hibrit Mod: Derin Eşikleme...');
      try {
        const dataUrl = await processImage(img, { width: 900, threshold: 128, contrast: 2.0 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) {
        throw new Error("QR kod otomatik olarak algılanamadı. Lütfen 'Gelişmiş Ayarlar'ı kullanarak görseli manuel optimize edin.");
      }

    } catch (err: any) {
      setFileError(err.message);
      setTimeout(() => startCamera(), 1000);
      setTimeout(() => setFileError(null), 7000);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const resetManualSettings = () => {
    setSettings({
      brightness: 1.0,
      contrast: 1.5,
      sharpen: 1,
      threshold: 128,
      useManual: true
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/95 backdrop-blur-3xl p-4 transition-all duration-500 overflow-y-auto">
      <div className="bg-white w-full max-w-lg rounded-[4rem] overflow-hidden shadow-[0_40px_120px_rgba(0,0,0,0.8)] animate-fade-in border border-white/20 my-auto">

        <div className="p-8 flex justify-between items-center border-b border-slate-50">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">Hibrit Vision Pro</h3>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Engine v4.2 Precision</p>
          </div>
          <div className="flex gap-2">
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`p-3 rounded-2xl transition-all active:scale-90 ${showSettings ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                title="Hassas Ayarlar"
            >
                <SlidersHorizontal size={22} />
            </button>
            <button 
                onClick={onClose}
                className="p-3 bg-rose-50 hover:bg-rose-100 text-rose-500 rounded-2xl transition-all active:scale-90"
            >
                <XCircle size={22} />
            </button>
          </div>
        </div>

        <div className="p-8 space-y-8">
          {/* Vizör Alanı */}
          <div className="relative aspect-square group">
            <div className={`absolute -inset-1 rounded-[3.5rem] bg-gradient-to-tr from-indigo-500/20 to-purple-500/20 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none`}></div>

            <div 
              id={scannerId} 
