                        <input type="range" min="0" max="10" step="1" value={settings.sharpen} onChange={e => setSettings({...settings, sharpen: parseInt(e.target.value)})} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    </div>

                    <div className="space-y-3">
