}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);

  // Manuel Ayarlar
  const [settings, setSettings] = useState<ManualSettings>({
    brightness: 1.0,
    contrast: 1.5,
    sharpen: 1,
    threshold: 128,
    useManual: false
  });

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const startCamera = useCallback(async () => {
    await stopScanner();
    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const devices = await Html5Qrcode.getCameras();

      if (devices && devices.length > 0) {
        setPermissionStatus('granted');
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 30,
            qrbox: { width: 260, height: 260 },
            aspectRatio: 1.0
          },
          (text) => {
            onScan(text);
            stopScanner().then(() => onClose());
          },
          () => {} 
        );
      } else {
        setPermissionStatus('denied');
      }
    } catch (err) {
      setPermissionStatus('denied');
    } finally {
      setIsInitializing(false);
    }
  }, [onScan, stopScanner, onClose]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, [startCamera, stopScanner]);

  const processImage = async (img: HTMLImageElement, options: { 
    contrast?: number, 
    brightness?: number,
    grayscale?: boolean, 
    threshold?: number,
    sharpen?: number,
    width?: number 
  }): Promise<string> => {
    const canvas = document.createElement('canvas');
    // willReadFrequently performansı artırmak için eklenmiştir
    const ctx = canvas.getContext('2d', { willReadFrequently: true } as any) as CanvasRenderingContext2D | null;
    if (!ctx) throw new Error('Canvas context error');

    let width = options.width || img.width;
    let height = (img.height / img.width) * width;

    canvas.width = width;
    canvas.height = height;

    let filters = [];
    if (options.grayscale) filters.push('grayscale(100%)');
    if (options.contrast) filters.push(`contrast(${options.contrast * 100}%)`);
    if (options.brightness) filters.push(`brightness(${options.brightness * 100}%)`);
    if (filters.length > 0) ctx.filter = filters.join(' ');

    ctx.drawImage(img, 0, 0, width, height);

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Eşikleme (Binarization)
    if (options.threshold) {
      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > options.threshold ? 255 : 0;
        data[i] = data[i+1] = data[i+2] = val;
      }
    }

    // Gelişmiş Keskinleştirme (Convolution Matrix)
    if (options.sharpen && options.sharpen > 0) {
      const amount = options.sharpen;
      const weights = [0, -amount, 0, -amount, 1 + 4*amount, -amount, 0, -amount, 0];
      const side = 3;
      const halfSide = 1;
      const src = data;
      const sw = width;
      const sh = height;
      const outputData = ctx.createImageData(sw, sh);
      const dst = outputData.data;

      for (let y = 0; y < sh; y++) {
        for (let x = 0; x < sw; x++) {
          const dstOff = (y * sw + x) * 4;
          let r = 0, g = 0, b = 0;
          for (let cy = 0; cy < side; cy++) {
            for (let cx = 0; cx < side; cx++) {
              const scy = y + cy - halfSide;
              const scx = x + cx - halfSide;
              if (scy >= 0 && scy < sh && scx >= 0 && scx < sw) {
                const srcOff = (scy * sw + scx) * 4;
                const wt = weights[cy * side + cx];
                r += src[srcOff] * wt;
                g += src[srcOff + 1] * wt;
                b += src[srcOff + 2] * wt;
              }
            }
          }
          dst[dstOff] = Math.min(255, Math.max(0, r));
          dst[dstOff + 1] = Math.min(255, Math.max(0, g));
          dst[dstOff + 2] = Math.min(255, Math.max(0, b));
          dst[dstOff + 3] = 255;
        }
      }
      ctx.putImageData(outputData, 0, 0);
    } else {
      ctx.putImageData(imageData, 0, 0);
    }

    return canvas.toDataURL('image/jpeg', 0.9);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Analiz Hazırlanıyor...');

    try {
      await stopScanner();
      await new Promise(resolve => setTimeout(resolve, 300));

      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      const tempScanner = new Html5Qrcode(scannerId);

      // MANUEL MOD
      if (settings.useManual) {
        setScanStep('Özel Ayarlar Uygulanıyor...');
        const dataUrl = await processImage(img, { 
          width: 1200, 
          grayscale: true, 
          contrast: settings.contrast,
          brightness: settings.brightness,
          sharpen: settings.sharpen,
          threshold: settings.threshold
        });
        try {
          const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
          onScan(res);
          return onClose();
        } catch (e) {
          throw new Error("Mevcut ayarlar ile kod çözülemedi. Lütfen ayarları optimize edin veya Otomatik Mod'u deneyin.");
        }
      }

      // HİBRİT OTOMATİK MOD
      setScanStep('Hibrit: Native Donanım Analizi...');
      if ('BarcodeDetector' in window) {
        try {
          // @ts-ignore
          const detector = new window.BarcodeDetector({ formats: ['qr_code'] });
          const barcodes = await detector.detect(img);
          if (barcodes.length > 0) {
            onScan(barcodes[0].rawValue);
            return onClose();
          }
        } catch (e) {}
      }

      setScanStep('Hibrit: Ham Veri Taraması...');
      try {
        const res = await tempScanner.scanFile(file, false);
        onScan(res);
        return onClose();
      } catch (e) {}

      setScanStep('Hibrit: Görsel Normalizasyonu...');
      try {
        const dataUrl = await processImage(img, { width: 1200, grayscale: true, contrast: 1.6 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) {}

      setScanStep('Hibrit: Derin Eşikleme...');
      try {
        const dataUrl = await processImage(img, { width: 900, threshold: 128, contrast: 2.2 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      } catch (e) {
        throw new Error("Otomatik tarama başarısız. Lütfen 'Hassas Ayarlar' panelini açarak görseli manuel optimize edin.");
      }

    } catch (err: any) {
      setFileError(err.message);
      setTimeout(() => startCamera(), 1000);
      setTimeout(() => setFileError(null), 8000);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const resetManualSettings = () => {
    setSettings({
      brightness: 1.0,
      contrast: 1.5,
      sharpen: 1,
      threshold: 128,
      useManual: true
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/95 backdrop-blur-3xl p-4 transition-all duration-500 overflow-y-auto">
      <div className="bg-white w-full max-w-lg rounded-[4rem] overflow-hidden shadow-[0_40px_120px_rgba(0,0,0,0.8)] animate-fade-in border border-white/20 my-auto">

        <div className="p-8 flex justify-between items-center border-b border-slate-50">
          <div className="space-y-1">
            <h3 className="font-black text-2xl text-slate-800 tracking-tight">Hibrit Vision Engine</h3>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Precision v4.2 PRO</p>
          </div>
          <div className="flex gap-2">
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`p-3 rounded-2xl transition-all active:scale-90 ${showSettings ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                title="Hassas Ayarlar"
            >
                <SlidersHorizontal size={22} />
            </button>
            <button 
                onClick={onClose}
                className="p-3 bg-rose-50 hover:bg-rose-100 text-rose-500 rounded-2xl transition-all active:scale-90"
            >
                <XCircle size={22} />
            </button>
          </div>
        </div>

        <div className="p-8 space-y-8">
          {/* Vizör Alanı */}
          <div className="relative aspect-square group">
            <div className={`absolute -inset-1 rounded-[3.5rem] bg-gradient-to-tr from-indigo-500/10 to-purple-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none`}></div>

            <div 
              id={scannerId} 
              className={`w-full h-full rounded-[3rem] overflow-hidden bg-slate-950 shadow-2xl border-4 border-white relative z-0 ${permissionStatus === 'granted' || isInitializing ? 'block' : 'hidden'}`}
            ></div>

            {/* Durum Katmanları */}
            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-6 bg-slate-950 rounded-[3rem] z-10">
                <Loader2 size={48} className="text-indigo-400 animate-spin" />
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.5em] animate-pulse">Hardware Link...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center rounded-[3rem] z-20 animate-fade-in text-white shadow-inner overflow-hidden">
                <div className="absolute inset-0 bg-indigo-500 animate-pulse opacity-20"></div>
                <div className="relative mb-8">
                  <Zap size={64} className="text-amber-400 animate-bounce" />
                  <div className="absolute -inset-6 bg-white/20 rounded-full animate-ping"></div>
                </div>
                <div className="text-center px-10 space-y-2 relative">
                    <p className="font-black text-xl tracking-tight uppercase">{scanStep}</p>
                    <p className="text-indigo-200 text-[10px] font-black uppercase tracking-widest opacity-60">Engine Katmanı: {settings.useManual ? 'MANUEL' : 'OTOMATİK'}</p>
                </div>
              </div>
            )}

            {permissionStatus === 'granted' && !isProcessingFile && !isInitializing && (
              <div className="absolute top-0 left-0 w-full h-1.5 bg-indigo-400 z-10 animate-[scan_3s_ease-in-out_infinite] opacity-60 shadow-[0_0_20px_rgba(99,102,241,1)]"></div>
            )}
          </div>

          {/* Ayarlar Paneli */}
          {showSettings && (
            <div className="p-6 bg-slate-50 rounded-[2.5rem] border border-slate-100 animate-fade-in space-y-6">
                <div className="flex justify-between items-center mb-2">
                    <h4 className="text-[10px] font-black text-slate-800 uppercase tracking-[0.2em] flex items-center gap-2">
                        <Settings2 size={16} className="text-indigo-600" />
                        Görüntü Optimizasyonu
                    </h4>
                    <button 
                        onClick={() => setSettings(prev => ({ ...prev, useManual: !prev.useManual }))}
                        className={`text-[9px] font-black px-4 py-2 rounded-full transition-all border ${settings.useManual ? 'bg-indigo-600 text-white border-indigo-700 shadow-md shadow-indigo-100' : 'bg-white text-slate-400 border-slate-200'}`}
                    >
                        {settings.useManual ? 'MANUEL AKTİF' : 'OTOMATİK HİBRİT'}
                    </button>
                </div>

                <div className={`space-y-6 transition-all duration-300 ${settings.useManual ? 'opacity-100 scale-100' : 'opacity-30 scale-[0.98] pointer-events-none'}`}>
                    <div className="space-y-3">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1.5"><Sun size={14} /> Parlaklık</span>
                            <span className="text-xs font-mono font-bold text-indigo-600">x{settings.brightness.toFixed(1)}</span>
                        </div>
                        <input type="range" min="0.5" max="2.0" step="0.1" value={settings.brightness} onChange={e => setSettings({...settings, brightness: parseFloat(e.target.value)})} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    </div>

                    <div className="space-y-3">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1.5"><Contrast size={14} /> Kontrast</span>
                            <span className="text-xs font-mono font-bold text-indigo-600">x{settings.contrast.toFixed(1)}</span>
                        </div>
                        <input type="range" min="0.5" max="4.0" step="0.1" value={settings.contrast} onChange={e => setSettings({...settings, contrast: parseFloat(e.target.value)})} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    </div>

                    <div className="space-y-3">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1.5"><Wind size={14} /> Keskinlik</span>
                            <span className="text-xs font-mono font-bold text-indigo-600">{settings.sharpen} lvl</span>
                        </div>
                        <input type="range" min="0" max="10" step="1" value={settings.sharpen} onChange={e => setSettings({...settings, sharpen: parseInt(e.target.value)})} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    </div>

                    <div className="space-y-3">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1.5"><Binary size={14} /> Eşikleme</span>
                            <span className="text-xs font-mono font-bold text-indigo-600">{settings.threshold}</span>
                        </div>
                        <input type="range" min="0" max="255" step="1" value={settings.threshold} onChange={e => setSettings({...settings, threshold: parseInt(e.target.value)})} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    </div>

                    <button 
                        onClick={resetManualSettings}
                        className="w-full py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black text-slate-400 hover:text-indigo-600 hover:border-indigo-200 transition-all flex items-center justify-center gap-2 uppercase tracking-widest active:scale-95"
                    >
                        <RotateCcw size={14} /> Ayarları Sıfırla
                    </button>
                </div>
            </div>
          )}

          {/* İşlem Butonları */}
          <div className="space-y-4">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*"
              className="hidden"
            />

            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isProcessingFile}
              className="w-full flex items-center justify-center gap-5 py-6 bg-slate-900 text-white rounded-[2.5rem] hover:bg-indigo-600 transition-all shadow-2xl shadow-slate-200 active:scale-[0.97] disabled:opacity-50 group border border-white/10"
            >
              <div className="p-3 bg-white/10 rounded-2xl group-hover:bg-white group-hover:text-indigo-600 transition-all">
                <ImagePlus size={24} />
              </div>
              <div className="text-left">
                <p className="font-black text-base leading-none">Dosyadan Fotoğraf Seç</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1.5 group-hover:text-indigo-100 transition-colors">
                    {settings.useManual ? 'Manuel Optimizasyon Aktif' : 'Otomatik Hibrit Motor Aktif'}
                </p>
              </div>
            </button>

            {fileError && (
              <div className="flex items-start gap-4 p-6 bg-rose-50 text-rose-600 rounded-[2rem] text-xs font-bold border border-rose-100 animate-fade-in shadow-sm">
                <AlertCircle size={22} className="shrink-0 mt-0.5" />
                <p className="leading-relaxed">{fileError}</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-slate-50 p-7 text-center border-t border-slate-100 flex items-center justify-center gap-3">
            <Maximize size={16} className="text-indigo-600" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Hardware Accelerated Vision</p>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { 
          width: 100% !important; 
          height: 100% !important; 
          object-fit: cover !important;
          border-radius: 2.5rem;
        }
        #qr-reader-container { 
          border: none !important; 
        }
        @keyframes scan {
          0% { transform: translateY(0); opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { transform: translateY(350px); opacity: 0; }
        }
        input[type='range'] {
          -webkit-appearance: none;
          background: #e2e8f0;
          height: 6px;
          border-radius: 10px;
        }
        input[type='range']::-webkit-slider-thumb {
          -webkit-appearance: none;
          appearance: none;
          width: 20px;
          height: 20px;
          background: #4f46e5;
          cursor: pointer;
          border-radius: 50%;
          border: 3px solid white;
          box-shadow: 0 4px 10px rgba(79, 70, 229, 0.3);
        }
      `}</style>
    </div>
  );
};

export default Scanner;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  ClipboardList,
  Info,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  PlusCircle
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'gen_in' | 'gen_out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [extraFields, setExtraFields] = useState<Record<string, string>>({});

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;

      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values()).sort((a, b) => b.remaining - a.remaining);
  }, [transactions]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      let data: Record<string, string> = {};
      const cleanText = text.trim();

      if (cleanText.startsWith('{')) {
        data = JSON.parse(cleanText);
      } else if (cleanText.includes(';;')) {
        const p = cleanText.split(';;').map(s => s.trim());
        data = { 'Firma': p[0], 'Miktar': p[1], 'Beden': p[2], 'Renk': p[4], 'Kod': p[6], 'Ad': p[7] };
      } else {
        data = { 'Kod': cleanText, 'Ad': 'Ürün ' + cleanText };
      }

      const getVal = (keys: string[]) => {
        for (const k of keys) {
          const found = Object.keys(data).find(dk => dk.toLowerCase() === k.toLowerCase());
          if (found) return data[found];
        }
        return '';
      };

      const code = getVal(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'sku']);
      const name = getVal(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'başlık']);
      const qty = getVal(['miktar', 'adet', 'qty', 'quantity', 'amount']);
      const ptnr = getVal(['firma', 'partner', 'tedarikci', 'alıcı', 'supplier', 'recipient', 'müşteri']);

      setProductCode(code || cleanText);
      setProductName(name || code || 'Tanımsız Ürün');

      if (activeTab.includes('out')) {
        setQuantity('');
        setPartner('');
      } else {
        setQuantity(parseInt(qty) || 1);
        setPartner(ptnr || '');
      }

      // Tekstil Modülü (Beden/Renk)
      if (!activeTab.includes('gen')) {
        setSize(getVal(['beden', 'size', 'ölçü']));
        setColor(getVal(['renk', 'color']));
        setFeature(getVal(['ozellik', 'feature', 'tip']));
      } else {
        // Genel Stok Modülü: Diğer tüm alanları extraFields'a at
        const core = ['kod', 'ad', 'miktar', 'firma', 'code', 'name', 'qty', 'partner', 'approver', 'onaylayan'];
        const extras: Record<string, string> = {};
        Object.entries(data).forEach(([k, v]) => {
          if (!core.some(c => k.toLowerCase().includes(c))) {
            extras[k] = v;
          }
        });
        setExtraFields(extras);
      }

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('QR Bilgileri İşlendi', 'success');
    } catch (e) {
      showNotification('QR Okuma Hatası', 'error');
    }
  };

  const resetForm = () => {
    setIsFormActive(false);
    setProductCode('');
    setProductName('');
    setQuantity('');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleSave = () => {
    if (!productCode || quantity === '' || quantity <= 0 || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun!', 'error');
      return;
    }

    const currentStock = inventory.find(p => p.productCode === productCode)?.remaining || 0;
    if (activeTab.includes('out') && currentStock < (quantity as number)) {
      showNotification(`Yetersiz stok! Mevcut bakiye: ${currentStock}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem Başarıyla Kaydedildi', 'success');
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Alt limit güncellendi', 'success');
  };

  const criticalProductsCount = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    }).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Nav */}
      <div className="md:hidden bg-white border-b p-4 flex justify-between items-center sticky top-0 z-40">
        <h1 className="font-bold text-indigo-600">KaratProStock QR</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-white border-r transform transition-transform md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex flex-col h-full">
          <div className="mb-10 hidden md:block text-center">
            <h1 className="text-2xl font-black text-indigo-600 tracking-tighter">KaratProStock</h1>
          </div>
          <nav className="space-y-2 flex-1 overflow-y-auto pr-2">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Kontrol Paneli" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />

            <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Tekstil Modülü</div>
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Üretim Giriş" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Üretim Çıkış" />

            <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Genel Stok Modülü</div>
            <NavItem active={activeTab==='gen_in'} onClick={()=>setActiveTab('gen_in')} icon={Box} label="Hammadde Giriş" />
            <NavItem active={activeTab==='gen_out'} onClick={()=>setActiveTab('gen_out')} icon={ClipboardList} label="Hammadde Çıkış" />

            {user.role === UserRole.ADMIN && (
              <>
                <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Yönetim</div>
                <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />
              </>
            )}
          </nav>
          <div className="mt-auto pt-8 border-t space-y-4">
            <div className="flex items-center gap-4 px-4">
              <div className="w-10 h-10 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-sm shadow-lg shadow-indigo-100">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-xs font-black text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-4 text-rose-500 font-black hover:bg-rose-50 rounded-2xl transition-all text-xs uppercase tracking-widest">
              <LogOut size={16} /> Güvenli Çıkış
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-6 md:p-12 overflow-y-auto">
        {notification && (
          <div className={`fixed top-8 right-8 z-[110] px-8 py-5 rounded-[2rem] shadow-[0_20px_60px_rgba(0,0,0,0.15)] text-white font-black animate-fade-in flex items-center gap-4 ${notification.type==='success' ? 'bg-indigo-600' : notification.type==='warning' ? 'bg-amber-500' : 'bg-rose-600'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
            <span className="text-sm tracking-tight">{notification.message}</span>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-fade-in">
            <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div className="space-y-2">
                <h2 className="text-4xl font-black text-slate-800 tracking-tight">Envanter Vizyonu</h2>
                <p className="text-slate-400 font-medium text-sm">Gerçek zamanlı depo takibi ve stok optimizasyonu</p>
              </div>
              {criticalProductsCount > 0 && (
                <div className="bg-rose-50 border border-rose-100 px-6 py-3 rounded-full flex items-center gap-3 text-rose-600 shadow-sm animate-pulse">
                  <Bell size={20} className="fill-rose-500/10" />
                  <span className="text-xs font-black uppercase tracking-widest">{criticalProductsCount} Kritik Stok Alarmı!</span>
                </div>
              )}
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
              <StatCard label="Mevcut Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
              <StatCard label="Aylık Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
              <StatCard label="Aylık Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
              <StatCard label="Kritik Limit" val={criticalProductsCount} icon={AlertCircle} color="amber" />
            </div>

            <div className="bg-white rounded-[3.5rem] border shadow-2xl shadow-slate-200/50 overflow-hidden p-2">
              <div className="p-8 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-4">
                <h3 className="font-black text-xl text-slate-800 flex items-center gap-3">
                  <Box size={24} className="text-indigo-600" />
                  Stok Durum Tablosu
                </h3>
                <div className="bg-slate-50 px-5 py-2.5 rounded-2xl flex items-center gap-2">
                   <Search size={16} className="text-slate-400" />
                   <input type="text" placeholder="Hızlı ürün ara..." className="bg-transparent border-none text-xs font-bold outline-none placeholder:text-slate-300 w-40" />
                </div>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-50/50 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">
                    <tr>
                      <th className="px-8 py-6">Ürün Detayı</th>
                      <th className="px-8 py-6">Mevcut Miktar</th>
                      <th className="px-8 py-6">Durum Analizi</th>
                      <th className="px-8 py-6">Eşik Limit</th>
                      <th className="px-8 py-6 text-right">Son Hareket</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {inventory.length > 0 ? inventory.map(item => {
                      const threshold = thresholds[item.productCode] || 0;
                      const isCritical = threshold > 0 && item.remaining <= threshold;

                      return (
                        <tr key={item.productCode} className="hover:bg-slate-50/80 transition-all duration-300 group">
                          <td className="px-8 py-6">
                            <div className="flex flex-col">
                              <span className="font-black text-slate-800 text-base">{item.productName}</span>
                              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mt-1">{item.productCode}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`text-2xl font-black ${isCritical ? 'text-rose-600' : 'text-slate-900'}`}>
                              {item.remaining.toLocaleString()}
                            </span>
                          </td>
                          <td className="px-8 py-6">
                            {isCritical ? (
                              <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100">
                                <div className="w-1.5 h-1.5 bg-rose-600 rounded-full animate-pulse"></div> Kritik
                              </span>
                            ) : (
                              <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase border border-emerald-100">
                                <div className="w-1.5 h-1.5 bg-emerald-600 rounded-full"></div> Stabil
                              </span>
                            )}
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              editingThreshold === item.productCode ? (
                                <input 
                                  type="number" 
                                  autoFocus
                                  className="w-20 px-3 py-2 border-2 border-indigo-200 rounded-xl text-sm font-black outline-none focus:border-indigo-600"
                                  value={tempThreshold}
                                  onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                  onBlur={() => handleSaveThreshold(item.productCode)}
                                  onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(item.productCode)}
                                />
                              ) : (
                                <button 
                                  onClick={() => { setEditingThreshold(item.productCode); setTempThreshold(threshold); }}
                                  className="flex items-center gap-3 text-slate-400 hover:text-indigo-600 transition-all"
                                >
                                  <span className="font-black text-sm">{threshold}</span>
                                  <Settings size={16} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                                </button>
                              )
                            ) : (
                              <span className="font-black text-slate-300 text-sm">{threshold}</span>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right text-[10px] font-bold text-slate-400">
                            {item.lastUpdate}
                          </td>
                        </tr>
                      );
                    }) : (
                      <tr>
                        <td colSpan={5} className="py-24 text-center">
                          <div className="flex flex-col items-center opacity-20">
                            <Box size={64} className="mb-4" />
                            <p className="font-black text-sm uppercase tracking-[0.3em]">Henüz Kayıt Yok</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out' || activeTab === 'gen_in' || activeTab === 'gen_out') && (
          <div className="max-w-4xl mx-auto space-y-10">
            <header className="text-center space-y-3">
              <div className="inline-flex p-4 bg-white rounded-[2rem] shadow-xl shadow-slate-100 mb-4">
                 {activeTab.includes('in') ? <PackagePlus size={32} className="text-indigo-600" /> : <PackageMinus size={32} className="text-rose-500" />}
              </div>
              <h2 className="text-4xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab.includes('gen') ? 'Hammadde İşlem' : 'Üretim/Tekstil İşlem'}
              </h2>
              <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em]">{activeTab.includes('in') ? 'Stok Giriş Prosedürü' : 'Stok Çıkış Prosedürü'}</p>
            </header>

            {!isFormActive ? (
              <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-4 border-dashed border-indigo-100 rounded-[4rem] p-24 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-300 hover:bg-indigo-50/20 transition-all group shadow-2xl shadow-slate-100 relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-transparent to-indigo-50 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <div className="p-10 bg-indigo-600 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-200 group-hover:scale-110 transition-transform mb-8 relative z-10">
                  <Search size={56} />
                </div>
                <h3 className="text-3xl font-black text-slate-800 mb-3 relative z-10">Vizörü Aktif Et</h3>
                <p className="text-slate-400 font-black uppercase text-xs tracking-[0.3em] relative z-10">QR Kod veya Görsel Analizi</p>
              </div>
            ) : (
              <div className="bg-white p-10 md:p-16 rounded-[4rem] shadow-[0_40px_100px_rgba(0,0,0,0.08)] border border-slate-50 space-y-12 animate-fade-in relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-500 to-purple-500"></div>

                <div className={`flex flex-col md:flex-row justify-between items-center p-10 rounded-[3rem] border ${activeTab.includes('out') ? 'bg-rose-50/40 border-rose-100' : 'bg-indigo-50/40 border-indigo-100'}`}>
                  <div className="mb-6 md:mb-0 space-y-2">
                    <p className="text-[11px] font-black text-indigo-500 uppercase tracking-[0.4em] leading-none mb-1">{productCode}</p>
                    <h3 className="text-3xl font-black text-slate-800">{productName}</h3>
                  </div>
                  <div className="text-center md:text-right space-y-1">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kayıtlı Güncel Bakiye</p>
                    <p className="text-5xl font-black text-slate-900 leading-none">
                      {inventory.find(i=>i.productCode===productCode)?.remaining || 0}
                      <span className="text-xs font-black text-slate-300 ml-3 uppercase tracking-widest">ADET</span>
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="İşlem Adeti (Miktar)" type="number" placeholder="Sayı giriniz..." value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} />
                  <Input label={activeTab.includes('in') ? 'Tedarikçi / Kaynak' : 'Alıcı / Departman'} placeholder="Firma veya kişi adı..." value={partner} onChange={setPartner} />
                  <Input label="Yetkili Onaylayan" placeholder="Yönetici ismi..." value={approver} onChange={setApprover} />

                  {!activeTab.includes('gen') ? (
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Beden/Ölçü" placeholder="M, L, XL..." value={size} onChange={setSize} />
                      <Input label="Renk" placeholder="Siyah, Beyaz..." value={color} onChange={setColor} />
                    </div>
                  ) : (
                    // Genel Stok Modülü Dinamik Alanlar
                    Object.keys(extraFields).length > 0 ? (
                      <div className="col-span-1 md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-8">
                        {Object.entries(extraFields).map(([key, value]) => (
                          <Input 
                            key={key} 
                            label={key} 
                            value={value} 
                            onChange={(v: string) => setExtraFields({...extraFields, [key]: v})} 
                          />
                        ))}
                      </div>
                    ) : (
                       <Input label="Ek Özellik" placeholder="Açıklama (opsiyonel)..." value={feature} onChange={setFeature} />
                    )
                  )}
                </div>

                <div className="flex flex-col md:flex-row gap-6 pt-8">
                  <button onClick={resetForm} className="flex-1 py-6 bg-slate-50 rounded-3xl font-black text-slate-400 hover:bg-slate-100 transition-all uppercase tracking-[0.2em] text-xs">Vazgeç</button>
                  <button onClick={handleSave} className={`flex-[2] py-6 rounded-3xl font-black text-white shadow-2xl uppercase tracking-[0.3em] text-sm transition-all active:scale-[0.98] ${activeTab.includes('in') ? 'bg-indigo-600 shadow-indigo-200 hover:bg-indigo-700' : 'bg-rose-500 shadow-rose-200 hover:bg-rose-600'}`}>
                    {activeTab.includes('in') ? 'Girişi Tamamla' : 'Çıkışı Tamamla'}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-8 animate-fade-in">
            <header className="flex justify-between items-end">
              <div className="space-y-2">
                <h3 className="text-3xl font-black text-slate-800 tracking-tight">İşlem Günlüğü</h3>
                <p className="text-slate-400 text-sm font-medium">Tüm giriş ve çıkış hareketlerinin detaylı dökümü</p>
              </div>
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-white px-6 py-3 rounded-2xl shadow-sm border border-slate-50">
                TOPLAM {transactions.length} HAREKET
              </div>
            </header>
            <div className="bg-white rounded-[3.5rem] shadow-sm border border-slate-50 overflow-hidden p-2">
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-50/50 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">
                    <tr>
                      <th className="p-8">Zaman Damgası</th>
                      <th className="p-8">Ürün & Kimlik</th>
                      <th className="p-8">Kategori / Tip</th>
                      <th className="p-8">Net Miktar</th>
                      <th className="p-8">Partner Bilgisi</th>
                      <th className="p-8">Onay Mekanizması</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {transactions.length > 0 ? transactions.map(t => (
                      <tr key={t.id} className="text-sm hover:bg-slate-50/50 transition-all group">
                        <td className="p-8 text-slate-400 text-[11px] font-black uppercase tracking-tighter">{t.date}</td>
                        <td className="p-8">
                          <div className="flex flex-col">
                            <span className="font-black text-slate-800 text-base">{t.productName}</span>
                            <span className="text-[10px] text-indigo-500 font-black uppercase tracking-widest mt-1">{t.productCode}</span>
                          </div>
                        </td>
                        <td className="p-8">
                          <span className={`inline-flex items-center gap-2 px-4 py-1.5 rounded-full text-[10px] font-black uppercase border ${t.type===TransactionType.IN ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                            {t.type}
                          </span>
                        </td>
                        <td className="p-8">
                          <span className="text-2xl font-black text-slate-900">{t.quantity}</span>
                        </td>
                        <td className="p-8 text-slate-500 font-bold italic text-xs">{t.supplier || t.recipient}</td>
                        <td className="p-8">
                          <div className="flex flex-col">
                            <span className="text-xs font-black text-slate-800">{t.approver}</span>
                            <span className="text-[9px] text-slate-400 uppercase font-black tracking-widest mt-1 opacity-60">Operatör: {t.operator}</span>
                          </div>
                        </td>
                      </tr>
                    )) : (
                      <tr>
                        <td colSpan={6} className="p-24 text-center">
                           <div className="opacity-10">
                              <History size={64} className="mx-auto mb-4" />
                              <p className="font-black text-xs uppercase tracking-widest">Kayıt Bulunmuyor</p>
                           </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && user.role === UserRole.ADMIN && (
          <div className="space-y-8 animate-fade-in">
             <div className="flex justify-between items-center">
               <h3 className="text-3xl font-black text-slate-800 tracking-tight">Ekip Yönetimi</h3>
               <button className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                 <PlusCircle size={16} /> Yeni Kullanıcı
               </button>
             </div>
             <UserSection />
          </div>
        )}
      </main>

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${active ? 'bg-indigo-600 text-white shadow-2xl shadow-indigo-100' : 'text-slate-400 hover:bg-white hover:text-indigo-600 hover:shadow-xl hover:shadow-slate-100'}`}>
    <Icon size={22} className={`${active ? 'scale-110' : 'group-hover:scale-110'} transition-transform`} /> 
    <span className="text-xs font-black tracking-widest uppercase">{label}</span>
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-8 rounded-[3.5rem] border shadow-sm flex items-start justify-between group hover:shadow-2xl hover:shadow-slate-200/50 transition-all cursor-default relative overflow-hidden">
    <div className={`absolute -right-4 -top-4 w-24 h-24 bg-${color}-50 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-700`}></div>
    <div className="space-y-3 relative z-10">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">{label}</p>
      <p className="text-5xl font-black text-slate-900 tracking-tighter">{val.toLocaleString()}</p>
    </div>
    <div className={`p-6 bg-${color}-50 text-${color}-600 rounded-[2rem] group-hover:scale-110 group-hover:bg-${color}-600 group-hover:text-white transition-all duration-500 relative z-10`}>
      <Icon size={32} />
    </div>
  </div>
);

const Input = ({ label, ...props }: any) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] ml-2">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange(e.target.value)} 
      className="w-full px-8 py-5 bg-slate-50 border-2 border-transparent rounded-[1.8rem] focus:border-indigo-600 focus:bg-white font-black text-slate-800 outline-none transition-all placeholder:text-slate-200 placeholder:font-bold text-sm" 
    />
  </div>
);

const UserSection = () => {
  const [users, setUsers] = useState(StorageService.getUsers());
  const handleDelete = (id: string) => {
    if (confirm('Bu kullanıcıyı silmek istediğinize emin misiniz?')) {
      StorageService.deleteUser(id);
      setUsers(StorageService.getUsers());
    }
  };
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-fade-in">
      {users.map(u => (
        <div key={u.id} className="bg-white p-10 rounded-[3.5rem] border shadow-sm flex items-center justify-between group hover:shadow-2xl transition-all duration-500">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-slate-50 rounded-[1.8rem] flex items-center justify-center text-indigo-600 font-black text-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all duration-500 shadow-inner">
              {u.fullName.charAt(0)}
            </div>
            <div className="space-y-1">
              <p className="font-black text-slate-800 text-lg tracking-tight">{u.fullName}</p>
              <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.3em]">{u.role}</p>
            </div>
          </div>
          {u.username !== 'admin' && (
            <button onClick={()=>handleDelete(u.id)} className="p-4 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
              <Trash2 size={24} />
            </button>
          )}
        </div>
      ))}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  ClipboardList,
  Info,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  PlusCircle,
  // Added missing Trash2 import
  Trash2
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'gen_in' | 'gen_out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [extraFields, setExtraFields] = useState<Record<string, string>>({});

  // Threshold edit state
  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };

      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;

      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values()).sort((a, b) => b.remaining - a.remaining);
  }, [transactions]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      let data: Record<string, string> = {};
      const cleanText = text.trim();

      if (cleanText.startsWith('{')) {
        data = JSON.parse(cleanText);
      } else if (cleanText.includes(';;')) {
        const p = cleanText.split(';;').map(s => s.trim());
        data = { 'Firma': p[0], 'Miktar': p[1], 'Beden': p[2], 'Renk': p[4], 'Kod': p[6], 'Ad': p[7] };
      } else {
        data = { 'Kod': cleanText, 'Ad': 'Ürün ' + cleanText };
      }

      const getVal = (keys: string[]) => {
        for (const k of keys) {
          const found = Object.keys(data).find(dk => dk.toLowerCase() === k.toLowerCase());
          if (found) return data[found];
        }
        return '';
      };

      const code = getVal(['urunKodu', 'productCode', 'kod', 'code', 'Ürün Kodu', 'sku']);
      const name = getVal(['urunAdi', 'productName', 'ad', 'name', 'Ürün Adı', 'başlık']);
      const qty = getVal(['miktar', 'adet', 'qty', 'quantity', 'amount']);
      const ptnr = getVal(['firma', 'partner', 'tedarikci', 'alıcı', 'supplier', 'recipient', 'müşteri']);

      setProductCode(code || cleanText);
      setProductName(name || code || 'Tanımsız Ürün');

      if (activeTab.includes('out')) {
        setQuantity('');
        setPartner('');
      } else {
        setQuantity(parseInt(qty) || 1);
        setPartner(ptnr || '');
      }

      // Tekstil Modülü (Beden/Renk)
      if (!activeTab.includes('gen')) {
        setSize(getVal(['beden', 'size', 'ölçü']));
        setColor(getVal(['renk', 'color']));
        setFeature(getVal(['ozellik', 'feature', 'tip']));
      } else {
        // Genel Stok Modülü: Diğer tüm alanları extraFields'a at
        const core = ['kod', 'ad', 'miktar', 'firma', 'code', 'name', 'qty', 'partner', 'approver', 'onaylayan'];
        const extras: Record<string, string> = {};
        Object.entries(data).forEach(([k, v]) => {
          if (!core.some(c => k.toLowerCase().includes(c))) {
            extras[k] = v;
          }
        });
        setExtraFields(extras);
      }

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('QR Bilgileri İşlendi', 'success');
    } catch (e) {
      showNotification('QR Okuma Hatası', 'error');
    }
  };

  const resetForm = () => {
    setIsFormActive(false);
    setProductCode('');
    setProductName('');
    setQuantity('');
    setPartner('');
    setApprover('');
    setSize('');
    setColor('');
    setFeature('');
    setExtraFields({});
  };

  const handleSave = () => {
    if (!productCode || quantity === '' || quantity <= 0 || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun!', 'error');
      return;
    }

    const currentStock = inventory.find(p => p.productCode === productCode)?.remaining || 0;
    if (activeTab.includes('out') && currentStock < (quantity as number)) {
      showNotification(`Yetersiz stok! Mevcut bakiye: ${currentStock}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab.includes('in') ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab.includes('in') ? partner : undefined,
      recipient: activeTab.includes('out') ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver,
      size: activeTab.includes('gen') ? undefined : size,
      color: activeTab.includes('gen') ? undefined : color,
      feature: activeTab.includes('gen') ? undefined : feature,
      metadata: activeTab.includes('gen') ? extraFields : undefined
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification('İşlem Başarıyla Kaydedildi', 'success');
  };

  const handleSaveThreshold = (code: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    StorageService.saveThreshold(code, tempThreshold);
    setThresholds(StorageService.getThresholds());
    setEditingThreshold(null);
    showNotification('Alt limit güncellendi', 'success');
  };

  const criticalProductsCount = useMemo(() => {
    return inventory.filter(p => {
      const threshold = thresholds[p.productCode] || 0;
      return threshold > 0 && p.remaining <= threshold;
    }).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      {/* Mobile Nav */}
      <div className="md:hidden bg-white border-b p-4 flex justify-between items-center sticky top-0 z-40">
        <h1 className="font-bold text-indigo-600">KaratProStock QR</h1>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-600">
          {sidebarOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-white border-r transform transition-transform md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex flex-col h-full">
          <div className="mb-10 hidden md:block text-center">
            <h1 className="text-2xl font-black text-indigo-600 tracking-tighter">KaratProStock</h1>
          </div>
          <nav className="space-y-2 flex-1 overflow-y-auto pr-2">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Kontrol Paneli" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />

            <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Tekstil Modülü</div>
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Üretim Giriş" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Üretim Çıkış" />

            <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Genel Stok Modülü</div>
            <NavItem active={activeTab==='gen_in'} onClick={()=>setActiveTab('gen_in')} icon={Box} label="Hammadde Giriş" />
            <NavItem active={activeTab==='gen_out'} onClick={()=>setActiveTab('gen_out')} icon={ClipboardList} label="Hammadde Çıkış" />

            {user.role === UserRole.ADMIN && (
              <>
                <div className="pt-8 pb-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Yönetim</div>
                <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />
              </>
            )}
          </nav>
          <div className="mt-auto pt-8 border-t space-y-4">
            <div className="flex items-center gap-4 px-4">
              <div className="w-10 h-10 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-sm shadow-lg shadow-indigo-100">
                {user.fullName.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-xs font-black text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-4 text-rose-500 font-black hover:bg-rose-50 rounded-2xl transition-all text-xs uppercase tracking-widest">
              <LogOut size={16} /> Güvenli Çıkış
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-6 md:p-12 overflow-y-auto">
        {notification && (
          <div className={`fixed top-8 right-8 z-[110] px-8 py-5 rounded-[2rem] shadow-[0_20px_60px_rgba(0,0,0,0.15)] text-white font-black animate-fade-in flex items-center gap-4 ${notification.type==='success' ? 'bg-indigo-600' : notification.type==='warning' ? 'bg-amber-500' : 'bg-rose-600'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
            <span className="text-sm tracking-tight">{notification.message}</span>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-fade-in">
            <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div className="space-y-2">
                <h2 className="text-4xl font-black text-slate-800 tracking-tight">Envanter Vizyonu</h2>
                <p className="text-slate-400 font-medium text-sm">Gerçek zamanlı depo takibi ve stok optimizasyonu</p>
              </div>
              {criticalProductsCount > 0 && (
                <div className="bg-rose-50 border border-rose-100 px-6 py-3 rounded-full flex items-center gap-3 text-rose-600 shadow-sm animate-pulse">
                  <Bell size={20} className="fill-rose-500/10" />
                  <span className="text-xs font-black uppercase tracking-widest">{criticalProductsCount} Kritik Stok Alarmı!</span>
                </div>
              )}
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
              <StatCard label="Mevcut Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
              <StatCard label="Aylık Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
              <StatCard label="Aylık Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
              <StatCard label="Kritik Limit" val={criticalProductsCount} icon={AlertCircle} color="amber" />
            </div>

            <div className="bg-white rounded-[3.5rem] border shadow-2xl shadow-slate-200/50 overflow-hidden p-2">
              <div className="p-8 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-4">
                <h3 className="font-black text-xl text-slate-800 flex items-center gap-3">
                  <Box size={24} className="text-indigo-600" />
                  Stok Durum Tablosu
                </h3>
                <div className="bg-slate-50 px-5 py-2.5 rounded-2xl flex items-center gap-2">
                   <Search size={16} className="text-slate-400" />
                   <input type="text" placeholder="Hızlı ürün ara..." className="bg-transparent border-none text-xs font-bold outline-none placeholder:text-slate-300 w-40" />
                </div>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-50/50 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">
                    <tr>
                      <th className="px-8 py-6">Ürün Detayı</th>
                      <th className="px-8 py-6">Mevcut Miktar</th>
                      <th className="px-8 py-6">Durum Analizi</th>
                      <th className="px-8 py-6">Eşik Limit</th>
                      <th className="px-8 py-6 text-right">Son Hareket</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {inventory.length > 0 ? inventory.map(item => {
                      const threshold = thresholds[item.productCode] || 0;
                      const isCritical = threshold > 0 && item.remaining <= threshold;

                      return (
                        <tr key={item.productCode} className="hover:bg-slate-50/80 transition-all duration-300 group">
                          <td className="px-8 py-6">
                            <div className="flex flex-col">
                              <span className="font-black text-slate-800 text-base">{item.productName}</span>
                              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mt-1">{item.productCode}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`text-2xl font-black ${isCritical ? 'text-rose-600' : 'text-slate-900'}`}>
                              {item.remaining.toLocaleString()}
                            </span>
                          </td>
                          <td className="px-8 py-6">
                            {isCritical ? (
                              <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100">
                                <div className="w-1.5 h-1.5 bg-rose-600 rounded-full animate-pulse"></div> Kritik
                              </span>
                            ) : (
                              <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase border border-emerald-100">
                                <div className="w-1.5 h-1.5 bg-emerald-600 rounded-full"></div> Stabil
                              </span>
                            )}
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              editingThreshold === item.productCode ? (
                                <input 
                                  type="number" 
                                  autoFocus
                                  className="w-20 px-3 py-2 border-2 border-indigo-200 rounded-xl text-sm font-black outline-none focus:border-indigo-600"
                                  value={tempThreshold}
                                  onChange={e => setTempThreshold(parseInt(e.target.value) || 0)}
                                  onBlur={() => handleSaveThreshold(item.productCode)}
                                  onKeyDown={e => e.key === 'Enter' && handleSaveThreshold(item.productCode)}
                                />
                              ) : (
                                <button 
                                  onClick={() => { setEditingThreshold(item.productCode); setTempThreshold(threshold); }}
                                  className="flex items-center gap-3 text-slate-400 hover:text-indigo-600 transition-all"
                                >
                                  <span className="font-black text-sm">{threshold}</span>
                                  <Settings size={16} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                                </button>
                              )
                            ) : (
                              <span className="font-black text-slate-300 text-sm">{threshold}</span>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right text-[10px] font-bold text-slate-400">
                            {item.lastUpdate}
                          </td>
                        </tr>
                      );
                    }) : (
                      <tr>
                        <td colSpan={5} className="py-24 text-center">
                          <div className="flex flex-col items-center opacity-20">
                            <Box size={64} className="mb-4" />
                            <p className="font-black text-sm uppercase tracking-[0.3em]">Henüz Kayıt Yok</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'in' || activeTab === 'out' || activeTab === 'gen_in' || activeTab === 'gen_out') && (
          <div className="max-w-4xl mx-auto space-y-10">
            <header className="text-center space-y-3">
              <div className="inline-flex p-4 bg-white rounded-[2rem] shadow-xl shadow-slate-100 mb-4">
                 {activeTab.includes('in') ? <PackagePlus size={32} className="text-indigo-600" /> : <PackageMinus size={32} className="text-rose-500" />}
              </div>
              <h2 className="text-4xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab.includes('gen') ? 'Hammadde İşlem' : 'Üretim/Tekstil İşlem'}
              </h2>
              <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em]">{activeTab.includes('in') ? 'Stok Giriş Prosedürü' : 'Stok Çıkış Prosedürü'}</p>
            </header>

            {!isFormActive ? (
              <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-4 border-dashed border-indigo-100 rounded-[4rem] p-24 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-300 hover:bg-indigo-50/20 transition-all group shadow-2xl shadow-slate-100 relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-transparent to-indigo-50 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <div className="p-10 bg-indigo-600 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-200 group-hover:scale-110 transition-transform mb-8 relative z-10">
                  <Search size={56} />
                </div>
                <h3 className="text-3xl font-black text-slate-800 mb-3 relative z-10">Vizörü Aktif Et</h3>
                <p className="text-slate-400 font-black uppercase text-xs tracking-[0.3em] relative z-10">QR Kod veya Görsel Analizi</p>
              </div>
            ) : (
              <div className="bg-white p-10 md:p-16 rounded-[4rem] shadow-[0_40px_100px_rgba(0,0,0,0.08)] border border-slate-50 space-y-12 animate-fade-in relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-500 to-purple-500"></div>

                <div className={`flex flex-col md:flex-row justify-between items-center p-10 rounded-[3rem] border ${activeTab.includes('out') ? 'bg-rose-50/40 border-rose-100' : 'bg-indigo-50/40 border-indigo-100'}`}>
                  <div className="mb-6 md:mb-0 space-y-2">
                    <p className="text-[11px] font-black text-indigo-500 uppercase tracking-[0.4em] leading-none mb-1">{productCode}</p>
                    <h3 className="text-3xl font-black text-slate-800">{productName}</h3>
                  </div>
                  <div className="text-center md:text-right space-y-1">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kayıtlı Güncel Bakiye</p>
                    <p className="text-5xl font-black text-slate-900 leading-none">
                      {inventory.find(i=>i.productCode===productCode)?.remaining || 0}
                      <span className="text-xs font-black text-slate-300 ml-3 uppercase tracking-widest">ADET</span>
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="İşlem Adeti (Miktar)" type="number" placeholder="Sayı giriniz..." value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} />
                  <Input label={activeTab.includes('in') ? 'Tedarikçi / Kaynak' : 'Alıcı / Departman'} placeholder="Firma veya kişi adı..." value={partner} onChange={setPartner} />
                  <Input label="Yetkili Onaylayan" placeholder="Yönetici ismi..." value={approver} onChange={setApprover} />

                  {!activeTab.includes('gen') ? (
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Beden/Ölçü" placeholder="M, L, XL..." value={size} onChange={setSize} />
                      <Input label="Renk" placeholder="Siyah, Beyaz..." value={color} onChange={setColor} />
                    </div>
                  ) : (
                    // Genel Stok Modülü Dinamik Alanlar
                    Object.keys(extraFields).length > 0 ? (
                      <div className="col-span-1 md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-8">
                        {Object.entries(extraFields).map(([key, value]) => (
                          <Input 
                            key={key} 
                            label={key} 
