import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  AlertCircle, 
  XCircle, 
  Loader2, 
  ImagePlus, 
  Zap, 
  Maximize, 
  Settings2, 
  Sun, 
  Contrast, 
  Wind, 
  Binary,
  RotateCcw,
  SlidersHorizontal
} from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

interface ManualSettings {
  brightness: number;
  contrast: number;
  sharpen: number;
  threshold: number;
  useManual: boolean;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [permissionStatus, setPermissionStatus] = useState<'prompt' | 'granted' | 'denied'>('prompt');
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);

  const [settings, setSettings] = useState<ManualSettings>({
    brightness: 1.0,
    contrast: 1.5,
    sharpen: 1,
    threshold: 128,
    useManual: false
  });

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const startCamera = useCallback(async () => {
    // DOM'un hazır olduğundan emin olmak için kısa bir bekleme
    await new Promise(resolve => setTimeout(resolve, 100));

    await stopScanner();
    const container = document.getElementById(scannerId);
    if (!container) return;

    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      // Kamera listesini almadan direkt facingMode deniyoruz (daha stabil)
      setPermissionStatus('granted');

      const config = {
        fps: 20,
        qrbox: (viewfinderWidth: number, viewfinderHeight: number) => {
          const minEdge = Math.min(viewfinderWidth, viewfinderHeight);
          const qrboxSize = Math.floor(minEdge * 0.7);
          return { width: qrboxSize, height: qrboxSize };
        },
        aspectRatio: 1.0
      };

      await html5QrCode.start(
        { facingMode: "environment" },
        config,
        (text) => {
          onScan(text);
          stopScanner().then(() => onClose());
        },
        () => {} 
      );
    } catch (err) {
      console.error("Kamera başlatma hatası:", err);
      setPermissionStatus('denied');
    } finally {
      setIsInitializing(false);
    }
  }, [onScan, stopScanner, onClose]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, []);

  // Image Processing logic remains same as per "Transaction 31" requirements
  const processImage = async (img: HTMLImageElement, options: any): Promise<string> => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true } as any) as CanvasRenderingContext2D | null;
    if (!ctx) throw new Error('Canvas context error');
    let width = options.width || img.width;
    let height = (img.height / img.width) * width;
    canvas.width = width;
    canvas.height = height;
    let filters = [];
    if (options.grayscale) filters.push('grayscale(100%)');
    if (options.contrast) filters.push(`contrast(${options.contrast * 100}%)`);
    if (options.brightness) filters.push(`brightness(${options.brightness * 100}%)`);
    if (filters.length > 0) ctx.filter = filters.join(' ');
    ctx.drawImage(img, 0, 0, width, height);
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    if (options.threshold) {
      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > options.threshold ? 255 : 0;
        data[i] = data[i+1] = data[i+2] = val;
      }
    }
    ctx.putImageData(imageData, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.9);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Analiz ediliyor...');
    try {
      await stopScanner();
      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });
      const tempScanner = new Html5Qrcode(scannerId);
      if (settings.useManual) {
        const dataUrl = await processImage(img, { 
          width: 1200, grayscale: true, contrast: settings.contrast, brightness: settings.brightness, threshold: settings.threshold
        });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      }
      // Hibrit otomatik deneme
      try {
        const res = await tempScanner.scanFile(file, false);
        onScan(res);
        return onClose();
      } catch (e) {
        setScanStep('Görüntü iyileştiriliyor...');
        const dataUrl = await processImage(img, { width: 1200, grayscale: true, contrast: 1.8 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        onScan(res);
        return onClose();
      }
    } catch (err: any) {
      setFileError("Kod okunamadı. Lütfen görselin net ve kodun tam olduğundan emin olun.");
      setTimeout(() => startCamera(), 500);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl p-4 transition-all">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in border border-white/20">

        <div className="p-6 flex justify-between items-center border-b border-slate-50">
          <div className="space-y-0.5">
            <h3 className="font-extrabold text-lg text-slate-800 tracking-tight">Vision Engine</h3>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.2em]">Precision Scan v4.2</p>
          </div>
          <div className="flex gap-1.5">
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-500'}`}
            >
                <SlidersHorizontal size={18} />
            </button>
            <button 
                onClick={onClose}
                className="p-2.5 bg-rose-50 text-rose-500 rounded-xl transition-all"
            >
                <XCircle size={18} />
            </button>
          </div>
        </div>

        <div className="p-6 space-y-6">
          <div className="relative aspect-square">
            <div id={scannerId} className="w-full h-full rounded-[2rem] overflow-hidden bg-slate-950 shadow-inner relative z-0"></div>

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-slate-950 rounded-[2rem] z-10">
                <Loader2 size={32} className="text-indigo-400 animate-spin" />
                <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.4em]">Hardware Link...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center rounded-[2rem] z-20 animate-fade-in text-white">
                <Zap size={48} className="text-amber-400 animate-bounce mb-4" />
                <p className="font-bold text-sm uppercase tracking-widest">{scanStep}</p>
              </div>
            )}
          </div>

          {showSettings && (
            <div className="p-5 bg-slate-50 rounded-3xl border border-slate-100 space-y-4 animate-fade-in">
                <div className="flex justify-between items-center">
                    <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-1.5">
                        <Settings2 size={12} /> Optimizasyon
                    </h4>
                    <button 
                        onClick={() => setSettings(prev => ({ ...prev, useManual: !prev.useManual }))}
                        className={`text-[8px] font-black px-3 py-1.5 rounded-full border ${settings.useManual ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}
                    >
                        {settings.useManual ? 'MANUEL' : 'OTOMATİK'}
                    </button>
                </div>
                <div className={`space-y-4 ${settings.useManual ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
                   <input type="range" min="0.5" max="2.0" step="0.1" value={settings.brightness} onChange={e => setSettings({...settings, brightness: parseFloat(e.target.value)})} className="w-full h-1.5 bg-slate-200 rounded-lg accent-indigo-600" />
                   <input type="range" min="0.5" max="4.0" step="0.1" value={settings.contrast} onChange={e => setSettings({...settings, contrast: parseFloat(e.target.value)})} className="w-full h-1.5 bg-slate-200 rounded-lg accent-indigo-600" />
                   <button onClick={() => setSettings({...settings, useManual: true})} className="w-full py-2 bg-white rounded-xl text-[8px] font-bold text-slate-400 border border-slate-200">AYARLARI SIFIRLA</button>
                </div>
            </div>
          )}

          <div className="space-y-3">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full flex items-center justify-center gap-3 py-4 bg-slate-900 text-white rounded-2xl hover:bg-indigo-600 transition-all font-bold text-xs"
            >
              <ImagePlus size={18} />
              Galeriden Seç
            </button>
            {fileError && (
              <p className="text-[10px] text-rose-500 font-bold text-center bg-rose-50 p-3 rounded-xl border border-rose-100">{fileError}</p>
            )}
          </div>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 2rem; }
        #qr-reader-container { border: none !important; }
      `}</style>
    </div>
  );
};

