                  type="text"
                  required
                  className="w-full bg-slate-50 border-none rounded-xl py-3.5 pl-12 pr-4 text-slate-900 font-bold text-xs outline-none focus:ring-1 focus:ring-indigo-100 transition-all"
                  placeholder="Kullanıcı Adı"
