import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  AlertCircle, 
  XCircle, 
  Loader2, 
  ImagePlus, 
  Zap, 
  Settings2, 
  SlidersHorizontal
} from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

interface ManualSettings {
  brightness: number;
  contrast: number;
  threshold: number;
  useManual: boolean;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [scanLocked, setScanLocked] = useState(false);

  const [settings, setSettings] = useState<ManualSettings>({
    brightness: 1.0,
    contrast: 1.5,
    threshold: 128,
    useManual: false
  });

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Kamera durdurma hatası:", err);
      }
    }
  }, []);

  const handleScanSuccess = useCallback((text: string) => {
    if (scanLocked) return;
    setScanLocked(true);

    // Sesli veya görsel geri bildirim için kısa bekleme (opsiyonel)
    onScan(text);

    // Güvenli durdurma
    stopScanner().then(() => {
      onClose();
    }).catch(() => {
      onClose();
    });
  }, [onScan, onClose, stopScanner, scanLocked]);

  const startCamera = useCallback(async () => {
    await new Promise(resolve => setTimeout(resolve, 200));
    await stopScanner();

    const container = document.getElementById(scannerId);
    if (!container) return;

    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const config = {
        fps: 25,
        qrbox: (vw: number, vh: number) => {
          const s = Math.floor(Math.min(vw, vh) * 0.75);
          return { width: s, height: s };
        },
        aspectRatio: 1.0
      };

      await html5QrCode.start(
        { facingMode: "environment" },
        config,
        handleScanSuccess,
        () => {} 
      );
    } catch (err) {
      console.error("Kamera başlatılamadı:", err);
    } finally {
      setIsInitializing(false);
    }
  }, [stopScanner, handleScanSuccess]);

  useEffect(() => {
    startCamera();
    return () => {
      stopScanner();
    };
  }, []);

  const processImage = async (img: HTMLImageElement, options: any): Promise<string> => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true } as any) as CanvasRenderingContext2D | null;
    if (!ctx) throw new Error('Canvas error');
    let width = options.width || img.width;
    let height = (img.height / img.width) * width;
    canvas.width = width;
    canvas.height = height;
    let filters = [];
    if (options.grayscale) filters.push('grayscale(100%)');
    if (options.contrast) filters.push(`contrast(${options.contrast * 100}%)`);
    if (options.brightness) filters.push(`brightness(${options.brightness * 100}%)`);
    if (filters.length > 0) ctx.filter = filters.join(' ');
    ctx.drawImage(img, 0, 0, width, height);
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    if (options.threshold) {
      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > options.threshold ? 255 : 0;
        data[i] = data[i+1] = data[i+2] = val;
      }
    }
    ctx.putImageData(imageData, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.9);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Analiz ediliyor...');
    try {
      await stopScanner();
      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });
      const tempScanner = new Html5Qrcode(scannerId);

      // Hibrit deneme mantığı
      try {
        const res = await tempScanner.scanFile(file, false);
        handleScanSuccess(res);
      } catch (e) {
        setScanStep('İyileştiriliyor...');
        const dataUrl = await processImage(img, { width: 1000, grayscale: true, contrast: 1.8 });
        const res = await tempScanner.scanFile(await (await fetch(dataUrl)).blob() as File, false);
        handleScanSuccess(res);
      }
    } catch (err: any) {
      setFileError("Kod okunamadı. Lütfen görseli kontrol edin.");
      setTimeout(() => startCamera(), 500);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/80 backdrop-blur-md p-4 transition-all">
      <div className="bg-white w-full max-w-sm rounded-[2rem] overflow-hidden shadow-2xl animate-fade-in border border-white/20">

        <div className="p-5 flex justify-between items-center border-b border-slate-50">
          <div className="space-y-0.5">
            <h3 className="font-extrabold text-sm text-slate-800 tracking-tight">Akıllı Vizör</h3>
            <p className="text-[8px] text-slate-400 font-bold uppercase tracking-[0.2em]">Hardware Vision</p>
          </div>
          <div className="flex gap-1.5">
            <button onClick={() => setShowSettings(!showSettings)} className={`p-2 rounded-xl transition-all ${showSettings ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
              <SlidersHorizontal size={14} />
            </button>
            <button onClick={onClose} className="p-2 bg-rose-50 text-rose-500 rounded-xl">
              <XCircle size={14} />
            </button>
          </div>
        </div>

        <div className="p-6 space-y-6">
          <div className="relative aspect-square">
            <div id={scannerId} className="w-full h-full rounded-2xl overflow-hidden bg-slate-950 relative z-0"></div>

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-3 bg-slate-950 rounded-2xl z-10">
                <Loader2 size={24} className="text-indigo-400 animate-spin" />
                <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Başlatılıyor...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center rounded-2xl z-20 text-white animate-fade-in">
                <Zap size={32} className="text-amber-400 animate-pulse mb-3" />
                <p className="font-bold text-[10px] uppercase tracking-widest">{scanStep}</p>
              </div>
            )}

            <div className="absolute inset-0 border-[30px] border-slate-950/20 pointer-events-none rounded-2xl z-0"></div>
          </div>

          <div className="space-y-3">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2.5 py-3.5 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 transition-all font-bold text-[10px] uppercase tracking-widest">
              <ImagePlus size={14} /> Dosya Analizi
            </button>
            {fileError && <p className="text-[9px] text-rose-500 font-bold text-center bg-rose-50 p-2.5 rounded-lg">{fileError}</p>}
          </div>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 1rem; }
        #qr-reader-container { border: none !important; }
      `}</style>
    </div>
  );
};

export default Scanner;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  PlusCircle,
  Tag,
  Palette,
  Maximize2
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  const [editingThreshold, setEditingThreshold] = useState<string | null>(null);
  const [tempThreshold, setTempThreshold] = useState<number>(0);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values()).sort((a, b) => b.remaining - a.remaining);
  }, [transactions]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: cleanText, name: `Ürün ${cleanText}`, partner: '', size: '', color: '', quantity: '' };

      // JSON Ayrıştırma ve Mapping
      if (cleanText.startsWith('{')) {
        try {
          const parsed = JSON.parse(cleanText);

          // Akıllı Key Mapping (Alternatif başlıkları yakala)
          const findVal = (keys: string[]) => {
            const foundKey = Object.keys(parsed).find(k => keys.some(target => k.toLowerCase() === target.toLowerCase()));
            return foundKey ? parsed[foundKey] : null;
          };

          extractedData.code = findVal(['Kod', 'productCode', 'code', 'sku', 'urunKodu']) || extractedData.code;
          extractedData.name = findVal(['Ad', 'productName', 'name', 'urunAdi', 'urun']) || extractedData.name;
          extractedData.partner = findVal(['tedarikciFirma', 'tedarikci', 'firma', 'supplier', 'partner', 'kaynak', 'alici']) || '';
          extractedData.size = findVal(['Beden', 'size', 'sz', 'olcu']) || '';
          extractedData.color = findVal(['Renk', 'color', 'clr']) || '';
          extractedData.quantity = findVal(['miktar', 'quantity', 'qty', 'adet']) || '';

        } catch (e) {
          console.warn("JSON Parse failed, falling back to raw text");
        }
      } 
      // ;; Formatı Ayrıştırma (Firma;;Miktar;;Beden;;Tip;;Renk;;Tip2;;Kod;;Ad)
      else if (cleanText.includes(';;')) {
        const p = cleanText.split(';;').map(s => s.trim());
        extractedData.partner = p[0] || '';
        extractedData.quantity = p[1] || '';
        extractedData.size = p[2] || '';
        extractedData.color = p[4] || '';
        extractedData.code = p[6] || cleanText;
        extractedData.name = p[7] || `Ürün ${extractedData.code}`;
      }

      // State'leri Güncelle
      setProductCode(extractedData.code);
      setProductName(extractedData.name);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      if (extractedData.quantity) setQuantity(parseInt(extractedData.quantity) || '');

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler başarıyla eşleştirildi', 'success');
    } catch (e) {
      console.error("Scan error:", e);
      showNotification('Kod çözümleme hatası!', 'error');
    }
  };

  const handleSave = () => {
    if (!productCode || !quantity || !partner || !approver) {
      showNotification('Eksik alanları doldurun', 'error');
      return;
    }
    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Sistem',
      approver,
      size,
      color,
      feature
    };
    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);

    // Formu temizle
    setQuantity('');
    setPartner('');
    setSize('');
    setColor('');
    setFeature('');

    showNotification('İşlem başarıyla kaydedildi', 'success');
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-60 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2">
            <h1 className="text-lg font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v4.3</p>
          </div>

          <nav className="space-y-1 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Panel" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Giriş" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkış" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlemler" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcılar" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2">
              <div className="w-7 h-7 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-[10px] uppercase">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-bold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-2.5 text-rose-500 font-bold hover:bg-rose-50 rounded-lg transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center">
          <span className="font-extrabold text-indigo-600 text-xs tracking-tighter uppercase">ProStock Mobile</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-1.5 bg-slate-50 rounded-lg text-slate-500">
            {sidebarOpen ? <X size={18} /> : <Menu size={18} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-10 space-y-6">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-5 py-3.5 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-3 text-[11px] ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={16} /> : <CheckCircle2 size={16} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <header className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div>
                  <h2 className="text-xl font-extrabold text-slate-900 tracking-tight">Depo Durumu</h2>
                  <p className="text-slate-400 text-[11px]">Envanter hareketleri ve kritik ürün seviyeleri</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-2 bg-rose-50 text-rose-600 px-4 py-2 rounded-xl border border-rose-100/50">
                    <Bell size={12} className="animate-bounce" />
                    <span className="text-[9px] font-black uppercase tracking-widest">{criticalCount} Ürün Eksik</span>
                  </div>
                )}
              </header>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Net Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Toplam Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Toplam Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Limit Aşımı" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              <div className="bg-white rounded-3xl border border-slate-100 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.04)] overflow-hidden">
                <div className="p-5 border-b border-slate-50 flex justify-between items-center">
                  <h3 className="font-bold text-[12px] text-slate-800 flex items-center gap-2"><Box size={14} /> Stok Listesi</h3>
                  <div className="relative group">
                     <Search size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" />
                     <input type="text" placeholder="Filtrele..." className="pl-8 pr-4 py-1.5 bg-slate-50 border-none rounded-lg text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-100 w-32 sm:w-40 transition-all" />
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[9px] font-bold text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-6 py-4">Ürün Adı / Kod</th>
                        <th className="px-6 py-4">Miktar</th>
                        <th className="px-6 py-4">Eşik</th>
                        <th className="px-6 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {inventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/30 transition-all text-[11px]">
                          <td className="px-6 py-4">
                            <div className="font-bold text-slate-800">{item.productName}</div>
                            <div className="text-[8px] font-bold text-indigo-400 uppercase tracking-wider">{item.productCode}</div>
                          </td>
                          <td className="px-6 py-4 font-extrabold text-slate-900">{item.remaining}</td>
                          <td className="px-6 py-4 text-slate-300 font-bold">{thresholds[item.productCode] || 0}</td>
                          <td className="px-6 py-4 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="text-[8px] font-black uppercase text-rose-500 bg-rose-50 px-2 py-0.5 rounded-md">Kritik</span>
                            ) : (
                              <span className="text-[8px] font-black uppercase text-emerald-500 bg-emerald-50 px-2 py-0.5 rounded-md">Normal</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-xl mx-auto space-y-8 animate-fade-in py-4">
              <div className="text-center space-y-3">
                <div className={`inline-flex p-3.5 rounded-2xl mb-1 ${activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500'} text-white shadow-xl`}>
                  {activeTab === 'in' ? <PackagePlus size={24} /> : <PackageMinus size={24} />}
                </div>
                <h2 className="text-lg font-extrabold text-slate-900 tracking-tight uppercase">{activeTab === 'in' ? 'Stok Girişi' : 'Stok Çıkışı'}</h2>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[2rem] p-12 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/20 transition-all group">
                  <div className="p-5 bg-indigo-600 rounded-2xl text-white shadow-xl group-hover:scale-105 transition-transform mb-5">
                    <Maximize2 size={28} />
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Okutmak İçin Dokun</p>
                </div>
              ) : (
                <div className="bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-slate-100 space-y-6 animate-fade-in">
                  <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="space-y-0.5">
                      <p className="text-[8px] font-bold text-indigo-600 uppercase tracking-widest opacity-60">{productCode}</p>
                      <h3 className="font-extrabold text-slate-900 text-[13px]">{productName}</h3>
                    </div>
                    <div className="text-right">
                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Bakiye</p>
                      <p className="text-lg font-black text-slate-900 leading-none">{inventory.find(i=>i.productCode===productCode)?.remaining || 0}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <InputSmall label="Miktar" type="number" value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} />
                    <InputSmall label={activeTab==='in' ? 'Tedarikçi / Kaynak' : 'Müşteri / Alıcı'} value={partner} onChange={setPartner} placeholder="Firma Adı" />
                    <InputSmall label="Beden" value={size} onChange={setSize} />
                    <InputSmall label="Renk" value={color} onChange={setColor} />
                    <div className="col-span-2">
                      <InputSmall label="Onaylayan" value={approver} onChange={setApprover} placeholder="İsim Soyisim" />
                    </div>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <button onClick={()=>{setIsFormActive(false); setQuantity('');}} className="flex-1 py-3.5 bg-slate-50 rounded-xl font-bold text-slate-400 text-[9px] uppercase tracking-widest">Vazgeç</button>
                    <button onClick={handleSave} className={`flex-1 py-3.5 rounded-xl font-bold text-white text-[9px] uppercase tracking-widest shadow-lg ${activeTab==='in' ? 'bg-indigo-600' : 'bg-rose-500'}`}>Kaydet</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6 animate-fade-in max-w-6xl mx-auto">
              <h3 className="text-lg font-extrabold text-slate-900 tracking-tight">İşlem Günlüğü</h3>
              <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[9px] font-bold text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-6 py-4">Tarih</th>
                        <th className="px-6 py-4">Ürün</th>
                        <th className="px-6 py-4">Tür</th>
                        <th className="px-6 py-4">Adet</th>
                        <th className="px-6 py-4">Yetkili</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {transactions.map(t => (
                        <tr key={t.id} className="text-[11px] hover:bg-slate-50/20">
                          <td className="px-6 py-4 text-slate-400 font-medium">{t.date.split(' ')[0]}</td>
                          <td className="px-6 py-4">
                            <span className="font-bold text-slate-800">{t.productName}</span>
                            <div className="text-[8px] text-slate-400 font-bold uppercase">{t.size} {t.color} {t.productCode}</div>
                            <div className="text-[8px] text-indigo-400 font-bold uppercase mt-0.5">{t.supplier || t.recipient}</div>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase ${t.type===TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{t.type}</span>
                          </td>
                          <td className="px-6 py-4 font-extrabold">{t.quantity}</td>
                          <td className="px-6 py-4 text-slate-500">{t.approver}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group ${active ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={16} /> 
    <span className="text-[10px] font-bold tracking-tight uppercase">{label}</span>
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-4 rounded-[1.8rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-md transition-all">
    <div className="space-y-1">
      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-lg font-extrabold text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-2 bg-${color}-50 text-${color}-600 rounded-lg group-hover:bg-${color}-600 group-hover:text-white transition-all`}>
      <Icon size={14} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-1.5">
    <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest ml-2 opacity-70">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange(e.target.value)} 
      className="w-full px-4 py-2.5 bg-slate-50 border border-transparent rounded-xl focus:border-indigo-100 focus:bg-white font-bold text-slate-800 outline-none transition-all placeholder:text-slate-200 text-[11px] shadow-sm" 
    />
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  PlusCircle,
  Tag,
  Palette,
  Maximize2,
  Info
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Form states - Aligning with user's specific labels
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values()).sort((a, b) => b.remaining - a.remaining);
  }, [transactions]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };

      // Generic Regex to catch "key":"value" or key:value patterns
      // This will specifically look for the content after the colon
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*:\\s*"([^"]+)"|'${key}'\\s*:\\s*'([^']+)'|${key}\\s*:\\s*([^,}\\s]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      // Try specific mapping for user's requested fields
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || regexMatch('partner') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.quantity = regexMatch('adet') || regexMatch('miktar') || regexMatch('quantity') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';

      // Fallback: If JSON is valid but regex missed something
      if (cleanText.startsWith('{')) {
        try {
          const parsed = JSON.parse(cleanText);
          const findInParsed = (keys: string[]) => {
            const k = Object.keys(parsed).find(pk => keys.some(tk => pk.toLowerCase() === tk.toLowerCase()));
            return k ? parsed[k] : null;
          };

          extractedData.code = extractedData.code || findInParsed(['urunKodu', 'productCode', 'kod']);
          extractedData.name = extractedData.name || findInParsed(['urunAdi', 'productName', 'ad']);
          extractedData.partner = extractedData.partner || findInParsed(['tedarikciFirma', 'tedarikci', 'firma', 'supplier']);
          extractedData.size = extractedData.size || findInParsed(['beden', 'size']);
          extractedData.color = extractedData.color || findInParsed(['renk', 'color']);
          extractedData.quantity = extractedData.quantity || findInParsed(['adet', 'miktar', 'quantity']);
          extractedData.feature = extractedData.feature || findInParsed(['ozellik', 'feature']);
        } catch (e) {}
      }

      // If nothing extracted, use whole text as code
      if (!extractedData.code) extractedData.code = cleanText;
      if (!extractedData.name) extractedData.name = `Ürün ${extractedData.code}`;

      // Update State
