import { User, Transaction, UserRole, ProductThreshold } from '../types';

const KEYS = {
  USERS: 'stock_app_users',
  TRANSACTIONS: 'stock_app_transactions',
  CURRENT_USER: 'stock_app_auth',
  THRESHOLDS: 'stock_app_thresholds'
};

const DEFAULT_ADMIN: User = {
  id: 'admin-1',
  username: 'admin',
  password: '123',
  role: UserRole.ADMIN,
  fullName: 'Sistem Yöneticisi'
};

export const StorageService = {
  getUsers: (): User[] => {
    const data = localStorage.getItem(KEYS.USERS);
    return data ? JSON.parse(data) : [DEFAULT_ADMIN];
  },

  saveUser: (user: User) => {
    const users = StorageService.getUsers();
    const existingIndex = users.findIndex(u => u.id === user.id);
    if (existingIndex > -1) {
      users[existingIndex] = user;
    } else {
      users.push(user);
    }
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
  },

  updateUser: (id: string, updates: Partial<User>) => {
    const users = StorageService.getUsers();
    const index = users.findIndex(u => u.id === id);
    if (index > -1) {
      users[index] = { ...users[index], ...updates };
      localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    }
  },

  deleteUser: (id: string) => {
    const users = StorageService.getUsers().filter(u => u.id !== id);
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
  },

  getTransactions: (): Transaction[] => {
    const data = localStorage.getItem(KEYS.TRANSACTIONS);
    return data ? JSON.parse(data) : [];
  },

  addTransaction: (transaction: Transaction) => {
    const transactions = StorageService.getTransactions();
    transactions.unshift(transaction);
    localStorage.setItem(KEYS.TRANSACTIONS, JSON.stringify(transactions));
  },

  deleteTransaction: (id: string) => {
    const transactions = StorageService.getTransactions().filter(t => t.id !== id);
    localStorage.setItem(KEYS.TRANSACTIONS, JSON.stringify(transactions));
  },

  clearAllTransactions: () => {
    localStorage.setItem(KEYS.TRANSACTIONS, JSON.stringify([]));
  },

  getThresholds: (): Record<string, number> => {
    const data = localStorage.getItem(KEYS.THRESHOLDS);
    return data ? JSON.parse(data) : {};
  },

  saveThreshold: (productCode: string, minLevel: number) => {
    const thresholds = StorageService.getThresholds();
    thresholds[productCode] = minLevel;
    localStorage.setItem(KEYS.THRESHOLDS, JSON.stringify(thresholds));
  },

  setCurrentUser: (user: User | null) => {
    if (user) {
      localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    } else {
      localStorage.removeItem(KEYS.CURRENT_USER);
    }
  },

  getCurrentUser: (): User | null => {
    const data = localStorage.getItem(KEYS.CURRENT_USER);
    return data ? JSON.parse(data) : null;
  }
};

