    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => 
      item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
      item.productCode.toLowerCase().includes(searchQuery.toLowerCase())
    ).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };

      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*:\\s*"([^"]+)"|'${key}'\\s*:\\s*'([^']+)'|${key}\\s*:\\s*([^,}\\s]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.quantity = regexMatch('adet') || regexMatch('miktar') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setQuantity(''); // Kullanıcı doldursun diye boş bırakıyoruz
      setOperatorName(user?.fullName || '');

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Ürün tanımlandı', 'success');
    } catch (e) {
      showNotification('Kod ayrıştırma hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;

    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }

    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! Mevcut: ${currentStock}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);

    // Reset form
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover('');
    showNotification('İşlem kaydedildi', 'success');
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı güncellendi', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    if (window.confirm('Bu işlemi kalıcı olarak silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem silindi', 'success');
    }
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-60 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2">
            <h1 className="text-lg font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">System v5.0</p>
          </div>

          <nav className="space-y-1 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Genel Bakış" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Giriş" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkış" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcılar" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2">
              <div className="w-7 h-7 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-[10px] uppercase">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-bold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-2.5 text-rose-500 font-bold hover:bg-rose-50 rounded-lg transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Çıkış Yap
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center">
          <span className="font-extrabold text-indigo-600 text-xs tracking-tighter uppercase">ProStock Mobile</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-1.5 bg-slate-50 rounded-lg text-slate-500">
            {sidebarOpen ? <X size={18} /> : <Menu size={18} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-10 space-y-6">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-5 py-3.5 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-3 text-[11px] ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={16} /> : <CheckCircle2 size={16} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <header className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div>
                  <h2 className="text-xl font-extrabold text-slate-900 tracking-tight">Rapor Paneli</h2>
                  <p className="text-slate-400 text-[11px]">Gelişmiş filtreleme ile tüm envanter detayları</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-2 bg-rose-50 text-rose-600 px-4 py-2 rounded-xl border border-rose-100/50">
                    <Bell size={12} className="animate-bounce" />
                    <span className="text-[9px] font-black uppercase tracking-widest">{criticalCount} Ürün Alt Limit Altında</span>
                  </div>
                )}
              </header>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Net Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Toplam Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Toplam Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Kritik Limit" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-5 border-b border-slate-50 flex flex-col sm:flex-row justify-between items-center gap-4">
                  <h3 className="font-bold text-[12px] text-slate-800 flex items-center gap-2"><Box size={14} /> Güncel Stok & Eşik Ayarları</h3>
                  <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="relative flex-1 sm:flex-none">
                       <Search size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" />
                       <input 
                        type="text" 
                        placeholder="Ürün veya kod ara..." 
                        value={searchQuery}
                        onChange={(e)=>setSearchQuery(e.target.value)}
                        className="pl-8 pr-4 py-2 bg-slate-50 border-none rounded-lg text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-100 w-full sm:w-48 transition-all" 
                       />
                    </div>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[9px] font-bold text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-6 py-4">Ürün Bilgisi</th>
                        <th className="px-6 py-4">Giriş / Çıkış</th>
                        <th className="px-6 py-4">Güncel Adet</th>
                        <th className="px-6 py-4">Alt Limit (Eşik)</th>
                        <th className="px-6 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/30 transition-all text-[11px]">
                          <td className="px-6 py-4">
                            <div className="font-bold text-slate-800">{item.productName}</div>
                            <div className="text-[8px] font-bold text-indigo-400 uppercase tracking-wider">{item.productCode}</div>
                          </td>
                          <td className="px-6 py-4">
                            <span className="text-emerald-500 font-bold">+{item.totalIn}</span>
                            <span className="mx-1 text-slate-200">/</span>
                            <span className="text-rose-500 font-bold">-{item.totalOut}</span>
                          </td>
                          <td className="px-6 py-4 font-black text-slate-900 text-[13px]">{item.remaining}</td>
                          <td className="px-6 py-4">
                            {user.role === UserRole.ADMIN ? (
                              <input 
                                type="number" 
                                value={thresholds[item.productCode] || 0}
                                onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                className="w-16 px-2 py-1 bg-slate-50 border border-slate-100 rounded-md font-bold text-[10px] outline-none focus:border-indigo-200"
                              />
                            ) : (
                              <span className="text-slate-400 font-bold">{thresholds[item.productCode] || 0}</span>
                            )}
                          </td>
                          <td className="px-6 py-4 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="text-[8px] font-black uppercase text-rose-500 bg-rose-50 px-2 py-1 rounded-md">YETERSİZ</span>
                            ) : (
                              <span className="text-[8px] font-black uppercase text-emerald-500 bg-emerald-50 px-2 py-1 rounded-md">YETERLİ</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-xl mx-auto space-y-8 animate-fade-in py-4">
              <div className="text-center space-y-3">
                <div className={`inline-flex p-4 rounded-3xl mb-1 ${activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500'} text-white shadow-2xl`}>
                  {activeTab === 'in' ? <PackagePlus size={28} /> : <PackageMinus size={28} />}
                </div>
                <h2 className="text-xl font-extrabold text-slate-900 tracking-tight uppercase">
                  {activeTab === 'in' ? 'Yeni Stok Girişi' : 'Yeni Stok Çıkışı'}
                </h2>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] p-20 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/20 transition-all group shadow-sm">
                  <div className="p-7 bg-indigo-600 rounded-[2rem] text-white shadow-xl group-hover:scale-110 transition-transform mb-6">
                    <Maximize2 size={36} />
                  </div>
                  <p className="text-[12px] font-black uppercase tracking-[0.3em] text-slate-500">QR / Barkod Tara</p>
                  <p className="text-[9px] text-slate-300 mt-2 font-bold uppercase">Kamera veya Galeri Kullanın</p>
                </div>
              ) : (
                <div className="bg-white p-8 sm:p-12 rounded-[3rem] shadow-xl border border-slate-50 space-y-10 animate-fade-in">
                  <div className="flex justify-between items-center p-6 bg-slate-50 rounded-[1.5rem] border border-slate-100">
                    <div className="space-y-1">
                      <p className="text-[9px] font-bold text-indigo-600 uppercase tracking-widest opacity-60">Seçili Ürün</p>
                      <h3 className="font-extrabold text-slate-900 text-[15px]">{productName}</h3>
                      <p className="text-[10px] font-bold text-slate-400">Kod: {productCode}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">En Son Kalan</p>
                      <p className="text-3xl font-black text-slate-900 leading-none">
                        {inventory.find(i=>i.productCode===productCode)?.remaining || 0}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div className="sm:col-span-2">
                       <InputSmall 
                        label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı / Departman"} 
                        value={partner} 
                        onChange={setPartner} 
                        placeholder="Firma veya Birim Adı" 
                       />
                    </div>
                    <InputSmall label="İşlem Adeti" type="number" value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} placeholder="0" />
                    <InputSmall label="Beden" value={size} onChange={setSize} />
                    <InputSmall label="Renk" value={color} onChange={setColor} />
                    <InputSmall label="Özellik" value={feature} onChange={setFeature} />
                    <InputSmall label="İşlemi Yapan" value={operatorName} onChange={setOperatorName} />
                    <InputSmall label="Onaylayan" value={approver} onChange={setApprover} placeholder="Yetkili Kişi" />
                  </div>

                  <div className="flex gap-4 pt-4">
                    <button onClick={()=>{setIsFormActive(false); setQuantity(''); setPartner('');}} className="flex-1 py-4 bg-slate-50 rounded-2xl font-bold text-slate-400 text-[10px] uppercase tracking-widest hover:bg-slate-100 transition-all">Vazgeç</button>
                    <button onClick={handleSave} className={`flex-1 py-4 rounded-2xl font-bold text-white text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95 ${activeTab==='in' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-rose-500 hover:bg-rose-600'}`}>İşlemi Tamamla</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-6 animate-fade-in max-w-6xl mx-auto">
              <div className="flex justify-between items-center">
                <h3 className="text-lg font-extrabold text-slate-900 tracking-tight">Kullanıcı Yönetimi</h3>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 text-white rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg">
                  <UserPlus size={14} /> Yeni Kullanıcı
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between group">
                    <div className="flex items-center gap-3">
                       <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-sm uppercase">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-bold text-slate-900">{u.fullName}</p>
                          <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{u.role} | @{u.username}</p>
                       </div>
                    </div>
                    <div className="flex gap-1">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><Edit size={14} /></button>
                       <button onClick={()=>{if(window.confirm('Bu kullanıcıyı silmek istiyor musunuz?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"><Trash2 size={14} /></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6 animate-fade-in max-w-6xl mx-auto">
              <div className="flex justify-between items-center">
                <h3 className="text-lg font-extrabold text-slate-900 tracking-tight">Haraket İzleyici</h3>
                {user.role === UserRole.ADMIN && (
                  <button onClick={()=>{if(window.confirm('Tüm geçmişi temizlemek istiyor musunuz?')){StorageService.clearAllTransactions(); setTransactions([]);}}} className="text-rose-500 font-bold text-[9px] uppercase tracking-widest flex items-center gap-2 bg-rose-50 px-3 py-2 rounded-lg">
                    <Trash2 size={12} /> Tümünü Sil
                  </button>
                )}
              </div>
              <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[9px] font-bold text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-6 py-4">Zaman</th>
                        <th className="px-6 py-4">Ürün & Detay</th>
                        <th className="px-6 py-4">Tür</th>
                        <th className="px-6 py-4">Adet</th>
                        <th className="px-6 py-4">İşlemi Yapan / Onaylayan</th>
                        {user.role === UserRole.ADMIN && <th className="px-6 py-4 text-right">#</th>}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {transactions.map(t => (
                        <tr key={t.id} className="text-[11px] hover:bg-slate-50/20">
                          <td className="px-6 py-4 text-slate-400 font-medium">{t.date}</td>
                          <td className="px-6 py-4">
                            <span className="font-bold text-slate-800">{t.productName}</span>
                            <div className="text-[8px] text-slate-400 font-bold uppercase mt-0.5">
                              {t.size && `B: ${t.size}`} {t.color && `| R: ${t.color}`} | {t.productCode}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase ${t.type===TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{t.type}</span>
                          </td>
                          <td className="px-6 py-4 font-black text-[13px]">{t.quantity}</td>
                          <td className="px-6 py-4">
                            <div className="text-slate-600 font-bold">{t.operator}</div>
                            <div className="text-[8px] text-slate-400 uppercase tracking-widest flex items-center gap-1 mt-0.5"><CheckCircle2 size={10} className="text-indigo-400" /> {t.approver}</div>
                          </td>
                          {user.role === UserRole.ADMIN && (
                            <td className="px-6 py-4 text-right">
                              <button onClick={()=>handleDeleteTransaction(t.id)} className="text-slate-200 hover:text-rose-500"><Trash2 size={12}/></button>
                            </td>
                          )}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* User Edit Modal */}
      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4">
           <div className="bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl animate-fade-in">
              <h4 className="text-lg font-black text-slate-900 mb-6">{editingUser ? 'Kullanıcı Düzenle' : 'Yeni Kullanıcı'}</h4>
              <form onSubmit={handleUserSave} className="space-y-4">
                 <InputSmall label="Tam Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-1.5">
                    <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1.5">Rol</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800 text-[12px] outline-none">
                       <option value={UserRole.ADMIN}>Yönetici (Admin)</option>
                       <option value={UserRole.USER}>Kullanıcı (User)</option>
                    </select>
                 </div>
                 <div className="flex gap-3 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-3.5 bg-slate-50 rounded-xl font-bold text-slate-400 text-[10px] uppercase">Vazgeç</button>
                    <button type="submit" className="flex-1 py-3.5 bg-indigo-600 rounded-xl font-bold text-white text-[10px] uppercase shadow-lg">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group ${active ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={16} /> 
    <span className="text-[10px] font-bold tracking-tight uppercase">{label}</span>
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-4 rounded-[1.8rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-md transition-all">
    <div className="space-y-1">
      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-lg font-extrabold text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-2 bg-${color}-50 text-${color}-600 rounded-lg group-hover:bg-${color}-600 group-hover:text-white transition-all`}>
      <Icon size={14} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1.5 opacity-80">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange?.(e.target.value)} 
      className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl focus:border-indigo-200 focus:bg-white focus:ring-4 focus:ring-indigo-50/30 font-bold text-slate-800 outline-none transition-all placeholder:text-slate-300 text-[12px] shadow-sm" 
    />
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [filterSize, setFilterSize] = useState('');
  const [filterColor, setFilterColor] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const matchesSearch = item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
      // Daha detaylı özellik filtreleme için transaction geçmişine bakılabilir 
      // Ancak genel stok görünümü için temel arama yeterlidir.
      return matchesSearch;
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };

      const regexMatch = (key: string) => {
        // Genel formatlar
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      // Adet için özel sayı yakalama (Örn: "adet"":""";100;")
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);

      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;

    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }

    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);

    // Temizlik
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover('');
    showNotification('İşlem Başarıyla Kaydedildi', 'success');
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Depo genel durumu ve eşik limitleri</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-3 bg-amber-50 text-amber-600 px-5 py-3 rounded-2xl border border-amber-100 shadow-sm">
                    <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest">{criticalCount} Ürün Alt Limit Altında</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
                <StatCard label="Toplam Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Aylık Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Aylık Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Alt Limit Aşımı" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden transition-all hover:shadow-md">
                <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col lg:flex-row justify-between items-center gap-6 bg-slate-50/30">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100"><Box size={18} /></div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Güncel Stok & Eşik Ayarları</h3>
                  </div>
                  <div className="flex items-center gap-3 w-full lg:w-auto">
                    <div className="relative flex-1 lg:w-72 group">
                       <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
                       <input 
                        type="text" 
                        placeholder="Ürün kodu veya isimle filtrele..." 
                        value={searchQuery}
                        onChange={(e)=>setSearchQuery(e.target.value)}
                        className="pl-11 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-200 w-full shadow-sm transition-all" 
                       />
                    </div>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">
                      <tr>
                        <th className="px-8 py-5">Ürün Detay Bilgisi</th>
                        <th className="px-8 py-5">Giriş / Çıkış</th>
                        <th className="px-8 py-5">En Son Kalan</th>
                        <th className="px-8 py-5">Alt Limit (Admin)</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/40 transition-all text-[12px] group">
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px] group-hover:text-indigo-600 transition-colors">{item.productName}</div>
                            <div className="text-[10px] font-bold text-slate-400 mt-1 flex items-center gap-2">
                               <span className="bg-slate-100 px-2 py-0.5 rounded-md text-[9px] uppercase">{item.productCode}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <div className="flex items-center gap-3 font-bold">
                              <span className="text-emerald-500 bg-emerald-50 px-2 py-1 rounded-lg text-[10px]">+{item.totalIn}</span>
                              <span className="text-rose-500 bg-rose-50 px-2 py-1 rounded-lg text-[10px]">-{item.totalOut}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                             <div className="font-black text-slate-900 text-[16px] tracking-tight">{item.remaining}</div>
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              <div className="flex items-center gap-2">
                                <input 
                                  type="number" 
                                  value={thresholds[item.productCode] || 0}
                                  onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                  className="w-20 px-3 py-2 bg-slate-50 border border-slate-100 rounded-xl font-black text-[11px] outline-none focus:bg-white focus:border-indigo-300 transition-all shadow-inner"
                                />
                                <Edit size={12} className="text-slate-200" />
                              </div>
                            ) : (
                              <div className="flex items-center gap-2 text-slate-400 font-bold bg-slate-50 px-3 py-2 rounded-xl w-fit">
                                <Lock size={12} className="opacity-40" />
                                <span>{thresholds[item.productCode] || 0}</span>
                              </div>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-rose-50 text-rose-600 rounded-xl border border-rose-100">
                                <AlertCircle size={14} />
                                <span className="text-[10px] font-black uppercase tracking-widest">Kritik</span>
                              </div>
                            ) : (
                              <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-emerald-50 text-emerald-600 rounded-xl border border-emerald-100">
                                <CheckCircle2 size={14} />
                                <span className="text-[10px] font-black uppercase tracking-widest">Yeterli</span>
                              </div>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {filteredInventory.length === 0 && (
                    <div className="p-24 text-center space-y-4">
                       <Box size={48} className="mx-auto text-slate-100" />
                       <p className="text-slate-300 font-extrabold uppercase text-[11px] tracking-[0.2em]">Sonuç Bulunamadı</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-xl mx-auto space-y-8 animate-fade-in py-6">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-5 rounded-[2rem] mb-2 ${activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'} text-white shadow-2xl scale-110`}>
                  {activeTab === 'in' ? <PackagePlus size={32} /> : <PackageMinus size={32} />}
                </div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">
                  {activeTab === 'in' ? 'Stok Giriş Formu' : 'Stok Çıkış Formu'}
                </h2>
                <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest px-10">Tüm bilgiler QR kodundan otomatik alınır veya manuel girilebilir.</p>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[3.5rem] p-24 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/10 transition-all group shadow-sm active:scale-95 duration-300">
                  <div className="p-8 bg-indigo-600 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-100 group-hover:scale-110 group-hover:-rotate-3 transition-all mb-8">
                    <Maximize2 size={40} />
                  </div>
                  <p className="text-[13px] font-black uppercase tracking-[0.4em] text-slate-500 mb-2">QR Kodu Taratın</p>
                  <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest">Kamera veya Galeri (JPG/PNG)</p>
                </div>
              ) : (
                <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-2xl shadow-slate-100 border border-slate-50 space-y-12 animate-fade-in relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/30 rounded-full -mr-16 -mt-16 blur-3xl"></div>

                  <div className="flex justify-between items-center p-8 bg-slate-50/50 rounded-[2rem] border border-slate-100 relative z-10">
                    <div className="space-y-1.5">
                      <p className="text-[9px] font-black text-indigo-600 uppercase tracking-[0.2em] opacity-80">Aktif Ürün Kartı</p>
                      <h3 className="font-black text-slate-900 text-[18px] tracking-tight">{productName}</h3>
                      <div className="flex items-center gap-2">
                         <span className="text-[11px] font-bold text-slate-400">KOD: {productCode}</span>
                         {size && <span className="w-1 h-1 bg-slate-300 rounded-full"></span>}
                         {size && <span className="text-[11px] font-black text-indigo-400 uppercase">BEDEN: {size}</span>}
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">En Son Kalan</p>
                      <p className={`text-4xl font-black leading-none ${activeTab === 'out' ? 'text-rose-600' : 'text-slate-900'}`}>
                        {inventory.find(i=>i.productCode===productCode)?.remaining || 0}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 relative z-10">
                    <div className="sm:col-span-2">
                       <InputSmall 
                        label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı / Departman"} 
