import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  AlertCircle, 
  XCircle, 
  Loader2, 
  ImagePlus, 
  Zap, 
  Settings2, 
  SlidersHorizontal,
  Camera
} from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [scanStep, setScanStep] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);
  const [scanLocked, setScanLocked] = useState(false);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Durdurma hatası:", err);
      }
    }
  }, []);

  const handleScanSuccess = useCallback((text: string) => {
    if (scanLocked) return;
    setScanLocked(true);
    onScan(text);
    stopScanner().finally(() => onClose());
  }, [onScan, onClose, stopScanner, scanLocked]);

  const startCamera = useCallback(async () => {
    await new Promise(resolve => setTimeout(resolve, 300));
    await stopScanner();

    const container = document.getElementById(scannerId);
    if (!container) return;

    const html5QrCode = new Html5Qrcode(scannerId, { verbose: false });
    html5QrCodeRef.current = html5QrCode;

    try {
      setIsInitializing(true);
      const config = {
        fps: 30,
        qrbox: (vw: number, vh: number) => {
          const s = Math.floor(Math.min(vw, vh) * 0.7);
          return { width: s, height: s };
        },
        aspectRatio: 1.0
      };

      await html5QrCode.start(
        { facingMode: "environment" },
        config,
        handleScanSuccess,
        () => {} 
      );
    } catch (err) {
      console.error("Kamera Hatası:", err);
      setFileError("Kamera başlatılamadı. Lütfen izinleri kontrol edin.");
    } finally {
      setIsInitializing(false);
    }
  }, [stopScanner, handleScanSuccess]);

  useEffect(() => {
    startCamera();
    return () => { stopScanner(); };
  }, []);

  // Görsel iyileştirme algoritması (Gürültü azaltma ve kontrast artırma)
  const processImage = async (img: HTMLImageElement): Promise<string> => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D;

    const scale = Math.min(1, 1200 / Math.max(img.width, img.height));
    canvas.width = img.width * scale;
    canvas.height = img.height * scale;

    // Filtreler: Siyah-Beyaz + Yüksek Kontrast
    ctx.filter = 'contrast(1.6) grayscale(1) brightness(1.1)';
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    return canvas.toDataURL('image/jpeg', 0.85);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileError(null);
    setIsProcessingFile(true);
    setScanStep('Görsel Analiz Ediliyor...');

    try {
      await stopScanner();
      const img = new Image();
      img.src = URL.createObjectURL(file);
      await new Promise((resolve) => img.onload = resolve);

      const tempScanner = new Html5Qrcode(scannerId);

      // 1. Deneme: Ham dosya
      try {
        const res = await tempScanner.scanFile(file, false);
        handleScanSuccess(res);
      } catch (e) {
        // 2. Deneme: İyileştirilmiş görsel
        setScanStep('Görüntü İyileştiriliyor...');
        const dataUrl = await processImage(img);
        const blob = await (await fetch(dataUrl)).blob();
        const res = await tempScanner.scanFile(blob as File, false);
        handleScanSuccess(res);
      }
    } catch (err) {
      setFileError("QR Kod Okunamadı! Lütfen net bir fotoğraf yükleyin.");
      setTimeout(() => startCamera(), 1000);
    } finally {
      setIsProcessingFile(false);
      setScanStep('');
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl p-6 transition-all animate-fade-in">
      <div className="bg-white w-full max-w-sm rounded-[3rem] overflow-hidden shadow-2xl border border-white/10">

        <div className="p-8 flex justify-between items-center border-b border-slate-50">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center shadow-inner">
                <Camera size={20} />
             </div>
             <div className="space-y-0.5">
                <h3 className="font-black text-[13px] text-slate-800 tracking-tight uppercase">Akıllı Vizör</h3>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Vision Engine v2.0</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-rose-50 text-rose-500 rounded-2xl hover:bg-rose-100 transition-colors shadow-sm">
            <XCircle size={18} />
          </button>
        </div>

        <div className="p-8 space-y-8">
          <div className="relative aspect-square">
            <div id={scannerId} className="w-full h-full rounded-[2rem] overflow-hidden bg-slate-950 relative z-0 shadow-inner"></div>

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-slate-950 rounded-[2rem] z-10 transition-all">
                <Loader2 size={32} className="text-indigo-400 animate-spin" />
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] animate-pulse">Mercek Hazırlanıyor...</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center rounded-[2rem] z-20 text-white animate-fade-in shadow-2xl">
                <Zap size={40} className="text-amber-300 animate-pulse mb-4" />
                <p className="font-black text-[12px] uppercase tracking-[0.2em]">{scanStep}</p>
                <div className="mt-4 w-32 h-1 bg-white/20 rounded-full overflow-hidden">
                   <div className="h-full bg-white animate-[loading_2s_infinite]"></div>
                </div>
              </div>
            )}

            {/* Vizör Çerçevesi */}
            <div className="absolute inset-0 border-[40px] border-slate-950/40 pointer-events-none rounded-[2rem] z-0"></div>
            <div className="absolute top-1/2 left-0 w-full h-[2px] bg-indigo-500/30 animate-[scan_3s_infinite] pointer-events-none"></div>
          </div>

          <div className="space-y-4">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-3 py-4.5 bg-slate-900 text-white rounded-[1.5rem] hover:bg-indigo-600 transition-all font-black text-[11px] uppercase tracking-[0.2em] shadow-xl active:scale-95 duration-300">
              <ImagePlus size={18} /> Galeriden Analiz Et
            </button>
            {fileError && (
              <div className="flex items-center gap-2 text-[10px] text-rose-500 font-black justify-center bg-rose-50 p-4 rounded-2xl border border-rose-100 animate-fade-in">
                <AlertCircle size={14} />
                <span className="uppercase tracking-widest">{fileError}</span>
              </div>
            )}
          </div>
        </div>
      </div>
      <style>{`
        #qr-reader-container video { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 1.5rem; }
        #qr-reader-container { border: none !important; }
        @keyframes loading {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0%, 100% { transform: translateY(-150px); }
          50% { transform: translateY(150px); }
        }
      `}</style>
    </div>
  );
};

export default Scanner;

