                          <div className="flex items-center gap-2">
                             <span className="text-[9px] text-white bg-indigo-500 font-black uppercase tracking-widest px-1.5 py-0.5 rounded-md">{u.role}</span>
                             <span className="text-[10px] text-slate-400 font-bold">@{u.username}</span>
                          </div>
                       </div>
                    </div>
                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all shadow-sm"><Edit size={16} /></button>
                       <button onClick={()=>{if(window.confirm(`${u.fullName} kullanıcısını silmek istediğinize emin misiniz?`)){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers()); showNotification('Kullanıcı Silindi', 'success');}}} className="p-2.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all shadow-sm"><Trash2 size={16} /></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col lg:flex-row justify-between items-end gap-6">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">İşlem ve Onay Günlüğü</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Geçmişe dönük tüm stok hareketleri</p>
                </div>
                {user.role === UserRole.ADMIN && (
                  <button onClick={()=>{if(window.confirm('Tüm geçmişi kalıcı olarak silmek istediğinize emin misiniz?')){StorageService.clearAllTransactions(); setTransactions([]); showNotification('Tüm Veriler Temizlendi', 'success');}}} className="text-rose-500 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 bg-rose-50 px-5 py-3 rounded-2xl border border-rose-100 hover:bg-rose-100 transition-all">
                    <Trash2 size={14} /> Arşivi Temizle
                  </button>
                )}
              </div>

              {/* Advanced Filter Bar */}
              <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col xl:flex-row gap-6 items-center">
                 <div className="flex-1 w-full relative group">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500" />
                    <input 
                      type="text" 
                      placeholder="Ürün Kodu veya İsim Ara..." 
                      className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-[12px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-inner"
                      value={historySearch}
                      onChange={(e)=>setHistorySearch(e.target.value)}
                    />
                 </div>

                 <div className="flex items-center gap-3 w-full xl:w-auto">
                    <div className="flex-1 lg:w-44 space-y-1">
                       <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Başlangıç</label>
                       <div className="relative">
                          <input 
                            type="date" 
                            className="w-full pl-3 pr-3 py-3 bg-slate-50 border border-slate-100 rounded-xl text-[11px] font-bold outline-none focus:bg-white"
                            value={historyStartDate}
                            onChange={(e)=>setHistoryStartDate(e.target.value)}
                          />
                       </div>
                    </div>
                    <div className="flex-1 lg:w-44 space-y-1">
                       <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Bitiş</label>
                       <input 
                        type="date" 
                        className="w-full pl-3 pr-3 py-3 bg-slate-50 border border-slate-100 rounded-xl text-[11px] font-bold outline-none focus:bg-white"
                        value={historyEndDate}
                        onChange={(e)=>setHistoryEndDate(e.target.value)}
                       />
                    </div>
                 </div>

                 <div className="flex items-center p-1 bg-slate-50 rounded-2xl border border-slate-100 w-full xl:w-auto">
                    <FilterButton active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Hepsi" />
                    <FilterButton active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Giriş" />
                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkış" />
                 </div>

                 {(historySearch || historyStartDate || historyEndDate || historyTypeFilter !== 'ALL') && (
                    <button onClick={()=>{setHistorySearch(''); setHistoryStartDate(''); setHistoryEndDate(''); setHistoryTypeFilter('ALL');}} className="p-3 text-slate-300 hover:text-rose-500 transition-colors">
                       <XCircle size={20} />
                    </button>
                 )}
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-8 py-5">Zaman / Tarih</th>
                        <th className="px-8 py-5">Ürün & Teknik Detay</th>
                        <th className="px-8 py-5">İşlem Türü</th>
                        <th className="px-8 py-5">Ürün Adeti</th>
                        <th className="px-8 py-5">Yapan / Onaylayan</th>
                        {user.role === UserRole.ADMIN && <th className="px-8 py-5 text-right">Eylem</th>}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50/30 transition-all">
                          <td className="px-8 py-6 text-slate-400 font-bold">{t.date}</td>
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{t.productName}</div>
                            <div className="text-[9px] text-indigo-400 font-black uppercase mt-1.5 flex items-center gap-2">
                               {t.size && <span className="bg-indigo-50 px-2 py-0.5 rounded-md">BEDEN: {t.size}</span>}
                               {t.color && <span className="bg-indigo-50 px-2 py-0.5 rounded-md">RENK: {t.color}</span>}
                               <span className="bg-slate-50 px-2 py-0.5 rounded-md text-slate-400">#{t.productCode}</span>
                            </div>
                            <div className="text-[10px] text-slate-400 font-bold mt-2 italic flex items-center gap-1">
                               <ArrowRightLeft size={10} /> {t.supplier || t.recipient || 'Tanımlanmamış'}
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${t.type===TransactionType.IN ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>{t.type}</span>
