                          verticalAlign="top" 
                          align="right" 
                          iconType="circle"
                          wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: '800', textTransform: 'uppercase', letterSpacing: '0.05em' }}
                        />
                        <Bar 
                          name="Giriş" 
                          dataKey="Giriş" 
                          fill="#4f46e5" 
                          radius={[6, 6, 0, 0]} 
                          barSize={32}
                        />
                        <Bar 
                          name="Çıkış" 
                          dataKey="Çıkış" 
                          fill="#f43f5e" 
                          radius={[6, 6, 0, 0]} 
                          barSize={32}
                        />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-3">
                       <BarChart3 size={48} className="opacity-20" />
                       <p className="text-[10px] font-black uppercase tracking-widest">Son 7 güne ait veri bulunamadı</p>
                    </div>
