                          />
                       </div>
                    </div>
                    <div className="flex-1 lg:w-44 space-y-1">
                       <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Bitiş</label>
                       <input 
                        type="date" 
                        className="w-full pl-3 pr-3 py-3 bg-slate-50 border border-slate-100 rounded-xl text-[11px] font-bold outline-none focus:bg-white"
                        value={historyEndDate}
                        onChange={(e)=>setHistoryEndDate(e.target.value)}
                       />
                    </div>
                 </div>

                 <div className="flex items-center p-1 bg-slate-50 rounded-2xl border border-slate-100 w-full xl:w-auto">
                    <FilterButton active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Hepsi" />
                    <FilterButton active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Giriş" />
                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkış" />
                 </div>

                 {(historySearch || historyStartDate || historyEndDate || historyTypeFilter !== 'ALL') && (
                    <button onClick={()=>{setHistorySearch(''); setHistoryStartDate(''); setHistoryEndDate(''); setHistoryTypeFilter('ALL');}} className="p-3 text-slate-300 hover:text-rose-500 transition-colors">
                       <XCircle size={20} />
                    </button>
                 )}
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-8 py-5">Zaman / Tarih</th>
                        <th className="px-8 py-5">Ürün & Teknik Detay</th>
                        <th className="px-8 py-5">İşlem Türü</th>
                        <th className="px-8 py-5">Ürün Adeti</th>
                        <th className="px-8 py-5">Yapan / Onaylayan</th>
                        {user.role === UserRole.ADMIN && <th className="px-8 py-5 text-right">Eylem</th>}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50/30 transition-all">
                          <td className="px-8 py-6 text-slate-400 font-bold">{t.date}</td>
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{t.productName}</div>
                            <div className="text-[9px] text-indigo-400 font-black uppercase mt-1.5 flex items-center gap-2">
                               {t.size && <span className="bg-indigo-50 px-2 py-0.5 rounded-md">BEDEN: {t.size}</span>}
                               {t.color && <span className="bg-indigo-50 px-2 py-0.5 rounded-md">RENK: {t.color}</span>}
                               <span className="bg-slate-50 px-2 py-0.5 rounded-md text-slate-400">#{t.productCode}</span>
                            </div>
                            <div className="text-[10px] text-slate-400 font-bold mt-2 italic flex items-center gap-1">
                               <ArrowRightLeft size={10} /> {t.supplier || t.recipient || 'Tanımlanmamış'}
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${t.type===TransactionType.IN ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>{t.type}</span>
                          </td>
                          <td className="px-8 py-6 font-black text-[18px] text-slate-900 tracking-tighter">{t.quantity}</td>
                          <td className="px-8 py-6">
                            <div className="text-slate-700 font-extrabold text-[12px]">{t.operator}</div>
                            <div className="text-[9px] text-indigo-500 font-black uppercase tracking-widest flex items-center gap-1.5 mt-1.5">
                               <CheckCircle2 size={12} className="opacity-70" /> 
                               Onay: {t.approver}
                            </div>
                          </td>
                          {user.role === UserRole.ADMIN && (
                            <td className="px-8 py-6 text-right">
                              <button onClick={()=>handleDeleteTransaction(t.id)} className="p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 size={16}/></button>
                            </td>
                          )}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {filteredTransactions.length === 0 && (
                    <div className="p-32 text-center space-y-4">
                       <History size={64} className="mx-auto text-slate-100" />
                       <p className="text-slate-300 font-black uppercase text-[11px] tracking-[0.3em]">Arama Sonucu Bulunamadı</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* User Edit Modal */}
      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-6">
           <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-2xl animate-fade-in border border-white/20">
              <div className="text-center mb-8">
                <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-[1.5rem] flex items-center justify-center mx-auto mb-4 shadow-inner">
                  <UserIcon size={32} />
                </div>
                <h4 className="text-xl font-black text-slate-900 tracking-tight uppercase">{editingUser ? 'Bilgileri Güncelle' : 'Yeni Personel Kaydı'}</h4>
              </div>

              <form onSubmit={handleUserSave} className="space-y-6">
                 <InputSmall label="Tam Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required placeholder="Örn: Ahmet Yılmaz" />
                 <InputSmall label="Kullanıcı Giriş Adı" name="username" defaultValue={editingUser?.username} required placeholder="ahmet_y" />
                 <InputSmall label="Sistem Şifresi" name="password" type="password" defaultValue={editingUser?.password} required placeholder="••••••••" />
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Sistem Yetki Rolü</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-800 text-[12px] outline-none focus:bg-white focus:ring-4 focus:ring-indigo-50 transition-all">
                       <option value={UserRole.ADMIN}>Yönetici (Full Yetki)</option>
                       <option value={UserRole.USER}>Personel (Kısıtlı)</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-6">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-4 bg-slate-50 rounded-2xl font-black text-slate-400 text-[11px] uppercase tracking-widest transition-all">Vazgeç</button>
                    <button type="submit" className="flex-1 py-4 bg-indigo-600 rounded-2xl font-black text-white text-[11px] uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Verileri Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} className={`${active ? 'scale-110' : 'opacity-60'} transition-transform`} /> 
    <span className="text-[11px] font-black tracking-tight uppercase whitespace-nowrap">{label}</span>
    {active && <ChevronRight size={14} className="ml-auto opacity-50" />}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-xl transition-all hover:-translate-y-1">
    <div className="space-y-2">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-2xl font-black text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-3.5 bg-${color}-50 text-${color}-600 rounded-2xl group-hover:bg-${color}-600 group-hover:text-white transition-all shadow-sm`}>
      <Icon size={20} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 opacity-90">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange?.(e.target.value)} 
      className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-200 focus:bg-white focus:ring-4 focus:ring-indigo-50/40 font-black text-slate-800 outline-none transition-all placeholder:text-slate-200 text-[13px] shadow-sm" 
    />
  </div>
);

const FilterButton = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100'}`}
  >
    {label}
  </button>
);

// Lucide iconları için local override
const UserIcon = ({ size }: {size: number}) => <Users size={size} />;
const Lock = ({ size, className }: {size: number, className?: string}) => <Settings size={size} className={className} />;

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight,
  Calendar,
  XCircle,
  BarChart3,
  UserCheck
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    [...transactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      return item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
             item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Grafik Verisi Hazırlama (Son 7 Gün - En Aktif 5 Ürün)
  const chartData = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const recentTx = transactions.filter(t => {
      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });

    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    recentTx.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [transactions]);

  // History Filtreleme Mantığı (Personel Adına Göre Arama Eklendi)
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase());

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');
      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }
    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature
    };
    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover('');
    showNotification('İşlem Başarıyla Kaydedildi', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const clearUserTransactions = (fullName: string) => {
    if (window.confirm(`${fullName} isimli personele ait tüm işlem verileri silinecek. Emin misiniz?`)) {
      const allTx = StorageService.getTransactions();
      const filtered = allTx.filter(t => t.operator !== fullName);
      localStorage.setItem('stock_app_transactions', JSON.stringify(filtered));
      setTransactions(filtered);
      showNotification(`${fullName} verileri temizlendi`, 'success');
    }
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
