type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru (SADECE ONAYLANMIŞLARI SAY)
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Giriş/Çıkış hacmini SADECE ONAYLANMIŞLARDAN hesapla
  const approvedRecentTx = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    return transactions.filter(t => {
      if (t.status !== TransactionStatus.APPROVED) return false;
      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      return item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
             item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Grafik Verisi
  const chartData = useMemo(() => {
    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    approvedRecentTx.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [approvedRecentTx]);

  // Onay Bekleyenler (Aktif Kullanıcının Adı Onaylayan Kısmındaysa)
  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  // History Filtreleme
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase());

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');
      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    // Stok kontrolü (Onay bekleyenler düşülmez ama stoktan fazlası talep edilemez)
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING, // BAŞLANGIÇTA BEKLEMEDE
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem başarıyla onaylandı ve stok güncellendi.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const clearUserTransactions = (fullName: string) => {
    if (window.confirm(`${fullName} isimli personele ait tüm işlem verileri silinecek. Emin misiniz?`)) {
      const allTx = StorageService.getTransactions();
      const filtered = allTx.filter(t => t.operator !== fullName);
      localStorage.setItem('stock_app_transactions', JSON.stringify(filtered));
      setTransactions(filtered);
      showNotification(`${fullName} verileri temizlendi`, 'success');
    }
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Onaylanmış depo hareketleri</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-3 bg-amber-50 text-amber-600 px-5 py-3 rounded-2xl border border-amber-100 shadow-sm">
                    <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest">{criticalCount} Ürün Alt Limit Altında</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
                <StatCard label="Mevcut Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Eşik Aşımı" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              {/* Chart Section */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden p-6 md:p-8">
                <div className="flex items-center gap-3 mb-8">
                  <div className="p-2.5 bg-slate-900 rounded-xl text-white shadow-lg"><BarChart3 size={18} /></div>
                  <div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Haftalık Onaylı Akış</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Son 7 günün onaylanmış giriş/çıkış hacmi</p>
                  </div>
                </div>

                <div className="h-[300px] w-full">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis 
                          dataKey="code" 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                          dy={10}
                        />
                        <YAxis 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                        />
                        <Tooltip 
                          cursor={{ fill: '#f8fafc' }}
                          contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: '800' }}
                        />
                        <Legend 
                          verticalAlign="top" 
                          align="right" 
                          iconType="circle"
                          wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: '800' }}
                        />
                        <Bar name="Giriş" dataKey="Giriş" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={32} />
                        <Bar name="Çıkış" dataKey="Çıkış" fill="#f43f5e" radius={[6, 6, 0, 0]} barSize={32} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-3">
                       <BarChart3 size={48} className="opacity-20" />
                       <p className="text-[10px] font-black uppercase tracking-widest">Onaylı veri bulunamadı</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden transition-all hover:shadow-md">
                <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col lg:flex-row justify-between items-center gap-6 bg-slate-50/30">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100"><Box size={18} /></div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Güncel Stok & Onaylı Bakiye</h3>
                  </div>
                  <div className="flex items-center gap-3 w-full lg:w-auto">
                    <div className="relative flex-1 lg:w-72 group">
                       <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500" />
                       <input 
                        type="text" 
                        placeholder="Ara..." 
                        value={searchQuery}
                        onChange={(e)=>setSearchQuery(e.target.value)}
                        className="pl-11 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-200 w-full shadow-sm" 
                       />
                    </div>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">
                      <tr>
                        <th className="px-8 py-5">Ürün Bilgisi</th>
                        <th className="px-8 py-5">Giriş / Çıkış (Onaylı)</th>
                        <th className="px-8 py-5">Kalan Stok</th>
                        <th className="px-8 py-5">Alt Limit</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/40 transition-all text-[12px] group">
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{item.productName}</div>
                            <div className="text-[10px] font-bold text-slate-400 mt-1">#{item.productCode}</div>
                          </td>
                          <td className="px-8 py-6">
                            <div className="flex items-center gap-3 font-bold">
                              <span className="text-emerald-500">+{item.totalIn}</span>
                              <span className="text-rose-500">-{item.totalOut}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                             <div className="font-black text-slate-900 text-[16px] tracking-tight">{item.remaining}</div>
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              <input 
                                type="number" 
                                value={thresholds[item.productCode] || 0}
                                onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 border border-slate-100 rounded-xl font-black text-[11px] outline-none"
                              />
                            ) : (
                              <span className="text-slate-400">{thresholds[item.productCode] || 0}</span>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="bg-rose-50 text-rose-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Kritik</span>
                            ) : (
                              <span className="bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Yeterli</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'approvals' && (
             <div className="space-y-8 animate-fade-in max-w-4xl mx-auto py-4">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Onay Bekleyen Talepler</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Senin tarafndan onaylanması beklenen işlemler</p>
                </div>

                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
                       <div className={`p-4 rounded-2xl ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={24} /> : <PackageMinus size={24} />}
                       </div>
                       <div className="flex-1 space-y-2">
                          <div className="flex items-center gap-3">
                             <h4 className="font-black text-slate-900 text-[16px]">{t.productName}</h4>
                             <span className="bg-slate-50 px-2 py-0.5 rounded text-[10px] font-bold text-slate-400">#{t.productCode}</span>
                          </div>
                          <p className="text-[11px] text-slate-500 font-bold">
                            Miktar: <span className="text-slate-900 font-black">{t.quantity} Adet</span> 
                            {t.size && ` | Beden: ${t.size}`}
                            {t.color && ` | Renk: ${t.color}`}
                          </p>
                          <div className="flex items-center gap-2 pt-1">
                             <div className="w-6 h-6 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center text-[8px] font-black">{t.operator.charAt(0)}</div>
                             <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{t.operator} tarafından talep edildi</span>
                          </div>
                       </div>
                       <div className="flex gap-3">
                          <button 
                            onClick={() => handleReject(t.id)}
                            className="px-6 py-3 bg-slate-50 text-rose-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-rose-50 transition-all border border-transparent hover:border-rose-100"
                          >
                             Reddet
                          </button>
                          <button 
                            onClick={() => handleApprove(t.id)}
                            className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 flex items-center gap-2"
                          >
                             <ThumbsUp size={14} /> Onayla
                          </button>
                       </div>
                    </div>
                  ))}
                  {pendingApprovals.length === 0 && (
                    <div className="py-20 text-center space-y-4">
                       <CheckCircle2 size={48} className="mx-auto text-emerald-200" />
                       <p className="text-slate-300 font-black uppercase text-[11px] tracking-widest">Onay bekleyen işleminiz bulunmuyor</p>
                    </div>
                  )}
                </div>
             </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-xl mx-auto space-y-8 animate-fade-in py-6">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-5 rounded-[2rem] mb-2 ${activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'} text-white shadow-2xl scale-110`}>
                  {activeTab === 'in' ? <PackagePlus size={32} /> : <PackageMinus size={32} />}
                </div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">
                  {activeTab === 'in' ? 'Stok Giriş Talebi' : 'Stok Çıkış Talebi'}
                </h2>
                <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest px-10">İşlem belirlenen yetkili onayından sonra gerçekleşecektir.</p>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[3.5rem] p-24 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/10 transition-all group shadow-sm">
                  <div className="p-8 bg-indigo-600 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-100 group-hover:scale-110 transition-all mb-8">
                    <Maximize2 size={40} />
                  </div>
                  <p className="text-[13px] font-black uppercase tracking-[0.4em] text-slate-500 mb-2">QR Kodu Taratın</p>
                </div>
              ) : (
                <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-2xl shadow-slate-100 border border-slate-50 space-y-12 animate-fade-in">
                  <div className="flex justify-between items-center p-8 bg-slate-50/50 rounded-[2rem] border border-slate-100">
                    <div className="space-y-1.5">
                      <p className="text-[9px] font-black text-indigo-600 uppercase tracking-[0.2em]">Seçilen Ürün</p>
                      <h3 className="font-black text-slate-900 text-[18px]">{productName}</h3>
                      <span className="text-[11px] font-bold text-slate-400">KOD: {productCode}</span>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                    <div className="sm:col-span-2">
                       <InputSmall label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı / Departman"} value={partner} onChange={setPartner} required />
                    </div>
                    <InputSmall label="Ürün Adeti" type="number" value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} required />
                    <InputSmall label="Renk" value={color} onChange={setColor} />
                    <InputSmall label="Beden" value={size} onChange={setSize} />
                    <InputSmall label="Özellik" value={feature} onChange={setFeature} />

                    <div className="sm:col-span-2 grid grid-cols-2 gap-6 pt-4 border-t border-slate-50">
                      <InputSmall label="İşlemi Yapan" value={operatorName} onChange={setOperatorName} disabled />
                      <InputSmall 
                        label="Onaylayacak Kişi" 
                        value={approver} 
                        onChange={setApprover} 
                        placeholder="Örn: Mehmet" 
                        required 
                      />
                    </div>
                  </div>

                  <div className="flex gap-5 pt-6">
                    <button onClick={()=>setIsFormActive(false)} className="flex-1 py-5 bg-slate-50 rounded-[1.5rem] font-black text-slate-400 text-[11px] uppercase tracking-widest">İptal</button>
                    <button onClick={handleSave} className={`flex-1 py-5 rounded-[1.5rem] font-black text-white text-[11px] uppercase tracking-widest shadow-2xl ${activeTab==='in' ? 'bg-indigo-600 shadow-indigo-100' : 'bg-rose-500 shadow-rose-100'}`}>Onaya Gönder</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex justify-between items-center">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Kullanıcı Yönetimi</h3>
                </div>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-3 px-6 py-3.5 bg-indigo-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest">
                  <UserPlus size={16} /> Yeni Kayıt
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col group relative">
                    <div className="flex items-center gap-4 mb-4">
                       <div className="w-12 h-12 rounded-2xl bg-slate-50 text-indigo-600 flex items-center justify-center font-black text-lg uppercase">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-extrabold text-slate-900 text-[14px] flex items-center gap-2">
                            {u.fullName}
                            {u.id === user.id && <span className="bg-indigo-50 text-indigo-600 text-[8px] font-black px-2 py-0.5 rounded-full">Siz</span>}
                          </p>
                          <span className="text-[9px] text-white bg-indigo-500 font-black uppercase tracking-widest px-1.5 py-0.5 rounded-md">{u.role}</span>
                       </div>
                    </div>
                    <div className="flex items-center gap-2 pt-4 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-2.5 text-slate-400 hover:text-indigo-600 transition-all font-black text-[9px] uppercase"><Edit size={14} /></button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Emin misiniz?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-2.5 text-slate-400 hover:text-rose-600 transition-all"><Trash2 size={16} /></button>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col lg:flex-row justify-between items-end gap-6">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">İşlem Günlüğü</h3>
                </div>
              </div>

              <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col xl:flex-row gap-6 items-center">
                 <div className="flex-1 w-full relative group">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input 
                      type="text" 
                      placeholder="Ara..." 
                      className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-[12px] font-bold outline-none"
                      value={historySearch}
                      onChange={(e)=>setHistorySearch(e.target.value)}
                    />
                 </div>
                 <div className="flex items-center p-1 bg-slate-50 rounded-2xl border border-slate-100">
                    <FilterButton active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Hepsi" />
                    <FilterButton active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Giriş" />
                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkış" />
                 </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-8 py-5">Tarih</th>
                        <th className="px-8 py-5">Ürün</th>
                        <th className="px-8 py-5">Durum</th>
                        <th className="px-8 py-5">Miktar</th>
                        <th className="px-8 py-5">Yapan / Onay</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50/30 transition-all">
                          <td className="px-8 py-6 text-slate-400 font-bold">{t.date}</td>
                          <td className="px-8 py-6 font-extrabold text-slate-800">{t.productName}</td>
                          <td className="px-8 py-6">
                            <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase flex items-center gap-1.5 w-fit ${
                              t.status === TransactionStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' :
                              t.status === TransactionStatus.REJECTED ? 'bg-rose-50 text-rose-600' :
                              'bg-amber-50 text-amber-600'
                            }`}>
                               {t.status === TransactionStatus.PENDING && <Hourglass size={10} />}
                               {t.status === TransactionStatus.APPROVED && <CheckCircle2 size={10} />}
                               {t.status === TransactionStatus.REJECTED && <XCircle size={10} />}
                               {t.status}
                            </span>
                          </td>
                          <td className="px-8 py-6 font-black text-[16px] text-slate-900">{t.quantity}</td>
                          <td className="px-8 py-6">
                            <div className="text-slate-700 font-extrabold">{t.operator}</div>
                            <div className="text-[9px] text-indigo-500 font-black uppercase">Onay: {t.approver}</div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-6">
           <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-2xl animate-fade-in">
              <h4 className="text-xl font-black text-slate-900 tracking-tight uppercase mb-8 text-center">{editingUser ? 'Güncelle' : 'Yeni Personel'}</h4>
              <form onSubmit={handleUserSave} className="space-y-6">
                 <InputSmall label="Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rol</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-800 text-[12px] outline-none">
                       <option value={UserRole.ADMIN}>Yönetici</option>
                       <option value={UserRole.USER}>Personel</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-4 bg-slate-50 rounded-2xl font-black text-slate-400 text-[11px] uppercase">Vazgeç</button>
                    <button type="submit" className="flex-1 py-4 bg-indigo-600 rounded-2xl font-black text-white text-[11px] uppercase shadow-xl shadow-indigo-100">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all relative ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} className={`${active ? 'scale-110' : 'opacity-60'}`} /> 
    <span className="text-[11px] font-black tracking-tight uppercase whitespace-nowrap">{label}</span>
    {badge > 0 && (
      <span className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 bg-rose-500 text-white text-[10px] font-black rounded-full flex items-center justify-center animate-pulse shadow-lg">
        {badge}
      </span>
    )}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-xl transition-all">
    <div className="space-y-2">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-2xl font-black text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-3.5 bg-${color}-50 text-${color}-600 rounded-2xl`}>
      <Icon size={20} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 opacity-90">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange?.(e.target.value)} 
      className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-50/40 font-black text-slate-800 outline-none transition-all text-[13px] shadow-sm" 
    />
  </div>
);

const FilterButton = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100'}`}
  >
    {label}
  </button>
);

const Lock = ({ size, className }: {size: number, className?: string}) => <Settings size={size} className={className} />;

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight,
  Calendar,
  XCircle,
  BarChart3,
  UserCheck,
  ClipboardList,
  ThumbsUp,
  ThumbsDown,
  Hourglass
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru (SADECE ONAYLANMIŞLARI SAY)
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Giriş/Çıkış hacmini SADECE ONAYLANMIŞLARDAN hesapla
  const approvedRecentTx = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    return transactions.filter(t => {
      if (t.status !== TransactionStatus.APPROVED) return false;
      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      return item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
             item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Grafik Verisi
  const chartData = useMemo(() => {
    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    approvedRecentTx.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [approvedRecentTx]);

  // Onay Bekleyenler (Aktif Kullanıcının Adı Onaylayan Kısmındaysa)
  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  // History Filtreleme
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase());

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');
      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    // Stok kontrolü (Onay bekleyenler düşülmez ama stoktan fazlası talep edilemez)
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING, // BAŞLANGIÇTA BEKLEMEDE
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem başarıyla onaylandı ve stok güncellendi.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const clearUserTransactions = (fullName: string) => {
    if (window.confirm(`${fullName} isimli personele ait tüm işlem verileri silinecek. Emin misiniz?`)) {
      const allTx = StorageService.getTransactions();
      const filtered = allTx.filter(t => t.operator !== fullName);
      localStorage.setItem('stock_app_transactions', JSON.stringify(filtered));
      setTransactions(filtered);
      showNotification(`${fullName} verileri temizlendi`, 'success');
    }
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Onaylanmış depo hareketleri</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-3 bg-amber-50 text-amber-600 px-5 py-3 rounded-2xl border border-amber-100 shadow-sm">
                    <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest">{criticalCount} Ürün Alt Limit Altında</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
                <StatCard label="Mevcut Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Eşik Aşımı" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              {/* Chart Section */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden p-6 md:p-8">
                <div className="flex items-center gap-3 mb-8">
                  <div className="p-2.5 bg-slate-900 rounded-xl text-white shadow-lg"><BarChart3 size={18} /></div>
                  <div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Haftalık Onaylı Akış</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Son 7 günün onaylanmış giriş/çıkış hacmi</p>
                  </div>
                </div>

                <div className="h-[300px] w-full">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis 
                          dataKey="code" 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                          dy={10}
                        />
                        <YAxis 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                        />
                        <Tooltip 
                          cursor={{ fill: '#f8fafc' }}
                          contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: '800' }}
                        />
                        <Legend 
                          verticalAlign="top" 
                          align="right" 
                          iconType="circle"
                          wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: '800' }}
                        />
                        <Bar name="Giriş" dataKey="Giriş" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={32} />
                        <Bar name="Çıkış" dataKey="Çıkış" fill="#f43f5e" radius={[6, 6, 0, 0]} barSize={32} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-3">
                       <BarChart3 size={48} className="opacity-20" />
                       <p className="text-[10px] font-black uppercase tracking-widest">Onaylı veri bulunamadı</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden transition-all hover:shadow-md">
                <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col lg:flex-row justify-between items-center gap-6 bg-slate-50/30">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100"><Box size={18} /></div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Güncel Stok & Onaylı Bakiye</h3>
                  </div>
                  <div className="flex items-center gap-3 w-full lg:w-auto">
                    <div className="relative flex-1 lg:w-72 group">
                       <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
                       <input 
                        type="text" 
                        placeholder="Ara..." 
                        value={searchQuery}
                        onChange={(e)=>setSearchQuery(e.target.value)}
                        className="pl-11 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-200 w-full shadow-sm" 
                       />
                    </div>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">
                      <tr>
                        <th className="px-8 py-5">Ürün Bilgisi</th>
                        <th className="px-8 py-5">Giriş / Çıkış (Onaylı)</th>
                        <th className="px-8 py-5">Kalan Stok</th>
                        <th className="px-8 py-5">Alt Limit</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/40 transition-all text-[12px] group">
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{item.productName}</div>
                            <div className="text-[10px] font-bold text-slate-400 mt-1">#{item.productCode}</div>
                          </td>
                          <td className="px-8 py-6">
                            <div className="flex items-center gap-3 font-bold">
                              <span className="text-emerald-500">+{item.totalIn}</span>
                              <span className="text-rose-500">-{item.totalOut}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                             <div className="font-black text-slate-900 text-[16px] tracking-tight">{item.remaining}</div>
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              <input 
                                type="number" 
                                value={thresholds[item.productCode] || 0}
                                onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 border border-slate-100 rounded-xl font-black text-[11px] outline-none"
                              />
                            ) : (
                              <span className="text-slate-400">{thresholds[item.productCode] || 0}</span>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="bg-rose-50 text-rose-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Kritik</span>
                            ) : (
                              <span className="bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Yeterli</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'approvals' && (
             <div className="space-y-8 animate-fade-in max-w-4xl mx-auto py-4">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Onay Bekleyen Talepler</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Senin tarafndan onaylanması beklenen işlemler</p>
                </div>

                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
                       <div className={`p-4 rounded-2xl ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={24} /> : <PackageMinus size={24} />}
                       </div>
                       <div className="flex-1 space-y-2">
                          <div className="flex items-center gap-3">
                             <h4 className="font-black text-slate-900 text-[16px]">{t.productName}</h4>
                             <span className="bg-slate-50 px-2 py-0.5 rounded text-[10px] font-bold text-slate-400">#{t.productCode}</span>
                          </div>
                          <p className="text-[11px] text-slate-500 font-bold">
                            Miktar: <span className="text-slate-900 font-black">{t.quantity} Adet</span> 
                            {t.size && ` | Beden: ${t.size}`}
                            {t.color && ` | Renk: ${t.color}`}
                          </p>
                          <div className="flex items-center gap-2 pt-1">
                             <div className="w-6 h-6 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center text-[8px] font-black">{t.operator.charAt(0)}</div>
                             <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{t.operator} tarafından talep edildi</span>
                          </div>
                       </div>
                       <div className="flex gap-3">
                          <button 
                            onClick={() => handleReject(t.id)}
                            className="px-6 py-3 bg-slate-50 text-rose-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-rose-50 transition-all border border-transparent hover:border-rose-100"
                          >
                             Reddet
                          </button>
                          <button 
                            onClick={() => handleApprove(t.id)}
                            className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 flex items-center gap-2"
                          >
                             <ThumbsUp size={14} /> Onayla
                          </button>
                       </div>
                    </div>
                  ))}
                  {pendingApprovals.length === 0 && (
                    <div className="py-20 text-center space-y-4">
                       <CheckCircle2 size={48} className="mx-auto text-emerald-200" />
                       <p className="text-slate-300 font-black uppercase text-[11px] tracking-widest">Onay bekleyen işleminiz bulunmuyor</p>
                    </div>
                  )}
                </div>
             </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-xl mx-auto space-y-8 animate-fade-in py-6">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-5 rounded-[2rem] mb-2 ${activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-200' : 'bg-rose-500 shadow-rose-200'} text-white shadow-2xl scale-110`}>
                  {activeTab === 'in' ? <PackagePlus size={32} /> : <PackageMinus size={32} />}
                </div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">
                  {activeTab === 'in' ? 'Stok Giriş Talebi' : 'Stok Çıkış Talebi'}
                </h2>
                <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest px-10">İşlem belirlenen yetkili onayından sonra gerçekleşecektir.</p>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[3.5rem] p-24 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/10 transition-all group shadow-sm">
                  <div className="p-8 bg-indigo-600 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-100 group-hover:scale-110 transition-all mb-8">
                    <Maximize2 size={40} />
                  </div>
                  <p className="text-[13px] font-black uppercase tracking-[0.4em] text-slate-500 mb-2">QR Kodu Taratın</p>
                </div>
              ) : (
                <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-2xl shadow-slate-100 border border-slate-50 space-y-12 animate-fade-in">
                  <div className="flex justify-between items-center p-8 bg-slate-50/50 rounded-[2rem] border border-slate-100">
                    <div className="space-y-1.5">
                      <p className="text-[9px] font-black text-indigo-600 uppercase tracking-[0.2em]">Seçilen Ürün</p>
                      <h3 className="font-black text-slate-900 text-[18px]">{productName}</h3>
                      <span className="text-[11px] font-bold text-slate-400">KOD: {productCode}</span>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                    <div className="sm:col-span-2">
                       <InputSmall label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı / Departman"} value={partner} onChange={setPartner} required />
                    </div>
                    <InputSmall label="Ürün Adeti" type="number" value={quantity} onChange={v=>setQuantity(v===''?'':parseInt(v))} required />
                    <InputSmall label="Renk" value={color} onChange={setColor} />
                    <InputSmall label="Beden" value={size} onChange={setSize} />
                    <InputSmall label="Özellik" value={feature} onChange={setFeature} />

                    <div className="sm:col-span-2 grid grid-cols-2 gap-6 pt-4 border-t border-slate-50">
                      <InputSmall label="İşlemi Yapan" value={operatorName} onChange={setOperatorName} disabled />
                      <InputSmall 
                        label="Onaylayacak Kişi" 
                        value={approver} 
                        onChange={setApprover} 
                        placeholder="Örn: Mehmet" 
                        required 
                      />
                    </div>
                  </div>

                  <div className="flex gap-5 pt-6">
                    <button onClick={()=>setIsFormActive(false)} className="flex-1 py-5 bg-slate-50 rounded-[1.5rem] font-black text-slate-400 text-[11px] uppercase tracking-widest">İptal</button>
                    <button onClick={handleSave} className={`flex-1 py-5 rounded-[1.5rem] font-black text-white text-[11px] uppercase tracking-widest shadow-2xl ${activeTab==='in' ? 'bg-indigo-600 shadow-indigo-100' : 'bg-rose-500 shadow-rose-100'}`}>Onaya Gönder</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex justify-between items-center">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Kullanıcı Yönetimi</h3>
                </div>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-3 px-6 py-3.5 bg-indigo-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest">
                  <UserPlus size={16} /> Yeni Kayıt
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col group relative">
                    <div className="flex items-center gap-4 mb-4">
                       <div className="w-12 h-12 rounded-2xl bg-slate-50 text-indigo-600 flex items-center justify-center font-black text-lg uppercase">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-extrabold text-slate-900 text-[14px] flex items-center gap-2">
                            {u.fullName}
                            {u.id === user.id && <span className="bg-indigo-50 text-indigo-600 text-[8px] font-black px-2 py-0.5 rounded-full">Siz</span>}
                          </p>
                          <span className="text-[9px] text-white bg-indigo-500 font-black uppercase tracking-widest px-1.5 py-0.5 rounded-md">{u.role}</span>
                       </div>
                    </div>
                    <div className="flex items-center gap-2 pt-4 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-2.5 text-slate-400 hover:text-indigo-600 transition-all font-black text-[9px] uppercase"><Edit size={14} /></button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Emin misiniz?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-2.5 text-slate-400 hover:text-rose-600 transition-all"><Trash2 size={16} /></button>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col lg:flex-row justify-between items-end gap-6">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">İşlem Günlüğü</h3>
                </div>
              </div>

              <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col xl:flex-row gap-6 items-center">
                 <div className="flex-1 w-full relative group">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input 
                      type="text" 
                      placeholder="Ara..." 
                      className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-[12px] font-bold outline-none"
                      value={historySearch}
                      onChange={(e)=>setHistorySearch(e.target.value)}
                    />
                 </div>
                 <div className="flex items-center p-1 bg-slate-50 rounded-2xl border border-slate-100">
                    <FilterButton active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Hepsi" />
                    <FilterButton active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Giriş" />
                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkış" />
                 </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-8 py-5">Tarih</th>
                        <th className="px-8 py-5">Ürün & Detaylar</th>
                        <th className="px-8 py-5">Durum</th>
                        <th className="px-8 py-5">Miktar</th>
                        <th className="px-8 py-5">Yapan / Onay</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50/30 transition-all">
                          <td className="px-8 py-6 text-slate-400 font-bold">{t.date}</td>
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{t.productName}</div>
                            <div className="text-[10px] text-slate-400 font-bold mt-1 flex flex-wrap gap-2">
                               <span className="bg-slate-50 px-1.5 py-0.5 rounded text-[9px]">#{t.productCode}</span>
                               {t.size && <span className="bg-indigo-50 text-indigo-500 px-1.5 py-0.5 rounded text-[9px]">BEDEN: {t.size}</span>}
                               {t.color && <span className="bg-indigo-50 text-indigo-500 px-1.5 py-0.5 rounded text-[9px]">RENK: {t.color}</span>}
                            </div>
                            <div className="text-[10px] text-indigo-400 font-black uppercase mt-2 flex items-center gap-1.5">
                               <ArrowRightLeft size={10} />
                               <span>{t.type === TransactionType.IN ? 'Tedarikçi: ' : 'Alıcı: '} {t.supplier || t.recipient || 'Belirtilmedi'}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase flex items-center gap-1.5 w-fit ${
                              t.status === TransactionStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' :
                              t.status === TransactionStatus.REJECTED ? 'bg-rose-50 text-rose-600' :
                              'bg-amber-50 text-amber-600'
                            }`}>
                               {t.status === TransactionStatus.PENDING && <Hourglass size={10} />}
                               {t.status === TransactionStatus.APPROVED && <CheckCircle2 size={10} />}
                               {t.status === TransactionStatus.REJECTED && <XCircle size={10} />}
                               {t.status}
                            </span>
                          </td>
                          <td className="px-8 py-6 font-black text-[16px] text-slate-900">{t.quantity}</td>
                          <td className="px-8 py-6">
                            <div className="text-slate-700 font-extrabold">{t.operator}</div>
                            <div className="text-[9px] text-indigo-500 font-black uppercase">Onay: {t.approver}</div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-6">
           <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-2xl animate-fade-in">
              <h4 className="text-xl font-black text-slate-900 tracking-tight uppercase mb-8 text-center">{editingUser ? 'Güncelle' : 'Yeni Personel'}</h4>
              <form onSubmit={handleUserSave} className="space-y-6">
                 <InputSmall label="Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rol</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-800 text-[12px] outline-none">
                       <option value={UserRole.ADMIN}>Yönetici</option>
                       <option value={UserRole.USER}>Personel</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-4 bg-slate-50 rounded-2xl font-black text-slate-400 text-[11px] uppercase">Vazgeç</button>
                    <button type="submit" className="flex-1 py-4 bg-indigo-600 rounded-2xl font-black text-white text-[11px] uppercase shadow-xl shadow-indigo-100">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all relative ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} className={`${active ? 'scale-110' : 'opacity-60'}`} /> 
    <span className="text-[11px] font-black tracking-tight uppercase whitespace-nowrap">{label}</span>
    {badge > 0 && (
      <span className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 bg-rose-500 text-white text-[10px] font-black rounded-full flex items-center justify-center animate-pulse shadow-lg">
        {badge}
      </span>
    )}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-xl transition-all">
    <div className="space-y-2">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-2xl font-black text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-3.5 bg-${color}-50 text-${color}-600 rounded-2xl`}>
      <Icon size={20} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 opacity-90">{label}</label>
    <input 
      {...props} 
      onChange={e=>props.onChange?.(e.target.value)} 
      className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-50/40 font-black text-slate-800 outline-none transition-all text-[13px] shadow-sm" 
    />
  </div>
);

const FilterButton = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-100'}`}
  >
    {label}
  </button>
);

const Lock = ({ size, className }: {size: number, className?: string}) => <Settings size={size} className={className} />;

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export interface User {
  id: string;
  username: string;
  password?: string;
  role: UserRole;
  fullName: string;
}

export enum TransactionType {
  IN = 'Giriş',
  OUT = 'Çıkış'
}

export enum TransactionStatus {
  PENDING = 'BEKLEMEDE',
  APPROVED = 'ONAYLANDI',
  REJECTED = 'REDDEDİLDİ'
}

export interface Transaction {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  size?: string;
  color?: string;
  feature?: string;
  brand?: string; // Yeni eklenen Marka alanı
  supplier?: string; // Sadece girişlerde
  recipient?: string; // Sadece çıkışlarda
  quantity: number;
  type: TransactionType;
  status: TransactionStatus;
  date: string;
  operator: string; // İşlemi yapan
  approver: string; // Onaylaması gereken kişinin tam adı
  metadata?: Record<string, string>; 
}

export interface ProductStock {
  productId: string;
  productName: string;
  productCode: string;
  totalIn: number;
  totalOut: number;
  remaining: number;
  lastUpdate: string;
}

export interface ProductThreshold {
  productCode: string;
  minLevel: number;
}

export interface QRPayload {
  id: string;
  name: string;
  productCode: string;
  supplier?: string;
  size?: string;
  color?: string;
  feature?: string;
  brand?: string;
  quantity?: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight,
  Calendar,
  XCircle,
  BarChart3,
  UserCheck,
  ClipboardList,
  ThumbsUp,
  ThumbsDown,
  Hourglass,
  Tag
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru (SADECE ONAYLANMIŞLARI SAY)
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Giriş/Çıkış hacmini SADECE ONAYLANMIŞLARDAN hesapla
  const approvedRecentTx = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    return transactions.filter(t => {
      if (t.status !== TransactionStatus.APPROVED) return false;
      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      return item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
             item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Grafik Verisi
  const chartData = useMemo(() => {
    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    approvedRecentTx.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [approvedRecentTx]);

  // Onay Bekleyenler (Aktif Kullanıcının Adı Onaylayan Kısmındaysa)
  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  // History Filtreleme
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase()) ||
                            (t.brand && t.brand.toLowerCase().includes(historySearch.toLowerCase()));

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '', brand: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.brand = regexMatch('marka') || regexMatch('brand') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setBrand(extractedData.brand);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    // Stok kontrolü
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover(''); setBrand('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem başarıyla onaylandı ve stok güncellendi.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const clearUserTransactions = (fullName: string) => {
    if (window.confirm(`${fullName} isimli personele ait tüm işlem verileri silinecek. Emin misiniz?`)) {
      const allTx = StorageService.getTransactions();
      const filtered = allTx.filter(t => t.operator !== fullName);
      localStorage.setItem('stock_app_transactions', JSON.stringify(filtered));
      setTransactions(filtered);
      showNotification(`${fullName} verileri temizlendi`, 'success');
    }
  };

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [inventory, thresholds]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Onaylanmış depo hareketleri</p>
                </div>
                {criticalCount > 0 && (
                  <div className="flex items-center gap-3 bg-amber-50 text-amber-600 px-5 py-3 rounded-2xl border border-amber-100 shadow-sm">
                    <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest">{criticalCount} Ürün Alt Limit Altında</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
                <StatCard label="Mevcut Stok" val={inventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={inventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={inventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Eşik Aşımı" val={criticalCount} icon={AlertCircle} color="amber" />
              </div>

              {/* Chart Section */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden p-6 md:p-8">
                <div className="flex items-center gap-3 mb-8">
                  <div className="p-2.5 bg-slate-900 rounded-xl text-white shadow-lg"><BarChart3 size={18} /></div>
                  <div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Haftalık Onaylı Akış</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Son 7 günün onaylanmış giriş/çıkış hacmi</p>
                  </div>
                </div>

                <div className="h-[300px] w-full">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis 
                          dataKey="code" 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                          dy={10}
                        />
                        <YAxis 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                        />
                        <Tooltip 
                          cursor={{ fill: '#f8fafc' }}
                          contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: '800' }}
                        />
                        <Legend 
                          verticalAlign="top" 
                          align="right" 
                          iconType="circle"
                          wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: '800' }}
                        />
                        <Bar name="Giriş" dataKey="Giriş" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={32} />
                        <Bar name="Çıkış" dataKey="Çıkış" fill="#f43f5e" radius={[6, 6, 0, 0]} barSize={32} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-3">
                       <BarChart3 size={48} className="opacity-20" />
                       <p className="text-[10px] font-black uppercase tracking-widest">Onaylı veri bulunamadı</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden transition-all hover:shadow-md">
                <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col lg:flex-row justify-between items-center gap-6 bg-slate-50/30">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100"><Box size={18} /></div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Güncel Stok & Onaylı Bakiye</h3>
                  </div>
                  <div className="flex items-center gap-3 w-full lg:w-auto">
