import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight,
  Calendar,
  XCircle,
  BarChart3,
  UserCheck,
  ClipboardList,
  ThumbsUp,
  ThumbsDown,
  Hourglass,
  Tag,
  ArrowRight,
  Download
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru (SADECE ONAYLANMIŞLARI SAY)
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Giriş/Çıkış hacmini SADECE ONAYLANMIŞLARDAN hesapla
  const approvedRecentTx = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    return transactions.filter(t => {
      if (t.status !== TransactionStatus.APPROVED) return false;
      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      return item.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
             item.productCode.toLowerCase().includes(searchQuery.toLowerCase());
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Grafik Verisi
  const chartData = useMemo(() => {
    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    approvedRecentTx.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [approvedRecentTx]);

  // Onay Bekleyenler (Aktif Kullanıcının Adı Onaylayan Kısmındaysa)
  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  // History Filtreleme
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase()) ||
                            (t.brand && t.brand.toLowerCase().includes(historySearch.toLowerCase()));

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const exportToExcel = () => {
    if (filteredTransactions.length === 0) {
      showNotification('İndirilecek veri bulunamadı.', 'warning');
      return;
    }

    const headers = [
      'Tarih',
      'Ürün Adı',
      'Ürün Kodu',
      'Marka',
      'İşlem Tipi',
      'Durum',
      'Miktar',
      'Beden',
      'Renk',
      'Özellik',
      'Tedarikçi/Alıcı',
      'İşlemi Yapan',
      'Onaylayan'
    ];

    const rows = filteredTransactions.map(t => [
      t.date,
      t.productName,
      t.productCode,
      t.brand || '',
      t.type,
      t.status,
      t.quantity,
      t.size || '',
      t.color || '',
      t.feature || '',
      t.supplier || t.recipient || '',
      t.operator,
      t.approver
    ]);

    // CSV formatına dönüştürme
    const csvContent = [
      headers.join(';'),
      ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(';'))
    ].join('\n');

    // Türkçe karakter desteği için BOM (Byte Order Mark) ekleme
    const BOM = '\uFEFF';
    const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `ProStock_Islem_Gecmisi_${new Date().toLocaleDateString('tr-TR').replace(/\./g, '-')}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showNotification('Excel dosyası indiriliyor...', 'success');
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '', brand: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.brand = regexMatch('marka') || regexMatch('brand') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setPartner(extractedData.partner);
      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setBrand(extractedData.brand);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    // Stok kontrolü
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover(''); setBrand('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem başarıyla onaylandı ve stok güncellendi.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
