  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Settings,
  Bell,
  Maximize2,
  Info,
  Trash2,
  UserPlus,
  Edit,
  Filter,
  ArrowRightLeft,
  ChevronRight,
  Calendar,
  XCircle,
  BarChart3,
  UserCheck,
  ClipboardList,
  ThumbsUp,
