  Hourglass,
  Tag,
  ArrowRight,
  Download
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Global Dashboard Search
  const [searchQuery, setSearchQuery] = useState('');

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');

  // Form states
  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  // User Management
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  // Stok Hesaplama Motoru (SADECE ONAYLANMIŞLARI SAY)
  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  // Dashboard Filtreleme
  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const query = searchQuery.toLowerCase();
      return item.productName.toLowerCase().includes(query) || 
             item.productCode.toLowerCase().includes(query);
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  // Giriş/Çıkış hacmini SADECE ONAYLANMIŞLARDAN ve SEÇİLEN ÜRÜNLERDEN hesapla
  const approvedRecentTxFiltered = useMemo(() => {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    return transactions.filter(t => {
      if (t.status !== TransactionStatus.APPROVED) return false;

      // Arama filtresine uyan ürün mü?
      const matchesSearch = t.productName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            t.productCode.toLowerCase().includes(searchQuery.toLowerCase());

      if (!matchesSearch) return false;

      const datePart = t.date.split(' ')[0];
      const [d, m, y] = datePart.split('.').map(Number);
      return new Date(y, m - 1, d) >= sevenDaysAgo;
    });
  }, [transactions, searchQuery]);

  // Grafik Verisi
  const chartData = useMemo(() => {
    const productVolumes: Record<string, { name: string, in: number, out: number, total: number }> = {};
    approvedRecentTxFiltered.forEach(t => {
      if (!productVolumes[t.productCode]) {
        productVolumes[t.productCode] = { name: t.productName, in: 0, out: 0, total: 0 };
      }
      if (t.type === TransactionType.IN) {
        productVolumes[t.productCode].in += t.quantity;
      } else {
        productVolumes[t.productCode].out += t.quantity;
      }
      productVolumes[t.productCode].total += t.quantity;
    });

    return Object.entries(productVolumes)
      .map(([code, data]) => ({
        code,
        name: data.name,
        Giriş: data.in,
        Çıkış: data.out,
        total: data.total
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 5);
  }, [approvedRecentTxFiltered]);

  // Onay Bekleyenler (Aktif Kullanıcının Adı Onaylayan Kısmındaysa)
  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  // History Filtreleme
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase()) ||
                            (t.brand && t.brand.toLowerCase().includes(historySearch.toLowerCase()));

      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      let matchesDate = true;
      if (historyStartDate || historyEndDate) {
        try {
          const datePart = t.date.split(' ')[0];
          const [d, m, y] = datePart.split('.').map(Number);
          const txDate = new Date(y, m - 1, d);
          if (historyStartDate) {
            const start = new Date(historyStartDate);
            start.setHours(0,0,0,0);
            if (txDate < start) matchesDate = false;
          }
          if (historyEndDate) {
            const end = new Date(historyEndDate);
            end.setHours(23,59,59,999);
            if (txDate > end) matchesDate = false;
          }
        } catch (e) { matchesDate = true; }
      }
      return matchesSearch && matchesType && matchesDate;
    });
  }, [transactions, historySearch, historyTypeFilter, historyStartDate, historyEndDate]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  const exportToExcel = () => {
    if (filteredTransactions.length === 0) {
      showNotification('İndirilecek veri bulunamadı.', 'warning');
      return;
    }

    const headers = [
      'Tarih',
      'Ürün Adı',
      'Ürün Kodu',
      'Marka',
      'İşlem Tipi',
      'Durum',
      'Miktar',
      'Beden',
      'Renk',
      'Özellik',
      'Tedarikçi/Alıcı',
      'İşlemi Yapan',
      'Onaylayan'
    ];

    const rows = filteredTransactions.map(t => [
      t.date,
      t.productName,
      t.productCode,
      t.brand || '',
      t.type,
      t.status,
      t.quantity,
      t.size || '',
      t.color || '',
      t.feature || '',
      t.supplier || t.recipient || '',
      t.operator,
      t.approver
    ]);

    // CSV formatına dönüştürme
    const csvContent = [
      headers.join(';'),
      ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(';'))
    ].join('\n');

    // Türkçe karakter desteği için BOM (Byte Order Mark) ekleme
    const BOM = '\uFEFF';
    const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `ProStock_Islem_Gecmisi_${new Date().toLocaleDateString('tr-TR').replace(/\./g, '-')}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showNotification('Excel dosyası indiriliyor...', 'success');
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '', brand: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };
      const quantityRegex = /"adet"[:";\s]+(\d+)/i;
      const qMatch = cleanText.match(quantityRegex);
      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';
      extractedData.partner = regexMatch('tedarikciFirma') || regexMatch('tedarikci') || regexMatch('firma') || '';
      extractedData.size = regexMatch('beden') || regexMatch('size') || '';
      extractedData.color = regexMatch('renk') || regexMatch('color') || '';
      extractedData.feature = regexMatch('ozellik') || regexMatch('feature') || '';
      extractedData.brand = regexMatch('marka') || regexMatch('brand') || '';
      extractedData.quantity = qMatch ? qMatch[1] : (regexMatch('adet') || regexMatch('miktar') || '');

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);

      // Stok Çıkışı yapılıyorsa Alıcı Departman kısmını boş bırakıyoruz (manuel giriş için)
      setPartner(activeTab === 'out' ? '' : extractedData.partner);

      setSize(extractedData.size);
      setColor(extractedData.color);
      setFeature(extractedData.feature);
      setBrand(extractedData.brand);
      setQuantity(extractedData.quantity ? parseInt(extractedData.quantity) : '');
      setOperatorName(user?.fullName || '');
      setApprover('');
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Veriler Başarıyla Yerleştirildi', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (!productCode || quantity === '' || !partner || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun', 'error');
      return;
    }
    // Stok kontrolü
    if (activeTab === 'out' && (quantity as number) > currentStock) {
      showNotification(`Yetersiz stok! En fazla ${currentStock} adet çıkış yapabilirsiniz.`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover(''); setBrand('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem başarıyla onaylandı ve stok güncellendi.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Bu işlemi silmek istediğinize emin misiniz?')) {
      StorageService.deleteTransaction(id);
      setTransactions(StorageService.getTransactions());
      showNotification('İşlem Başarıyla Silindi', 'success');
    }
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı Bilgileri Güncellendi', 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const clearUserTransactions = (fullName: string) => {
    if (window.confirm(`${fullName} isimli personele ait tüm işlem verileri silinecek. Emin misiniz?`)) {
      const allTx = StorageService.getTransactions();
      const filtered = allTx.filter(t => t.operator !== fullName);
      localStorage.setItem('stock_app_transactions', JSON.stringify(filtered));
      setTransactions(filtered);
      showNotification(`${fullName} verileri temizlendi`, 'success');
    }
  };

  const criticalCountFiltered = useMemo(() => {
    return filteredInventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= thresholds[p.productCode]).length;
  }, [filteredInventory, thresholds]);

  const currentItemStock = useMemo(() => {
    return inventory.find(i => i.productCode === productCode)?.remaining || 0;
  }, [inventory, productCode]);

  const resultStock = useMemo(() => {
    const qtyNum = typeof quantity === 'number' ? quantity : 0;
    if (activeTab === 'in') return currentItemStock + qtyNum;
    if (activeTab === 'out') return Math.max(0, currentItemStock - qtyNum);
    return currentItemStock;
  }, [currentItemStock, quantity, activeTab]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 tracking-tighter leading-none">Pro<span className="text-indigo-600">Stock</span></h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2 opacity-60">Inventory v5.2</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter Paneli" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Kullanıcı Yönetimi" />}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
            <div className="flex items-center gap-3 px-2 bg-slate-50/50 p-3 rounded-2xl border border-slate-100">
              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">
                    {searchQuery ? `"${searchQuery}" için sonuçlar` : 'Tüm onaylanmış depo hareketleri'}
                  </p>
                </div>
                {criticalCountFiltered > 0 && (
                  <div className="flex items-center gap-3 bg-amber-50 text-amber-600 px-5 py-3 rounded-2xl border border-amber-100 shadow-sm">
                    <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest">{criticalCountFiltered} Seçili Ürün Alt Limit Altında</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
                <StatCard label="Mevcut Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Eşik Aşımı" val={criticalCountFiltered} icon={AlertCircle} color="amber" />
              </div>

              {/* Chart Section */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden p-6 md:p-8">
                <div className="flex items-center gap-3 mb-8">
                  <div className="p-2.5 bg-slate-900 rounded-xl text-white shadow-lg"><BarChart3 size={18} /></div>
                  <div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Onaylı Ürün Akışı</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Son 7 günün filtrelenmiş giriş/çıkış hacmi</p>
                  </div>
                </div>

                <div className="h-[300px] w-full">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis 
                          dataKey="code" 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                          dy={10}
                        />
                        <YAxis 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                        />
                        <Tooltip 
                          cursor={{ fill: '#f8fafc' }}
                          contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: '800' }}
                        />
                        <Legend 
                          verticalAlign="top" 
                          align="right" 
                          iconType="circle"
                          wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: '800' }}
                        />
                        <Bar name="Giriş" dataKey="Giriş" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={32} />
                        <Bar name="Çıkış" dataKey="Çıkış" fill="#f43f5e" radius={[6, 6, 0, 0]} barSize={32} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-3">
                       <BarChart3 size={48} className="opacity-20" />
                       <p className="text-[10px] font-black uppercase tracking-widest">
                         {searchQuery ? `"${searchQuery}" için veri bulunamadı` : 'Onaylı veri bulunamadı'}
                       </p>
                    </div>
                  )}
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden transition-all hover:shadow-md">
                <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col lg:flex-row justify-between items-center gap-6 bg-slate-50/30">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100"><Box size={18} /></div>
                    <h3 className="font-black text-[14px] text-slate-800 uppercase tracking-tight">Güncel Stok & Onaylı Bakiye</h3>
                  </div>
                  <div className="flex items-center gap-3 w-full lg:w-auto">
                    <div className="relative flex-1 lg:w-72 group">
                       <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
                       <input 
                        type="text" 
                        placeholder="Ürün seçin veya arayın..." 
                        value={searchQuery}
                        onChange={(e)=>setSearchQuery(e.target.value)}
                        className="pl-11 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-200 w-full shadow-sm" 
                       />
                    </div>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">
                      <tr>
                        <th className="px-8 py-5">Ürün Bilgisi</th>
                        <th className="px-8 py-5">Giriş / Çıkış (Onaylı)</th>
                        <th className="px-8 py-5">Kalan Stok</th>
                        <th className="px-8 py-5">Alt Limit</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50/40 transition-all text-[12px] group">
                          <td className="px-8 py-6">
                            <div className="font-extrabold text-slate-800 text-[13px]">{item.productName}</div>
                            <div className="text-[10px] font-bold text-slate-400 mt-1">#{item.productCode}</div>
                          </td>
                          <td className="px-8 py-6">
                            <div className="flex items-center gap-3 font-bold">
                              <span className="text-emerald-500">+{item.totalIn}</span>
                              <span className="text-rose-500">-{item.totalOut}</span>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                             <div className="font-black text-slate-900 text-[16px] tracking-tight">{item.remaining}</div>
                          </td>
                          <td className="px-8 py-6">
                            {user.role === UserRole.ADMIN ? (
                              <input 
                                type="number" 
                                value={thresholds[item.productCode] || 0}
                                onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 border border-slate-100 rounded-xl font-black text-[11px] outline-none"
                              />
                            ) : (
                              <span className="text-slate-400">{thresholds[item.productCode] || 0}</span>
                            )}
                          </td>
                          <td className="px-8 py-6 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="bg-rose-50 text-rose-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Kritik</span>
                            ) : (
                              <span className="bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase">Yeterli</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'approvals' && (
             <div className="space-y-8 animate-fade-in max-w-4xl mx-auto py-4">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Onay Bekleyen Talepler</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Senin tarafndan onaylanması beklenen işlemler</p>
                </div>

                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
                       <div className={`p-4 rounded-2xl ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={24} /> : <PackageMinus size={24} />}
                       </div>
                       <div className="flex-1 space-y-2">
