              <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-[11px] shadow-lg shadow-indigo-100">{user.fullName.charAt(0)}</div>
              <div className="overflow-hidden">
                <p className="text-[11px] font-extrabold text-slate-900 truncate leading-none mb-1">{user.fullName}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 font-bold hover:bg-rose-50 rounded-xl transition-all text-[9px] uppercase tracking-widest">
              <LogOut size={12} /> Oturumu Kapat
            </button>
          </div>
        </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center z-40">
          <span className="font-extrabold text-indigo-600 text-sm tracking-tighter uppercase">ProStock QR</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-50 rounded-xl text-slate-500 shadow-sm">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-2xl shadow-2xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border-b-4 border-black/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto pb-12">
              <div className="bg-white p-6 md:p-10 rounded-[3rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-8">
                <div className="space-y-2">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">Raporlama ve Analiz</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">
                    {searchQuery ? `"${searchQuery}" ürünü için filtrelenen veriler` : 'Tüm depo hareketleri ve genel analiz'}
                  </p>
                </div>
                <div className="relative w-full md:w-80 group">
                   <Search size={16} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
                   <input 
                    type="text" 
                    placeholder="Ürün adı veya kodu ile analiz et..." 
                    value={searchQuery}
                    onChange={(e)=>setSearchQuery(e.target.value)}
                    className="w-full pl-14 pr-6 py-4.5 bg-slate-50 border border-slate-100 rounded-[1.5rem] text-[12px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-inner" 
                   />
                </div>
              </div>

              {criticalCountFiltered > 0 && (
                <div className="flex items-center gap-4 bg-amber-50 text-amber-600 px-6 py-4 rounded-[2rem] border border-amber-100 shadow-sm animate-fade-in">
                  <div className="w-2.5 h-2.5 rounded-full bg-amber-500 animate-pulse"></div>
                  <span className="text-[11px] font-black uppercase tracking-widest">{criticalCountFiltered} Filtrelenen Ürün Kritik Limit Altında!</span>
                </div>
              )}

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Analiz Edilen Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş (Seçili)" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış (Seçili)" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Eşik Aşımı" val={criticalCountFiltered} icon={AlertCircle} color="amber" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Chart Section */}
                <div className="xl:col-span-2 bg-white rounded-[3rem] border border-slate-100 shadow-sm p-8 md:p-10">
                  <div className="flex items-center gap-4 mb-10">
                    <div className="p-3 bg-slate-900 rounded-2xl text-white shadow-xl shadow-slate-100"><BarChart3 size={20} /></div>
                    <div>
                      <h3 className="font-black text-[15px] text-slate-800 uppercase tracking-tight">Akış Analizi</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Seçili ürünlerin son 7 günlük onaylı hacmi</p>
                    </div>
                  </div>
                  <div className="h-[350px] w-full">
                    {chartData.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="code" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }} dy={10} />
                          <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }} />
                          <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '1.2rem', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: '800' }} />
                          <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '30px', fontSize: '10px', fontWeight: '800' }} />
                          <Bar name="Giriş" dataKey="Giriş" fill="#4f46e5" radius={[8, 8, 0, 0]} barSize={35} />
                          <Bar name="Çıkış" dataKey="Çıkış" fill="#f43f5e" radius={[8, 8, 0, 0]} barSize={35} />
                        </BarChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-4">
                         <BarChart3 size={60} className="opacity-10" />
                         <p className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Analiz için uygun veri yok</p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Dashboard Recent Movements */}
                <div className="bg-white rounded-[3rem] border border-slate-100 shadow-sm p-8 flex flex-col">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="p-3 bg-indigo-600 rounded-2xl text-white shadow-xl shadow-indigo-100"><ListFilter size={20} /></div>
                    <div>
                      <h3 className="font-black text-[15px] text-slate-800 uppercase tracking-tight">Son İşlemler</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Seçili ürünlerin hareketleri</p>
                    </div>
                  </div>
                  <div className="flex-1 space-y-4 overflow-y-auto pr-2 max-h-[350px]">
                    {dashboardRecentTransactions.map(t => (
                      <div key={t.id} className="p-4 bg-slate-50/50 rounded-2xl border border-slate-100/50 hover:bg-white hover:shadow-md transition-all flex items-center gap-4">
                        <div className={`p-2.5 rounded-xl ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                           {t.type === TransactionType.IN ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-[11px] font-black text-slate-800 truncate leading-tight mb-1">{t.productName}</p>
                          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.date}</p>
