                          </td>
                          <td className="px-10 py-7">
                            <span className="bg-rose-50 text-rose-600 px-3 py-1.5 rounded-xl font-black text-[11px] leading-none">-{item.totalOut}</span>
                          </td>
                          <td className="px-10 py-7">
                             <div className="font-black text-slate-900 text-[18px] tracking-tighter">{item.remaining}</div>
                          </td>
                          <td className="px-10 py-7 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= thresholds[item.productCode] ? (
                              <span className="bg-rose-500 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-rose-100">Kritik</span>
                            ) : (
                              <span className="bg-slate-100 text-slate-500 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest">Normal</span>
                            )}
                          </td>
