          {activeTab === 'approvals' && (
             <div className="space-y-8 animate-fade-in max-w-4xl mx-auto py-4">
                <div className="space-y-1">
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Onay Bekleyen Talepler</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Onaylaman gereken depo hareketleri</p>
                </div>
