                               {t.status === TransactionStatus.PENDING && <Hourglass size={12} />}
                               {t.status === TransactionStatus.APPROVED && <CheckCircle2 size={12} />}
                               {t.status === TransactionStatus.REJECTED && <XCircle size={12} />}
                               {t.status}
