          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto py-4">
              <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Kullanıcı Yönetimi</h3>
