      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-6">
           <div className="bg-white w-full max-w-sm rounded-[3.5rem] p-10 shadow-2xl animate-fade-in border border-white/20">
              <h4 className="text-2xl font-black text-slate-900 tracking-tight uppercase mb-10 text-center">{editingUser ? 'Personel Güncelle' : 'Yeni Kayıt'}</h4>
              <form onSubmit={handleUserSave} className="space-y-8">
                 <InputSmall label="Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-3">
                    <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-2">Yetki Seviyesi</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-6 py-4.5 bg-slate-50 border border-slate-100 rounded-[1.5rem] font-black text-slate-800 text-[13px] outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all">
                       <option value={UserRole.ADMIN}>Yönetici (Full Erişim)</option>
                       <option value={UserRole.USER}>Personel (Sınırlı)</option>
                    </select>
                 </div>
                 <div className="flex gap-5 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-5 bg-slate-50 rounded-[1.5rem] font-black text-slate-400 text-[11px] uppercase tracking-widest hover:bg-slate-100">İptal</button>
                    <button type="submit" className="flex-1 py-5 bg-indigo-600 rounded-[1.5rem] font-black text-white text-[11px] uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

