                             <span>{t.type === TransactionType.IN ? 'Tedarikçi: ' : 'Alıcı: '} {t.supplier || t.recipient || 'Belirtilmedi'}</span>
                          </div>
                          <div className="flex items-center gap-2 pt-2">
                             <div className="w-6 h-6 rounded-full bg-slate-900 text-white flex items-center justify-center text-[9px] font-black">{t.operator.charAt(0)}</div>
