                <div className={`inline-flex p-6 rounded-[2.5rem] mb-2 ${activeTab === 'in' ? 'bg-indigo-600 shadow-indigo-100' : 'bg-rose-500 shadow-rose-100'} text-white shadow-2xl scale-110`}>
