                  <div className="flex justify-between items-start p-10 bg-slate-50/50 rounded-[2.5rem] border border-slate-100">
                    <div className="space-y-3 flex-1">
                      <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Okutulan Ürün</p>
