                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkışlar" />
                 </div>
              </div>

              <div className="bg-white rounded-[3.5rem] border border-slate-100 overflow-hidden shadow-sm mb-12">
