                        <th className="px-10 py-7 text-right">Miktar</th>
                        <th className="px-10 py-7 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[13px] hover:bg-slate-50/30 transition-all">
                          <td className="px-10 py-8 text-slate-400 font-bold whitespace-nowrap">{t.date}</td>
                          <td className="px-10 py-8">
                            <div className="font-black text-slate-800 text-[14px] leading-tight mb-1">{t.productName}</div>
                            <div className="flex gap-2">
                               <span className="text-[10px] font-bold text-slate-400 uppercase">#{t.productCode}</span>
                               {t.brand && <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-tighter">{t.brand}</span>}
                            </div>
                          </td>
                          <td className="px-10 py-8">
                            <div className="text-[10px] text-slate-500 font-bold uppercase flex flex-wrap gap-x-3 gap-y-1">
                               {t.size && <span>BEDEN: {t.size}</span>}
                               {t.color && <span>RENK: {t.color}</span>}
                               <span className="text-indigo-400">{t.type === TransactionType.IN ? 'TEDARİKÇİ' : 'ALICI'}: {t.supplier || t.recipient}</span>
                            </div>
                          </td>
                          <td className="px-10 py-8">
                             <div className="flex flex-col gap-2">
                                <div className="flex items-center gap-2">
                                   <div className="w-5 h-5 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">{t.operator.charAt(0)}</div>
                                   <div className="text-[10px] font-black text-slate-700 truncate max-w-[120px]"><span className="text-slate-400 font-bold uppercase mr-1">Talebi:</span> {t.operator}</div>
                                </div>
                                <div className="flex items-center gap-2">
                                   <div className="w-5 h-5 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[8px] font-black shrink-0 uppercase">{t.approver.charAt(0)}</div>
                                   <div className="text-[10px] font-black text-slate-700 truncate max-w-[120px]"><span className="text-indigo-400 font-bold uppercase mr-1">Onay:</span> {t.approver}</div>
                                </div>
                             </div>
                          </td>
                          <td className="px-10 py-8 font-black text-[18px] text-slate-900 text-right">
                             <span className={t.type === TransactionType.IN ? 'text-emerald-500' : 'text-rose-500'}>
                                {t.type === TransactionType.IN ? '+' : '-'}{t.quantity}
                             </span>
                          </td>
                          <td className="px-10 py-8 text-right">
                            <div className="flex justify-end">
                              <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 w-fit ${
                                t.status === TransactionStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' :
                                t.status === TransactionStatus.REJECTED ? 'bg-rose-50 text-rose-600' :
                                'bg-amber-50 text-amber-600'
                              }`}>
                                {t.status === TransactionStatus.PENDING && <Hourglass size={12} />}
                                {t.status === TransactionStatus.APPROVED && <CheckCircle2 size={12} />}
                                {t.status === TransactionStatus.REJECTED && <XCircle size={12} />}
                                {t.status}
                              </span>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto py-4">
              <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Kullanıcı Yönetimi</h3>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-3 px-8 py-4.5 bg-indigo-600 text-white rounded-[1.5rem] text-[12px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 active:scale-95">
                  <UserPlus size={18} /> Yeni Personel Ekle
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm flex flex-col group hover:shadow-2xl hover:-translate-y-1 transition-all">
                    <div className="flex items-center gap-5 mb-6">
                       <div className="w-16 h-16 rounded-[1.5rem] bg-slate-900 text-white flex items-center justify-center font-black text-2xl uppercase shadow-xl">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-black text-slate-900 text-[17px] leading-tight mb-1">{u.fullName}</p>
                          <span className="text-[10px] text-indigo-600 font-black uppercase tracking-[0.2em]">{u.role}</span>
                       </div>
                    </div>
                    <div className="flex items-center gap-3 mt-auto pt-6 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-3 text-slate-400 hover:text-indigo-600 transition-all font-black text-[11px] uppercase tracking-widest hover:bg-indigo-50 rounded-2xl flex items-center justify-center gap-2">Düzenle</button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Emin misiniz?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 transition-all rounded-2xl"><Trash2 size={18} /></button>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-6">
           <div className="bg-white w-full max-w-sm rounded-[3.5rem] p-10 shadow-2xl animate-fade-in border border-white/20">
              <h4 className="text-2xl font-black text-slate-900 tracking-tight uppercase mb-10 text-center">{editingUser ? 'Personel Güncelle' : 'Yeni Kayıt'}</h4>
              <form onSubmit={handleUserSave} className="space-y-8">
                 <InputSmall label="Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-3">
                    <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-2">Yetki Seviyesi</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-6 py-4.5 bg-slate-50 border border-slate-100 rounded-[1.5rem] font-black text-slate-800 text-[13px] outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all">
                       <option value={UserRole.ADMIN}>Yönetici (Full Erişim)</option>
                       <option value={UserRole.USER}>Personel (Sınırlı)</option>
                    </select>
                 </div>
                 <div className="flex gap-5 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-5 bg-slate-50 rounded-[1.5rem] font-black text-slate-400 text-[11px] uppercase tracking-widest hover:bg-slate-100">İptal</button>
                    <button type="submit" className="flex-1 py-5 bg-indigo-600 rounded-[1.5rem] font-black text-white text-[11px] uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4.5 rounded-[1.4rem] transition-all relative ${active ? 'bg-indigo-600 text-white shadow-2xl shadow-indigo-200 scale-105' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} className={`${active ? 'scale-110' : 'opacity-60'} transition-transform`} /> 
    <span className="text-[12px] font-black tracking-tight uppercase whitespace-nowrap">{label}</span>
    {badge > 0 && (
      <span className="absolute right-5 top-1/2 -translate-y-1/2 w-5.5 h-5.5 bg-rose-500 text-white text-[10px] font-black rounded-full flex items-center justify-center animate-pulse shadow-lg border-2 border-white">
        {badge}
      </span>
    )}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-7 rounded-[2.8rem] border border-slate-100 shadow-sm flex items-start justify-between group hover:shadow-2xl transition-all hover:-translate-y-1 active:scale-95">
    <div className="space-y-2">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-3xl font-black text-slate-900 tracking-tighter leading-none">{val.toLocaleString()}</p>
    </div>
    <div className={`p-4 bg-${color}-50 text-${color}-600 rounded-[1.5rem] group-hover:bg-${color}-600 group-hover:text-white transition-all shadow-sm`}>
      <Icon size={24} />
    </div>
  </div>
);

const InputSmall = ({ label, ...props }: any) => (
  <div className="space-y-3">
    <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-2 opacity-90">{label}</label>
    <input 
      {...props} 
      onChange={(e: any)=>props.onChange?.(e.target.value)} 
      className="w-full px-6 py-4.5 bg-slate-50 border border-slate-100 rounded-[1.5rem] focus:bg-white focus:ring-4 focus:ring-indigo-50/40 font-black text-slate-800 outline-none transition-all text-[14px] shadow-sm placeholder:text-slate-300" 
    />
