);

const FilterButton = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-8 py-3 rounded-[1.2rem] text-[11px] font-black uppercase tracking-widest transition-all ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-100'}`}
  >
    {label}
  </button>
);

export default App;

