import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Html5Qrcode, Html5QrcodeSupportedFormats } from 'html5-qrcode';
import { 
  AlertCircle, 
  X, 
  Loader2, 
  ImagePlus, 
  Zap, 
  Camera,
  RotateCcw
} from 'lucide-react';

interface ScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScan, onClose }) => {
  const [isInitializing, setIsInitializing] = useState(true);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [scanLocked, setScanLocked] = useState(false);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scannerId = "qr-reader-container";

  const stopScanner = useCallback(async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
      } catch (err) {
        console.warn("Scanner durdurulurken hata:", err);
      }
    }
  }, []);

  const handleScanSuccess = useCallback((text: string) => {
    if (scanLocked) return;
    setScanLocked(true);
    onScan(text);
    stopScanner().finally(() => onClose());
  }, [onScan, onClose, stopScanner, scanLocked]);

  const startCamera = useCallback(async () => {
    setError(null);
    setIsInitializing(true);
    await stopScanner();
    await new Promise(resolve => setTimeout(resolve, 300));

    const container = document.getElementById(scannerId);
    if (!container) {
      setError("Kamera alanı yüklenemedi.");
      setIsInitializing(false);
      return;
    }

    const html5QrCode = new Html5Qrcode(scannerId, { 
      verbose: false,
      formatsToSupport: [ 
        Html5QrcodeSupportedFormats.QR_CODE, 
        Html5QrcodeSupportedFormats.CODE_128,
        Html5QrcodeSupportedFormats.EAN_13
      ]
    });
    html5QrCodeRef.current = html5QrCode;

    try {
      const config = {
        fps: 25,
        qrbox: (vw: number, vh: number) => {
          const s = Math.floor(Math.min(vw, vh) * 0.7);
          return { width: s, height: s };
        },
        aspectRatio: 1.0
      };

      await html5QrCode.start(
        { facingMode: "environment" },
        config,
        handleScanSuccess,
        () => {}
      );
    } catch (err: any) {
      setError("Kamera başlatılamadı. İzinleri kontrol edin.");
    } finally {
      setIsInitializing(false);
    }
  }, [stopScanner, handleScanSuccess]);

  useEffect(() => {
    startCamera();
    return () => { stopScanner(); };
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessingFile(true);

    try {
      await stopScanner();
      const tempScanner = new Html5Qrcode(scannerId);
      const res = await tempScanner.scanFile(file, true);
      handleScanSuccess(res);
    } catch (err) {
      setError("Fotoğrafta geçerli bir kod bulunamadı.");
      setTimeout(() => startCamera(), 1500);
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/80 backdrop-blur-xl p-6 transition-all animate-fade-in">
      <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col border border-white/20">

        {/* Header */}
        <div className="p-8 flex justify-between items-center border-b border-slate-50">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
                <Camera size={20} />
             </div>
             <div>
                <h3 className="font-bold text-sm text-slate-900 tracking-tight">Akıllı Tarayıcı</h3>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">QR & Barkod</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2.5 text-slate-300 hover:text-rose-500 transition-soft">
            <X size={24} />
          </button>
        </div>

        {/* Scanner Body */}
        <div className="p-8 space-y-8">
          <div className="relative aspect-square w-full rounded-[2rem] overflow-hidden bg-slate-900 shadow-inner border-8 border-slate-50">
            <div id={scannerId} className="w-full h-full relative z-0"></div>

            {isInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-slate-900 z-10 text-white">
                <Loader2 size={32} className="text-indigo-400 animate-spin" />
                <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Kamera Hazırlanıyor</p>
              </div>
            )}

            {isProcessingFile && (
              <div className="absolute inset-0 bg-indigo-600 flex flex-col items-center justify-center z-20 text-white">
                <Zap size={32} className="text-amber-300 animate-bounce mb-3" />
                <p className="font-bold text-xs uppercase tracking-widest">Analiz Ediliyor</p>
              </div>
            )}

            {!isInitializing && !isProcessingFile && !error && (
              <>
                <div className="absolute inset-0 border-[35px] border-black/40 pointer-events-none z-0"></div>
                <div className="absolute top-1/2 left-0 w-full h-[2px] bg-indigo-500 shadow-[0_0_20px_rgba(99,102,241,1)] animate-scan pointer-events-none"></div>
                {/* Corners */}
                <div className="absolute top-10 left-10 w-8 h-8 border-t-4 border-l-4 border-white rounded-tl-xl pointer-events-none"></div>
                <div className="absolute top-10 right-10 w-8 h-8 border-t-4 border-r-4 border-white rounded-tr-xl pointer-events-none"></div>
                <div className="absolute bottom-10 left-10 w-8 h-8 border-b-4 border-l-4 border-white rounded-bl-xl pointer-events-none"></div>
                <div className="absolute bottom-10 right-10 w-8 h-8 border-b-4 border-r-4 border-white rounded-br-xl pointer-events-none"></div>
              </>
            )}
          </div>

          <div className="space-y-4">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />

            {error ? (
              <div className="space-y-4">
                <div className="flex items-center gap-3 text-xs text-rose-500 font-bold justify-center bg-rose-50 p-5 rounded-2xl border border-rose-100">
                  <AlertCircle size={16} className="shrink-0" />
                  <span>{error}</span>
                </div>
                <button onClick={startCamera} className="w-full py-4 bg-indigo-50 text-indigo-600 rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-100 transition-soft flex items-center justify-center gap-2">
                  <RotateCcw size={16} /> Yeniden Başlat
                </button>
              </div>
            ) : (
              <button 
                onClick={() => fileInputRef.current?.click()} 
                disabled={isInitializing || isProcessingFile}
                className="w-full py-4.5 bg-slate-900 text-white rounded-2xl hover:bg-indigo-600 disabled:opacity-50 transition-soft font-bold text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-3"
              >
                <ImagePlus size={18} /> Galeriden Seç
              </button>
            )}
          </div>
        </div>

        <div className="p-6 bg-slate-50 text-center">
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">QR Kodu kutu içine hizalayın</p>
        </div>
      </div>

      <style>{`
        #qr-reader-container video { 
          width: 100% !important; 
          height: 100% !important; 
          object-fit: cover !important; 
        }
        @keyframes scan {
          0%, 100% { transform: translateY(-120px); }
          50% { transform: translateY(120px); }
        }
        .animate-scan {
          animation: scan 3s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default Scanner;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Maximize2,
  Trash2,
  UserPlus,
  ArrowRightLeft,
  XCircle,
  BarChart3,
  ClipboardList,
  ThumbsUp,
  Hourglass,
  Download,
  ListFilter,
  ShieldAlert,
  ChevronRight,
  Bell,
  // Added UserCheck to fix the "Cannot find name 'UserCheck'" error
  UserCheck
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');

  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const query = searchQuery.toLowerCase();
      return item.productName.toLowerCase().includes(query) || 
             item.productCode.toLowerCase().includes(query);
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const chartData = useMemo(() => {
    const items = filteredInventory.slice(0, 5);
    return items.map(item => ({
      name: item.productName.length > 12 ? item.productName.substring(0, 10) + '..' : item.productName,
      Stok: item.remaining
    }));
  }, [filteredInventory]);

  const criticalCount = useMemo(() => {
    return inventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= (thresholds[p.productCode] || 0)).length;
  }, [inventory, thresholds]);

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      let extractedData: any = { code: '', name: '', partner: '', size: '', color: '', quantity: '', feature: '', brand: '' };
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";]+\\s*"([^"]+)"|'${key}'\\s*[:";]+\\s*'([^']+)'|${key}\\s*[:";]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      extractedData.code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod') || '';
      extractedData.name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad') || '';

      setProductCode(extractedData.code || cleanText);
      setProductName(extractedData.name || `Ürün ${extractedData.code || cleanText}`);
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Ürün başarıyla tanımlandı.', 'success');
    } catch (e) {
      showNotification('Kod ayrıştırılamadı.', 'error');
    }
  };

  const handleSave = () => {
    if (!productCode || quantity === '' || !approver) {
      showNotification('Lütfen zorunlu alanları doldurun.', 'error');
      return;
    }

    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;
    if (activeTab === 'out' && Number(quantity) > currentStock) {
      showNotification(`Yetersiz stok! Mevcut: ${currentStock}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: Number(quantity),
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover(''); setBrand('');
    showNotification(`Talep ${approver} onayına gönderildi.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem onaylandı.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const userData: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      fullName: formData.get('fullName') as string,
      role: formData.get('role') as UserRole,
    };
    StorageService.saveUser(userData);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    setEditingUser(null);
    showNotification('Kullanıcı güncellendi.', 'success');
  };

  const exportToExcel = () => {
    const headers = ['Tarih', 'Ürün', 'Miktar', 'İşlem', 'Yapan', 'Onaylayan'];
    const rows = transactions.map(t => [t.date, t.productName, t.quantity, t.type, t.operator, t.approver]);
    const csvContent = "data:text/csv;charset=utf-8,\ufeff" + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "stok_raporu.csv");
    document.body.appendChild(link);
    link.click();
  };

  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  const filteredHistory = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productName.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productCode.toLowerCase().includes(historySearch.toLowerCase());
      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      return matchesSearch && matchesType;
    });
  }, [transactions, historySearch, historyTypeFilter]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-[#1E293B]">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-white border-r border-slate-100 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="mb-12">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <Box size={20} />
              </div>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-slate-900">ProStock<span className="text-indigo-600">.</span></h1>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">Smart Inventory</p>
              </div>
            </div>
          </div>

          <nav className="flex-1 space-y-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Genel Bakış" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onaylar" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="İşlem Geçmişi" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Personel" />}
          </nav>

          <div className="mt-auto pt-8 border-t border-slate-50">
            <div className="flex items-center gap-4 mb-6 px-2">
              <div className="w-11 h-11 bg-slate-100 rounded-2xl flex items-center justify-center font-bold text-slate-600 text-sm">{user.fullName.charAt(0)}</div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-slate-900 truncate">{user.fullName}</p>
                <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider">{user.role}</p>
              </div>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-soft font-bold text-sm">
              <LogOut size={18} /> Çıkış Yap
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-h-screen overflow-hidden">
        {/* Top Header */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-8 sticky top-0 z-40">
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="md:hidden p-2.5 bg-slate-50 rounded-xl text-slate-500">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="hidden md:flex items-center gap-2 text-sm text-slate-400 font-medium">
             <span>Uygulamalar</span> <ChevronRight size={14} /> <span className="text-slate-900 font-bold capitalize">{activeTab}</span>
          </div>
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 hover:text-indigo-600 cursor-pointer transition-soft">
                <Bell size={18} />
             </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-8">
          {notification && (
            <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[100] px-6 py-3.5 rounded-2xl shadow-xl text-white font-bold animate-slide-up flex items-center gap-3 text-sm ${notification.type === 'error' ? 'bg-rose-500' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-slide-up max-w-7xl mx-auto">
              <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                <div>
                  <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Depo Envanter Paneli</h2>
                  <p className="text-slate-400 text-sm font-medium">Güncel stok durumunu ve akışını buradan takip edebilirsiniz.</p>
                </div>
                <div className="relative w-full md:w-80">
                   <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                   <input 
                    type="text" 
                    placeholder="Ürün adı veya kod ara..." 
                    value={searchQuery}
                    onChange={(e)=>setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-sm font-medium outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-200 transition-soft shadow-sm" 
                   />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Toplam Ürün" val={filteredInventory.length} icon={Layers} color="indigo" />
                <StatCard label="Mevcut Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining, 0)} icon={Box} color="blue" />
                <StatCard label="Kritik Stok" val={criticalCount} icon={AlertCircle} color="rose" />
                <StatCard label="Bekleyen Onay" val={pendingApprovals.length} icon={ClipboardList} color="amber" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                <div className="xl:col-span-2 bg-white rounded-[2rem] border border-slate-100 shadow-sm p-8">
                  <h3 className="text-base font-bold text-slate-900 mb-8 flex items-center gap-2">
                    <BarChart3 size={18} className="text-indigo-600" /> Stok Dağılımı (Top 5)
                  </h3>
                  <div className="h-72 w-full">
                    {chartData.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 600}} dy={10} />
                          <YAxis axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 600}} />
                          <Tooltip 
                            cursor={{fill: '#F8FAFC'}} 
                            contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontSize: '12px', fontWeight: 'bold'}} 
                          />
                          <Bar dataKey="Stok" radius={[8, 8, 0, 0]} barSize={40}>
                            {chartData.map((_, index) => (
                              <Cell key={`cell-${index}`} fill={index === 0 ? '#4F46E5' : '#E2E8F0'} />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="h-full flex items-center justify-center text-slate-300 font-medium">Analiz edilecek veri bulunamadı.</div>
                    )}
                  </div>
                </div>

                <div className="bg-white rounded-[2rem] border border-slate-100 shadow-sm p-8 flex flex-col">
                  <h3 className="text-base font-bold text-slate-900 mb-6">Son İşlemler</h3>
                  <div className="flex-1 space-y-4">
                    {transactions.slice(0, 5).map(t => (
                      <div key={t.id} className="flex items-center gap-4 p-4 rounded-2xl bg-slate-50/50 hover:bg-slate-50 transition-soft">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                           {t.type === TransactionType.IN ? <TrendingUp size={18} /> : <TrendingDown size={18} />}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-bold text-slate-900 truncate">{t.productName}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{t.date}</p>
                        </div>
                        <div className="text-right">
                          <p className={`text-sm font-bold ${t.type === TransactionType.IN ? 'text-emerald-500' : 'text-rose-500'}`}>
                            {t.type === TransactionType.IN ? '+' : '-'}{t.quantity}
                          </p>
                        </div>
                      </div>
                    ))}
                    {transactions.length === 0 && <p className="text-center py-10 text-slate-300 text-sm font-medium">İşlem kaydı yok.</p>}
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                    <h3 className="text-base font-bold text-slate-900 uppercase tracking-tight">Ürün Bakiyeleri</h3>
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 bg-slate-50 px-3 py-1.5 rounded-full uppercase tracking-widest">
                       <Box size={14} /> Toplam: {filteredInventory.length} Kalem
                    </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
