              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Analiz Edilen Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Kritik Limit Altı" val={criticalCountFiltered} icon={AlertCircle} color="amber" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
