export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Maximize2,
  Trash2,
  UserPlus,
  ArrowRightLeft,
  XCircle,
  BarChart3,
  ClipboardList,
  ThumbsUp,
  Hourglass,
  Download,
  ListFilter,
  ShieldAlert
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');

  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => { clearTimeout(timer); };
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const query = searchQuery.toLowerCase();
      return item.productName.toLowerCase().includes(query) || 
             item.productCode.toLowerCase().includes(query);
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const dashboardRecentTransactions = useMemo(() => {
    return transactions.filter(t => {
      const query = searchQuery.toLowerCase();
      return t.productName.toLowerCase().includes(query) || 
             t.productCode.toLowerCase().includes(query);
    }).slice(0, 10);
  }, [transactions, searchQuery]);

  const chartData = useMemo(() => {
    const items = filteredInventory.slice(0, 5);
    return items.map(item => ({
      name: item.productCode,
      Stok: item.remaining
    }));
  }, [filteredInventory]);

  const criticalCountFiltered = useMemo(() => {
    return filteredInventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= (thresholds[p.productCode] || 0)).length;
  }, [filteredInventory, thresholds]);

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";=]+\\s*"([^"]+)"|'${key}'\\s*[:";=]+\\s*'([^']+)'|${key}\\s*[:";=]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      const qtyRegex = /"adet"[^0-9]+(\d+)/i;
      const qtyMatch = cleanText.match(qtyRegex);
      const extractedQty = qtyMatch ? qtyMatch[1] : (regexMatch('adet') || regexMatch('miktar') || regexMatch('quantity'));

      const code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod');
      const name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad');
      const ptnr = regexMatch('tedarikci') || regexMatch('alici') || regexMatch('partner') || regexMatch('firma');
      const sz = regexMatch('beden') || regexMatch('size');
      const clr = regexMatch('renk') || regexMatch('color');
      const brnd = regexMatch('marka') || regexMatch('brand');
      const ftr = regexMatch('ozellik') || regexMatch('feature');

      setProductCode(code || cleanText);
      setProductName(name || (code ? `Ürün ${code}` : `Ürün ${cleanText}`));
      if (extractedQty) setQuantity(parseInt(extractedQty));
      if (ptnr) setPartner(ptnr);
      if (sz) setSize(sz);
      if (clr) setColor(clr);
      if (brnd) setBrand(brnd);
      if (ftr) setFeature(ftr);

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('QR Bilgileri Başarıyla Aktarıldı', 'success');
    } catch (e) {
      showNotification('Ayrıştırma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    const currentStock = inventory.find(i => i.productCode === productCode)?.remaining || 0;

    if (!productCode || !productName || quantity === '' || !approver) {
      showNotification('Zorunlu alanları (Ürün Kodu, Ürün Adı, Adet, Onaylayan) doldurun', 'error');
      return;
    }

    if (activeTab === 'out' && Number(quantity) > currentStock) {
      showNotification(`Yetersiz Stok! (Mevcut: ${currentStock})`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    setIsFormActive(false);
    setQuantity(''); setPartner(''); setSize(''); setColor(''); setFeature(''); setApprover(''); setBrand(''); setProductName(''); setProductCode('');
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleThresholdChange = (code: string, val: string) => {
    if (user?.role !== UserRole.ADMIN) return;
    const num = parseInt(val) || 0;
    StorageService.saveThreshold(code, num);
    setThresholds(StorageService.getThresholds());
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem onaylandı.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleUserSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newUser: User = {
      id: editingUser?.id || Math.random().toString(36).substring(2, 9),
      fullName: formData.get('fullName') as string,
      username: formData.get('username') as string,
      password: formData.get('password') as string,
      role: formData.get('role') as UserRole
    };
    StorageService.saveUser(newUser);
    setUserList(StorageService.getUsers());
    setIsUserModalOpen(false);
    showNotification('Kullanıcı kaydedildi', 'success');
  };

  const exportToExcel = () => {
    const headers = ['Tarih', 'Ürün', 'Miktar', 'İşlem', 'Personel', 'Onaylayan'];
    const rows = filteredTransactions.map(t => [t.date, t.productName, t.quantity, t.type, t.operator, t.approver]);
    const csvContent = headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'stok_gecmisi.csv';
    link.click();
  };

  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase());
      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      return matchesSearch && matchesType;
    });
  }, [transactions, historySearch, historyTypeFilter]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center gap-3">
             <div className="p-2 bg-indigo-600 rounded-lg text-white"><Box size={20} /></div>
             <h1 className="text-xl font-bold text-slate-900">ProStock</h1>
          </div>
          <nav className="space-y-1 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="Geçmiş" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Personel" />}
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-100">
            <div className="mb-4 px-2">
              <p className="text-[11px] font-bold text-slate-900">{user.fullName}</p>
              <p className="text-[10px] text-slate-400 uppercase">{user.role}</p>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
              <LogOut size={16} /> Çıkış
            </button>
          </div>
        </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-200 p-4 flex justify-between items-center z-40">
          <span className="font-bold text-indigo-600">ProStock</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-100 rounded-lg">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-xl shadow-xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto pb-12">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">Envanter Paneli</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Depo hareketleri ve genel analiz</p>
                </div>
                <div className="relative w-full md:w-80">
                   <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                   <input 
                    type="text" 
                    placeholder="Ürün adı veya kodu ara..." 
                    value={searchQuery}
                    onChange={(e)=>setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-[12px] font-bold outline-none focus:ring-2 focus:ring-indigo-100 transition-all" 
                   />
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Analiz Edilen Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Onaylı Giriş" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Onaylı Çıkış" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Kritik Limit Altı" val={criticalCountFiltered} icon={AlertCircle} color="amber" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                <div className="xl:col-span-2 bg-white rounded-3xl border border-slate-200 p-8 shadow-sm">
                  <h3 className="font-bold text-[14px] text-slate-800 uppercase tracking-tight mb-6">Stok Durumu (Top 5)</h3>
                  <div className="h-[300px] w-full">
                    {chartData.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10 }} />
                          <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10 }} />
                          <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                          <Bar dataKey="Stok" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={40} />
                        </BarChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="h-full flex items-center justify-center text-slate-300">Uygun veri yok</div>
                    )}
                  </div>
                </div>

                <div className="bg-white rounded-3xl border border-slate-200 p-8 shadow-sm flex flex-col">
                  <h3 className="font-bold text-[14px] text-slate-800 uppercase mb-6">Son İşlemler</h3>
                  <div className="flex-1 space-y-4 overflow-y-auto pr-2 max-h-[300px]">
                    {dashboardRecentTransactions.map(t => (
                      <div key={t.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                           {t.type === TransactionType.IN ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-[11px] font-bold text-slate-800 truncate">{t.productName}</p>
                          <p className="text-[9px] text-slate-400">{t.date}</p>
                        </div>
                        <div className="text-right">
                          <p className={`text-[11px] font-bold ${t.type === TransactionType.IN ? 'text-emerald-500' : 'text-rose-500'}`}>
                            {t.type === TransactionType.IN ? '+' : '-'}{t.quantity}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 font-bold uppercase text-[12px] text-slate-500">Ürün Bakiyeleri</div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase">
                      <tr>
                        <th className="px-8 py-4">Ürün Bilgisi</th>
                        <th className="px-8 py-4">Giriş / Çıkış</th>
                        <th className="px-8 py-4">Güncel Stok</th>
                        <th className="px-8 py-4">Alt Limit</th>
                        <th className="px-8 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50 transition-all text-[12px]">
                          <td className="px-8 py-5">
                            <div className="font-bold text-slate-800">{item.productName}</div>
                            <div className="text-[10px] text-slate-400 uppercase">KOD: {item.productCode}</div>
                          </td>
                          <td className="px-8 py-5">
                            <span className="text-emerald-500">+{item.totalIn}</span> / <span className="text-rose-500">-{item.totalOut}</span>
                          </td>
                          <td className="px-8 py-5 font-bold text-[14px]">{item.remaining}</td>
                          <td className="px-8 py-5">
                            {user.role === UserRole.ADMIN ? (
                              <input 
                                type="number" 
                                value={thresholds[item.productCode] || 0}
                                onChange={(e)=>handleThresholdChange(item.productCode, e.target.value)}
                                className="w-20 px-2 py-1 bg-slate-100 border border-slate-200 rounded-lg text-center"
                              />
                            ) : (
                              <span className="text-slate-400">{thresholds[item.productCode] || 0}</span>
                            )}
                          </td>
                          <td className="px-8 py-5 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= (thresholds[item.productCode] || 0) ? (
                              <span className="bg-rose-500 text-white px-2 py-1 rounded-lg text-[9px] font-bold uppercase">Kritik</span>
                            ) : (
                              <span className="bg-slate-100 text-slate-400 px-2 py-1 rounded-lg text-[9px] font-bold uppercase">Normal</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'approvals' && (
             <div className="space-y-6 animate-fade-in max-w-4xl mx-auto py-4">
                <h3 className="text-xl font-bold text-slate-900 uppercase">Onay Bekleyenler</h3>
                <div className="space-y-4">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 items-center">
                       <div className={`p-4 rounded-xl ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={24} /> : <PackageMinus size={24} />}
                       </div>
                       <div className="flex-1">
                          <h4 className="font-bold text-slate-900">{t.productName} ({t.productCode})</h4>
                          <p className="text-[11px] text-slate-500">
                             Adet: <span className="font-bold text-slate-900">{t.quantity}</span> | 
                             Tip: <span className="font-bold">{t.type}</span> | 
                             Personel: <span className="font-bold">{t.operator}</span>
                          </p>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={() => handleReject(t.id)} className="px-4 py-2 text-rose-500 text-[11px] font-bold uppercase hover:bg-rose-50 rounded-lg transition-all">Reddet</button>
                          <button onClick={() => handleApprove(t.id)} className="px-6 py-2 bg-indigo-600 text-white rounded-lg text-[11px] font-bold uppercase shadow-lg shadow-indigo-100">Onayla</button>
                       </div>
                    </div>
                  ))}
                  {pendingApprovals.length === 0 && <p className="text-center py-12 text-slate-300 font-bold uppercase tracking-widest text-[11px]">Onay bekleyen işlem yok</p>}
                </div>
             </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-2xl mx-auto space-y-8 animate-fade-in py-10">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-5 rounded-2xl ${activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500'} text-white shadow-xl`}>
                  {activeTab === 'in' ? <PackagePlus size={32} /> : <PackageMinus size={32} />}
                </div>
                <h2 className="text-2xl font-bold text-slate-900">{activeTab === 'in' ? 'Stok Giriş Formu' : 'Stok Çıkış Formu'}</h2>
              </div>

              {!isFormActive ? (
                <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-16 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 transition-all">
                  <Maximize2 size={40} className="text-slate-300 mb-4" />
                  <p className="text-[12px] font-bold uppercase text-slate-400">QR KOD OKUTARAK FORMU DOLDUR</p>
                </div>
              ) : (
                <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-200 space-y-6 animate-fade-in">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <InputSmall label="Ürün Kodu" value={productCode} onChange={setProductCode} placeholder="KOD-123" required />
                    <InputSmall label="Ürün Adı" value={productName} onChange={setProductName} placeholder="Ürün Tanımı" required />

                    <InputSmall label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı Firma"} value={partner} onChange={setPartner} placeholder="Firma Adı" />
                    <InputSmall label="Marka" value={brand} onChange={setBrand} placeholder="Marka Bilgisi" />

                    <InputSmall label="Özellik" value={feature} onChange={setFeature} placeholder="Ek Özellikler" />
                    <InputSmall label="Renk" value={color} onChange={setColor} placeholder="Renk" />

                    <InputSmall label="Beden" value={size} onChange={setSize} placeholder="Beden" />
                    <InputSmall label="Adet" type="number" value={quantity} onChange={(v: string)=>setQuantity(v===''?'':parseInt(v))} required />

                    <div className="sm:col-span-2">
                       <InputSmall label="Onay Veren Yetkili" value={approver} onChange={setApprover} placeholder="Yetkili Adı Soyadı" required />
                    </div>
                  </div>

                  <div className="flex gap-4 pt-4 border-t border-slate-50">
                    <button onClick={()=>{setIsFormActive(false); setProductName(''); setProductCode('');}} className="flex-1 py-3 bg-slate-50 rounded-xl font-bold text-slate-400 text-[11px] uppercase">İptal / Yeni Tarama</button>
                    <button onClick={handleSave} className={`flex-1 py-3 rounded-xl font-bold text-white text-[11px] uppercase shadow-lg ${activeTab==='in' ? 'bg-indigo-600 shadow-indigo-100' : 'bg-rose-500 shadow-rose-100'}`}>Kayıt Talebi Gönder</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto">
              <div className="flex flex-col lg:flex-row justify-between items-end gap-6">
                <div>
                  <h3 className="text-2xl font-bold text-slate-900">İşlem Geçmişi</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Tüm depo hareketleri</p>
                </div>
                <button onClick={exportToExcel} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-[11px] font-bold uppercase shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all">
                  <Download size={16} /> Excel İndir
                </button>
              </div>

              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col xl:flex-row gap-4 items-center">
                 <div className="flex-1 w-full relative">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input 
                      type="text" 
                      placeholder="Filtrele..." 
                      className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-[12px] font-bold outline-none"
                      value={historySearch}
                      onChange={(e)=>setHistorySearch(e.target.value)}
                    />
                 </div>
                 <div className="flex items-center p-1 bg-slate-100 rounded-xl">
                    <FilterButton active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Tümü" />
                    <FilterButton active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Giriş" />
                    <FilterButton active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkış" />
                 </div>
              </div>

              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase">
                      <tr>
                        <th className="px-8 py-4">Tarih</th>
                        <th className="px-8 py-4">Ürün Bilgisi</th>
                        <th className="px-8 py-4">Detaylar</th>
                        <th className="px-8 py-4 text-right">Adet</th>
                        <th className="px-8 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50 transition-all">
                          <td className="px-8 py-4 text-slate-400">{t.date}</td>
                          <td className="px-8 py-4">
                            <div className="font-bold text-slate-800">{t.productName}</div>
                            <div className="text-[10px] text-slate-400 font-bold uppercase">KOD: {t.productCode}</div>
                          </td>
                          <td className="px-8 py-4">
                            <div className="text-[10px] text-slate-500 font-bold uppercase flex flex-wrap gap-2">
                               {t.brand && <span>Marka: {t.brand}</span>}
                               {t.size && <span>Beden: {t.size}</span>}
                               <span className="text-indigo-500 font-bold">{t.supplier || t.recipient}</span>
                            </div>
                          </td>
                          <td className="px-8 py-4 font-bold text-right">
                             <span className={t.type === TransactionType.IN ? 'text-emerald-500' : 'text-rose-500'}>
                                {t.type === TransactionType.IN ? '+' : '-'}{t.quantity}
                             </span>
                          </td>
                          <td className="px-8 py-4 text-right">
                            <span className={`px-3 py-1 rounded-lg text-[9px] font-bold uppercase ${
                              t.status === TransactionStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' :
                              t.status === TransactionStatus.REJECTED ? 'bg-rose-50 text-rose-600' :
                              'bg-amber-50 text-amber-600'
                            }`}>
                               {t.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-6 animate-fade-in max-w-6xl mx-auto py-4">
              <div className="flex justify-between items-center">
                <h3 className="text-xl font-bold text-slate-900 uppercase">Personel Yönetimi</h3>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg text-[11px] font-bold uppercase shadow-lg shadow-indigo-100 hover:bg-indigo-700">
                  <UserPlus size={16} /> Yeni Personel
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all">
                    <div className="flex items-center gap-4 mb-4">
                       <div className="w-12 h-12 rounded-xl bg-slate-900 text-white flex items-center justify-center font-bold text-lg uppercase">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-bold text-slate-900">{u.fullName}</p>
                          <p className="text-[10px] text-indigo-600 font-bold uppercase tracking-widest">{u.role}</p>
                       </div>
                    </div>
                    <div className="flex gap-2 mt-auto pt-4 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-2 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg font-bold text-[10px] uppercase">Düzenle</button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Silinsin mi?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-2 text-rose-400 hover:bg-rose-50 rounded-lg"><Trash2 size={16} /></button>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/80 p-6 backdrop-blur-sm">
