                    <div className="flex gap-2 mt-auto pt-4 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-2 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg font-bold text-[10px] uppercase">Düzenle</button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Silinsin mi?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-2 text-rose-400 hover:bg-rose-50 rounded-lg"><Trash2 size={16} /></button>
                       )}
