                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/80 p-6 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-3xl p-8 shadow-2xl animate-fade-in border border-slate-200">
              <h4 className="text-xl font-bold text-slate-900 uppercase mb-6 text-center">{editingUser ? 'Güncelle' : 'Yeni Personel'}</h4>
              <form onSubmit={handleUserSave} className="space-y-6">
                 <InputSmall label="Tam Ad Soyad" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Yetki</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 text-[12px] outline-none">
                       <option value={UserRole.ADMIN}>Yönetici</option>
                       <option value={UserRole.USER}>Personel</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-3 bg-slate-50 rounded-xl font-bold text-slate-400 text-[11px] uppercase">İptal</button>
                    <button type="submit" className="flex-1 py-3 bg-indigo-600 rounded-xl font-bold text-white text-[11px] uppercase shadow-lg shadow-indigo-100 hover:bg-indigo-700">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

