                        <th className="px-8 py-5">Ürün Tanımı</th>
                        <th className="px-8 py-5">Toplam Hareket</th>
                        <th className="px-8 py-5">Kalan Stok</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
