                              <span className="bg-rose-100 text-rose-600 px-3 py-1.5 rounded-xl text-[9px] font-bold uppercase">Kritik Limit</span>
                            ) : (
                              <span className="bg-slate-100 text-slate-500 px-3 py-1.5 rounded-xl text-[9px] font-bold uppercase">Düzenli</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
