                </div>

                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col md:flex-row group">
                       <div className={`w-full md:w-28 flex items-center justify-center p-6 ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={40} strokeWidth={1.5} /> : <PackageMinus size={40} strokeWidth={1.5} />}
                       </div>

                       <div className="flex-1 p-8">
                          <div className="flex flex-col xl:flex-row justify-between gap-8">
                             <div className="space-y-6 flex-1">
                                <div>
                                   <div className="flex items-center gap-3 mb-2">
                                      <span className={`px-2 py-0.5 rounded-lg text-[9px] font-bold uppercase ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-rose-100 text-rose-700 border border-rose-200'}`}>
                                         Stok {t.type} Talebi
                                      </span>
                                      <span className="text-slate-300">/</span>
                                      <span className="text-slate-400 text-[10px] font-bold">İşlem ID: #{t.id}</span>
                                   </div>
                                   <h4 className="text-xl font-black text-slate-900 leading-tight">{t.productName}</h4>
                                   <div className="flex items-center gap-2 text-slate-400 text-[10px] font-bold uppercase mt-1">
                                      <Tag size={12} /> Kod: {t.productCode}
                                   </div>
                                </div>

                                <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 py-6 border-y border-slate-50">
                                   <DetailItem label="Marka" value={t.brand || '-'} />
                                   <DetailItem label="Beden" value={t.size || '-'} />
                                   <DetailItem label={t.type === TransactionType.IN ? 'Tedarikçi' : 'Alıcı / Departman'} value={t.supplier || t.recipient || '-'} highlight />
                                   <DetailItem label="Adet / Miktar" value={t.quantity} highlight big />
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-2 text-[11px]">
                                   <div className="flex items-center gap-3 text-slate-600 bg-slate-50 p-2 rounded-xl">
                                      <Calendar size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Tarih / Saat</p>
                                         <span className="font-bold">{t.date}</span>
                                      </div>
                                   </div>
                                   <div className="flex items-center gap-3 text-slate-600 bg-slate-50 p-2 rounded-xl">
                                      <UserPlus2 size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Talep Eden</p>
                                         <span className="font-bold">{t.operator}</span>
                                      </div>
                                   </div>
                                   <div className="flex items-center gap-3 text-slate-600 bg-slate-50 p-2 rounded-xl">
                                      <UserCheck size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Atanan Onaycı</p>
                                         <span className="font-bold">{t.approver}</span>
                                      </div>
                                   </div>
                                </div>
                             </div>

                             <div className="flex flex-row xl:flex-col justify-end gap-3 min-w-[160px]">
                                <button onClick={() => handleApprove(t.id)} className="flex-1 xl:flex-none px-8 py-4 bg-indigo-600 text-white rounded-[1.25rem] text-[11px] font-black uppercase shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:-translate-y-1 transition-all">İşlemi Onayla</button>
                                <button onClick={() => handleReject(t.id)} className="flex-1 xl:flex-none px-8 py-4 bg-white border border-rose-200 text-rose-500 rounded-[1.25rem] text-[11px] font-black uppercase hover:bg-rose-50 transition-all">Reddet</button>
                             </div>
                          </div>
                       </div>
                    </div>
                  ))}
                  {pendingApprovals.length === 0 && (
                    <div className="bg-white border border-slate-100 rounded-[3rem] p-24 text-center space-y-6">
                       <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200">
                          <CheckCircle2 size={40} />
                       </div>
                       <p className="text-slate-300 font-bold uppercase tracking-[0.3em] text-[10px]">Onay bekleyen herhangi bir hareket bulunmuyor</p>
                    </div>
                  )}
                </div>
             </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-2xl mx-auto space-y-8 animate-fade-in py-10">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-6 rounded-[2rem] ${activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500'} text-white shadow-2xl shadow-indigo-200`}>
                  {activeTab === 'in' ? <PackagePlus size={40} /> : <PackageMinus size={40} />}
                </div>
                <h2 className="text-3xl font-black text-slate-900 tracking-tighter">{activeTab === 'in' ? 'Stok Giriş Formu' : 'Stok Çıkış Formu'}</h2>
              </div>

              {!isFormActive ? (
                <div className="space-y-4">
                  <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] p-20 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/10 transition-all group">
                    <Maximize2 size={48} className="text-slate-200 mb-6 group-hover:text-indigo-400 group-hover:scale-110 transition-all" />
                    <p className="text-[12px] font-black uppercase text-slate-400 tracking-widest">Kamerayı Başlat ve Kod Tara</p>
                  </div>
                  <button 
                    onClick={()=>setIsFormActive(true)}
                    className="w-full py-5 bg-white border border-slate-200 rounded-[1.5rem] text-[11px] font-black uppercase text-slate-400 hover:bg-slate-50 transition-all flex items-center justify-center gap-3 shadow-sm"
                  >
                    <Keyboard size={18} /> Bilgileri Manuel Doldur
                  </button>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10">
                     <div className="flex items-center gap-5">
                        <div className="p-4 bg-white/10 rounded-2xl border border-white/5"><Calculator size={24} /></div>
                        <div>
                           <p className="text-[10px] font-bold text-white/40 uppercase tracking-widest mb-1">Mevcut Bakiye</p>
                           <p className="text-2xl font-black">{currentProductBalance} Adet</p>
                        </div>
                     </div>
                     <div className="text-right">
                        <p className="text-[10px] font-bold text-white/40 uppercase tracking-widest mb-1">İşlem Sonrası</p>
                        <p className={`text-2xl font-black ${projectedBalance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
                           {projectedBalance} Adet
                        </p>
                     </div>
                  </div>

                  <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-200 space-y-8 animate-fade-in">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <InputSmall label="Ürün Kodu" value={productCode} onChange={setProductCode} placeholder="Örn: PRD-001" required />
                      <InputSmall label="Ürün Tanımı" value={productName} onChange={setProductName} placeholder="Ürün Adı Soyadı" required />

                      <InputSmall 
                        label={activeTab==='in' ? "Tedarikçi Kaynağı" : "Alıcı / Hedef Birim"} 
                        value={partner} 
                        onChange={setPartner} 
                        placeholder={activeTab==='in' ? "Lojistik/Firma" : "Departman Adı"} 
                        required={activeTab === 'out'}
                      />
                      <InputSmall label="Marka" value={brand} onChange={setBrand} placeholder="Marka Adı" />

                      <InputSmall label="Renk Seçeneği" value={color} onChange={setColor} placeholder="Renk" />
                      <InputSmall label="Beden / Ölçü" value={size} onChange={setSize} placeholder="Beden" />

                      <div className="sm:col-span-1">
                        <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest ml-1 mb-2 block">İşlem Miktarı (Adet)</label>
                        <input 
                          type="number" 
                          value={quantity} 
                          onChange={(e: any)=>setQuantity(e.target.value===''?'':parseInt(e.target.value))} 
                          required 
                          className={`w-full px-5 py-4 border rounded-2xl font-black text-slate-900 text-[14px] outline-none transition-all focus:bg-white focus:ring-4 ${projectedBalance < 0 && activeTab === 'out' ? 'border-rose-500 bg-rose-50 ring-rose-50' : 'border-slate-200 bg-slate-50 ring-indigo-50'}`}
                        />
                      </div>

                      <div className="sm:col-span-1">
                        <InputSmall label="Onay Verecek Yetkili" value={approver} onChange={setApprover} placeholder="Yetkili Seçin/Yazın" required />
                      </div>
                    </div>

                    <div className="flex gap-4 pt-6 border-t border-slate-100">
                      <button onClick={resetForm} className="flex-1 py-4 bg-slate-50 rounded-2xl font-black text-slate-400 text-[11px] uppercase tracking-widest hover:bg-slate-100 transition-all">Formu Sıfırla</button>
                      <button 
                        onClick={handleSave} 
                        disabled={activeTab === 'out' && projectedBalance < 0}
                        className={`flex-1 py-4 rounded-2xl font-black text-white text-[11px] uppercase tracking-widest shadow-xl transition-all ${
                          activeTab==='in' ? 'bg-indigo-600 shadow-indigo-100 hover:bg-indigo-700' : 
                          (projectedBalance < 0 ? 'bg-slate-300 cursor-not-allowed opacity-50' : 'bg-rose-500 shadow-rose-100 hover:bg-rose-600')
                        }`}
                      >
                        {activeTab === 'out' && projectedBalance < 0 ? 'Stok Yetersiz' : 'Kayıt Talebi Oluştur'}
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-8 animate-fade-in max-w-7xl mx-auto">
              <div className="flex flex-col lg:flex-row justify-between items-end gap-6">
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight">Tüm İşlem Geçmişi</h3>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Arşivlenmiş depo hareketleri</p>
                </div>
                <button className="flex items-center gap-3 px-6 py-3 bg-emerald-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all">
                  <Download size={18} /> Verileri Dışa Aktar (CSV)
                </button>
              </div>

              <div className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col xl:flex-row gap-6 items-center">
                 <div className="flex-1 w-full relative">
                    <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input 
                      type="text" 
                      placeholder="Ürün, Personel veya Referans No ile filtreleyin..." 
                      className="w-full pl-14 pr-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.25rem] text-[13px] font-bold outline-none focus:bg-white focus:ring-4 focus:ring-indigo-50 transition-all"
                      value={historySearch}
                      onChange={(e)=>setHistorySearch(e.target.value)}
                    />
                 </div>
                 <div className="flex items-center p-1.5 bg-slate-100 rounded-[1.25rem]">
                    <HistoryFilter active={historyTypeFilter==='ALL'} onClick={()=>setHistoryTypeFilter('ALL')} label="Tümü" />
                    <HistoryFilter active={historyTypeFilter===TransactionType.IN} onClick={()=>setHistoryTypeFilter(TransactionType.IN)} label="Girişler" />
                    <HistoryFilter active={historyTypeFilter===TransactionType.OUT} onClick={()=>setHistoryTypeFilter(TransactionType.OUT)} label="Çıkışlar" />
                 </div>
              </div>

              <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
