                      <tr>
                        <th className="px-8 py-5">Tarih / Saat</th>
                        <th className="px-8 py-5">Ürün Detayı</th>
                        <th className="px-8 py-5">Varyant & Kaynak</th>
                        <th className="px-8 py-5">Sorumlular (Talep/Onay)</th>
                        <th className="px-8 py-5 text-right">Miktar</th>
                        <th className="px-8 py-5 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="text-[12px] hover:bg-slate-50/50 transition-all">
