                            <div className="flex flex-col gap-1">
                               <div className="flex gap-2">
                                 {t.brand && <span className="text-[9px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-500 font-bold uppercase">M: {t.brand}</span>}
                                 {t.size && <span className="text-[9px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-500 font-bold uppercase">B: {t.size}</span>}
                               </div>
                               <span className="text-indigo-600 font-bold text-[10px]">{t.supplier || t.recipient || 'Genel Depo'}</span>
                            </div>
                          </td>
                          <td className="px-8 py-5">
                             <div className="flex flex-col text-[10px] gap-1">
                                <div className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-slate-300"></div><span className="text-slate-400 font-bold uppercase">Talep:</span> <span className="font-bold text-slate-700">{t.operator}</span></div>
                                <div className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-indigo-400"></div><span className="text-slate-400 font-bold uppercase">Onay:</span> <span className="font-bold text-slate-700">{t.approver}</span></div>
                             </div>
                          </td>
                          <td className="px-8 py-5 font-black text-right text-[14px]">
                             <span className={t.type === TransactionType.IN ? 'text-emerald-500' : 'text-rose-500'}>
                                {t.type === TransactionType.IN ? '+' : '-'}{t.quantity}
                             </span>
                          </td>
                          <td className="px-8 py-5 text-right">
                            <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase border ${
                              t.status === TransactionStatus.APPROVED ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                              t.status === TransactionStatus.REJECTED ? 'bg-rose-50 text-rose-600 border-rose-100' :
                              'bg-amber-50 text-amber-600 border-amber-100'
                            }`}>
                               {t.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto py-4">
              <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Personel Listesi</h3>
                <button onClick={()=>{setEditingUser(null); setIsUserModalOpen(true);}} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700">
                  <UserPlus size={18} /> Yeni Personel Ekle
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {userList.map(u => (
                  <div key={u.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col hover:shadow-xl transition-all group">
                    <div className="flex items-center gap-5 mb-6">
                       <div className="w-14 h-14 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-xl shadow-lg uppercase">{u.fullName.charAt(0)}</div>
                       <div>
                          <p className="font-black text-slate-900 text-lg leading-tight">{u.fullName}</p>
                          <p className="text-[10px] text-indigo-600 font-extrabold uppercase tracking-[0.2em]">{u.role}</p>
                       </div>
                    </div>
                    <div className="flex gap-3 mt-auto pt-6 border-t border-slate-50">
                       <button onClick={()=>{setEditingUser(u); setIsUserModalOpen(true);}} className="flex-1 py-3 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all">Bilgileri Güncelle</button>
                       {u.id !== user.id && (
                         <button onClick={()=>{if(window.confirm('Kullanıcıyı silmek istediğinize emin misiniz?')){StorageService.deleteUser(u.id); setUserList(StorageService.getUsers());}}} className="p-3 text-rose-300 hover:bg-rose-50 hover:text-rose-500 rounded-xl transition-all border border-transparent hover:border-rose-100"><Trash2 size={20} /></button>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/80 p-6 backdrop-blur-lg">
           <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-2xl animate-fade-in border border-white/10">
              <h4 className="text-2xl font-black text-slate-900 uppercase mb-8 text-center">{editingUser ? 'Personel Güncelle' : 'Yeni Kayıt'}</h4>
              <form onSubmit={(e) => {
                 e.preventDefault();
                 const formData = new FormData(e.currentTarget);
                 StorageService.saveUser({
                   id: editingUser?.id || Math.random().toString(36).substring(2, 9),
                   fullName: formData.get('fullName') as string,
                   username: formData.get('username') as string,
                   password: formData.get('password') as string,
                   role: formData.get('role') as UserRole
                 });
                 setUserList(StorageService.getUsers());
                 setIsUserModalOpen(false);
                 showNotification('Kayıt başarıyla tamamlandı.', 'success');
              }} className="space-y-6">
                 <InputSmall label="Tam İsim Soyisim" name="fullName" defaultValue={editingUser?.fullName} required />
                 <InputSmall label="Sistem Kullanıcı Adı" name="username" defaultValue={editingUser?.username} required />
                 <InputSmall label="Giriş Şifresi" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-2">
                    <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest ml-1 block">Yetki Seviyesi</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-slate-800 text-[13px] outline-none appearance-none cursor-pointer focus:bg-white focus:ring-4 focus:ring-indigo-50 transition-all">
                       <option value={UserRole.ADMIN}>Yönetici (Full Erişim)</option>
                       <option value={UserRole.USER}>Personel (Sınırlı)</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-6">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-4 bg-slate-50 rounded-2xl font-black text-slate-400 text-[11px] uppercase tracking-widest">İptal</button>
                    <button type="submit" className="flex-1 py-4 bg-indigo-600 rounded-2xl font-black text-white text-[11px] uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700">Veriyi Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl transition-all relative group ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100 scale-[1.02]' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} strokeWidth={active ? 2.5 : 2} /> 
    <span className={`text-[12px] font-black uppercase tracking-tight ${active ? 'text-white' : 'text-slate-400 group-hover:text-indigo-600'}`}>{label}</span>
    {badge > 0 && (
      <span className="absolute right-4 top-1/2 -translate-y-1/2 w-6 h-6 bg-rose-500 text-white text-[10px] font-black rounded-full flex items-center justify-center shadow-lg animate-pulse">
        {badge}
      </span>
    )}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-start justify-between hover:translate-y-[-4px] transition-all">
    <div className="space-y-2">
      <p className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-3xl font-black text-slate-900 tracking-tighter">{val.toLocaleString()}</p>
    </div>
    <div className={`p-4 bg-${color}-50 text-${color}-600 rounded-2xl border border-${color}-100`}>
      <Icon size={24} />
    </div>
  </div>
);

const DetailItem = ({ label, value, highlight, big }: { label: string, value: string | number, highlight?: boolean, big?: boolean }) => (
  <div>
    <p className="text-[9px] font-extrabold text-slate-400 uppercase tracking-widest mb-1.5">{label}</p>
    <p className={`font-black truncate ${highlight ? 'text-indigo-600' : 'text-slate-800'} ${big ? 'text-xl' : 'text-[13px]'}`}>
       {value}
    </p>
  </div>
);

const InputSmall = ({ label, className, ...props }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest ml-1 block">{label}</label>
    <input 
      {...props} 
      onChange={(e: any)=>props.onChange?.(e.target.value)} 
      className={className || "w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-50 font-black text-slate-900 outline-none transition-all text-[13px] placeholder:text-slate-300"} 
    />
  </div>
);

const HistoryFilter = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-6 py-2.5 rounded-[1rem] text-[10px] font-black uppercase tracking-widest transition-all ${active ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
  >
    {label}
  </button>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Maximize2,
  Trash2,
  UserPlus,
  ClipboardList,
  Hourglass,
  Download,
  Calculator,
  Keyboard,
  Calendar,
  UserCheck,
  UserPlus2,
  Tag
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');

  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1); 
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [operatorName, setOperatorName] = useState(user?.fullName || '');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => { clearTimeout(timer); };
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const currentProductBalance = useMemo(() => {
    if (!productCode) return 0;
    const found = inventory.find(i => i.productCode === productCode);
    return found ? found.remaining : 0;
  }, [productCode, inventory]);

  const projectedBalance = useMemo(() => {
    const qty = quantity === '' ? 0 : Number(quantity);
    if (activeTab === 'in') return currentProductBalance + qty;
    return currentProductBalance - qty;
  }, [currentProductBalance, quantity, activeTab]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const query = searchQuery.toLowerCase();
      return item.productName.toLowerCase().includes(query) || 
             item.productCode.toLowerCase().includes(query);
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const chartData = useMemo(() => {
    return filteredInventory.slice(0, 5).map(item => ({
      name: item.productCode,
      Stok: item.remaining
    }));
  }, [filteredInventory]);

  const resetForm = () => {
    setIsFormActive(false);
    setProductName('');
    setProductCode('');
    setQuantity(1); 
    setPartner('');
    setSize('');
    setColor('');
    setFeature('');
    setApprover('');
    setBrand('');
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";=]+\\s*"([^"]+)"|'${key}'\\s*[:";=]+\\s*'([^']+)'|${key}\\s*[:";=]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      const code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod');
      const name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad');

      setProductCode(code || cleanText);
      setProductName(name || (code ? `Ürün ${code}` : `Ürün ${cleanText}`));
      setQuantity(1);
      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Kod tarandı.', 'success');
    } catch (e) {
      showNotification('Hata!', 'error');
    }
  };

  const handleSave = () => {
    if (!productCode || !productName || quantity === '' || !approver || (activeTab === 'out' && !partner)) {
      showNotification('Lütfen zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out' && Number(quantity) > currentProductBalance) {
      showNotification(`Yetersiz Stok!`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: operatorName || user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification(`Talebiniz ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem onaylandı.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.approver.toLowerCase().includes(historySearch.toLowerCase());
      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      return matchesSearch && matchesType;
    });
  }, [transactions, historySearch, historyTypeFilter]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center gap-3">
             <div className="p-2 bg-indigo-600 rounded-lg text-white"><Box size={20} /></div>
             <h1 className="text-xl font-bold text-slate-900">ProStock</h1>
          </div>
          <nav className="space-y-1 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="Geçmiş" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Personel" />}
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-100">
            <div className="mb-4 px-2">
              <p className="text-[11px] font-bold text-slate-900">{user.fullName}</p>
              <p className="text-[10px] text-slate-400 uppercase">{user.role}</p>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
              <LogOut size={16} /> Çıkış
            </button>
          </div>
        </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-200 p-4 flex justify-between items-center z-40">
          <span className="font-bold text-indigo-600">ProStock</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-100 rounded-lg">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-xl shadow-xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto pb-12">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">Envanter Paneli</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Depo hareketleri ve genel analiz</p>
                </div>
                <div className="relative w-full md:w-80">
                   <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                   <input 
                    type="text" 
                    placeholder="Ürün ara..." 
                    value={searchQuery}
                    onChange={(e)=>setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-[12px] font-bold outline-none focus:ring-2 focus:ring-indigo-100 transition-all" 
                   />
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Net Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Girişler" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Çıkışlar" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Kritik Limit" val={filteredInventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= (thresholds[p.productCode] || 0)).length} icon={AlertCircle} color="amber" />
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 font-bold uppercase text-[12px] text-slate-500">Ürün Bakiyeleri</div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase">
                      <tr>
                        <th className="px-8 py-4">Ürün Bilgisi</th>
                        <th className="px-8 py-4">Toplam G/Ç</th>
                        <th className="px-8 py-4">Kalan Stok</th>
                        <th className="px-8 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50 transition-all text-[12px]">
                          <td className="px-8 py-5">
                            <div className="font-bold text-slate-800">{item.productName}</div>
                            <div className="text-[10px] text-slate-400 uppercase">KOD: {item.productCode}</div>
                          </td>
                          <td className="px-8 py-5">
