                 <InputSmall label="Şifre" name="password" type="password" defaultValue={editingUser?.password} required />
                 <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 block">Yetki Seviyesi</label>
                    <select name="role" defaultValue={editingUser?.role || UserRole.USER} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-slate-800 text-[13px] outline-none cursor-pointer appearance-none">
                       <option value={UserRole.ADMIN}>Yönetici</option>
                       <option value={UserRole.USER}>Personel</option>
                    </select>
                 </div>
                 <div className="flex gap-4 pt-4">
                    <button type="button" onClick={()=>setIsUserModalOpen(false)} className="flex-1 py-4 bg-slate-50 rounded-2xl font-bold text-slate-400 text-[11px] uppercase tracking-widest">İptal</button>
                    <button type="submit" className="flex-1 py-4 bg-indigo-600 rounded-2xl font-bold text-white text-[11px] uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700">Kaydet</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {isScannerOpen && <Scanner onScan={handleQRScan} onClose={()=>setIsScannerOpen(false)} />}
    </div>
  );
};

const NavItem = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl transition-all relative ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <Icon size={18} strokeWidth={active ? 2.5 : 2} /> 
    <span className="text-[12px] font-bold uppercase tracking-tight">{label}</span>
    {badge > 0 && (
      <span className="absolute right-4 top-1/2 -translate-y-1/2 w-6 h-6 bg-rose-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center shadow-lg">
        {badge}
      </span>
    )}
  </button>
);

const StatCard = ({ label, val, icon: Icon, color }: any) => (
  <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm flex items-start justify-between hover:translate-y-[-2px] transition-all">
    <div className="space-y-2">
      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-2xl font-bold text-slate-900 tracking-tight">{val.toLocaleString()}</p>
    </div>
    <div className={`p-4 bg-${color}-50 text-${color}-600 rounded-2xl border border-${color}-100`}>
      <Icon size={24} />
    </div>
  </div>
);

const InfoBox = ({ label, value, highlight, big }: { label: string, value: string | number, highlight?: boolean, big?: boolean }) => (
  <div>
    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter mb-1">{label}</p>
    <p className={`font-bold truncate ${highlight ? 'text-indigo-600' : 'text-slate-800'} ${big ? 'text-lg' : 'text-[12px]'}`}>
       {value}
    </p>
  </div>
);

const InputSmall = ({ label, className, ...props }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 block">{label}</label>
    <input 
      {...props} 
      onChange={(e: any)=>props.onChange?.(e.target.value)} 
      className={className || "w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-50 font-bold text-slate-800 outline-none transition-all text-[13px] placeholder:text-slate-300"} 
    />
  </div>
);

const FilterButton = ({ active, onClick, label }: any) => (
  <button 
    onClick={onClick} 
    className={`px-6 py-2.5 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${active ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
  >
    {label}
  </button>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from './services/storage';
import { User, UserRole, Transaction, TransactionType, TransactionStatus, ProductStock } from './types';
import Login from './components/Login';
import Scanner from './components/Scanner';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { 
  LayoutDashboard, 
  PackagePlus, 
  PackageMinus, 
  History, 
  Users, 
  LogOut, 
  Menu, 
  X, 
  Search,
  CheckCircle2,
  AlertCircle,
  Box,
  TrendingUp,
  TrendingDown,
  Layers,
  Maximize2,
  Trash2,
  UserPlus,
  ClipboardList,
  Hourglass,
  Download,
  Calculator,
  Keyboard,
  Calendar,
  UserCheck,
  UserPlus2,
  Tag,
  Sliders
} from 'lucide-react';

type ActiveTab = 'dashboard' | 'in' | 'out' | 'history' | 'users' | 'approvals' | 'limits';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(StorageService.getCurrentUser());
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(StorageService.getTransactions());
  const [thresholds, setThresholds] = useState<Record<string, number>>(StorageService.getThresholds());
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [historySearch, setHistorySearch] = useState('');
  const [historyTypeFilter, setHistoryTypeFilter] = useState<'ALL' | TransactionType>('ALL');

  const [isFormActive, setIsFormActive] = useState(false);
  const [productName, setProductName] = useState('');
  const [productCode, setProductCode] = useState('');
  const [quantity, setQuantity] = useState<number | ''>(1); 
  const [partner, setPartner] = useState('');
  const [approver, setApprover] = useState('');
  const [size, setSize] = useState('');
  const [color, setColor] = useState('');
  const [feature, setFeature] = useState('');
  const [brand, setBrand] = useState('');

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userList, setUserList] = useState<User[]>(StorageService.getUsers());

  const showNotification = (message: string, type: 'success' | 'error' | 'warning') => {
    setNotification({ message, type });
  };

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => { clearTimeout(timer); };
    }
  }, [notification]);

  const handleLogout = () => {
    StorageService.setCurrentUser(null);
    setUser(null);
  };

  const inventory = useMemo(() => {
    const map = new Map<string, ProductStock>();
    const approvedTransactions = transactions.filter(t => t.status === TransactionStatus.APPROVED);

    [...approvedTransactions].reverse().forEach(tx => {
      const existing = map.get(tx.productCode) || {
        productId: tx.productId,
        productName: tx.productName,
        productCode: tx.productCode,
        totalIn: 0,
        totalOut: 0,
        remaining: 0,
        lastUpdate: tx.date
      };
      if (tx.type === TransactionType.IN) existing.totalIn += tx.quantity;
      else existing.totalOut += tx.quantity;
      existing.remaining = existing.totalIn - existing.totalOut;
      existing.lastUpdate = tx.date;
      map.set(tx.productCode, existing);
    });
    return Array.from(map.values());
  }, [transactions]);

  const currentProductBalance = useMemo(() => {
    if (!productCode) return 0;
    const found = inventory.find(i => i.productCode === productCode);
    return found ? found.remaining : 0;
  }, [productCode, inventory]);

  const projectedBalance = useMemo(() => {
    // Fixed: Removed the redundant 'qty' declaration that was incorrectly using 'qty' before it was defined.
    const numQty = quantity === '' ? 0 : Number(quantity);
    if (activeTab === 'in') return currentProductBalance + numQty;
    return currentProductBalance - numQty;
  }, [currentProductBalance, quantity, activeTab]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => {
      const query = searchQuery.toLowerCase();
      return item.productName.toLowerCase().includes(query) || 
             item.productCode.toLowerCase().includes(query);
    }).sort((a, b) => b.remaining - a.remaining);
  }, [inventory, searchQuery]);

  const resetForm = () => {
    setIsFormActive(false);
    setProductName('');
    setProductCode('');
    setQuantity(1); 
    setPartner('');
    setSize('');
    setColor('');
    setFeature('');
    setApprover('');
    setBrand('');
  };

  const handleQRScan = (text: string) => {
    try {
      const cleanText = text.trim();
      const regexMatch = (key: string) => {
        const regex = new RegExp(`"${key}"\\s*[:";=]+\\s*"([^"]+)"|'${key}'\\s*[:";=]+\\s*'([^']+)'|${key}\\s*[:";=]+\\s*([^,}\\s;]+)`, 'i');
        const match = cleanText.match(regex);
        return match ? (match[1] || match[2] || match[3]) : null;
      };

      const code = regexMatch('urunKodu') || regexMatch('productCode') || regexMatch('kod');
      const name = regexMatch('urunAdi') || regexMatch('productName') || regexMatch('ad');
      const brnd = regexMatch('marka') || regexMatch('brand');
      const clr = regexMatch('renk') || regexMatch('color');
      const ftr = regexMatch('ozellik') || regexMatch('feature');
      const sz = regexMatch('beden') || regexMatch('size');
      const ptnr = regexMatch('tedarikci') || regexMatch('firma') || regexMatch('supplier');
      const qty = regexMatch('adet') || regexMatch('miktar') || regexMatch('quantity');

      setProductCode(code || cleanText);
      setProductName(name || (code ? `Ürün ${code}` : `Ürün ${cleanText}`));
      setBrand(brnd || '');
      setColor(clr || '');
      setFeature(ftr || '');
      setSize(sz || '');
      if (ptnr) setPartner(ptnr);
      if (qty) setQuantity(parseInt(qty) || 1);
      else setQuantity(1);

      setIsFormActive(true);
      setIsScannerOpen(false);
      showNotification('Kod başarıyla çözümlendi.', 'success');
    } catch (e) {
      showNotification('Okuma Hatası!', 'error');
    }
  };

  const handleSave = () => {
    if (!productCode || !productName || quantity === '' || !approver || (activeTab === 'out' && !partner)) {
      showNotification('Lütfen zorunlu alanları doldurun.', 'error');
      return;
    }

    if (activeTab === 'out' && Number(quantity) > currentProductBalance) {
      showNotification(`Yetersiz Stok! Mevcut bakiye: ${currentProductBalance}`, 'error');
      return;
    }

    const newTx: Transaction = {
      id: Math.random().toString(36).substring(2, 9),
      productId: productCode,
      productName,
      productCode,
      quantity: quantity as number,
      type: activeTab === 'in' ? TransactionType.IN : TransactionType.OUT,
      status: TransactionStatus.PENDING,
      supplier: activeTab === 'in' ? partner : undefined,
      recipient: activeTab === 'out' ? partner : undefined,
      date: new Date().toLocaleString('tr-TR'),
      operator: user?.fullName || 'Bilinmiyor',
      approver,
      size,
      color,
      feature,
      brand
    };

    StorageService.addTransaction(newTx);
    setTransactions(StorageService.getTransactions());
    resetForm();
    showNotification(`İşlem ${approver} onayına sunuldu.`, 'success');
  };

  const handleApprove = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.APPROVED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem onaylandı.', 'success');
  };

  const handleReject = (txId: string) => {
    StorageService.updateTransactionStatus(txId, TransactionStatus.REJECTED);
    setTransactions(StorageService.getTransactions());
    showNotification('İşlem reddedildi.', 'warning');
  };

  const handleSaveThreshold = (code: string, value: number) => {
    StorageService.saveThreshold(code, value);
    setThresholds(StorageService.getThresholds());
    showNotification(`${code} için limit güncellendi.`, 'success');
  };

  const pendingApprovals = useMemo(() => {
    return transactions.filter(t => 
      t.status === TransactionStatus.PENDING && 
      t.approver.trim().toLowerCase() === user?.fullName.trim().toLowerCase()
    );
  }, [transactions, user]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = t.productCode.toLowerCase().includes(historySearch.toLowerCase()) || 
                            t.productName.toLowerCase().includes(historySearch.toLowerCase()) ||
                            t.operator.toLowerCase().includes(historySearch.toLowerCase());
      const matchesType = historyTypeFilter === 'ALL' || t.type === historyTypeFilter;
      return matchesSearch && matchesType;
    });
  }, [transactions, historySearch, historyTypeFilter]);

  if (!user) return <Login onLogin={setUser} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden font-medium text-[13px]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 md:translate-x-0 md:static ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="mb-10 px-2 flex items-center gap-3">
             <div className="p-2 bg-indigo-600 rounded-lg text-white shadow-lg shadow-indigo-100"><Box size={20} /></div>
             <h1 className="text-xl font-bold text-slate-900">ProStock</h1>
          </div>
          <nav className="space-y-1 flex-1">
            <NavItem active={activeTab==='dashboard'} onClick={()=>setActiveTab('dashboard')} icon={LayoutDashboard} label="Envanter" />
            <NavItem active={activeTab==='in'} onClick={()=>setActiveTab('in')} icon={PackagePlus} label="Stok Girişi" />
            <NavItem active={activeTab==='out'} onClick={()=>setActiveTab('out')} icon={PackageMinus} label="Stok Çıkışı" />
            <NavItem active={activeTab==='approvals'} onClick={()=>setActiveTab('approvals')} icon={ClipboardList} label="Onay Bekleyenler" badge={pendingApprovals.length} />
            <NavItem active={activeTab==='history'} onClick={()=>setActiveTab('history')} icon={History} label="Geçmiş" />
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='limits'} onClick={()=>setActiveTab('limits')} icon={Sliders} label="Stok Limitleri" />}
            {user.role === UserRole.ADMIN && <NavItem active={activeTab==='users'} onClick={()=>setActiveTab('users')} icon={Users} label="Personel" />}
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-100">
            <div className="mb-4 px-2">
              <p className="text-[11px] font-bold text-slate-900">{user.fullName}</p>
              <p className="text-[10px] text-slate-400 uppercase tracking-widest">{user.role}</p>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
              <LogOut size={16} /> Çıkış
            </button>
          </div>
        </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="md:hidden bg-white border-b border-slate-200 p-4 flex justify-between items-center z-40">
          <span className="font-bold text-indigo-600">ProStock</span>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 bg-slate-100 rounded-lg">
            {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {notification && (
            <div className={`fixed top-6 right-6 z-[110] px-6 py-4 rounded-xl shadow-xl text-white font-bold animate-fade-in flex items-center gap-4 text-[12px] border border-white/10 ${notification.type === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              {notification.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
              {notification.message}
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto pb-12">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">Envanter Paneli</h2>
                  <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Güncel Depo Durumu</p>
                </div>
                <div className="relative w-full md:w-80">
                   <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                   <input 
                    type="text" 
                    placeholder="Ürün ara..." 
                    value={searchQuery}
                    onChange={(e)=>setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-[12px] font-bold outline-none focus:ring-2 focus:ring-indigo-100 shadow-sm transition-all" 
                   />
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Net Stok" val={filteredInventory.reduce((a,b)=>a+b.remaining,0)} icon={Layers} color="indigo" />
                <StatCard label="Girişler" val={filteredInventory.reduce((a,b)=>a+b.totalIn,0)} icon={TrendingUp} color="emerald" />
                <StatCard label="Çıkışlar" val={filteredInventory.reduce((a,b)=>a+b.totalOut,0)} icon={TrendingDown} color="rose" />
                <StatCard label="Kritik Limit" val={filteredInventory.filter(p => (thresholds[p.productCode] || 0) > 0 && p.remaining <= (thresholds[p.productCode] || 0)).length} icon={AlertCircle} color="amber" />
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 font-bold uppercase text-[12px] text-slate-500 tracking-wider">Stok Bakiyeleri</div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
                      <tr>
                        <th className="px-8 py-4">Ürün Bilgisi</th>
                        <th className="px-8 py-4">Toplam Giriş/Çıkış</th>
                        <th className="px-8 py-4">Kalan Stok</th>
                        <th className="px-8 py-4 text-right">Durum</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredInventory.map(item => (
                        <tr key={item.productCode} className="hover:bg-slate-50 transition-all text-[12px]">
                          <td className="px-8 py-5">
                            <div className="font-bold text-slate-800">{item.productName}</div>
                            <div className="text-[10px] text-slate-400 font-bold uppercase">KOD: {item.productCode}</div>
                          </td>
                          <td className="px-8 py-5">
                            <span className="text-emerald-500 font-bold">+{item.totalIn}</span> / <span className="text-rose-500 font-bold">-{item.totalOut}</span>
                          </td>
                          <td className="px-8 py-5 font-bold text-[16px] text-slate-900">{item.remaining}</td>
                          <td className="px-8 py-5 text-right">
                            {(thresholds[item.productCode] || 0) > 0 && item.remaining <= (thresholds[item.productCode] || 0) ? (
                              <span className="bg-rose-500 text-white px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase animate-pulse">Kritik</span>
                            ) : (
                              <span className="bg-slate-100 text-slate-400 px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase">Düzenli</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'limits' && user.role === UserRole.ADMIN && (
            <div className="space-y-8 animate-fade-in max-w-6xl mx-auto pb-12">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Stok Limit Yönetimi</h2>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-wider">Ürünler için minimum stok seviyelerini belirleyin</p>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-8 py-5">Ürün Tanımı</th>
                        <th className="px-8 py-5">Mevcut Stok</th>
                        <th className="px-8 py-5">Minimum Limit</th>
                        <th className="px-8 py-5 text-right">İşlem</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredInventory.map(item => {
                        const [val, setVal] = useState(thresholds[item.productCode] || 0);
                        return (
                          <tr key={item.productCode} className="text-[12px] hover:bg-slate-50 transition-all">
                            <td className="px-8 py-5">
                              <div className="font-bold text-slate-900">{item.productName}</div>
                              <div className="text-[10px] text-slate-400 font-bold uppercase">KOD: {item.productCode}</div>
                            </td>
                            <td className="px-8 py-5 font-bold text-slate-700">{item.remaining}</td>
                            <td className="px-8 py-5">
                              <input 
                                type="number" 
                                value={val}
                                onChange={(e) => setVal(parseInt(e.target.value) || 0)}
                                className="w-24 px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-indigo-100 transition-all"
                              />
                            </td>
                            <td className="px-8 py-5 text-right">
                              <button 
                                onClick={() => handleSaveThreshold(item.productCode, val)}
                                className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-bold uppercase hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
                              >
                                Kaydet
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'approvals' && (
             <div className="space-y-8 animate-fade-in max-w-5xl mx-auto py-4">
                <div className="flex items-center justify-between">
                   <h3 className="text-2xl font-bold text-slate-900 tracking-tight">Onay Bekleyen İşlemler</h3>
                   <div className="px-4 py-2 bg-amber-50 text-amber-600 rounded-xl text-[11px] font-bold flex items-center gap-2 border border-amber-100 shadow-sm">
                      <Hourglass size={14} className="animate-spin-slow" /> {pendingApprovals.length} İşlem Bekliyor
                   </div>
                </div>
                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden flex flex-col md:flex-row hover:shadow-md transition-all">
                       <div className={`w-full md:w-28 flex items-center justify-center p-6 ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={40} strokeWidth={1.5} /> : <PackageMinus size={40} strokeWidth={1.5} />}
                       </div>

                       <div className="flex-1 p-8">
                          <div className="flex flex-col lg:flex-row justify-between gap-6">
                             <div className="space-y-5 flex-1">
                                <div>
