        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">KOD: {item.productCode}</div>
      </td>
      <td className="px-10 py-6">
        <span className={`inline-flex px-3 py-1 rounded-lg font-bold ${item.remaining <= val ? 'bg-amber-50 text-amber-600' : 'bg-slate-50 text-slate-500'}`}>
