                        <th className="px-10 py-6">Ürün Detayı</th>
                        <th className="px-10 py-6">Mevcut Stok</th>
                        <th className="px-10 py-6">Minimum Limit</th>
                        <th className="px-10 py-6 text-right">İşlem</th>
