                   <div className="px-4 py-2 bg-amber-50 text-amber-600 rounded-xl text-[11px] font-bold flex items-center gap-2 border border-amber-100 shadow-sm">
                      <Hourglass size={14} className="animate-spin-slow" /> {pendingApprovals.length} Talep Bekliyor
                   </div>
                </div>
                <div className="grid grid-cols-1 gap-6">
                  {pendingApprovals.map(t => (
                    <div key={t.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden flex flex-col md:flex-row hover:shadow-md transition-all">
                       <div className={`w-full md:w-28 flex items-center justify-center p-6 ${t.type === TransactionType.IN ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                          {t.type === TransactionType.IN ? <PackagePlus size={40} strokeWidth={1.5} /> : <PackageMinus size={40} strokeWidth={1.5} />}
                       </div>

                       <div className="flex-1 p-8">
                          <div className="flex flex-col lg:flex-row justify-between gap-6">
                             <div className="space-y-5 flex-1">
                                <div>
                                   <span className={`inline-block px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase mb-2 ${t.type === TransactionType.IN ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-rose-100 text-rose-700 border border-rose-200'}`}>
                                      Stok {t.type} Talebi
                                   </span>
                                   <h4 className="text-xl font-bold text-slate-900">{t.productName}</h4>
                                   <p className="text-slate-400 text-[11px] font-bold uppercase">Ürün Kodu: {t.productCode}</p>
                                </div>

                                <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 py-5 border-y border-slate-50">
                                   <InfoBox label="Marka" value={t.brand || '-'} />
                                   <InfoBox label="Beden" value={t.size || '-'} />
                                   <InfoBox label={t.type === TransactionType.IN ? 'Tedarikçi' : 'Alıcı / Departman'} value={t.supplier || t.recipient || '-'} highlight />
                                   <InfoBox label="Miktar (Adet)" value={t.quantity} highlight big />
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 pt-2 text-[11px]">
                                   <div className="flex items-center gap-3 text-slate-500 bg-slate-50/50 p-2 rounded-xl">
                                      <Calendar size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Tarih</p>
                                         <span className="font-bold">{t.date}</span>
                                      </div>
                                   </div>
                                   <div className="flex items-center gap-3 text-slate-500 bg-slate-50/50 p-2 rounded-xl">
                                      <UserPlus2 size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Talep Eden</p>
                                         <span className="font-bold">{t.operator}</span>
                                      </div>
                                   </div>
                                   <div className="flex items-center gap-3 text-slate-500 bg-slate-50/50 p-2 rounded-xl">
                                      <UserCheck size={16} className="text-indigo-400" />
                                      <div>
                                         <p className="text-[9px] text-slate-400 uppercase font-bold">Onay Yetkilisi</p>
                                         <span className="font-bold">{t.approver}</span>
                                      </div>
                                   </div>
                                </div>
                             </div>

                             <div className="flex flex-row lg:flex-col justify-end gap-3 min-w-[150px]">
                                <button onClick={() => handleApprove(t.id)} className="flex-1 lg:flex-none px-6 py-4 bg-indigo-600 text-white rounded-2xl text-[11px] font-bold uppercase shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:-translate-y-0.5 transition-all">Onayla</button>
                                <button onClick={() => handleReject(t.id)} className="flex-1 lg:flex-none px-6 py-4 bg-white border border-rose-200 text-rose-500 rounded-2xl text-[11px] font-bold uppercase hover:bg-rose-50 transition-all">Reddet</button>
                             </div>
                          </div>
                       </div>
                    </div>
                  ))}
                  {pendingApprovals.length === 0 && (
                    <div className="bg-white border border-slate-100 rounded-3xl p-24 text-center space-y-4">
                       <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200">
                          <CheckCircle2 size={32} />
                       </div>
                       <p className="text-slate-300 font-bold uppercase tracking-widest text-[11px]">Onay bekleyen işlem bulunmuyor</p>
                    </div>
                  )}
                </div>
             </div>
          )}

          {(activeTab === 'in' || activeTab === 'out') && (
            <div className="max-w-3xl mx-auto space-y-8 animate-fade-in py-10">
              <div className="text-center space-y-4">
                <div className={`inline-flex p-6 rounded-[2rem] ${activeTab === 'in' ? 'bg-indigo-600' : 'bg-rose-500'} text-white shadow-2xl shadow-indigo-100`}>
                  {activeTab === 'in' ? <PackagePlus size={40} /> : <PackageMinus size={40} />}
                </div>
                <h2 className="text-3xl font-bold text-slate-900 tracking-tight uppercase">{activeTab === 'in' ? 'Stok Girişi' : 'Stok Çıkışı'}</h2>
              </div>

              {!isFormActive ? (
                <div className="space-y-4">
                  <div onClick={()=>setIsScannerOpen(true)} className="bg-white border-2 border-dashed border-slate-200 rounded-[2.5rem] p-20 flex flex-col items-center justify-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/10 transition-all group">
                    <Maximize2 size={48} className="text-slate-200 mb-6 group-hover:scale-110 transition-all" />
                    <p className="text-[12px] font-bold uppercase text-slate-400 tracking-widest">QR KOD OKUTARAK DOLDUR</p>
                  </div>
                  <button 
                    onClick={()=>setIsFormActive(true)}
                    className="w-full py-5 bg-white border border-slate-200 rounded-2xl text-[11px] font-bold uppercase text-slate-400 hover:bg-slate-50 transition-all flex items-center justify-center gap-2 shadow-sm"
                  >
                    <Keyboard size={18} /> Manuel Veri Girişi
                  </button>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="bg-slate-900 text-white p-8 rounded-[2rem] shadow-2xl flex items-center justify-between border border-white/5">
                     <div className="flex items-center gap-5">
                        <div className="p-4 bg-white/10 rounded-2xl"><Calculator size={24} /></div>
                        <div>
                           <p className="text-[10px] font-bold text-white/40 uppercase tracking-widest mb-1">Mevcut Depo Stoğu</p>
                           <p className="text-2xl font-bold">{currentProductBalance} Adet</p>
                        </div>
                     </div>
                     <div className="text-right">
                        <p className="text-[10px] font-bold text-white/40 uppercase tracking-widest mb-1">Tahmini Bakiye</p>
                        <p className={`text-2xl font-bold ${projectedBalance < 0 ? 'text-rose-400' : (isBelowThreshold ? 'text-amber-400' : 'text-emerald-400')}`}>
                           {projectedBalance} Adet
                        </p>
                     </div>
                  </div>

                  <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-200 space-y-8 animate-fade-in">
                    {isBelowThreshold && (
                      <div className="bg-amber-50 border border-amber-200 p-4 rounded-2xl flex items-center gap-4 text-amber-700 font-bold text-[12px] animate-pulse">
                         <AlertTriangle size={20} />
                         <span>Uyarı: Bu işlem sonrası stok miktarı minimum limitin ({thresholds[productCode]}) altına düşecektir!</span>
                      </div>
                    )}

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6">
                      <InputSmall label={activeTab==='in' ? "Tedarikçi Firma" : "Alıcı / Departman"} value={partner} onChange={setPartner} placeholder={activeTab==='in' ? "Firma Ünvanı" : "Hedef Departman"} required={activeTab === 'out'} />
                      <InputSmall label="Marka" value={brand} onChange={setBrand} placeholder="Marka Bilgisi" />

                      <InputSmall label="Ürün Kodu" value={productCode} onChange={setProductCode} placeholder="PRD-0001" required />
                      <InputSmall label="Ürün Adı" value={productName} onChange={setProductName} placeholder="Ürün Açıklaması" required />

                      <InputSmall label="Özellik" value={feature} onChange={setFeature} placeholder="Ek Detaylar" />
                      <InputSmall label="Renk" value={color} onChange={setColor} placeholder="Renk Seçeneği" />

                      <InputSmall label="Beden" value={size} onChange={setSize} placeholder="Beden/Ölçü" />
                      <div className="sm:col-span-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 mb-2 block">İşlem Miktarı (Adet)</label>
